import { Settings, AIProvider } from '../types.ts';
import { GoogleGenAI, Type } from "@google/genai";

const extractJSON = (str: string) => {
  if (!str) return {};
  const trimmed = str.trim();
  try {
    return JSON.parse(trimmed);
  } catch (e) {
    const jsonRegex = /\{[\s\S]*\}/;
    const match = trimmed.match(jsonRegex);
    if (match) {
      try {
        const cleaned = match[0].replace(/```json/g, '').replace(/```/g, '').trim();
        return JSON.parse(cleaned);
      } catch (inner) {}
    }
    return {};
  }
};

export const linkify = (text: string) => {
  const urlRegex = /(https?:\/\/[^\s]+)/g;
  return text.split(urlRegex).map((part) => {
    if (part.match(urlRegex)) {
      return `<a href="${part}" target="_blank" rel="noopener noreferrer" class="text-blue-500 underline">${part}</a>`;
    }
    return part;
  }).join('');
};

export const openInGoogle = (query: string) => {
  if (!query) return;
  window.open(`https://www.google.com/search?q=${encodeURIComponent(query)}`, '_blank');
};

/**
 * Declaring global interface for AI Studio helpers provided by the environment.
 */
declare global {
  interface Window {
    aistudio: {
      hasSelectedApiKey: () => Promise<boolean>;
      openSelectKey: () => Promise<void>;
    };
  }
}

async function callAI(
  prompt: string, 
  provider: AIProvider, 
  model: string, 
  apiKey: string, 
  baseUrl: string, 
  isJson: boolean, 
  systemInstruction?: string,
  imagePart?: { data: string, mimeType: string }
) {
  if (provider === AIProvider.Gemini) {
    // Guidelines: Check if an API key has been selected before advanced models/tasks.
    // Models like gemini-3-pro and Veo require user-selected keys from paid projects.
    if (typeof window.aistudio !== 'undefined') {
      try {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        if (!hasKey) {
          await window.aistudio.openSelectKey();
          // Assume success after triggering the dialog to avoid race conditions.
        }
      } catch (e) {
        console.warn('AI Studio helper check failed', e);
      }
    }

    // Guidelines: Create a new instance right before the call to use the latest process.env.API_KEY.
    const key = process.env.API_KEY || apiKey;
    const ai = new GoogleGenAI({ apiKey: key });

    try {
      const contents = imagePart 
        ? { parts: [{ inlineData: imagePart }, { text: prompt }] }
        : prompt;

      const response = await ai.models.generateContent({
        model: model || 'gemini-3-flash-preview',
        contents: contents,
        config: {
          systemInstruction,
          responseMimeType: isJson ? "application/json" : undefined
        }
      });
      return isJson ? extractJSON(response.text || '{}') : response.text;
    } catch (err: any) {
      const errMsg = typeof err === 'string' ? err : (err.message || JSON.stringify(err));

      // Handle Rate Limiting
      if (errMsg.includes('429')) {
        throw new Error("Лимит запросов исчерпан (429). Попробуйте позже или смените модель.");
      }

      // Guidelines: Handle 'Requested entity was not found' (404) by resetting key state.
      if (errMsg.includes('Requested entity was not found.') || errMsg.includes('404')) {
        if (typeof window.aistudio !== 'undefined') {
          await window.aistudio.openSelectKey();
        }
        throw new Error("Модель не найдена или доступ ограничен (404). Пожалуйста, выберите API ключ из ПЛАТНОГО проекта (Google Cloud Billing) в открывшемся окне.");
      }

      throw new Error(`Gemini Error: ${errMsg}`);
    }
  }

  // Common OpenAI-like API call logic (Ollama, LM Studio, OpenRouter)
  const isOllama = provider === AIProvider.Ollama;
  const isOR = provider === AIProvider.OpenRouter;
  let url = (baseUrl || '').trim().replace(/\/$/, '');

  if (isOllama) {
    if (!url) url = 'http://localhost:11434';
    url += '/api/chat';
  } else {
    if (!url) url = isOR ? 'https://openrouter.ai/api/v1' : 'http://localhost:1234/v1';
    if (!url.endsWith('/chat/completions')) {
        if (!url.includes('/v1') && !isOR) url += '/v1';
        url += '/chat/completions';
    }
  }

  const userContent: any[] = [{ type: 'text', text: prompt }];
  if (imagePart) {
    userContent.push({
      type: 'image_url',
      image_url: { url: `data:${imagePart.mimeType};base64,${imagePart.data}` }
    });
  }

  const messages = [
    ...(systemInstruction ? [{ role: 'system', content: systemInstruction }] : []),
    { role: 'user', content: imagePart && !isOllama ? userContent : prompt }
  ];

  const body: any = { 
    model: model, 
    messages: messages,
    stream: false,
    ...(isOllama && isJson ? { format: 'json' } : {})
  };

  const headers: Record<string, string> = { 'Content-Type': 'application/json' };
  if (apiKey) headers['Authorization'] = `Bearer ${apiKey}`;
  if (isOR) {
    headers['HTTP-Referer'] = window.location.origin;
    headers['X-Title'] = 'ScreenMind2';
  }

  try {
    const res = await fetch(url, { method: 'POST', headers, body: JSON.stringify(body) });
    if (res.status === 429) throw new Error("Лимит запросов (429). Смените провайдера или модель.");
    if (!res.ok) throw new Error(`HTTP ${res.status}`);

    const data = await res.json();
    const content = isOllama ? data.message.content : data.choices[0].message.content;
    return isJson ? extractJSON(content) : content;
  } catch (error: any) {
    throw new Error(`${provider}: ${error.message}`);
  }
}

export const analyzeText = async (text: string, settings: Settings) => {
  const prompt = `ВЕРНИ ТОЛЬКО JSON: { "title": "название", "tags": ["тег"], "category": "категория из ${settings.customCategories.join(',')}", "summary": "суть" }. ТЕКСТ: ${text}`;
  return await callAI(prompt, settings.provider, settings.model, settings.apiKey, settings.url, true, "Ты — аналитик знаний.");
};

export const chatWithNotes = async (query: string, context: string, settings: Settings) => {
  return await callAI(`Контекст:\n${context}\n\nВопрос: ${query}`, settings.provider, settings.model, settings.apiKey, settings.url, false);
};

export const chatWithAgent = async (query: string, appData: any, settings: Settings) => {
  return await callAI(`Данные: ${JSON.stringify(appData)}\nЗапрос: ${query}`, settings.agentProvider, settings.agentModel, settings.agentApiKey, settings.agentUrl || settings.url, false, "Ты — системный ассистент приложения.");
};

export const performOCR = async (base64Data: string, mimeType: string, settings: Settings) => {
  const dataOnly = base64Data.split(',')[1] || base64Data;
  return await callAI(
    "Извлеки весь текст из этого изображения. Верни только текст.",
    settings.ocrProvider, 
    settings.ocrModel, 
    settings.ocrApiKey, 
    settings.ocrUrl, 
    false, 
    undefined,
    { data: dataOnly, mimeType }
  );
};

export const testConnection = async (settings: Settings) => {
  try {
    await callAI("ping", settings.provider, settings.model, settings.apiKey, settings.url, false);
    return { success: true, message: `Связь с ${settings.provider} ОК` };
  } catch (e: any) {
    return { success: false, message: e.message };
  }
};

export const splitLargeText = async (text: string, settings: Settings) => {
  const prompt = `Раздели текст на логические блоки JSON [ { "title": "...", "content": "..." } ]. ТЕКСТ: ${text}`;
  return await callAI(prompt, settings.provider, settings.model, settings.apiKey, settings.url, true);
};

export const transcribeAudio = async (blob: Blob, settings: Settings) => "Транскрибация (заглушка).";

