import React, { useState } from 'react';
import { useNotes } from '../contexts/NotesContext.tsx';
import { AIProvider } from '../types.ts';
import { 
  Settings as SettingsIcon, ShieldCheck, 
  Terminal, RefreshCw, Download, Upload, Zap, Server, Cpu, Key, Database, Send, MessageCircle, Image, Mic, Bot, Info
} from 'lucide-react';
import * as storage from '../utils/storage.ts';

const SettingsPage: React.FC = () => {
  const { settings, updateSettings, logs, runSystemCheck, reanalyzeAll } = useNotes();
  const [localSettings, setLocalSettings] = useState(settings);
  const [isReanalyzing, setIsReanalyzing] = useState(false);

  const handleReanalyze = async () => {
    setIsReanalyzing(true);
    await reanalyzeAll();
    setIsReanalyzing(false);
  };

  const handleExport = async () => {
    await storage.exportData();
  };

  const handleImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const success = await storage.importData(file);
    if (success) {
      window.location.reload();
    }
  };

  const ProviderSelector = ({ label, icon: Icon, value, onProviderChange, urlValue, onUrlChange, apiValue, onApiChange, modelValue, onModelChange }: any) => {
    // Guidelines: Gemini API key is obtained exclusively from process.env.API_KEY or AI Studio dialog.
    // Do not show an input field for entering/managing the Gemini API key.
    const isGemini = value === AIProvider.Gemini;
    const isOpenRouter = value === AIProvider.OpenRouter;
    const isLM = value === AIProvider.LMStudio;
    const isOllama = value === AIProvider.Ollama;

    return (
      <section className="bg-white dark:bg-slate-900 p-8 rounded-[3rem] border border-gray-100 dark:border-slate-800 space-y-6 shadow-sm">
        <div className="flex justify-between items-center">
            <h3 className="font-black text-[10px] uppercase tracking-widest flex items-center gap-3 text-gray-400">
                <Icon size={16} className="text-blue-500"/> {label}
            </h3>
            {isLM && <span className="text-[8px] font-black text-amber-500 uppercase px-2 py-1 bg-amber-500/10 rounded-lg">Port 1234</span>}
            {isOllama && <span className="text-[8px] font-black text-blue-500 uppercase px-2 py-1 bg-blue-500/10 rounded-lg">Port 11434</span>}
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-4">
            <div className="space-y-2">
                <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Провайдер</label>
                <select 
                  className="w-full p-4 bg-gray-50 dark:bg-slate-950 rounded-[1.2rem] font-bold text-xs border-none focus:ring-4 focus:ring-blue-500/10 cursor-pointer dark:text-white"
                  value={value}
                  onChange={e => onProviderChange(e.target.value as AIProvider)}
                >
                  {Object.values(AIProvider).map(p => <option key={p} value={p}>{p}</option>)}
                </select>
            </div>
            {!isGemini && !isOpenRouter && (
              <div className="space-y-2">
                  <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">URL Сервера</label>
                  <input 
                    type="text" className="w-full p-4 bg-gray-50 dark:bg-slate-950 rounded-[1.2rem] font-mono text-[10px] border-none dark:text-white"
                    value={urlValue} onChange={e => onUrlChange(e.target.value)}
                    placeholder={isLM ? "http://localhost:1234" : "http://localhost:11434"}
                  />
                  <p className="text-[8px] text-gray-400 ml-2 italic">Для LM Studio добавьте /v1 если эндпоинт не находит модель.</p>
              </div>
            )}
            {isOpenRouter && (
              <div className="space-y-2">
                  <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">API Ключ</label>
                  <input 
                    type="password" className="w-full p-4 bg-gray-50 dark:bg-slate-950 rounded-[1.2rem] font-mono text-[10px] border-none dark:text-white"
                    value={apiValue} onChange={e => onApiChange(e.target.value)}
                  />
              </div>
            )}
          </div>
          <div className="space-y-4">
            <div className="space-y-2">
                <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Модель</label>
                <input 
                  type="text" className="w-full p-4 bg-gray-50 dark:bg-slate-950 rounded-[1.2rem] font-bold text-xs border-none dark:text-white"
                  value={modelValue} onChange={e => onModelChange(e.target.value)}
                  placeholder="Напр. mistral, gemini-3-flash-preview, llama3..."
                />
            </div>
            <div className="p-4 bg-blue-50 dark:bg-blue-900/10 rounded-2xl flex items-start gap-3">
                <Info size={14} className="text-blue-500 shrink-0 mt-0.5" />
                <p className="text-[8px] font-bold text-blue-700 dark:text-blue-300 leading-relaxed uppercase">
                    {isGemini ? "Gemini использует системный API ключ или диалог выбора ключа AI Studio." : "Убедитесь, что модель загружена в вашем локальном сервере перед тестом."}
                </p>
            </div>
          </div>
        </div>
      </section>
    );
  };

  return (
    <div className="max-w-6xl mx-auto p-12 space-y-12 animate-in slide-in-from-bottom duration-500 pb-32">
      <header className="flex items-center justify-between bg-white dark:bg-slate-900 p-8 rounded-[3rem] border border-gray-100 dark:border-slate-800 shadow-sm">
        <div className="flex items-center gap-8">
          <div className="p-5 bg-blue-600 text-white rounded-[2rem] shadow-xl shadow-blue-500/30"><SettingsIcon size={32}/></div>
          <div>
            <h2 className="text-4xl font-black dark:text-white tracking-tighter leading-none">Система</h2>
            <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.4em] mt-2">Control Panel v3.1</p>
          </div>
        </div>
        <div className="flex gap-4">
          <button onClick={handleReanalyze} disabled={isReanalyzing} className="px-6 py-4 bg-amber-50 text-amber-600 dark:bg-amber-900/10 rounded-[1.5rem] font-black text-[10px] uppercase tracking-widest flex items-center gap-3 hover:bg-amber-100 transition-all">
            {isReanalyzing ? <RefreshCw size={16} className="animate-spin" /> : <Database size={16}/>} Индексация
          </button>
          <button onClick={runSystemCheck} className="px-8 py-4 bg-blue-600 text-white rounded-[1.5rem] font-black text-[10px] uppercase tracking-widest flex items-center gap-3 active:scale-95 shadow-xl shadow-blue-500/20 hover:bg-blue-700 transition-all">
            <Zap size={16}/> Тест связи
          </button>
        </div>
      </header>

      <div className="space-y-8">
        <ProviderSelector 
          label="Основной ИИ (Анализ и Чат)" icon={Server}
          value={localSettings.provider} onProviderChange={(v: AIProvider) => setLocalSettings({...localSettings, provider: v})}
          urlValue={localSettings.url} onUrlChange={(v: string) => setLocalSettings({...localSettings, url: v})}
          apiValue={localSettings.apiKey} onApiChange={(v: string) => setLocalSettings({...localSettings, apiKey: v})}
          modelValue={localSettings.model} onModelChange={(v: string) => setLocalSettings({...localSettings, model: v})}
        />

        <ProviderSelector 
          label="ИИ-Ассистент (Системный)" icon={Bot}
          value={localSettings.agentProvider} onProviderChange={(v: AIProvider) => setLocalSettings({...localSettings, agentProvider: v})}
          urlValue={localSettings.agentUrl} onUrlChange={(v: string) => setLocalSettings({...localSettings, agentUrl: v})}
          apiValue={localSettings.agentApiKey} onApiChange={(v: string) => setLocalSettings({...localSettings, agentApiKey: v})}
          modelValue={localSettings.agentModel} onModelChange={(v: string) => setLocalSettings({...localSettings, agentModel: v})}
        />

        <ProviderSelector 
          label="OCR Движок (Vision)" icon={Image}
          value={localSettings.ocrProvider} onProviderChange={(v: AIProvider) => setLocalSettings({...localSettings, ocrProvider: v})}
          urlValue={localSettings.ocrUrl} onUrlChange={(v: string) => setLocalSettings({...localSettings, ocrUrl: v})}
          apiValue={localSettings.ocrApiKey} onApiChange={(v: string) => setLocalSettings({...localSettings, ocrApiKey: v})}
