import { Settings, AIProvider } from '../types.ts';
import { GoogleGenAI, Type } from "@google/genai";

const extractJSON = (str: string) => {
  if (!str) return {};
  const trimmed = str.trim();
  try {
    return JSON.parse(trimmed);
  } catch (e) {
    const jsonRegex = /\{[\s\S]*\}/;
    const match = trimmed.match(jsonRegex);
    if (match) {
      try {
        const cleaned = match[0].replace(/```json/g, '').replace(/```/g, '').trim();
        return JSON.parse(cleaned);
      } catch (inner) {}
    }
    return {};
  }
};

export const linkify = (text: string) => {
  const urlRegex = /(https?:\/\/[^\s]+)/g;
  return text.split(urlRegex).map((part) => {
    if (part.match(urlRegex)) {
      return `<a href="${part}" target="_blank" rel="noopener noreferrer" class="text-blue-500 underline">${part}</a>`;
    }
    return part;
  }).join('');
};

export const openInGoogle = (query: string) => {
  if (!query) return;
  window.open(`https://www.google.com/search?q=${encodeURIComponent(query)}`, '_blank');
};

declare global {
  interface Window {
    aistudio: any;
  }
}

async function callAI(
  prompt: string, 
  provider: AIProvider, 
  model: string, 
  apiKey: string, 
  baseUrl: string, 
  isJson: boolean, 
  systemInstruction?: string,
  imagePart?: { data: string, mimeType: string }
) {
  if (provider === AIProvider.Gemini) {
    if (typeof window.aistudio !== 'undefined') {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      if (!hasKey) {
        await window.aistudio.openSelectKey();
      }
    }

    // Всегда создаем новый экземпляр перед вызовом
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    try {
      const contents = imagePart 
        ? { parts: [{ inlineData: imagePart }, { text: prompt }] }
        : prompt;

      const response = await ai.models.generateContent({
        model: model || 'gemini-3-flash-preview',
        contents: contents,
        config: {
          systemInstruction,
          responseMimeType: isJson ? "application/json" : undefined
        }
      });
      return isJson ? extractJSON(response.text || '{}') : response.text;
    } catch (err: any) {
      const errMsg = err.message || JSON.stringify(err);

      // Обработка 404: модель не найдена или проект без биллинга
      if (errMsg.includes('Requested entity was not found') || errMsg.includes('404')) {
        if (typeof window.aistudio !== 'undefined') {
          await window.aistudio.openSelectKey();
        }
        throw new Error("Ошибка 404: Модель не найдена. Пожалуйста, выберите API-ключ ПЛАТНОГО проекта Google Cloud.");
      }
      throw new Error(`Gemini Error: ${errMsg}`);
    }
  }

  // Локальные и прочие провайдеры (Ollama, LM Studio, OpenRouter)
  const isOllama = provider === AIProvider.Ollama;
  const isOR = provider === AIProvider.OpenRouter;
  let url = (baseUrl || '').trim().replace(/\/$/, '');

  if (isOllama) {
    if (!url) url = 'http://localhost:11434';
    url += '/api/chat';
  } else {
    if (!url) url = isOR ? 'https://openrouter.ai/api/v1' : 'http://localhost:1234/v1';
    if (!url.endsWith('/chat/completions')) {
        if (!url.includes('/v1') && !isOR) url += '/v1';
        url += '/chat/completions';
    }
  }

  const userContent: any[] = [{ type: 'text', text: prompt }];
  if (imagePart) {
    userContent.push({
      type: 'image_url',
      image_url: { url: `data:${imagePart.mimeType};base64,${imagePart.data}` }
    });
  }

  const messages = [
    ...(systemInstruction ? [{ role: 'system', content: systemInstruction }] : []),
    { role: 'user', content: imagePart && !isOllama ? userContent : prompt }
  ];

  const body: any = { 
    model: model, 
    messages: messages,
    stream: false,
    ...(isOllama && isJson ? { format: 'json' } : {})
  };

  const headers: Record<string, string> = { 'Content-Type': 'application/json' };
  if (apiKey) headers['Authorization'] = `Bearer ${apiKey}`;

  const res = await fetch(url, { method: 'POST', headers, body: JSON.stringify(body) });
  if (!res.ok) throw new Error(`HTTP Error: ${res.status}`);

  const data = await res.json();
  const content = isOllama ? data.message.content : data.choices[0].message.content;
  return isJson ? extractJSON(content) : content;
}

