export default NotesPage;

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Note, Settings, AIProvider, AppLog, NoteStatus, TelegramMessage, Goal } from '../types.ts';
import * as storage from '../utils/storage.ts';
import * as ai from '../utils/aiAdapter.ts';

interface NotesContextType {
  notes: Note[];
  goals: Goal[];
  settings: Settings;
  isLoading: boolean;
  logs: AppLog[];
  filterTag: string | null;
  filterCategory: string | null;
  telegramMessages: TelegramMessage[];
  setFilterTag: (tag: string | null) => void;
  setFilterCategory: (cat: string | null) => void;
  addNote: (content: string, title?: string, sourceType?: Note['sourceType'], useAI?: boolean) => Promise<void>;
  processLargeText: (text: string) => Promise<void>;
  updateNote: (note: Note) => Promise<void>;
  moveToTrash: (id: string) => Promise<void>;
  restoreNote: (id: string) => Promise<void>;
  hardDelete: (id: string) => Promise<void>;
  setNoteStatus: (id: string, status: NoteStatus) => Promise<void>;
  updateSettings: (s: Settings) => Promise<void>;
  addLog: (level: AppLog['level'], message: string, details?: string) => void;
  runAIAnalysis: (id: string) => Promise<void>;
  reanalyzeAll: () => Promise<void>;
  runSystemCheck: () => Promise<void>;
  updateNotePosition: (id: string, x: number, y: number) => Promise<void>;
  updateNoteSize: (id: string, w: number, h: number) => Promise<void>;
  syncTelegram: () => Promise<void>;
  addGoal: (title: string, description: string) => Promise<void>;
  deleteGoal: (id: string) => Promise<void>;
  addCategory: (name: string) => Promise<void>;
  deleteCategory: (name: string) => Promise<void>;
}

const NotesContext = createContext<NotesContextType | undefined>(undefined);

export const NotesProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [notes, setNotes] = useState<Note[]>([]);
  const [goals, setGoals] = useState<Goal[]>([]);
  const [settings, setSettings] = useState<Settings>(storage.getDefaultSettings());
  const [isLoading, setIsLoading] = useState(true);
  const [logs, setLogs] = useState<AppLog[]>([]);
  const [filterTag, setFilterTag] = useState<string | null>(null);
  const [filterCategory, setFilterCategory] = useState<string | null>(null);
  const [telegramMessages, setTelegramMessages] = useState<TelegramMessage[]>([]);

  const addLog = (level: AppLog['level'], message: string, details?: string) => {
    setLogs(prev => [{ id: crypto.randomUUID(), timestamp: new Date().toISOString(), level, message, details }, ...prev].slice(0, 50));
  };

  useEffect(() => {
    const init = async () => {
      const [n, s, g] = await Promise.all([storage.getNotes(), storage.getSettings(), storage.getGoals()]);
      setNotes(n);
      setSettings(s);
      setGoals(g);
      setIsLoading(false);
      document.documentElement.classList.toggle('dark', s.theme === 'dark');
    };
    init();
  }, []);

  const addNote = async (content: string, title?: string, sourceType: Note['sourceType'] = 'manual', useAI = true) => {
    let analysis: any = { tags: [], category: filterCategory || 'Общее', summary: '', title: title };

    if (useAI) {
      addLog('info', 'ИИ анализирует контент...');
      try { 
        analysis = await ai.analyzeText(content, settings); 
        // Если категория ИИ не входит в наши настройки, приводим к ближайшей
        if (!settings.customCategories.includes(analysis.category)) {
          analysis.category = filterCategory || 'Общее';
        }
      } catch (e: any) { 
        addLog('warn', `ИИ анализ пропущен: ${e.message}`); 
      }
    }

    const finalTitle = title || analysis.title || content.slice(0, 40);

    const newNote: Note = {
      id: crypto.randomUUID(),
      title: finalTitle,
      content,
      tags: analysis.tags || [],
      category: analysis.category || filterCategory || 'Общее',
      summary: analysis.summary || '',
      status: 'new',
      sourceType,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      links: [],
      position: { x: 100, y: 100 },
      size: { w: 320, h: 280 }
    };
    const updated = [newNote, ...notes];
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const addCategory = async (name: string) => {
    if (settings.customCategories.includes(name)) return;
    const newSettings = { ...settings, customCategories: [...settings.customCategories, name] };
    setSettings(newSettings);
    await storage.saveSettings(newSettings);
  };

  const deleteCategory = async (name: string) => {
    if (name === 'Общее') return;
    const newSettings = { ...settings, customCategories: settings.customCategories.filter(c => c !== name) };
    setSettings(newSettings);
    await storage.saveSettings(newSettings);
    // Переносим заметки удаленной категории в Общее
    const updatedNotes = notes.map(n => n.category === name ? { ...n, category: 'Общее' } : n);
    setNotes(updatedNotes);
    await storage.saveNotes(updatedNotes);
  };

  const processLargeText = async (text: string) => {
    addLog('info', 'Семантический разбор текста...');
    try {
      const blocks = await ai.splitLargeText(text, settings);
      if (Array.isArray(blocks)) {
        const newNotes: Note[] = blocks.map(block => ({
          id: crypto.randomUUID(),
          title: block.title || block.content.slice(0, 40),
          content: block.content,
          tags: [],
          category: block.category || 'Общее',
          summary: '',
          status: 'new',
          sourceType: 'split',
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
          links: [],
          position: { x: 100, y: 100 },
          size: { w: 320, h: 280 }
        }));
        const updated = [...newNotes, ...notes];
        setNotes(updated);
        await storage.saveNotes(updated);
        addLog('success', `Разбор завершен. Создано ${newNotes.length} блоков.`);
      }
    } catch (e: any) {
      addLog('error', `Сбой разбора: ${e.message}`);
    }
  };

  const addGoal = async (title: string, description: string) => {
    const newGoal: Goal = {
      id: crypto.randomUUID(),
      title,
      description,
      createdAt: new Date().toISOString(),
      color: `hsl(${Math.random() * 360}, 70%, 50%)`
    };
    const updated = [newGoal, ...goals];
    setGoals(updated);
    await storage.saveGoals(updated);
  };

  const deleteGoal = async (id: string) => {
    const updated = goals.filter(g => g.id !== id);
    setGoals(updated);
    await storage.saveGoals(updated);
  };

  const syncTelegram = async () => {
    if (!settings.tgToken) return;
    try {
      const response = await fetch(`https://api.telegram.org/bot${settings.tgToken}/getUpdates?offset=${settings.tgLastUpdateId + 1}`);
      const data = await response.json();
      if (data.ok && data.result.length > 0) {
        const newMsgs: TelegramMessage[] = data.result
          .filter((u: any) => u.message && (u.message.text || u.message.caption))
          .map((u: any) => ({
            id: u.update_id,
            text: u.message.text || u.message.caption,
            from: u.message.from.first_name || 'Anonymous',
            date: new Date(u.message.date * 1000).toISOString(),
            type: 'text'
          }));
        setTelegramMessages(prev => [...newMsgs, ...prev]);
        const lastId = data.result[data.result.length - 1].update_id;
        const newSettings = { ...settings, tgLastUpdateId: lastId };
        setSettings(newSettings);
        await storage.saveSettings(newSettings);
      }
    } catch (e: any) {
      addLog('error', `Ошибка Telegram: ${e.message}`);
    }
  };

  const updateSettings = async (s: Settings) => {
    setSettings(s);
    await storage.saveSettings(s);
    document.documentElement.classList.toggle('dark', s.theme === 'dark');
  };

  const moveToTrash = async (id: string) => {
    const updated = notes.map(n => n.id === id ? { ...n, status: 'trash' as NoteStatus } : n);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const restoreNote = async (id: string) => {
    const updated = notes.map(n => n.id === id ? { ...n, status: 'new' as NoteStatus } : n);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const hardDelete = async (id: string) => {
    const updated = notes.filter(n => n.id !== id);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const updateNote = async (n: Note) => {
    const updated = notes.map(x => x.id === n.id ? n : x);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const setNoteStatus = async (id: string, status: NoteStatus) => {
    const updated = notes.map(n => n.id === id ? { ...n, status } : n);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const updateNotePosition = async (id: string, x: number, y: number) => {
    const updated = notes.map(n => n.id === id ? { ...n, position: { x, y } } : n);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const updateNoteSize = async (id: string, w: number, h: number) => {
    const updated = notes.map(n => n.id === id ? { ...n, size: { w, h } } : n);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const runAIAnalysis = async (id: string) => {
    const note = notes.find(n => n.id === id);
    if (!note) return;
    try {
      const res = await ai.analyzeText(note.content, settings);
      const updated = notes.map(n => n.id === id ? { ...n, ...res, updatedAt: new Date().toISOString() } : n);
      setNotes(updated);
      await storage.saveNotes(updated);
    } catch (e: any) {
      addLog('error', `Ошибка анализа: ${e.message}`);
      throw e; 
    }
  };

  const runSystemCheck = async () => {
    const res = await ai.testConnection(settings);
    if (res.success) addLog('success', res.message);
    else addLog('error', res.message);
  };

  const reanalyzeAll = async () => {
    const updated = [...notes];
    for (let i = 0; i < updated.length; i++) {
       if (updated[i].status === 'trash') continue;
       try {
         const res = await ai.analyzeText(updated[i].content, settings);
         updated[i] = { ...updated[i], ...res };
       } catch (e) {}
    }
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  return (
    <NotesContext.Provider value={{ 
      notes, goals, settings, isLoading, logs, filterTag, filterCategory, telegramMessages,
      setFilterTag, setFilterCategory, addNote, processLargeText, updateNote, moveToTrash, restoreNote, hardDelete,
      setNoteStatus, updateSettings, addLog, runAIAnalysis, reanalyzeAll,
      runSystemCheck, updateNotePosition, updateNoteSize, syncTelegram, addGoal, deleteGoal, addCategory, deleteCategory
    }}>
      {children}
    </NotesContext.Provider>
  );
};

export const useNotes = () => {
  const c = useContext(NotesContext);
  if (!c) throw new Error("useNotes error");
  return c;
};

import { Settings, AIProvider } from '../types.ts';
import { GoogleGenAI, Type } from "@google/genai";

const extractJSON = (str: string) => {
  if (!str) return {};
  const trimmed = str.trim();
  try {
    return JSON.parse(trimmed);
  } catch (e) {
    const jsonRegex = /\{[\s\S]*\}/;
    const match = trimmed.match(jsonRegex);
    if (match) {
      try {
        const cleaned = match[0].replace(/```json/g, '').replace(/```/g, '').trim();
        return JSON.parse(cleaned);
      } catch (inner) {}
    }
    return {};
  }
};

export const linkify = (text: string) => {
  const urlRegex = /(https?:\/\/[^\s]+)/g;
  return text.split(urlRegex).map((part) => {
    if (part.match(urlRegex)) {
      return `<a href="${part}" target="_blank" rel="noopener noreferrer" class="text-blue-500 underline">${part}</a>`;
    }
    return part;
  }).join('');
};

export const openInGoogle = (query: string) => {
  if (!query) return;
  window.open(`https://www.google.com/search?q=${encodeURIComponent(query)}`, '_blank');
};

// Define AIStudio interface to match existing global definitions and requirements
interface AIStudio {
  hasSelectedApiKey(): Promise<boolean>;
  openSelectKey(): Promise<void>;
}

declare global {
  interface Window {
    // Fixed: Using AIStudio type to match global definitions and requirements
    aistudio: AIStudio;
  }
}

async function callAI(
  prompt: string, 
  provider: AIProvider, 
  model: string, 
  apiKey: string, 
  baseUrl: string, 
  isJson: boolean, 
  systemInstruction?: string,
  imagePart?: { data: string, mimeType: string }
) {
  if (provider === AIProvider.Gemini) {
    if (typeof window.aistudio !== 'undefined') {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      if (!hasKey) {
        await window.aistudio.openSelectKey();
      }
    }

    // Always create a new GoogleGenAI instance right before making an API call 
    // to ensure it always uses the most up-to-date API key from the dialog.
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    try {
      const contents = imagePart 
        ? { parts: [{ inlineData: imagePart }, { text: prompt }] }
        : prompt;

      const response = await ai.models.generateContent({
        model: model || 'gemini-3-flash-preview',
        contents: contents,
        config: {
          systemInstruction,
          responseMimeType: isJson ? "application/json" : undefined
        }
      });
      return isJson ? extractJSON(response.text || '{}') : response.text;
    } catch (err: any) {
      const errMsg = err.message || JSON.stringify(err);

      // If the request fails with 404/Requested entity was not found, reset key selection state and prompt user.
      if (errMsg.includes('Requested entity was not found') || errMsg.includes('404')) {
        if (typeof window.aistudio !== 'undefined') {
          await window.aistudio.openSelectKey();
        }
        throw new Error("Ошибка 404: Модель не найдена. Пожалуйста, выберите API-ключ ПЛАТНОГО проекта Google Cloud.");
      }
      throw new Error(`Gemini Error: ${errMsg}`);
    }
  }

  // Локальные и прочие провайдеры (Ollama, LM Studio, OpenRouter)
  const isOllama = provider === AIProvider.Ollama;
  const isOR = provider === AIProvider.OpenRouter;
  let url = (baseUrl || '').trim().replace(/\/$/, '');

  if (isOllama) {
    if (!url) url = 'http://localhost:11434';
    url += '/api/chat';
  } else {
    if (!url) url = isOR ? 'https://openrouter.ai/api/v1' : 'http://localhost:1234/v1';
    if (!url.endsWith('/chat/completions')) {
        if (!url.includes('/v1') && !isOR) url += '/v1';
        url += '/chat/completions';
    }
  }

  const userContent: any[] = [{ type: 'text', text: prompt }];
  if (imagePart) {
    userContent.push({
      type: 'image_url',
      image_url: { url: `data:${imagePart.mimeType};base64,${imagePart.data}` }
    });
  }

  const messages = [
    ...(systemInstruction ? [{ role: 'system', content: systemInstruction }] : []),
    { role: 'user', content: imagePart && !isOllama ? userContent : prompt }
  ];

  const body: any = { 
    model: model, 
    messages: messages,
    stream: false,
    ...(isOllama && isJson ? { format: 'json' } : {})
  };

  const headers: Record<string, string> = { 'Content-Type': 'application/json' };
  if (apiKey) headers['Authorization'] = `Bearer ${apiKey}`;

  const res = await fetch(url, { method: 'POST', headers, body: JSON.stringify(body) });
  if (!res.ok) throw new Error(`HTTP Error: ${res.status}`);

  const data = await res.json();
  const content = isOllama ? data.message.content : data.choices[0].message.content;
  return isJson ? extractJSON(content) : content;
}

