export type NoteStatus = 'new' | 'in-work' | 'read' | 'finished' | 'trash' | 'archived';

export interface Note {
  id: string;
  title: string;
  content: string;
  tags: string[];
  category: string;
  summary: string;
  links: string[]; // Связанные ID целей или других заметок
  createdAt: string;
  updatedAt: string;
  status: NoteStatus;
  isIndexed?: boolean; // Флаг для оффлайн-режима
  sourceType?: 'manual' | 'ocr' | 'audio' | 'telegram' | 'split';
