import React, { createContext, useContext, useState, useEffect } from 'react';
import { Note, Settings, AIProvider, AppLog, NoteStatus, TelegramMessage, Goal } from '../types.ts';
import * as storage from '../utils/storage.ts';
import * as ai from '../utils/aiAdapter.ts';

interface NotesContextType {
  notes: Note[];
  goals: Goal[];
  settings: Settings;
  isLoading: boolean;
  logs: AppLog[];
  filterTag: string | null;
  filterCategory: string | null;
  telegramMessages: TelegramMessage[];
  setFilterTag: (tag: string | null) => void;
  setFilterCategory: (cat: string | null) => void;
  addNote: (content: string, title?: string, sourceType?: Note['sourceType'], useAI?: boolean) => Promise<void>;
  processLargeText: (text: string) => Promise<void>;
  updateNote: (note: Note) => Promise<void>;
  moveToTrash: (id: string) => Promise<void>;
  restoreNote: (id: string) => Promise<void>;
  hardDelete: (id: string) => Promise<void>;
  setNoteStatus: (id: string, status: NoteStatus) => Promise<void>;
  updateSettings: (s: Settings) => Promise<void>;
  addLog: (level: AppLog['level'], message: string, details?: string) => void;
  runAIAnalysis: (id: string) => Promise<void>;
  reanalyzeAll: () => Promise<void>;
  runSystemCheck: () => Promise<void>;
  updateNotePosition: (id: string, x: number, y: number) => Promise<void>;
  updateNoteSize: (id: string, w: number, h: number) => Promise<void>;
  syncTelegram: () => Promise<void>;
  addGoal: (title: string, description: string) => Promise<void>;
  toggleGoalStatus: (id: string) => Promise<void>;
  deleteGoal: (id: string) => Promise<void>;
  addCategory: (name: string) => Promise<void>;
  deleteCategory: (name: string) => Promise<void>;
}

const NotesContext = createContext<NotesContextType | undefined>(undefined);

export const NotesProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [notes, setNotes] = useState<Note[]>([]);
  const [goals, setGoals] = useState<Goal[]>([]);
  const [settings, setSettings] = useState<Settings>(storage.getDefaultSettings());
  const [isLoading, setIsLoading] = useState(true);
  const [logs, setLogs] = useState<AppLog[]>([]);
  const [filterTag, setFilterTag] = useState<string | null>(null);
  const [filterCategory, setFilterCategory] = useState<string | null>(null);
  const [telegramMessages, setTelegramMessages] = useState<TelegramMessage[]>([]);

  const addLog = (level: AppLog['level'], message: string, details?: string) => {
    setLogs(prev => [{ id: crypto.randomUUID(), timestamp: new Date().toISOString(), level, message, details }, ...prev].slice(0, 50));
  };

  useEffect(() => {
    const init = async () => {
      const [n, s, g] = await Promise.all([storage.getNotes(), storage.getSettings(), storage.getGoals()]);
      setNotes(n);
      setSettings(s);
      setGoals(g || []);
      setIsLoading(false);
      document.documentElement.classList.toggle('dark', s.theme === 'dark');
    };
    init();
  }, []);

  const addNote = async (content: string, title?: string, sourceType: Note['sourceType'] = 'manual', useAI = true) => {
    let analysis: any = { tags: [], category: filterCategory || 'Общее', summary: '', title: title };
    let isIndexed = false;

    if (useAI && navigator.onLine) {
      addLog('info', 'ИИ анализирует контент...');
      try { 
        analysis = await ai.analyzeText(content, settings); 
        isIndexed = true;
      } catch (e: any) { 
        addLog('warn', `ИИ анализ отложен: ${e.message}`); 
      }
    } else if (useAI) {
      addLog('warn', 'Нет интернета. Анализ отложен.');
    }

    const newNote: Note = {
      id: crypto.randomUUID(),
      title: title || analysis.title || content.slice(0, 40),
      content,
      tags: analysis.tags || [],
      category: analysis.category || filterCategory || 'Общее',
      summary: analysis.summary || '',
      status: 'new',
      isIndexed,
      sourceType,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      links: [],
      position: { x: Math.random() * 200, y: Math.random() * 200 },
      size: { w: 320, h: 280 }
    };

    const updated = [newNote, ...notes];
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const addGoal = async (title: string, description: string) => {
    const newGoal: Goal = {
      id: crypto.randomUUID(),
      title,
      description,
      createdAt: new Date().toISOString(),
      color: `hsl(${Math.random() * 360}, 70%, 50%)`,
      status: 'active'
    };
    const updated = [newGoal, ...goals];
    setGoals(updated);
    await storage.saveGoals(updated);
  };

  const toggleGoalStatus = async (id: string) => {
    const updated = goals.map(g => g.id === id ? { ...g, status: g.status === 'active' ? 'completed' : 'active' as any } : g);
    setGoals(updated);
    await storage.saveGoals(updated);
  };

  const deleteGoal = async (id: string) => {
    const updated = goals.filter(g => g.id !== id);
    setGoals(updated);
    await storage.saveGoals(updated);
  };

  const reanalyzeAll = async () => {
    if (!navigator.onLine) {
        addLog('error', 'Индексация невозможна без интернета');
        return;
    }
    addLog('info', 'Запуск глобальной переиндексации...');
    const updated = [...notes];
    let count = 0;
    for (let i = 0; i < updated.length; i++) {
       if (updated[i].isIndexed || updated[i].status === 'trash') continue;
       try {
         const res = await ai.analyzeText(updated[i].content, settings);
         updated[i] = { ...updated[i], ...res, isIndexed: true };
         count++;
       } catch (e) {
           break; 
       }
    }
    setNotes(updated);
    await storage.saveNotes(updated);
    addLog('success', `Индексация завершена. Обработано: ${count}`);
  };

  const updateNote = async (n: Note) => {
    const updated = notes.map(x => x.id === n.id ? n : x);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const setNoteStatus = async (id: string, status: NoteStatus) => {
    const updated = notes.map(n => n.id === id ? { ...n, status } : n);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const moveToTrash = async (id: string) => {
    const updated = notes.map(n => n.id === id ? { ...n, status: 'trash' as NoteStatus } : n);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const addCategory = async (name: string) => {
    if (settings.customCategories.includes(name)) return;
    const newSettings = { ...settings, customCategories: [...settings.customCategories, name] };
    await updateSettings(newSettings);
  };

  const deleteCategory = async (name: string) => {
    if (name === 'Общее') return;
    const newSettings = { ...settings, customCategories: settings.customCategories.filter(c => c !== name) };
    await updateSettings(newSettings);
    const updatedNotes = notes.map(n => n.category === name ? { ...n, category: 'Общее' } : n);
    setNotes(updatedNotes);
    await storage.saveNotes(updatedNotes);
  };

  const updateSettings = async (s: Settings) => {
    setSettings(s);
    await storage.saveSettings(s);
    document.documentElement.classList.toggle('dark', s.theme === 'dark');
  };

  const runAIAnalysis = async (id: string) => {
    const note = notes.find(n => n.id === id);
    if (!note) return;
    try {
      const res = await ai.analyzeText(note.content, settings);
      const updated = notes.map(n => n.id === id ? { ...n, ...res, isIndexed: true, updatedAt: new Date().toISOString() } : n);
      setNotes(updated);
      await storage.saveNotes(updated);
    } catch (e: any) {
      addLog('error', `Ошибка анализа: ${e.message}`);
      throw e; 
    }
  };

  return (
    <NotesContext.Provider value={{ 
      notes, goals, settings, isLoading, logs, filterTag, filterCategory, telegramMessages,
      setFilterTag, setFilterCategory, addNote, processLargeText, updateNote, moveToTrash, 
      restoreNote: async (id) => setNoteStatus(id, 'new'), 
      hardDelete: async (id) => { const u = notes.filter(x => x.id !== id); setNotes(u); await storage.saveNotes(u); },
      setNoteStatus, updateSettings, addLog, runAIAnalysis, reanalyzeAll,
      runSystemCheck: async () => { const r = await ai.testConnection(settings); r.success ? addLog('success', r.message) : addLog('error', r.message); },
      updateNotePosition: async (id, x, y) => { const u = notes.map(n => n.id === id ? { ...n, position: { x, y } } : n); setNotes(u); await storage.saveNotes(u); },
      updateNoteSize: async (id, w, h) => { const u = notes.map(n => n.id === id ? { ...n, size: { w, h } } : n); setNotes(u); await storage.saveNotes(u); },
      syncTelegram: async () => {}, // Plug
      addGoal, toggleGoalStatus, deleteGoal, addCategory, deleteCategory
    }}>
      {children}
    </NotesContext.Provider>
  );
};

export const useNotes = () => {
  const c = useContext(NotesContext);
  if (!c) throw new Error("useNotes error");
  return c;
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useNotes } from '../contexts/NotesContext.tsx';
import { Note } from '../types.ts';
import { 
  ChevronLeft, Save, Loader2, Sparkles, MessageSquare, Send, X, Folder, Globe, Hash, Link as LinkIcon, FileText
} from 'lucide-react';
import * as ai from '../utils/aiAdapter.ts';

const NoteEditor: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { notes, addNote, updateNote, runAIAnalysis, settings } = useNotes();

  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [tags, setTags] = useState<string[]>([]);
  const [category, setCategory] = useState('Общее');
  const [isSaving, setIsSaving] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [note, setNote] = useState<Note | null>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatMessages, setChatMessages] = useState<{role: 'user' | 'ai', text: string}[]>([]);
  const [isChatLoading, setIsChatLoading] = useState(false);
  const chatScrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (id && id !== 'new') {
      const found = notes.find(n => n.id === id);
      if (found) {
        setNote(found);
        setTitle(found.title);
        setContent(found.content);
        setTags(found.tags || []);
        setCategory(found.category || 'Общее');

        if (found.summary && chatMessages.length === 0) {
            setChatMessages([{ role: 'ai', text: `Суть заметки: ${found.summary}\n\nЯ готов ответить на любые вопросы.` }]);
        }
      }
    }
  }, [id, notes]);

  const similarNotes = useMemo(() => {
    if (!note) return [];
    return notes.filter(n => {
        if (n.id === note.id || n.status === 'trash') return false;
        const commonTags = tags.filter(t => n.tags.includes(t));
        return commonTags.length > 0 || n.category === category;
    }).slice(0, 4);
  }, [note, notes, tags, category]);

  useEffect(() => {
    chatScrollRef.current?.scrollTo(0, chatScrollRef.current.scrollHeight);
  }, [chatMessages]);

  const handleSave = async (useAI = false) => {
    if (!content.trim() && !title.trim()) return;
    setIsSaving(true);
    if (useAI) setIsAnalyzing(true);

    try {
        if (id === 'new') {
          await addNote(content, title, 'manual', useAI);
          navigate('/');
        } else if (note) {
          const updatedNote = { ...note, title, content, tags, category, updatedAt: new Date().toISOString() };
          await updateNote(updatedNote);
          if (useAI && navigator.onLine) {
            await runAIAnalysis(note.id);
          }
        }
    } catch (e: any) {
      console.error(e);
    } finally {
        setIsSaving(false);
        setIsAnalyzing(false);
    }
  };

  const handleChat = async () => {
    if (!chatInput.trim()) return;
    const userMsg = chatInput;
    setChatMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setChatInput('');
    setIsChatLoading(true);
    try {
      const context = `Заметка: ${title}\nТекст: ${content}`;
      const response = await ai.chatWithNotes(userMsg, context, settings);
      setChatMessages(prev => [...prev, { role: 'ai', text: response }]);
    } catch (e: any) {
      setChatMessages(prev => [...prev, { role: 'ai', text: `Ошибка: ${e.message}` }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  return (
    <div className="h-screen flex flex-col bg-white dark:bg-[#020617] overflow-hidden">
      <header className="flex items-center justify-between px-12 py-8 border-b border-gray-100 dark:border-white/5 bg-white/80 dark:bg-slate-950/80 backdrop-blur-2xl z-20 shrink-0">
        <div className="flex items-center gap-6 flex-1">
          <button onClick={() => navigate(-1)} className="p-4 text-gray-400 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-2xl transition-all"><ChevronLeft size={24}/></button>
          <input 
            className="text-4xl font-black bg-transparent border-none focus:outline-none text-black dark:text-white w-full tracking-tighter placeholder:text-gray-200" 
            value={title} 
            onChange={e => setTitle(e.target.value)} 
            placeholder="Заголовок..."
          />
        </div>
        <div className="flex items-center gap-4">
          <button 
            onClick={() => ai.openInGoogle(title || content.slice(0, 50))}
            className="p-4 text-gray-400 hover:text-blue-500 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-2xl transition-all"
            title="Искать в Google"
          >
            <Globe size={20} />
          </button>
          <button 
            onClick={() => handleSave(true)} 
            className="px-8 py-4 bg-cyan-600/10 text-cyan-600 dark:text-cyan-400 rounded-2xl font-black uppercase text-[10px] tracking-widest hover:bg-cyan-600/20 transition-all flex items-center gap-3"
          >
            {isAnalyzing ? <Loader2 size={18} className="animate-spin"/> : <Sparkles size={18}/>}
            Индексация
          </button>
          <button 
            onClick={() => handleSave(false)} 
            className="px-8 py-4 bg-blue-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest hover:shadow-xl active:scale-95 transition-all flex items-center gap-3"
          >
            {isSaving && !isAnalyzing ? <Loader2 size={18} className="animate-spin"/> : <Save size={18}/>}
            Сохранить
          </button>
        </div>
      </header>

      <div className="flex-1 flex overflow-hidden">
        <div className="flex-1 flex flex-col overflow-y-auto custom-scrollbar">
          <div className="p-16 flex-1 flex flex-col min-h-full">
            <textarea 
              className="w-full flex-1 bg-transparent border-none focus:outline-none text-2xl leading-relaxed text-black dark:text-white resize-none font-bold placeholder:text-gray-200"
              value={content}
              onChange={e => setContent(e.target.value)}
              placeholder="Начните печатать..."
            />

            {similarNotes.length > 0 && (
                <div className="mt-20 pt-10 border-t border-gray-100 dark:border-white/5">
                    <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-6 flex items-center gap-2">
                        <LinkIcon size={14} className="text-blue-500" /> Связанные смыслы
                    </h4>
                    <div className="grid grid-cols-2 gap-4">
                        {similarNotes.map(sn => (
                            <div key={sn.id} onClick={() => navigate(`/editor/${sn.id}`)} className="p-6 bg-gray-50 dark:bg-slate-900/50 rounded-2xl border border-gray-100 dark:border-white/5 hover:border-blue-500 cursor-pointer transition-all group">
                                <h5 className="font-black text-sm dark:text-white group-hover:text-blue-500 truncate mb-1">{sn.title}</h5>
                                <p className="text-[10px] text-gray-400 line-clamp-2">{sn.summary || sn.content}</p>
                            </div>
                        ))}
                    </div>
                </div>
            )}
          </div>
        </div>

        <div className="w-[420px] border-l border-gray-100 dark:border-white/5 flex flex-col bg-gray-50/50 dark:bg-slate-950/20 p-8 gap-6 overflow-y-auto custom-scrollbar">
          <div className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] border border-gray-100 dark:border-white/5 shadow-md">
             <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2 mb-4">
               <Folder size={14} className="text-blue-500"/> Группа
             </h4>
             <select 
               className="w-full p-4 bg-gray-50 dark:bg-slate-950 rounded-xl font-black text-sm border-none dark:text-white cursor-pointer"
               value={category}
               onChange={e => setCategory(e.target.value)}
             >
                {settings.customCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
             </select>
          </div>

          <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] border border-gray-100 dark:border-white/5 flex flex-col h-[400px] shadow-lg overflow-hidden shrink-0">
            <header className="p-4 border-b border-gray-50 dark:border-white/5 text-[10px] font-black uppercase tracking-widest text-blue-500 flex items-center gap-2">
              <MessageSquare size={14}/> Разум Заметки
            </header>
            <div className="flex-1 p-4 overflow-y-auto space-y-3 custom-scrollbar" ref={chatScrollRef}>
              {chatMessages.map((msg, i) => (
                <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[90%] p-4 rounded-2xl text-xs font-bold ${msg.role === 'user' ? 'bg-blue-600 text-white' : 'bg-gray-100 dark:bg-slate-800 dark:text-slate-300'}`}>
                    {msg.text}
                  </div>
                </div>
              ))}
              {isChatLoading && <div className="text-blue-500 animate-pulse text-[10px] font-black p-2">ИИ думает...</div>}
            </div>
            <div className="p-4 border-t border-gray-50 dark:border-white/5 relative">
              <input 
                className="w-full pl-4 pr-12 py-4 bg-gray-50 dark:bg-slate-950 rounded-xl text-xs font-bold border-none dark:text-white"
                placeholder="Спросить..."
                value={chatInput}
                onChange={e => setChatInput(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleChat()}
              />
              <button onClick={handleChat} className="absolute right-6 top-1/2 -translate-y-1/2 text-blue-600"><Send size={18}/></button>
            </div>
          </div>

          <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-gray-100 dark:border-white/5 space-y-6">
            <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
              <Hash size={14} className="text-blue-500"/> Теги
            </h4>
            <div className="flex flex-wrap gap-2">
              {tags.map(t => (
                  <span key={t} className="px-3 py-1.5 bg-blue-500/5 rounded-lg text-[9px] font-black text-blue-500 uppercase flex items-center gap-2 border border-blue-500/10">
                    #{t} <button onClick={() => setTags(tags.filter(x => x !== t))} className="hover:text-red-500"><X size={10}/></button>
                  </span>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default NoteEditor;

