  const [tags, setTags] = useState<string[]>([]);
  const [category, setCategory] = useState('Общее');
  const [isSaving, setIsSaving] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [note, setNote] = useState<Note | null>(null);
  const [newTag, setNewTag] = useState('');

  const [chatInput, setChatInput] = useState('');
  const [chatMessages, setChatMessages] = useState<{role: 'user' | 'ai', text: string}[]>([]);
  const [isChatLoading, setIsChatLoading] = useState(false);
  const chatScrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (id && id !== 'new') {
      const found = notes.find(n => n.id === id);
      if (found) {
        setNote(found);
        setTitle(found.title);
        setContent(found.content);
        setTags(found.tags || []);
        setCategory(found.category || 'Общее');

        if (found.summary && chatMessages.length === 0) {
            setChatMessages([{ role: 'ai', text: `Суть заметки: ${found.summary}\n\nЯ готов ответить на любые вопросы.` }]);
        }
      }
    }
  }, [id, notes]);

  const similarNotes = useMemo(() => {
    if (!note) return [];
    return notes.filter(n => {
        if (n.id === note.id || n.status === 'trash') return false;
        const commonTags = tags.filter(t => n.tags.includes(t));
        return commonTags.length > 0 || n.category === category;
    }).slice(0, 4);
  }, [note, notes, tags, category]);

  useEffect(() => {
    chatScrollRef.current?.scrollTo(0, chatScrollRef.current.scrollHeight);
  }, [chatMessages]);

  const handleAddTag = () => {
    const trimmed = newTag.trim().toLowerCase();
    if (trimmed && !tags.includes(trimmed)) {
      setTags([...tags, trimmed]);
      setNewTag('');
    }
  };

  const handleSave = async (useAI = false) => {
    if (!content.trim() && !title.trim()) return;
    setIsSaving(true);
    if (useAI) setIsAnalyzing(true);

    try {
        if (id === 'new') {
          await addNote(content, title, 'manual', useAI);
          navigate('/');
        } else if (note) {
          const updatedNote = { ...note, title, content, tags, category, updatedAt: new Date().toISOString() };
          await updateNote(updatedNote);
          if (useAI && navigator.onLine) {
            await runAIAnalysis(note.id);
          }
        }
    } catch (e: any) {
      console.error(e);
    } finally {
        setIsSaving(false);
        setIsAnalyzing(false);
    }
  };

  const handleChat = async () => {
    if (!chatInput.trim()) return;
    const userMsg = chatInput;
    setChatMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setChatInput('');
    setIsChatLoading(true);
    try {
      const context = `Заметка: ${title}\nТекст: ${content}`;
      const response = await ai.chatWithNotes(userMsg, context, settings);
      setChatMessages(prev => [...prev, { role: 'ai', text: response }]);
    } catch (e: any) {
      setChatMessages(prev => [...prev, { role: 'ai', text: `Ошибка: ${e.message}` }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  return (
    <div className="h-screen flex flex-col bg-white dark:bg-[#020617] overflow-hidden">
      <header className="flex items-center justify-between px-12 py-8 border-b border-gray-100 dark:border-white/5 bg-white/80 dark:bg-slate-950/80 backdrop-blur-2xl z-20 shrink-0">
        <div className="flex items-center gap-6 flex-1">
          <button onClick={() => navigate(-1)} className="p-4 text-gray-400 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-2xl transition-all"><ChevronLeft size={24}/></button>
          <input 
            className="text-4xl font-extrabold bg-transparent border-none focus:outline-none text-black dark:text-white w-full tracking-tighter placeholder:text-gray-200" 
            value={title} 
            onChange={e => setTitle(e.target.value)} 
            placeholder="Заголовок..."
          />
        </div>
        <div className="flex items-center gap-4">
          <button 
            onClick={() => ai.openInGoogle(title || content.slice(0, 50))}
            className="p-4 text-gray-400 hover:text-blue-500 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-2xl transition-all"
            title="Искать в Google"
          >
            <Globe size={20} />
          </button>
          <button 
            onClick={() => handleSave(true)} 
            className="px-8 py-4 bg-cyan-600/10 text-cyan-600 dark:text-cyan-400 rounded-2xl font-black uppercase text-[10px] tracking-widest hover:bg-cyan-600/20 transition-all flex items-center gap-3"
          >
            {isAnalyzing ? <Loader2 size={18} className="animate-spin"/> : <Sparkles size={18}/>}
            Индексация
          </button>
          <button 
            onClick={() => handleSave(false)} 
            className="px-8 py-4 bg-blue-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest hover:shadow-xl active:scale-95 transition-all flex items-center gap-3"
          >
            {isSaving && !isAnalyzing ? <Loader2 size={18} className="animate-spin"/> : <Save size={18}/>}
            Сохранить
          </button>
        </div>
      </header>

      <div className="flex-1 flex overflow-hidden">
        <div className="flex-1 flex flex-col overflow-y-auto custom-scrollbar">
          <div className="p-16 flex-1 flex flex-col min-h-full">
            <textarea 
              className="w-full flex-1 bg-transparent border-none focus:outline-none text-2xl leading-relaxed text-black dark:text-white resize-none font-semibold placeholder:text-gray-200"
              value={content}
              onChange={e => setContent(e.target.value)}
              placeholder="Начните печатать..."
            />

            {similarNotes.length > 0 && (
                <div className="mt-20 pt-10 border-t border-gray-100 dark:border-white/5">
                    <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-6 flex items-center gap-2">
                        <LinkIcon size={14} className="text-blue-500" /> Связанные смыслы
                    </h4>
                    <div className="grid grid-cols-2 gap-4">
                        {similarNotes.map(sn => (
                            <div key={sn.id} onClick={() => navigate(`/editor/${sn.id}`)} className="p-6 bg-gray-50 dark:bg-slate-900/50 rounded-2xl border border-gray-100 dark:border-white/5 hover:border-blue-500 cursor-pointer transition-all group">
                                <h5 className="font-extrabold text-sm dark:text-white group-hover:text-blue-500 truncate mb-1">{sn.title}</h5>
                                <p className="text-[10px] text-gray-400 line-clamp-2">{sn.summary || sn.content}</p>
                            </div>
                        ))}
                    </div>
                </div>
            )}
          </div>
        </div>

        <div className="w-[420px] border-l border-gray-100 dark:border-white/5 flex flex-col bg-gray-50/50 dark:bg-slate-950/20 p-8 gap-6 overflow-y-auto custom-scrollbar">
          <div className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] border border-gray-100 dark:border-white/5 shadow-md">
             <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2 mb-4">
               <Folder size={14} className="text-blue-500"/> Группа
             </h4>
             <select 
               className="w-full p-4 bg-gray-50 dark:bg-slate-950 rounded-xl font-black text-sm border-none dark:text-white cursor-pointer"
               value={category}
               onChange={e => setCategory(e.target.value)}
             >
                {settings.customCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
             </select>
          </div>

          <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] border border-gray-100 dark:border-white/5 flex flex-col h-[400px] shadow-lg overflow-hidden shrink-0">
            <header className="p-4 border-b border-gray-50 dark:border-white/5 text-[10px] font-black uppercase tracking-widest text-blue-500 flex items-center gap-2">
              <MessageSquare size={14}/> Разум Заметки
            </header>
            <div className="flex-1 p-4 overflow-y-auto space-y-3 custom-scrollbar" ref={chatScrollRef}>
              {chatMessages.map((msg, i) => (
                <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[90%] p-4 rounded-2xl text-xs font-bold ${msg.role === 'user' ? 'bg-blue-600 text-white' : 'bg-gray-100 dark:bg-slate-800 dark:text-slate-300'}`}>
                    {msg.text}
                  </div>
                </div>
              ))}
              {isChatLoading && <div className="text-blue-500 animate-pulse text-[10px] font-black p-2">ИИ думает...</div>}
            </div>
            <div className="p-4 border-t border-gray-50 dark:border-white/5 relative">
              <input 
                className="w-full pl-4 pr-12 py-4 bg-gray-50 dark:bg-slate-950 rounded-xl text-xs font-bold border-none dark:text-white"
                placeholder="Спросить..."
                value={chatInput}
                onChange={e => setChatInput(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleChat()}
              />
              <button onClick={handleChat} className="absolute right-6 top-1/2 -translate-y-1/2 text-blue-600"><Send size={18}/></button>
            </div>
          </div>

          <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-gray-100 dark:border-white/5 space-y-6">
            <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
              <Hash size={14} className="text-blue-500"/> Теги
            </h4>
            <div className="flex flex-wrap gap-2 mb-4">
              {tags.map(t => {
                const colors = getTagColor(t);
                return (
                  <span 
                    key={t} 
                    style={{ color: colors.text, backgroundColor: colors.bg, borderColor: colors.border }} 
                    className="px-3 py-1.5 rounded-lg text-[9px] font-black uppercase flex items-center gap-2 border"
                  >
                    #{t} 
                    <button 
                      onClick={() => setTags(tags.filter(x => x !== t))} 
                      className="hover:text-red-500 transition-colors ml-1"
                    >
                      <X size={10}/>
                    </button>
                  </span>
                );
              })}
            </div>
            <div className="flex gap-2">
              <input 
                type="text"
                placeholder="Новый тег..."
                className="flex-1 p-3 bg-gray-50 dark:bg-slate-950 rounded-xl text-[10px] font-black uppercase border-none dark:text-white"
                value={newTag}
                onChange={e => setNewTag(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleAddTag()}
              />
              <button 
                onClick={handleAddTag}
                className="p-3 bg-blue-600 text-white rounded-xl hover:bg-blue-700 transition-all"
              >
                <Plus size={14} />
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default NoteEditor;

import React, { useState, useMemo } from 'react';
import { useNotes } from '../contexts/NotesContext.tsx';
import { NoteStatus, Note } from '../types.ts';
import { getTagColor } from '../utils/tagColors.ts';
import { 
  Search, Trash2, Sparkles, Circle, PlayCircle, Eye, CheckCircle2, 
  FileText, Globe, Folder, Plus, LayoutGrid, List, ScanLine, Lightbulb, Target, Send, Mic, Split, Upload, X, Loader2
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import * as ai from '../utils/aiAdapter.ts';

const StatusIcon = ({ status, className }: { status: NoteStatus, className?: string }) => {
  switch (status) {
    case 'new': return <Circle className={`${className} text-amber-500 fill-amber-500 shadow-[0_0_12px_rgba(245,158,11,0.6)]`} size={10} />;
    case 'in-work': return <PlayCircle className={`${className} text-blue-500 shadow-[0_0_12px_rgba(59,130,246,0.6)]`} size={16} />;
    case 'read': return <Eye className={`${className} text-slate-400`} size={16} />;
    case 'finished': return <CheckCircle2 className={`${className} text-green-500 shadow-[0_0_12px_rgba(34,197,94,0.6)]`} size={16} />;
    default: return null;
  }
};

const SourceBadge = ({ type }: { type?: Note['sourceType'] }) => {
    switch (type) {
        case 'ocr': return <ScanLine size={12} className="text-cyan-500" />;
        case 'split': return <Split size={12} className="text-purple-500" />;
        case 'telegram': return <Send size={12} className="text-blue-400" />;
        case 'audio': return <Mic size={12} className="text-red-400" />;
        default: return <FileText size={12} className="text-gray-400" />;
    }
}

const NotesPage: React.FC = () => {
  const { notes, moveToTrash, filterTag, filterCategory, setFilterCategory, setNoteStatus, settings, addCategory, deleteCategory, processLargeText } = useNotes();
  const navigate = useNavigate();
  const [search, setSearch] = useState('');
  const [showAddGroup, setShowAddGroup] = useState(false);
  const [showImport, setShowImport] = useState(false);
  const [importText, setImportText] = useState('');
  const [newGroupName, setNewGroupName] = useState('');
  const [filterStatus, setFilterStatus] = useState<NoteStatus | 'all'>('all');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const [isProcessing, setIsProcessing] = useState(false);

  const filteredNotes = useMemo(() => notes.filter(n => {
    const query = search.toLowerCase();
    const matchesSearch = n.title.toLowerCase().includes(query) || n.content.toLowerCase().includes(query);
    const matchesTag = !filterTag || n.tags.includes(filterTag);
    const matchesCategory = !filterCategory || n.category === filterCategory;
    const matchesStatus = filterStatus === 'all' || n.status === filterStatus;
    return matchesSearch && matchesTag && matchesCategory && matchesStatus && n.status !== 'trash';
  }), [notes, search, filterTag, filterCategory, filterStatus]);

  const handleCreateGroup = async () => {
    if (!newGroupName.trim()) return;
    await addCategory(newGroupName);
    setNewGroupName('');
    setShowAddGroup(false);
  };

  const handleImportText = async () => {
    if (!importText.trim()) return;
    setIsProcessing(true);
    await processLargeText(importText);
    setIsProcessing(false);
    setImportText('');
    setShowImport(false);
  };

  const cycleStatus = (e: React.MouseEvent, note: Note) => {
    e.stopPropagation();
    const statuses: NoteStatus[] = ['new', 'in-work', 'read', 'finished'];
    const currentIndex = statuses.indexOf(note.status);
    const nextIndex = (currentIndex + 1) % statuses.length;
    setNoteStatus(note.id, statuses[nextIndex]);
  };

  const statusFilters: {id: NoteStatus | 'all', label: string, color: string}[] = [
    { id: 'all', label: 'Все', color: 'bg-slate-500' },
    { id: 'new', label: 'Новые', color: 'bg-amber-500' },
    { id: 'in-work', label: 'В работе', color: 'bg-blue-500' },
    { id: 'read', label: 'Чтение', color: 'bg-slate-400' },
    { id: 'finished', label: 'Готово', color: 'bg-green-500' }
  ];

  return (
    <div className="p-12 max-w-7xl mx-auto min-h-screen relative pb-32 animate-in fade-in duration-700">
      <header className="flex flex-col gap-8 mb-12">
        <div className="flex flex-col md:flex-row items-end justify-between gap-8">
          <div>
            <h2 className="text-6xl font-extrabold text-gray-900 dark:text-white tracking-tighter leading-none select-none">
              Библиотека<span className="text-blue-600 dark:text-cyan-500">.</span>
            </h2>
          </div>

          <div className="flex gap-4 w-full md:w-auto">
            <div className="relative group flex-1 md:w-[400px]">
              <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-gray-400 group-focus-within:text-cyan-400 transition-colors" size={20}/>
              <input
                type="text"
                placeholder="Поиск по нейронной базе..."
                className="w-full pl-16 pr-8 py-6 bg-white dark:bg-slate-900 border border-gray-100 dark:border-white/10 rounded-[2.5rem] focus:outline-none focus:ring-4 focus:ring-cyan-500/10 font-bold text-sm shadow-xl transition-all dark:text-white"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
            </div>
            <div className="flex bg-gray-100 dark:bg-slate-800 p-2 rounded-[2.5rem]">
               <button onClick={() => setViewMode('grid')} className={`p-4 rounded-full transition-all ${viewMode === 'grid' ? 'bg-white dark:bg-slate-700 shadow-md text-blue-600' : 'text-gray-400'}`}><LayoutGrid size={24}/></button>
               <button onClick={() => setViewMode('list')} className={`p-4 rounded-full transition-all ${viewMode === 'list' ? 'bg-white dark:bg-slate-700 shadow-md text-blue-600' : 'text-gray-400'}`}><List size={24}/></button>
            </div>
          </div>
        </div>

        <div className="space-y-4">
          <div className="flex items-center justify-between px-2">
             <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
               <Folder size={12}/> Группы Знаний
             </h4>
             <div className="flex gap-4">
                <button onClick={() => setShowImport(true)} className="text-[10px] font-black text-purple-500 uppercase tracking-widest flex items-center gap-2 hover:opacity-70 transition-opacity">
                    <Split size={12}/> Разбор текста
