              }`}
            >
              <div className={`w-2 h-2 rounded-full ${sf.color}`} />
              {sf.label}
            </button>
          ))}
        </div>
      </header>

      {viewMode === 'grid' ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10">
          {filteredNotes.map((note) => {
            const isIdea = note.category === 'Идеи';
            const isGoal = note.links && note.links.length > 0;
            return (
              <div 
                key={note.id}
                onClick={() => navigate(`/editor/${note.id}`)}
                className="group bg-white dark:bg-slate-900/40 p-10 rounded-[3.5rem] border transition-all cursor-pointer relative h-[32rem] flex flex-col shadow-lg hover:shadow-2xl hover:-translate-y-4 border-gray-100 dark:border-white/10 overflow-hidden"
              >
                <div className="flex items-center justify-between mb-8">
                  <div className="flex items-center gap-3">
                    <button onClick={(e) => cycleStatus(e, note)} className="p-2.5 bg-gray-50 dark:bg-white/5 rounded-2xl">
                        <StatusIcon status={note.status} />
                    </button>
                    <div className="p-2 bg-gray-50 dark:bg-white/5 rounded-xl flex items-center justify-center">
                        <SourceBadge type={note.sourceType} />
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    {isIdea && <Lightbulb size={16} className="text-amber-500" />}
                    {isGoal && <Target size={16} className="text-blue-500" />}
                    <button 
