                    >
                        <Globe size={18}/>
                    </button>
                  </div>
                </div>

                <h3 className="font-bold text-2xl text-gray-900 dark:text-white mb-6 line-clamp-2 leading-[1.05] tracking-tighter">
                  {note.title}
                </h3>

                <div className="text-sm text-gray-500 dark:text-slate-400 leading-relaxed line-clamp-5 font-medium mb-10 overflow-hidden">
                  {note.summary && <div className="p-4 mb-4 bg-blue-500/5 rounded-2xl border-l-4 border-blue-500 italic text-blue-700 dark:text-blue-300 text-xs leading-relaxed">"{note.summary}"</div>}
                  {note.content}
