              <button onClick={(e) => cycleStatus(e, note)} className="shrink-0"><StatusIcon status={note.status}/></button>
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-3">
                   <h3 className="text-xl font-bold dark:text-white truncate">{note.title}</h3>
