export const getTagColor = (tag: string) => {
  let hash = 0;
  for (let i = 0; i < tag.length; i++) {
    hash = tag.charCodeAt(i) + ((hash << 5) - hash);
  }

  const h = Math.abs(hash % 360);
  // Используем высокую насыщенность для фона (с большой прозрачностью)
  // И очень низкую яркость для текста, чтобы он был почти черным/читаемым
  return {
    bg: `hsla(${h}, 75%, 92%, 1)`, // Очень светлый пастельный фон
    text: `hsla(${h}, 85%, 15%, 1)`, // Глубокий темный цвет того же оттенка (почти черный)
    border: `hsla(${h}, 70%, 80%, 1)` // Четкая граница
  };
};

