          <MessageCircle size={100} />
          <p className="text-2xl font-extrabold uppercase tracking-widest italic">Ваш почтовый ящик пуст</p>
          <p className="text-sm font-medium">Бот ждет ваших первых сообщений...</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 gap-10">
          {telegramMessages.map((msg) => (
            <div key={msg.id} className="group bg-white dark:bg-slate-900 p-10 rounded-[3.5rem] border border-gray-100 dark:border-slate-800 shadow-sm flex flex-col gap-8 hover:shadow-2xl hover:border-blue-200 transition-all relative">
              <button 
                onClick={() => deleteTelegramMsg(msg.id)}
