                    className="flex items-center gap-3 px-6 py-4 bg-blue-50 text-blue-600 dark:bg-blue-900/20 dark:text-blue-400 rounded-2xl hover:bg-blue-100 transition-all text-[10px] font-black uppercase tracking-widest disabled:opacity-50"
