            <div className="flex gap-4 mt-8">
               <button onClick={() => setShowAddGroup(false)} className="flex-1 py-5 bg-gray-100 rounded-2xl font-black uppercase text-[10px] tracking-widest">Отмена</button>
               <button onClick={handleCreateGroup} className="flex-1 py-5 bg-blue-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-xl shadow-blue-500/20">Создать</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

