export const getTagColor = (tag: string) => {
  let hash = 0;
  for (let i = 0; i < tag.length; i++) {
    hash = tag.charCodeAt(i) + ((hash << 5) - hash);
  }

  const h = Math.abs(hash % 360);
  // Используем более яркие и чистые цвета для границ и текста
  return {
    bg: `hsla(${h}, 80%, 96%, 1)`, // Очень светлый фон
    text: `hsla(${h}, 70%, 35%, 1)`, // Насыщенный цвет для текста (читаемый)
    border: `hsla(${h}, 60%, 50%, 1)` // Яркий цвет для обводки
  };
};

