const extractJSON = (str: string) => {
  if (!str) return {};
  const trimmed = str.trim();
  try {
    return JSON.parse(trimmed);
  } catch (e) {
    const jsonRegex = /\{[\s\S]*\}/;
    const match = trimmed.match(jsonRegex);
    if (match) {
      try {
        const cleaned = match[0].replace(/```json/g, '').replace(/```/g, '').trim();
        return JSON.parse(cleaned);
      } catch (inner) {}
    }
    return {};
  }
};

export const linkify = (text: string) => {
  const urlRegex = /(https?:\/\/[^\s]+)/g;
  return text.split(urlRegex).map((part) => {
    if (part.match(urlRegex)) {
      return `<a href="${part}" target="_blank" rel="noopener noreferrer" class="text-blue-500 underline">${part}</a>`;
    }
    return part;
  }).join('');
};

export const openInGoogle = (query: string) => {
  if (!query) return;
  window.open(`https://www.google.com/search?q=${encodeURIComponent(query)}`, '_blank');
};

async function callAI(
  prompt: string, 
  provider: AIProvider, 
  model: string, 
  apiKey: string, 
  baseUrl: string, 
  isJson: boolean, 
  systemInstruction?: string,
  mediaPart?: { data: string, mimeType: string }
) {
  if (provider === AIProvider.Gemini) {
    const executeWithRetry = async (retries = 2, delay = 2000) => {
      for (let attempt = 0; attempt < retries; attempt++) {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
        try {
          const parts: any[] = [{ text: prompt }];
          if (mediaPart) {
            parts.unshift({ inlineData: mediaPart });
          }

          const response = await ai.models.generateContent({
            model: model || 'gemini-3-flash-preview',
            contents: { parts },
            config: {
              systemInstruction,
              responseMimeType: isJson ? "application/json" : undefined
            }
          });
          return isJson ? extractJSON(response.text || '{}') : response.text;
        } catch (err: any) {
          const errMsg = err.message || JSON.stringify(err);
          const isQuotaError = errMsg.includes('429') || errMsg.includes('RESOURCE_EXHAUSTED');

          if (isQuotaError && attempt < retries - 1) {
            await new Promise(resolve => setTimeout(resolve, delay));
            delay *= 2;
            continue;
          }
          throw new Error(`Gemini: ${errMsg}`);
        }
      }
    };
    return await executeWithRetry();
  }

  // Другие провайдеры (Ollama, LM Studio и т.д.)
  let url = (baseUrl || '').trim().replace(/\/$/, '');
  if (provider === AIProvider.Ollama) {
    url = url || 'http://localhost:11434';
    url += '/api/chat';
  } else {
    url = url || (provider === AIProvider.OpenRouter ? 'https://openrouter.ai/api/v1' : 'http://localhost:1234/v1');
    if (!url.endsWith('/chat/completions')) url += '/chat/completions';
  }

  const messages = [
    ...(systemInstruction ? [{ role: 'system', content: systemInstruction }] : []),
    { role: 'user', content: prompt }
  ];

  const body = { 
    model, 
    messages, 
    stream: false, 
    ...(provider === AIProvider.Ollama && isJson ? { format: 'json' } : {}) 
  };
  const headers: any = { 'Content-Type': 'application/json' };
  if (apiKey) headers['Authorization'] = `Bearer ${apiKey}`;

  const res = await fetch(url, { method: 'POST', headers, body: JSON.stringify(body) });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  const data = await res.json();
  const content = provider === AIProvider.Ollama ? data.message.content : data.choices[0].message.content;
  return isJson ? extractJSON(content) : content;
}

export const analyzeText = async (text: string, settings: Settings) => {
  const prompt = `ВЕРНИ JSON: { "title": "...", "tags": ["..."], "category": "...", "summary": "..." }. ТЕКСТ: ${text}`;
  return await callAI(prompt, settings.provider, settings.model, settings.apiKey, settings.url, true, "Ты — аналитик.");
};

export const transcribeAudio = async (blob: Blob, settings: Settings) => {
  const reader = new FileReader();
  const base64: string = await new Promise((resolve) => {
    reader.onload = () => resolve((reader.result as string).split(',')[1]);
    reader.readAsDataURL(blob);
  });

  return await callAI(
    "Распознай речь и верни только текст. Если речи нет, напиши [Тишина].",
    settings.transProvider,
    settings.transModel || 'gemini-2.5-flash-native-audio-preview-12-2025',
    settings.transApiKey,
    settings.transUrl,
    false,
    "Ты — эксперт по транскрибации.",
    { data: base64, mimeType: blob.type }
  );
};

