import React, { useState, useRef } from 'react';
import { Mic, Square, Loader2, Save, X, RotateCcw, Volume2, Sparkles, AlertCircle, Cpu } from 'lucide-react';
import { useNotes } from '../contexts/NotesContext.tsx';
import * as ai from '../utils/aiAdapter.ts';

const AudioRecorder: React.FC<{ onComplete?: () => void }> = ({ onComplete }) => {
  const { addNote, addLog, settings, updateSettings } = useNotes();
  const [isRecording, setIsRecording] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [audioBlob, setAudioBlob] = useState<Blob | null>(null);
  const [transcript, setTranscript] = useState('');
  const [error, setError] = useState<string | null>(null);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationRef = useRef<number | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  const startRecording = async () => {
    try {
      setError(null);
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      const chunks: BlobPart[] = [];
      mediaRecorder.ondataavailable = (e) => chunks.push(e.data);
      mediaRecorder.onstop = () => setAudioBlob(new Blob(chunks, { type: 'audio/webm' }));
      mediaRecorder.start();
      setIsRecording(true);
      addLog('info', 'Голосовой интерфейс активирован');
      visualize(stream);
    } catch (err: any) {
      setError("Ошибка микрофона: " + err.message);
    }
  };

  const stopRecording = () => {
    mediaRecorderRef.current?.stop();
    streamRef.current?.getTracks().forEach(t => t.stop());
    setIsRecording(false);
    if (animationRef.current) cancelAnimationFrame(animationRef.current);
    if (audioContextRef.current) audioContextRef.current.close();
  };

  const visualize = (stream: MediaStream) => {
    const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
    audioContextRef.current = audioCtx;
    const source = audioCtx.createMediaStreamSource(stream);
    const analyser = audioCtx.createAnalyser();
    analyser.fftSize = 128;
    source.connect(analyser);
    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const draw = () => {
      animationRef.current = requestAnimationFrame(draw);
      analyser.getByteFrequencyData(dataArray);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      const barWidth = (canvas.width / bufferLength) * 1.5;
      let x = 0;
      for (let i = 0; i < bufferLength; i++) {
        const barHeight = (dataArray[i] / 255) * canvas.height * 0.8;
        ctx.fillStyle = '#3b82f6';
        const y = (canvas.height - barHeight) / 2;
        ctx.beginPath(); ctx.roundRect(x, y, barWidth - 4, barHeight, 10); ctx.fill();
        x += barWidth + 2;
      }
    };
    draw();
  };

  const handleTranscribe = async () => {
    if (!audioBlob) return;
    setIsProcessing(true);
    addLog('info', 'Декодирование голоса...');
    try {
      const result = await ai.transcribeAudio(audioBlob, settings);
      setTranscript(result);
    } catch (e: any) {
      setError("Ошибка: " + e.message);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleSave = async () => {
    if (!audioBlob) return;
    const reader = new FileReader();
    const base64: string = await new Promise((resolve) => {
      reader.onload = () => resolve(reader.result as string);
      reader.readAsDataURL(audioBlob);
    });
    const finalContent = transcript || "[Голосовая заметка]";
    await addNote(finalContent, `Аудио: ${new Date().toLocaleTimeString()}`, 'audio', true, undefined, base64);
    onComplete?.();
  };

  return (
    <div className="bg-white dark:bg-slate-900 p-10 rounded-[3.5rem] border border-gray-100 dark:border-white/10 shadow-2xl space-y-8 backdrop-blur-xl animate-in zoom-in duration-300">
      <div className="flex items-center justify-between">
        <h3 className="text-xl font-black dark:text-white uppercase tracking-[0.2em] flex items-center gap-3">
            <Volume2 size={20} className="text-blue-500" /> Vocal Interface
        </h3>
        <div className="flex gap-4">
            <select 
              value={settings.transModel}
              onChange={e => updateSettings({...settings, transModel: e.target.value})}
              className="bg-gray-100 dark:bg-slate-800 rounded-xl px-3 py-1 text-[10px] font-black uppercase border-none dark:text-white"
            >
              <option value="gemini-2.5-flash-native-audio-preview-12-2025">Gemini Audio</option>
              <option value="whisper-large-v3">Local Whisper</option>
            </select>
            <button onClick={() => { setAudioBlob(null); setTranscript(''); setError(null); }} className="p-2 text-gray-400 hover:text-red-500"><RotateCcw size={20}/></button>
        </div>
      </div>

      <div className="h-48 bg-gray-50 dark:bg-slate-950 rounded-[2.5rem] flex items-center justify-center overflow-hidden border-2 border-dashed border-gray-100 dark:border-white/5 relative">
        {isRecording ? (
          <canvas ref={canvasRef} width={600} height={180} className="w-full h-full p-6" />
        ) : audioBlob ? (
          <div className="flex flex-col items-center gap-4">
            <div className="w-5 h-5 bg-green-500 rounded-full animate-ping" />
            <p className="text-green-500 font-black text-[10px] uppercase tracking-widest text-center">Голос зафиксирован</p>
          </div>
        ) : error ? (
           <div className="flex flex-col items-center gap-3 text-red-500 text-center px-8">
             <AlertCircle size={32}/>
             <p className="text-[10px] font-black uppercase tracking-widest">{error}</p>
           </div>
        ) : (
          <div className="flex flex-col items-center gap-4 opacity-30">
            <Mic size={48} />
            <p className="text-gray-400 font-black text-[10px] uppercase tracking-[0.3em]">Готов к приему...</p>
          </div>
        )}
      </div>

      <div className="flex justify-center gap-6">
        {!isRecording && !audioBlob && (
          <button onClick={startRecording} className="p-10 bg-blue-600 text-white rounded-full shadow-2xl hover:scale-110 transition-all active:scale-90">
            <Mic size={40} />
          </button>
        )}
        {isRecording && (
          <button onClick={stopRecording} className="p-10 bg-red-500 text-white rounded-full shadow-2xl animate-pulse">
            <Square size={40} />
          </button>
        )}
        {audioBlob && !transcript && (
          <button 
            onClick={handleTranscribe} 
            disabled={isProcessing} 
            className="w-full bg-blue-600 text-white py-6 rounded-[2rem] font-black uppercase text-xs tracking-widest flex items-center justify-center gap-4 shadow-xl disabled:opacity-30"
          >
            {isProcessing ? <Loader2 className="animate-spin" /> : <Sparkles size={20}/>}
            {isProcessing ? 'Транскрибация...' : 'Распознать текст'}
          </button>
        )}
      </div>

      {(transcript || audioBlob) && !isRecording && (
        <div className="space-y-6 animate-in slide-in-from-bottom">
            {transcript && (
                <textarea 
                    value={transcript}
                    onChange={e => setTranscript(e.target.value)}
                    className="w-full h-40 bg-gray-50 dark:bg-slate-950 border-none rounded-[2rem] p-6 text-sm font-medium focus:ring-4 focus:ring-blue-500/10 shadow-inner dark:text-slate-300"
                />
            )}
            <button onClick={handleSave} className="w-full bg-green-600 text-white py-6 rounded-[2rem] font-black uppercase text-xs tracking-widest flex items-center justify-center gap-4 shadow-xl active:scale-95 transition-all">
                <Save size={20}/> Сохранить как заметку
            </button>
        </div>
      )}
    </div>
  );
};

