              />
              <div className="flex items-center gap-4 mt-2 px-1">
                {note?.isIndexed ? (
                    <span className="text-[10px] font-black text-green-600 bg-green-500/10 px-3 py-1 rounded-lg uppercase tracking-widest flex items-center gap-2 border border-green-500/20">
                        <CheckCircle2 size={12}/> ИИ активен
                    </span>
                ) : (
                    <span className="text-[10px] font-black text-amber-600 bg-amber-500/10 px-3 py-1 rounded-lg uppercase tracking-widest flex items-center gap-2 border border-amber-500/20">
                        <AlertCircle size={12}/> Ожидает анализа
                    </span>
                )}
                {note?.audioData && (
                    <button onClick={playAudio} className="flex items-center gap-2 px-3 py-1 bg-red-500/10 text-red-600 rounded-lg text-[10px] font-black uppercase tracking-widest border border-red-500/20">
                        <Play size={10} fill="currentColor"/> Прослушать
                    </button>
                )}
              </div>
          </div>
        </div>
        <div className="flex items-center gap-4">
          <button 
            onClick={() => ai.openInGoogle(title || content.slice(0, 50))}
            className="p-4 text-gray-400 hover:text-blue-500 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-2xl transition-all"
          >
            <Globe size={20} />
          </button>
          <button 
            onClick={() => handleSave(true)} 
            className="px-8 py-4 bg-cyan-600/10 text-cyan-600 dark:text-cyan-400 rounded-2xl font-black uppercase text-[10px] tracking-widest hover:bg-cyan-600/20 transition-all flex items-center gap-3"
          >
            {isAnalyzing ? <Loader2 size={18} className="animate-spin"/> : <Sparkles size={18}/>}
            Индексация
          </button>
          <button 
            onClick={() => handleSave(false)} 
            className="px-8 py-4 bg-blue-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest hover:shadow-xl active:scale-95 transition-all flex items-center gap-3"
          >
            {isSaving && !isAnalyzing ? <Loader2 size={18} className="animate-spin"/> : <Save size={18}/>}
            Сохранить
          </button>
        </div>
      </header>

      <div className="flex-1 flex overflow-hidden">
        <div className="flex-1 flex flex-col overflow-y-auto custom-scrollbar bg-gray-50/20">
          <div className="max-w-5xl mx-auto w-full p-20 flex-1 flex flex-col min-h-full">
            <textarea 
              className="w-full flex-1 bg-transparent border-none focus:outline-none text-2xl leading-relaxed text-gray-800 dark:text-slate-200 resize-none font-medium placeholder:text-gray-200"
              value={content}
              onChange={e => setContent(e.target.value)}
              placeholder="О чем вы думаете сегодня?.."
            />

            {similarNotes.length > 0 && (
                <div className="mt-20 pt-12 border-t border-gray-100 dark:border-white/5">
                    <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-8 flex items-center gap-3">
                        <LinkIcon size={14} className="text-blue-500" /> Связанные смыслы
                    </h4>
                    <div className="grid grid-cols-2 gap-6">
                        {similarNotes.map(sn => {
                            const sc = getTagColor(sn.category);
                            return (
                                <div key={sn.id} onClick={() => navigate(`/editor/${sn.id}`)} style={{ borderLeftColor: sc.text }} className="p-8 bg-white dark:bg-slate-900 border-l-8 border border-gray-100 dark:border-white/5 rounded-[2rem] hover:shadow-lg cursor-pointer transition-all group">
                                    <h5 className="font-extrabold text-lg dark:text-white group-hover:text-blue-500 truncate mb-2 leading-tight">{sn.title}</h5>
                                    <p className="text-[11px] text-gray-400 line-clamp-2 leading-relaxed font-medium">{sn.summary || sn.content}</p>
                                </div>
                            );
                        })}
                    </div>
                </div>
            )}
          </div>
        </div>

        <div className="w-[440px] border-l border-gray-100 dark:border-white/5 flex flex-col bg-gray-50/50 dark:bg-slate-950/20 p-8 gap-8 overflow-y-auto custom-scrollbar">
          <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-gray-100 dark:border-white/5 shadow-md">
             <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-3 mb-6">
               <Folder size={14} className="text-blue-500"/> Категория
             </h4>
             <select 
               className="w-full p-5 bg-gray-50 dark:bg-slate-950 rounded-2xl font-black text-xs border-none dark:text-white cursor-pointer hover:bg-gray-100 transition-colors"
               value={category}
               onChange={e => setCategory(e.target.value)}
             >
                {settings.customCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
             </select>
          </div>

          <div className="bg-white dark:bg-slate-900 rounded-[3rem] border border-gray-100 dark:border-white/5 flex flex-col h-[480px] shadow-xl overflow-hidden shrink-0">
            <header className="p-6 border-b border-gray-50 dark:border-white/5 text-[10px] font-black uppercase tracking-[0.2em] text-blue-500 flex items-center gap-3">
              <MessageSquare size={16}/> Разум Заметки
