            </h4>
            <div className="flex flex-wrap gap-2.5 mb-4">
              {tags.map(t => {
                const colors = getTagColor(t);
                return (
                  <span 
                    key={t} 
                    onClick={() => handleTagAction(t)}
                    style={{ color: colors.text, backgroundColor: colors.bg, borderColor: colors.border }} 
                    className="px-4 py-2 rounded-xl text-[10px] font-black uppercase flex items-center gap-3 border cursor-pointer hover:shadow-md transition-all active:scale-95"
