                    >
                      <X size={12}/>
                    </button>
                  </span>
                );
              })}
            </div>
            <div className="flex gap-3">
              <input 
                type="text"
                placeholder="Новый тег..."
                className="flex-1 p-4 bg-gray-50 dark:bg-slate-950 rounded-2xl text-[11px] font-black uppercase border-none dark:text-white shadow-inner"
                value={newTag}
                onChange={e => setNewTag(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleAddTag()}
              />
              <button onClick={handleAddTag} className="p-4 bg-blue-600 text-white rounded-2xl shadow-lg active:scale-95"><Plus size={18} /></button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

