const AudioRecorder: React.FC<{ onComplete?: () => void }> = ({ onComplete }) => {
  const { addNote, addLog, settings, updateSettings } = useNotes();
  const [isRecording, setIsRecording] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [audioBlob, setAudioBlob] = useState<Blob | null>(null);
  const [transcript, setTranscript] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const animationRef = useRef<number | null>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const startRecording = async () => {
    try {
      setError(null);
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      const chunks: BlobPart[] = [];
      mediaRecorder.ondataavailable = (e) => chunks.push(e.data);
      mediaRecorder.onstop = () => setAudioBlob(new Blob(chunks, { type: 'audio/webm' }));
      mediaRecorder.start();
      setIsRecording(true);
      visualize(stream);
    } catch (err: any) {
      setError("Микрофон недоступен: " + err.message);
    }
  };

  const stopRecording = () => {
    mediaRecorderRef.current?.stop();
    streamRef.current?.getTracks().forEach(t => t.stop());
    setIsRecording(false);
    if (animationRef.current) cancelAnimationFrame(animationRef.current);
  };

  const visualize = (stream: MediaStream) => {
    const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
    const source = audioCtx.createMediaStreamSource(stream);
    const analyser = audioCtx.createAnalyser();
    analyser.fftSize = 256;
    source.connect(analyser);

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const draw = () => {
      animationRef.current = requestAnimationFrame(draw);
      analyser.getByteFrequencyData(dataArray);
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      const barWidth = (canvas.width / bufferLength) * 2.5;
      let x = 0;
      for (let i = 0; i < bufferLength; i++) {
        const barHeight = (dataArray[i] / 255) * canvas.height;
        ctx.fillStyle = `hsla(${200 + i}, 70%, 50%, 0.8)`;
        ctx.fillRect(x, canvas.height - barHeight, barWidth - 1, barHeight);
        x += barWidth;
      }
    };
    draw();
  };

  const handleTranscribe = async () => {
    if (!audioBlob) return;
    setIsProcessing(true);
    try {
      const result = await ai.transcribeAudio(audioBlob, settings);
      setTranscript(result);
    } catch (e: any) {
      setError(e.message);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleSave = async () => {
    if (!audioBlob) return;
    const reader = new FileReader();
    const base64: string = await new Promise((resolve) => {
      reader.onload = () => resolve(reader.result as string);
      reader.readAsDataURL(audioBlob);
    });
    await addNote(transcript || "[Голосовая заметка]", `Аудио ${new Date().toLocaleTimeString()}`, 'audio', true, undefined, base64);
    onComplete?.();
  };

  return (
    <div className="bg-white dark:bg-slate-900 p-8 rounded-[3rem] border border-gray-100 dark:border-white/10 shadow-2xl space-y-6">
      <div className="flex items-center justify-between">
        <h3 className="font-black text-xs uppercase tracking-widest text-blue-500 flex items-center gap-2">
            <Volume2 size={16}/> Voice Interface
        </h3>
        <button onClick={() => { setAudioBlob(null); setTranscript(''); }} className="text-gray-400 hover:text-red-500"><RotateCcw size={18}/></button>
      </div>

      <div className="h-40 bg-gray-50 dark:bg-slate-950 rounded-[2rem] flex items-center justify-center overflow-hidden border-2 border-dashed border-gray-100 dark:border-white/5 relative">
        {isRecording ? (
          <canvas ref={canvasRef} width={400} height={150} className="w-full h-full opacity-80" />
        ) : audioBlob ? (
          <div className="flex flex-col items-center gap-4">
             <div className="flex gap-2">
                <button 
                  onClick={() => { if(isPlaying) audioRef.current?.pause(); else audioRef.current?.play(); setIsPlaying(!isPlaying); }}
                  className="p-4 bg-blue-600 text-white rounded-full shadow-lg"
                >
                  {isPlaying ? <Pause size={24}/> : <Play size={24}/>}
                </button>
             </div>
             <p className="text-[10px] font-black uppercase text-green-500">Запись готова</p>
             <audio ref={audioRef} src={URL.createObjectURL(audioBlob)} onEnded={() => setIsPlaying(false)} className="hidden" />
          </div>
        ) : error ? (
           <p className="text-red-500 text-[10px] font-bold px-8 text-center uppercase">{error}</p>
        ) : (
          <Mic size={48} className="text-gray-200 dark:text-slate-800 animate-pulse" />
        )}
      </div>

      <div className="flex gap-4">
        {!isRecording && !audioBlob && (
          <button onClick={startRecording} className="flex-1 py-5 bg-blue-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-xl shadow-blue-500/20">Начать запись</button>
        )}
        {isRecording && (
          <button onClick={stopRecording} className="flex-1 py-5 bg-red-500 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest animate-pulse">Остановить</button>
        )}
        {audioBlob && !transcript && (
          <button onClick={handleTranscribe} disabled={isProcessing} className="flex-1 py-5 bg-purple-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-xl flex items-center justify-center gap-2">
            {isProcessing ? <Loader2 size={14} className="animate-spin"/> : <Sparkles size={14}/>} Транскрибировать
          </button>
        )}
      </div>

      {transcript && (
        <div className="space-y-4 animate-in fade-in">
          <textarea 
            value={transcript}
            onChange={e => setTranscript(e.target.value)}
            className="w-full h-32 p-4 bg-gray-50 dark:bg-slate-950 rounded-2xl text-xs font-bold border-none resize-none dark:text-white"
          />
          <button onClick={handleSave} className="w-full py-5 bg-green-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest">Сохранить заметку</button>
        </div>
      )}
    </div>
  );
};

