import { get, set } from 'https://cdn.jsdelivr.net/npm/idb-keyval@6/+esm';
import { Note, Settings, AIProvider, Goal } from '../types.ts';

const NOTES_KEY = 'screenmind_notes';
const SETTINGS_KEY = 'screenmind_settings';
const GOALS_KEY = 'screenmind_goals';

export const saveNotes = async (notes: Note[]) => {
  await set(NOTES_KEY, notes);
};

export const getNotes = async (): Promise<Note[]> => {
  const notes = await get(NOTES_KEY);
  return notes || [];
};

export const saveGoals = async (goals: Goal[]) => {
  await set(GOALS_KEY, goals);
};

export const getGoals = async (): Promise<Goal[]> => {
  const goals = await get(GOALS_KEY);
  return goals || [];
};

export const saveSettings = async (settings: Settings) => {
  await set(SETTINGS_KEY, settings);
};

export const getDefaultSettings = (): Settings => ({
  provider: AIProvider.Ollama,
  url: 'http://localhost:11434',
  model: 'mistral',
  apiKey: '',
  theme: 'light',
  customCategories: ['Общее', 'Идеи', 'Работа', 'ИИ'],
  ocrProvider: AIProvider.Gemini,
  ocrModel: 'gemini-2.5-flash-image',
  ocrApiKey: '',
  ocrUrl: '',
  transProvider: AIProvider.Gemini,
  transModel: 'gemini-2.5-flash-native-audio-preview-12-2025',
  transApiKey: '',
  transUrl: '',
  agentProvider: AIProvider.Gemini,
  agentModel: 'gemini-3-pro-preview',
  agentApiKey: '',
  agentUrl: '',
  tgToken: '',
  tgChatId: '',
  tgLastUpdateId: 0
});

export const getSettings = async (): Promise<Settings> => {
  const settings = await get(SETTINGS_KEY);
  return settings || getDefaultSettings();
};

export const exportData = async () => {
  const notes = await getNotes();
  const settings = await getSettings();
  const goals = await getGoals();
  const data = JSON.stringify({ notes, settings, goals, version: '3.1.0', exportedAt: new Date().toISOString() }, null, 2);
  const blob = new Blob([data], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `screenmind_backup_${new Date().toISOString().slice(0,10)}.json`;
  a.click();
  URL.revokeObjectURL(url);
};

export const importData = async (file: File): Promise<boolean> => {
  try {
    const text = await file.text();
    const data = JSON.parse(text);
    if (data.notes) await saveNotes(data.notes);
    if (data.settings) await saveSettings(data.settings);
    if (data.goals) await saveGoals(data.goals);
    return true;
  } catch (e) {
    console.error("Import failed", e);
    return false;
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { Mic, Square, Loader2, Save, X, RotateCcw, Volume2, Sparkles, AlertCircle, Play, Pause, Headphones } from 'lucide-react';
import { useNotes } from '../contexts/NotesContext.tsx';
import * as ai from '../utils/aiAdapter.ts';

const AudioRecorder: React.FC<{ onComplete?: () => void }> = ({ onComplete }) => {
  const { addNote, addLog, settings } = useNotes();
  const [isRecording, setIsRecording] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [audioBlob, setAudioBlob] = useState<Blob | null>(null);
  const [transcript, setTranscript] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const animationRef = useRef<number | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);

  const startRecording = async () => {
    try {
      setError(null);
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;

      const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
      const analyser = audioContext.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;

      const source = audioContext.createMediaStreamSource(stream);
      source.connect(analyser);

      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      const chunks: BlobPart[] = [];

      mediaRecorder.ondataavailable = (e) => chunks.push(e.data);
      mediaRecorder.onstop = () => setAudioBlob(new Blob(chunks, { type: 'audio/webm' }));

      mediaRecorder.start();
      setIsRecording(true);
      addLog('info', 'Голосовой поток открыт');
      visualize();
    } catch (err: any) {
      setError("Ошибка: " + err.message);
      addLog('error', 'Микрофон заблокирован или отсутствует');
    }
  };

  const stopRecording = () => {
    mediaRecorderRef.current?.stop();
    streamRef.current?.getTracks().forEach(t => t.stop());
    setIsRecording(false);
    if (animationRef.current) cancelAnimationFrame(animationRef.current);
  };

  const visualize = () => {
    const canvas = canvasRef.current;
    if (!canvas || !analyserRef.current) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const bufferLength = analyserRef.current.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);

    const draw = () => {
      animationRef.current = requestAnimationFrame(draw);
      analyserRef.current!.getByteFrequencyData(dataArray);

      ctx.clearRect(0, 0, canvas.width, canvas.height);
      const barWidth = (canvas.width / bufferLength) * 2.5;
      let x = 0;

      for (let i = 0; i < bufferLength; i++) {
        const barHeight = (dataArray[i] / 255) * canvas.height;
        ctx.fillStyle = `hsla(${210 + i}, 80%, 50%, 0.8)`;
        ctx.fillRect(x, canvas.height - barHeight, barWidth - 1, barHeight);
        x += barWidth;
      }
    };
    draw();
  };

  const handleTranscribe = async () => {
    if (!audioBlob) return;
    setIsProcessing(true);
    addLog('info', 'ИИ анализирует аудио-спектр...');
    try {
      const result = await ai.transcribeAudio(audioBlob, settings);
      setTranscript(result);
      addLog('success', 'Речь успешно декодирована');
    } catch (e: any) {
      setError(e.message);
      addLog('error', 'Сбой транскрибации: ' + e.message);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleSave = async () => {
    if (!audioBlob) return;
    const reader = new FileReader();
    const base64: string = await new Promise((resolve) => {
      reader.onload = () => resolve(reader.result as string);
      reader.readAsDataURL(audioBlob);
    });

    // Сохраняем заметку с аудио, даже если нет текста
    const finalContent = transcript || "[Голосовая заметка ожидает транскрибации]";
    await addNote(finalContent, `Голос ${new Date().toLocaleTimeString()}`, 'audio', !!transcript, undefined, base64);
    onComplete?.();
  };

  return (
    <div className="bg-white dark:bg-slate-900 p-10 rounded-[3rem] border border-gray-100 dark:border-white/10 shadow-2xl space-y-8 animate-in zoom-in duration-300">
      <div className="flex items-center justify-between">
        <h3 className="font-black text-xs uppercase tracking-[0.3em] text-blue-600 flex items-center gap-3">
            <Volume2 size={18} /> Vocal Core
        </h3>
        <button onClick={() => { setAudioBlob(null); setTranscript(''); setError(null); }} className="text-gray-300 hover:text-red-500 transition-colors">
            <RotateCcw size={20}/>
        </button>
      </div>

      <div className="h-48 bg-gray-50 dark:bg-slate-950 rounded-[2.5rem] flex items-center justify-center overflow-hidden border-2 border-dashed border-gray-100 dark:border-white/5 relative">
        {isRecording ? (
          <canvas ref={canvasRef} width={400} height={150} className="w-full h-full opacity-70" />
        ) : audioBlob ? (
          <div className="flex flex-col items-center gap-6">
             <button 
                onClick={() => { if(isPlaying) audioRef.current?.pause(); else audioRef.current?.play(); setIsPlaying(!isPlaying); }}
                className="w-20 h-20 bg-blue-600 text-white rounded-full shadow-2xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all"
             >
                {isPlaying ? <Pause size={32}/> : <Play size={32} className="ml-1" />}
             </button>
             <p className="text-[10px] font-black uppercase tracking-widest text-green-500 flex items-center gap-2">
                 <Headphones size={12}/> Запись готова
             </p>
             <audio ref={audioRef} src={URL.createObjectURL(audioBlob)} onEnded={() => setIsPlaying(false)} className="hidden" />
          </div>
        ) : error ? (
           <div className="text-center px-8 text-red-500 space-y-2">
              <AlertCircle className="mx-auto" size={32} />
              <p className="text-[10px] font-black uppercase">{error}</p>
           </div>
        ) : (
          <div className="flex flex-col items-center gap-4 opacity-20">
             <Mic size={56} />
             <p className="text-[10px] font-black uppercase tracking-[0.4em]">Ожидание голоса...</p>
          </div>
        )}
      </div>

      <div className="flex gap-4">
        {!isRecording && !audioBlob && (
          <button onClick={startRecording} className="flex-1 py-6 bg-blue-600 text-white rounded-[1.8rem] font-black uppercase text-xs tracking-widest shadow-xl shadow-blue-500/20 active:scale-95 transition-all">
            Начать запись
          </button>
        )}
        {isRecording && (
          <button onClick={stopRecording} className="flex-1 py-6 bg-red-500 text-white rounded-[1.8rem] font-black uppercase text-xs tracking-widest animate-pulse">
            Завершить
          </button>
        )}
        {audioBlob && !transcript && (
          <button 
            onClick={handleTranscribe} 
            disabled={isProcessing} 
            className="flex-1 py-6 bg-purple-600 text-white rounded-[1.8rem] font-black uppercase text-xs tracking-widest shadow-xl flex items-center justify-center gap-3 disabled:opacity-50"
          >
            {isProcessing ? <Loader2 size={18} className="animate-spin"/> : <Sparkles size={18}/>}
            Транскрибировать
          </button>
        )}
      </div>

      {(transcript || (audioBlob && !isRecording)) && (
        <div className="space-y-4 animate-in fade-in">
          {transcript && (
            <textarea 
              value={transcript}
              onChange={e => setTranscript(e.target.value)}
              className="w-full h-32 p-5 bg-gray-50 dark:bg-slate-950 border-none rounded-[1.8rem] text-sm font-bold dark:text-white shadow-inner resize-none"
            />
          )}
          <button onClick={handleSave} className="w-full py-6 bg-green-600 text-white rounded-[1.8rem] font-black uppercase text-xs tracking-widest shadow-xl hover:bg-green-700 active:scale-95 transition-all">
            Сохранить в базу
          </button>
        </div>
      )}
    </div>
  );
};

