const StatusIcon = ({ status, className }: { status: NoteStatus, className?: string }) => {
  switch (status) {
    case 'new': return <Circle className={`${className} text-amber-500 fill-amber-500`} size={10} />;
    case 'in-work': return <PlayCircle className={`${className} text-blue-500`} size={16} />;
    case 'read': return <Eye className={`${className} text-slate-400`} size={16} />;
    case 'finished': return <CheckCircle2 className={`${className} text-green-500`} size={16} />;
    default: return null;
  }
};

const SourceBadge = ({ type, hasAudio }: { type?: Note['sourceType'], hasAudio?: boolean }) => {
    return (
      <div className="flex items-center gap-2">
        {hasAudio && <Headphones size={12} className="text-red-500" title="Есть аудиозапись" />}
        {(() => {
          switch (type) {
              case 'ocr': return <ScanLine size={12} className="text-cyan-500" title="OCR Скан" />;
              case 'split': return <Split size={12} className="text-purple-500" title="Разбор текста" />;
              case 'telegram': return <Send size={12} className="text-blue-400" title="Telegram" />;
              case 'audio': return <Mic size={12} className="text-red-400" title="Аудиозапись" />;
              default: return <FileText size={12} className="text-gray-400" title="Вручную" />;
          }
        })()}
      </div>
    )
}

