import React, { useState, useRef, useEffect } from 'react';
import { Mic, Square, Loader2, Save, X, RotateCcw, Volume2, Sparkles, AlertCircle, Play, Pause, Headphones } from 'lucide-react';
import { useNotes } from '../contexts/NotesContext.tsx';
import * as ai from '../utils/aiAdapter.ts';

const AudioRecorder: React.FC<{ onComplete?: () => void }> = ({ onComplete }) => {
  const { addNote, addLog, settings } = useNotes();
  const [isRecording, setIsRecording] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [audioBlob, setAudioBlob] = useState<Blob | null>(null);
  const [transcript, setTranscript] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const animationRef = useRef<number | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);

  const startRecording = async () => {
    try {
      setError(null);
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;

      const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
      const analyser = audioContext.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;

      const source = audioContext.createMediaStreamSource(stream);
      source.connect(analyser);

      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      const chunks: BlobPart[] = [];

      mediaRecorder.ondataavailable = (e) => chunks.push(e.data);
      mediaRecorder.onstop = () => setAudioBlob(new Blob(chunks, { type: 'audio/webm' }));

      mediaRecorder.start();
      setIsRecording(true);
      addLog('info', 'Микрофон активирован');
      visualize();
    } catch (err: any) {
      setError("Микрофон недоступен");
    }
  };

  const stopRecording = () => {
    mediaRecorderRef.current?.stop();
    streamRef.current?.getTracks().forEach(t => t.stop());
    setIsRecording(false);
    if (animationRef.current) cancelAnimationFrame(animationRef.current);
  };

  const visualize = () => {
    const canvas = canvasRef.current;
    if (!canvas || !analyserRef.current) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const bufferLength = analyserRef.current.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);

    const draw = () => {
      animationRef.current = requestAnimationFrame(draw);
      analyserRef.current!.getByteFrequencyData(dataArray);

      ctx.clearRect(0, 0, canvas.width, canvas.height);
      const barWidth = (canvas.width / bufferLength) * 2.5;
      let x = 0;

      for (let i = 0; i < bufferLength; i++) {
        const barHeight = (dataArray[i] / 255) * canvas.height;
        ctx.fillStyle = `hsla(${200 + i * 2}, 70%, 50%, 0.8)`;
        ctx.fillRect(x, canvas.height - barHeight, barWidth - 1, barHeight);
        x += barWidth;
      }
    };
    draw();
  };

  const handleTranscribe = async () => {
    if (!audioBlob) return;
    setIsProcessing(true);
    try {
      const result = await ai.transcribeAudio(audioBlob, settings);
      setTranscript(result);
      addLog('success', 'Транскрибация завершена');
    } catch (e: any) {
      setError(e.message);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleSave = async () => {
    if (!audioBlob) return;
    const reader = new FileReader();
    const base64: string = await new Promise((resolve) => {
      reader.onload = () => resolve(reader.result as string);
      reader.readAsDataURL(audioBlob);
    });

    const finalContent = transcript || "[Голосовая заметка]";
    await addNote(finalContent, `Аудио ${new Date().toLocaleTimeString()}`, 'audio', !!transcript, undefined, base64);
    onComplete?.();
  };

  return (
    <div className="bg-white dark:bg-slate-900 p-8 rounded-[3rem] border border-gray-100 dark:border-white/10 shadow-2xl space-y-6">
      <div className="flex items-center justify-between">
        <h3 className="font-black text-xs uppercase tracking-widest text-blue-500 flex items-center gap-2">
            <Volume2 size={16} /> Neural Voice
        </h3>
        <button onClick={() => { setAudioBlob(null); setTranscript(''); }} className="text-gray-400 hover:text-red-500 transition-colors">
            <RotateCcw size={18}/>
        </button>
      </div>

      <div className="h-40 bg-gray-50 dark:bg-slate-950 rounded-[2rem] flex items-center justify-center overflow-hidden border-2 border-dashed border-gray-100 dark:border-white/5 relative">
        {isRecording ? (
          <canvas ref={canvasRef} width={400} height={150} className="w-full h-full opacity-60" />
        ) : audioBlob ? (
          <div className="flex flex-col items-center gap-4">
             <button 
                onClick={() => { if(isPlaying) audioRef.current?.pause(); else audioRef.current?.play(); setIsPlaying(!isPlaying); }}
                className="w-16 h-16 bg-blue-600 text-white rounded-full flex items-center justify-center hover:scale-110 active:scale-95 transition-all"
             >
                {isPlaying ? <Pause size={24}/> : <Play size={24} className="ml-1" />}
             </button>
             <audio ref={audioRef} src={URL.createObjectURL(audioBlob)} onEnded={() => setIsPlaying(false)} className="hidden" />
          </div>
        ) : (
          <Mic size={48} className="text-gray-200 dark:text-slate-800 animate-pulse" />
        )}
      </div>

      <div className="flex gap-4">
        {!isRecording && !audioBlob && (
          <button onClick={startRecording} className="flex-1 py-5 bg-blue-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-xl shadow-blue-500/20 active:scale-95 transition-all">Начать запись</button>
        )}
        {isRecording && (
          <button onClick={stopRecording} className="flex-1 py-5 bg-red-500 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest animate-pulse">Стоп</button>
        )}
        {audioBlob && !transcript && (
          <button onClick={handleTranscribe} disabled={isProcessing} className="flex-1 py-5 bg-purple-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-xl flex items-center justify-center gap-2">
            {isProcessing ? <Loader2 size={14} className="animate-spin"/> : <Sparkles size={14}/>} Распознать
          </button>
        )}
      </div>

      {(transcript || (audioBlob && !isRecording)) && (
        <div className="space-y-4 animate-in fade-in">
          {transcript && (
            <textarea 
              value={transcript}
              onChange={e => setTranscript(e.target.value)}
              className="w-full h-32 p-4 bg-gray-50 dark:bg-slate-950 border-none rounded-2xl text-xs font-bold dark:text-white shadow-inner resize-none"
            />
          )}
          <button onClick={handleSave} className="w-full py-5 bg-green-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-xl active:scale-95 transition-all">Сохранить</button>
        </div>
      )}
    </div>
  );
};

