                placeholder="Поиск..."
                className="w-full pl-16 pr-8 py-6 bg-white dark:bg-slate-900 border border-gray-100 dark:border-white/10 rounded-[2.5rem] focus:ring-4 focus:ring-blue-500/10 font-bold text-sm shadow-xl transition-all dark:text-white"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
