             <div className="flex items-center gap-4">
                <button onClick={() => handleScroll('l')} className="p-2 text-gray-400 hover:text-blue-500"><ChevronLeft size={20}/></button>
                <button onClick={() => handleScroll('r')} className="p-2 text-gray-400 hover:text-blue-500"><ChevronRight size={20}/></button>
                <div className="w-px h-4 bg-gray-200 dark:bg-slate-800 mx-2" />
