import { GoogleGenAI, Type } from "@google/genai";

const extractJSON = (str: string) => {
  if (!str) return {};
  const trimmed = str.trim();
  try {
    return JSON.parse(trimmed);
  } catch (e) {
    const jsonRegex = /\{[\s\S]*\}/;
    const match = trimmed.match(jsonRegex);
    if (match) {
      try {
        const cleaned = match[0].replace(/```json/g, '').replace(/```/g, '').trim();
        return JSON.parse(cleaned);
      } catch (inner) {}
    }
    return {};
  }
};

export const linkify = (text: string) => {
  const urlRegex = /(https?:\/\/[^\s]+)/g;
  return text.split(urlRegex).map((part) => {
    if (part.match(urlRegex)) {
      return `<a href="${part}" target="_blank" rel="noopener noreferrer" class="text-blue-500 underline">${part}</a>`;
    }
    return part;
  }).join('');
};

export const openInGoogle = (query: string) => {
  if (!query) return;
  window.open(`https://www.google.com/search?q=${encodeURIComponent(query)}`, '_blank');
};

async function callAI(
  prompt: string, 
  provider: AIProvider, 
  model: string, 
  apiKey: string, 
  baseUrl: string, 
  isJson: boolean, 
  systemInstruction?: string,
  mediaPart?: { data: string, mimeType: string }
) {
  if (provider === AIProvider.Gemini) {
    const executeWithRetry = async (retries = 2, delay = 2000) => {
      for (let attempt = 0; attempt < retries; attempt++) {
        // Correct initialization of GoogleGenAI using a named parameter and direct process.env.API_KEY
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        try {
          const parts: any[] = [{ text: prompt }];
          if (mediaPart) {
            parts.unshift({ inlineData: mediaPart });
          }

          const response = await ai.models.generateContent({
            model: model || 'gemini-3-flash-preview',
            contents: { parts },
            config: {
              systemInstruction,
              responseMimeType: isJson ? "application/json" : undefined
            }
          });
          // Directly accessing .text property as per guidelines
          return isJson ? extractJSON(response.text || '{}') : response.text;
        } catch (err: any) {
          const errMsg = err.message || JSON.stringify(err);
          const isQuotaError = errMsg.includes('429') || errMsg.includes('RESOURCE_EXHAUSTED');

          if (isQuotaError && attempt < retries - 1) {
            await new Promise(resolve => setTimeout(resolve, delay));
            delay *= 2;
            continue;
          }
          throw new Error(`Gemini: ${errMsg}`);
        }
      }
    };
    return await executeWithRetry();
  }

  // Другие провайдеры (Ollama, LM Studio и т.д.)
  let url = (baseUrl || '').trim().replace(/\/$/, '');
  if (provider === AIProvider.Ollama) {
    url = url || 'http://localhost:11434';
    url += '/api/chat';
  } else {
    url = url || (provider === AIProvider.OpenRouter ? 'https://openrouter.ai/api/v1' : 'http://localhost:1234/v1');
    if (!url.endsWith('/chat/completions')) url += '/chat/completions';
  }

  const messages = [
    ...(systemInstruction ? [{ role: 'system', content: systemInstruction }] : []),
    { role: 'user', content: prompt }
  ];

  const body = { 
    model, 
    messages, 
    stream: false, 
    ...(provider === AIProvider.Ollama && isJson ? { format: 'json' } : {}) 
  };
  const headers: any = { 'Content-Type': 'application/json' };
  if (apiKey) headers['Authorization'] = `Bearer ${apiKey}`;

  const res = await fetch(url, { method: 'POST', headers, body: JSON.stringify(body) });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  const data = await res.json();
  const content = provider === AIProvider.Ollama ? data.message.content : data.choices[0].message.content;
  return isJson ? extractJSON(content) : content;
}

export const analyzeText = async (text: string, settings: Settings) => {
  const prompt = `ВЕРНИ JSON: { "title": "...", "tags": ["..."], "category": "...", "summary": "..." }. ТЕКСТ: ${text}`;
  return await callAI(prompt, settings.provider, settings.model, settings.apiKey, settings.url, true, "Ты — аналитик.");
};

export const transcribeAudio = async (blob: Blob, settings: Settings) => {
  const reader = new FileReader();
  const base64: string = await new Promise((resolve) => {
    reader.onload = () => resolve((reader.result as string).split(',')[1]);
    reader.readAsDataURL(blob);
  });

  return await callAI(
    "Распознай речь и верни только текст. Если речи нет, напиши [Тишина].",
    settings.transProvider,
    settings.transModel || 'gemini-2.5-flash-native-audio-preview-12-2025',
    settings.transApiKey,
    settings.transUrl,
    false,
    "Ты — эксперт по транскрибации.",
    { data: base64, mimeType: blob.type }
  );
};

export const chatWithNotes = async (query: string, context: string, settings: Settings) => {
  return await callAI(`Контекст: ${context}\nВопрос: ${query}`, settings.provider, settings.model, settings.apiKey, settings.url, false);
};

export const chatWithAgent = async (query: string, appData: any, settings: Settings) => {
  return await callAI(`Данные: ${JSON.stringify(appData)}\nЗапрос: ${query}`, settings.agentProvider, settings.agentModel, settings.agentApiKey, settings.agentUrl, false);
};

export const performOCR = async (base64Data: string, mimeType: string, settings: Settings) => {
  const dataOnly = base64Data.split(',')[1] || base64Data;
  return await callAI("Распознай текст на картинке.", settings.ocrProvider, settings.ocrModel, settings.ocrApiKey, settings.ocrUrl, false, undefined, { data: dataOnly, mimeType });
};

export const testConnection = async (settings: Settings) => {
  try {
    await callAI("ping", settings.provider, settings.model, settings.apiKey, settings.url, false);
    return { success: true, message: "ОК" };
  } catch (e: any) {
    return { success: false, message: e.message };
  }
};

export const splitLargeText = async (text: string, settings: Settings) => {
  const prompt = `Раздели текст на JSON массив: [ { "title": "...", "content": "...", "category": "..." } ]. ТЕКСТ: ${text}`;
  return await callAI(prompt, settings.provider, settings.model, settings.apiKey, settings.url, true);
};

import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useNotes } from '../contexts/NotesContext.tsx';
import { Note } from '../types.ts';
import { getTagColor } from '../utils/tagColors.ts';
import { 
  ChevronLeft, Save, Loader2, Sparkles, MessageSquare, Send, X, Folder, Globe, Hash, Plus, Play, Pause, Headphones, Volume2, Search
} from 'lucide-react';
import * as ai from '../utils/aiAdapter.ts';

const NoteEditor: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { notes, addNote, updateNote, runAIAnalysis, settings, addLog } = useNotes();

  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [tags, setTags] = useState<string[]>([]);
  const [category, setCategory] = useState('Общее');
  const [isSaving, setIsSaving] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [note, setNote] = useState<Note | null>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatMessages, setChatMessages] = useState<{role: 'user' | 'assistant', content: string}[]>([]);
  const [isChatLoading, setIsChatLoading] = useState(false);

  const [isPlaying, setIsPlaying] = useState(false);
  const [audioProgress, setAudioProgress] = useState(0);
  const [isTranscribing, setIsTranscribing] = useState(false);

  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    if (id && id !== 'new') {
      const found = notes.find(n => n.id === id);
      if (found) {
        setNote(found);
        setTitle(found.title);
        setContent(found.content);
        setTags(found.tags || []);
        setCategory(found.category || 'Общее');

        if (found.summary && chatMessages.length === 0) {
            setChatMessages([{ role: 'assistant', content: `Анализ: ${found.summary}` }]);
        }
      }
    }
  }, [id, notes]);

  const handleTranscribe = async () => {
    if (!note?.audioData) return;
    setIsTranscribing(true);
    addLog('info', 'Запуск транскрибации сохраненного аудио...');
    try {
        const response = await fetch(note.audioData);
        const blob = await response.blob();
        const text = await ai.transcribeAudio(blob, settings);
        setContent(text);
        addLog('success', 'Речь успешно распознана');
    } catch (e: any) {
        addLog('error', 'Ошибка распознавания: ' + e.message);
    } finally {
        setIsTranscribing(false);
    }
  };

  const toggleAudio = () => {
    if (!audioRef.current) return;
    if (isPlaying) {
      audioRef.current.pause();
    } else {
      audioRef.current.play();
    }
    setIsPlaying(!isPlaying);
  };

  const handleAudioTimeUpdate = () => {
    if (audioRef.current) {
      const progress = (audioRef.current.currentTime / audioRef.current.duration) * 100;
      setAudioProgress(progress);
    }
  };

  const handleSave = async (useAI = false) => {
    if (!content.trim() && !title.trim()) return;
    setIsSaving(true);
    if (useAI) setIsAnalyzing(true);

    try {
        if (id === 'new') {
          await addNote(content, title, 'manual', useAI);
          navigate('/');
        } else if (note) {
          const updatedNote = { ...note, title, content, tags, category, updatedAt: new Date().toISOString() };
          await updateNote(updatedNote);
          if (useAI && navigator.onLine) {
            await runAIAnalysis(note.id);
          }
        }
    } catch (e: any) {
      addLog('error', 'Ошибка сохранения: ' + e.message);
    } finally {
        setIsSaving(false);
        setIsAnalyzing(false);
    }
  };

  const handleChatSend = async () => {
    if (!chatInput.trim() || isChatLoading) return;
    const userMsg = chatInput;
    setChatMessages(prev => [...prev, { role: 'user', content: userMsg }]);
    setChatInput('');
    setIsChatLoading(true);

    try {
      const response = await ai.chatWithNotes(userMsg, content, settings);
      setChatMessages(prev => [...prev, { role: 'assistant', content: response }]);
    } catch (e: any) {
      setChatMessages(prev => [...prev, { role: 'assistant', content: `Ошибка: ${e.message}` }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  return (
    <div className="h-screen flex flex-col bg-white dark:bg-[#020617] overflow-hidden">
      <header className="flex items-center justify-between px-12 py-8 border-b border-gray-100 dark:border-white/5 bg-white/80 dark:bg-slate-950/80 backdrop-blur-2xl z-20 shrink-0">
        <div className="flex items-center gap-6 flex-1">
          <button onClick={() => navigate(-1)} className="p-4 text-gray-400 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-2xl transition-all">
            <ChevronLeft size={24}/>
          </button>
          <div className="flex flex-col flex-1">
              <div className="flex items-center gap-4">
                <input 
                  className="text-4xl font-extrabold bg-transparent border-none focus:outline-none text-black dark:text-white flex-1 tracking-tighter placeholder:text-gray-200" 
                  value={title} 
                  onChange={e => setTitle(e.target.value)} 
                  placeholder="Заголовок..."
                />
                <button 
                  onClick={() => ai.openInGoogle(title)}
                  className="p-3 text-gray-400 hover:text-blue-600 transition-colors"
                  title="Искать в Google"
                >
                  <Search size={20} />
                </button>
              </div>

              {note?.audioData && (
                <div className="flex items-center gap-4 mt-4 animate-in fade-in slide-in-from-top duration-500">
                  <div className="flex items-center gap-2 px-4 py-2 bg-blue-50 dark:bg-blue-900/20 rounded-full border border-blue-100 dark:border-blue-500/20">
                    <button 
                      onClick={toggleAudio}
                      className="p-2 bg-blue-600 text-white rounded-full hover:scale-105 transition-all"
                    >
                      {isPlaying ? <Pause size={14} fill="currentColor"/> : <Play size={14} fill="currentColor" className="ml-0.5"/>}
                    </button>
                    <div className="w-32 h-1.5 bg-gray-200 dark:bg-slate-700 rounded-full overflow-hidden relative">
                       <div 
                        className="absolute inset-y-0 left-0 bg-blue-500 transition-all duration-100" 
                        style={{ width: `${audioProgress}%` }}
                       />
                    </div>
                    <Volume2 size={14} className="text-blue-500" />
                    <audio 
                      ref={audioRef} 
                      src={note.audioData} 
                      onTimeUpdate={handleAudioTimeUpdate}
                      onEnded={() => setIsPlaying(false)}
                      className="hidden" 
                    />
                  </div>
                  <button 
                      disabled={isTranscribing}
                      onClick={handleTranscribe} 
                      className="flex items-center gap-2 px-4 py-2 bg-purple-500/10 text-purple-600 rounded-full text-[10px] font-black uppercase tracking-widest border border-purple-500/20 hover:bg-purple-500/20 transition-all disabled:opacity-50"
                  >
                      {isTranscribing ? <Loader2 size={12} className="animate-spin" /> : <Sparkles size={12}/>}
                      Распознать речь
                  </button>
                </div>
              )}
          </div>
        </div>
        <div className="flex items-center gap-4">
          <button onClick={() => handleSave(true)} className="px-8 py-4 bg-cyan-600/10 text-cyan-600 dark:text-cyan-400 rounded-2xl font-black uppercase text-[10px] tracking-widest flex items-center gap-3">
            {isAnalyzing ? <Loader2 size={18} className="animate-spin"/> : <Sparkles size={18}/>}
            ИИ Анализ
          </button>
          <button onClick={() => handleSave(false)} className="px-8 py-4 bg-blue-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-xl flex items-center gap-3 active:scale-95 transition-all">
            {isSaving ? <Loader2 size={18} className="animate-spin"/> : <Save size={18}/>}
            Сохранить
          </button>
        </div>
      </header>

      <div className="flex-1 flex overflow-hidden">
        <div className="flex-1 overflow-y-auto custom-scrollbar bg-gray-50/20 dark:bg-transparent p-12 lg:p-20">
          <div className="max-w-5xl mx-auto w-full h-full">
            <textarea 
              className="w-full h-full bg-transparent border-none focus:outline-none text-2xl leading-relaxed text-gray-800 dark:text-slate-200 resize-none font-medium placeholder:text-gray-200"
              value={content}
              onChange={e => setContent(e.target.value)}
              placeholder="Начните писать или распознайте голос..."
            />
          </div>
        </div>

        <div className="w-[440px] border-l border-gray-100 dark:border-white/5 bg-white dark:bg-slate-900/50 p-8 flex flex-col gap-8 overflow-y-auto custom-scrollbar">
           <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-gray-100 dark:border-white/5 shadow-sm">
             <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-3 mb-6">
               <Folder size={14} className="text-blue-500"/> Категория
             </h4>
             <select 
               className="w-full p-5 bg-gray-50 dark:bg-slate-950 rounded-2xl font-black text-xs border-none dark:text-white cursor-pointer"
               value={category}
               onChange={e => setCategory(e.target.value)}
             >
                {settings.customCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
             </select>
          </div>

          <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-gray-100 dark:border-white/5 shadow-sm">
            <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-3 mb-6">
              <Hash size={14} className="text-blue-500"/> Теги
            </h4>
            <div className="flex flex-wrap gap-2 mb-4">
              {tags.map(t => (
                <span key={t} className="px-3 py-1 bg-blue-50 text-blue-600 dark:bg-blue-900/20 dark:text-blue-400 rounded-lg text-[9px] font-black flex items-center gap-2 border border-blue-100 dark:border-blue-500/10">
                  #{t} <button onClick={() => setTags(tags.filter(x => x !== t))} className="hover:text-red-500"><X size={10}/></button>
                </span>
              ))}
            </div>
            <input 
              className="w-full p-4 bg-gray-50 dark:bg-slate-950 rounded-xl text-xs font-bold border-none dark:text-white" 
              placeholder="Добавить тег..."
              onKeyDown={e => {
                if (e.key === 'Enter') {
                   const val = e.currentTarget.value.trim();
                   if (val && !tags.includes(val)) {
                      setTags([...tags, val]);
                      e.currentTarget.value = '';
                   }
                }
              }}
            />
          </div>

          <div className="bg-white dark:bg-slate-900 rounded-[3rem] border border-gray-100 dark:border-white/5 flex flex-col flex-1 shadow-xl overflow-hidden min-h-[400px]">
            <header className="p-6 border-b border-gray-50 dark:border-white/5 text-[10px] font-black uppercase text-blue-500 flex items-center gap-3">
              <MessageSquare size={16}/> Neural Agent
            </header>
            <div className="flex-1 p-6 overflow-y-auto space-y-4 custom-scrollbar">
              {chatMessages.map((msg, i) => (
                <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[90%] p-4 rounded-2xl text-xs font-bold ${msg.role === 'user' ? 'bg-blue-600 text-white shadow-lg' : 'bg-gray-50 dark:bg-slate-800 dark:text-slate-300 border border-gray-100 dark:border-white/5'}`}>
                    {msg.content}
                  </div>
                </div>
              ))}
              {isChatLoading && (
                <div className="flex justify-start">
                   <div className="p-4 bg-gray-50 dark:bg-slate-800 rounded-2xl border border-gray-100 dark:border-white/5">
                      <Loader2 size={14} className="animate-spin text-blue-500" />
                   </div>
                </div>
              )}
            </div>
            <div className="p-4 border-t border-gray-50 dark:border-white/5 flex gap-2">
              <input 
                className="flex-1 p-3 bg-gray-50 dark:bg-slate-950 rounded-xl text-xs font-bold border-none dark:text-white"
                placeholder="Обсудить заметку..."
                value={chatInput}
                onChange={e => setChatInput(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleChatSend()}
              />
              <button 
                onClick={handleChatSend}
                disabled={!chatInput.trim() || isChatLoading}
                className="p-3 bg-blue-600 text-white rounded-xl shadow-lg active:scale-90 transition-all disabled:opacity-30"
              >
                <Send size={16}/>
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

