import React, { useState, useRef, useEffect } from 'react';
import { Mic, Square, Loader2, Save, X, RotateCcw, Volume2, Sparkles, AlertCircle, Play, Pause, Headphones } from 'lucide-react';
import { useNotes } from '../contexts/NotesContext.tsx';
import * as ai from '../utils/aiAdapter.ts';

const AudioRecorder: React.FC<{ onComplete?: () => void }> = ({ onComplete }) => {
  const { addNote, addLog, settings } = useNotes();
  const [isRecording, setIsRecording] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [audioBlob, setAudioBlob] = useState<Blob | null>(null);
  const [transcript, setTranscript] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const animationRef = useRef<number | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);

  const startRecording = async () => {
    try {
      setError(null);
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;

      const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
      const analyser = audioContext.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;

      const source = audioContext.createMediaStreamSource(stream);
      source.connect(analyser);

      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      const chunks: BlobPart[] = [];

      mediaRecorder.ondataavailable = (e) => chunks.push(e.data);
      mediaRecorder.onstop = () => {
        const blob = new Blob(chunks, { type: 'audio/webm' });
        setAudioBlob(blob);
      };

      mediaRecorder.start();
      setIsRecording(true);
      addLog('info', 'Микрофон активирован');
      visualize();
    } catch (err: any) {
      setError("Микрофон недоступен");
      addLog('error', 'Ошибка доступа к микрофону');
    }
  };

  const stopRecording = () => {
    mediaRecorderRef.current?.stop();
    streamRef.current?.getTracks().forEach(t => t.stop());
    setIsRecording(false);
    if (animationRef.current) cancelAnimationFrame(animationRef.current);
  };

  const visualize = () => {
    const canvas = canvasRef.current;
    if (!canvas || !analyserRef.current) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const bufferLength = analyserRef.current.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);

    const draw = () => {
      animationRef.current = requestAnimationFrame(draw);
      analyserRef.current!.getByteFrequencyData(dataArray);

      ctx.clearRect(0, 0, canvas.width, canvas.height);
      const barWidth = (canvas.width / bufferLength) * 2;
      let x = 0;

      for (let i = 0; i < bufferLength; i++) {
        const barHeight = (dataArray[i] / 255) * canvas.height;

        // Dynamic coloring based on volume/frequency
        const hue = 200 + (i / bufferLength) * 60;
        ctx.fillStyle = `hsla(${hue}, 80%, 50%, 0.8)`;

        // Mirror effect for better visuals
        ctx.fillRect(x, (canvas.height - barHeight) / 2, barWidth - 1, barHeight);
        x += barWidth;
      }
    };
    draw();
  };

  const handleTranscribe = async () => {
    if (!audioBlob) return;
    setIsProcessing(true);
    addLog('info', 'ИИ анализирует аудио...');
    try {
      const result = await ai.transcribeAudio(audioBlob, settings);
      setTranscript(result);
      addLog('success', 'Транскрибация завершена');
    } catch (e: any) {
      setError(e.message);
      addLog('error', 'Транскрибация не удалась: ' + e.message);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleSave = async () => {
    if (!audioBlob) return;
    const reader = new FileReader();
    const base64: string = await new Promise((resolve) => {
      reader.onload = () => resolve(reader.result as string);
      reader.readAsDataURL(audioBlob);
    });

    const finalContent = transcript || "[Голосовая заметка]";
    await addNote(finalContent, `Запись ${new Date().toLocaleTimeString()}`, 'audio', !!transcript, undefined, base64);
    onComplete?.();
  };

  return (
    <div className="bg-white dark:bg-slate-900 p-10 rounded-[3rem] border border-gray-100 dark:border-white/10 shadow-2xl space-y-8 animate-in zoom-in duration-300">
      <div className="flex items-center justify-between">
        <h3 className="font-black text-xs uppercase tracking-widest text-blue-500 flex items-center gap-3">
            <Volume2 size={18} /> Neural Voice Engine
        </h3>
        <button 
          onClick={() => { setAudioBlob(null); setTranscript(''); setError(null); }} 
          className="text-gray-400 hover:text-red-500 transition-colors"
          title="Сбросить"
        >
            <RotateCcw size={20}/>
        </button>
      </div>

      <div className="h-48 bg-gray-50 dark:bg-slate-950 rounded-[2.5rem] flex items-center justify-center overflow-hidden border-2 border-dashed border-gray-100 dark:border-white/5 relative">
        {isRecording ? (
          <canvas ref={canvasRef} width={400} height={150} className="w-full h-full opacity-80" />
        ) : audioBlob ? (
          <div className="flex flex-col items-center gap-6">
             <button 
                onClick={() => { if(isPlaying) audioRef.current?.pause(); else audioRef.current?.play(); setIsPlaying(!isPlaying); }}
                className="w-20 h-20 bg-blue-600 text-white rounded-full flex items-center justify-center hover:scale-110 active:scale-95 transition-all shadow-xl"
             >
                {isPlaying ? <Pause size={32}/> : <Play size={32} className="ml-1" />}
             </button>
             <p className="text-[10px] font-black uppercase tracking-widest text-blue-500 flex items-center gap-2">
                <Headphones size={14}/> Прослушивание
             </p>
             <audio ref={audioRef} src={URL.createObjectURL(audioBlob)} onEnded={() => setIsPlaying(false)} className="hidden" />
          </div>
        ) : error ? (
           <div className="flex flex-col items-center gap-4 text-red-500 px-8 text-center">
              <AlertCircle size={40} />
              <p className="text-[10px] font-black uppercase">{error}</p>
           </div>
        ) : (
          <div className="flex flex-col items-center gap-4 opacity-20">
            <Mic size={56} className="animate-pulse" />
            <p className="text-[10px] font-black uppercase tracking-[0.3em]">Ожидание...</p>
          </div>
        )}
      </div>

      <div className="flex gap-4">
        {!isRecording && !audioBlob && (
          <button onClick={startRecording} className="flex-1 py-6 bg-blue-600 text-white rounded-[1.8rem] font-black uppercase text-xs tracking-widest shadow-xl shadow-blue-500/20 active:scale-95 transition-all">
            Начать запись
          </button>
        )}
        {isRecording && (
          <button onClick={stopRecording} className="flex-1 py-6 bg-red-500 text-white rounded-[1.8rem] font-black uppercase text-xs tracking-widest animate-pulse shadow-xl">
            Завершить
          </button>
        )}
        {audioBlob && !transcript && (
          <button 
            onClick={handleTranscribe} 
            disabled={isProcessing} 
            className="flex-1 py-6 bg-purple-600 text-white rounded-[1.8rem] font-black uppercase text-xs tracking-widest shadow-xl flex items-center justify-center gap-3 disabled:opacity-50"
          >
            {isProcessing ? <Loader2 size={18} className="animate-spin"/> : <Sparkles size={18}/>} 
            Транскрибировать
          </button>
        )}
      </div>

      {(transcript || (audioBlob && !isRecording)) && (
        <div className="space-y-4 animate-in fade-in slide-in-from-bottom duration-500">
          {transcript && (
            <textarea 
              value={transcript}
              onChange={e => setTranscript(e.target.value)}
              className="w-full h-32 p-5 bg-gray-50 dark:bg-slate-950 border-none rounded-[1.8rem] text-sm font-bold dark:text-white shadow-inner resize-none focus:ring-2 focus:ring-blue-500/10 transition-all"
            />
          )}
          <button onClick={handleSave} className="w-full py-6 bg-green-600 text-white rounded-[1.8rem] font-black uppercase text-xs tracking-widest shadow-xl hover:bg-green-700 active:scale-95 transition-all">
            Сохранить в базу
          </button>
        </div>
      )}
    </div>
  );
};

export default AudioRecorder;

import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useNotes } from '../contexts/NotesContext.tsx';
import { Note } from '../types.ts';
import { getTagColor } from '../utils/tagColors.ts';
import { 
  ChevronLeft, Save, Loader2, Sparkles, MessageSquare, Send, X, Folder, Globe, Hash, Play, Pause, Headphones, Volume2, Search, ExternalLink
} from 'lucide-react';
import * as ai from '../utils/aiAdapter.ts';

const NoteEditor: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { notes, addNote, updateNote, runAIAnalysis, settings, addLog } = useNotes();

  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [tags, setTags] = useState<string[]>([]);
  const [category, setCategory] = useState('Общее');
  const [isSaving, setIsSaving] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [note, setNote] = useState<Note | null>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatMessages, setChatMessages] = useState<{role: 'user' | 'assistant', content: string}[]>([]);
  const [isChatLoading, setIsChatLoading] = useState(false);

  const [isPlaying, setIsPlaying] = useState(false);
  const [audioProgress, setAudioProgress] = useState(0);
  const [isTranscribing, setIsTranscribing] = useState(false);

  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    if (id && id !== 'new') {
      const found = notes.find(n => n.id === id);
      if (found) {
        setNote(found);
        setTitle(found.title);
        setContent(found.content);
        setTags(found.tags || []);
        setCategory(found.category || 'Общее');

        if (found.summary && chatMessages.length === 0) {
            setChatMessages([{ role: 'assistant', content: `Краткий анализ: ${found.summary}` }]);
        }
      }
    }
  }, [id, notes]);

  const handleTranscribe = async () => {
    if (!note?.audioData) return;
    setIsTranscribing(true);
    addLog('info', 'Транскрибация сохраненного аудио...');
    try {
        const response = await fetch(note.audioData);
        const blob = await response.blob();
        const text = await ai.transcribeAudio(blob, settings);
        setContent(text);
        addLog('success', 'Текст обновлен из аудио');
    } catch (e: any) {
        addLog('error', 'Ошибка: ' + e.message);
    } finally {
        setIsTranscribing(false);
    }
  };

  const toggleAudio = () => {
    if (!audioRef.current) return;
    if (isPlaying) {
      audioRef.current.pause();
    } else {
      audioRef.current.play();
    }
    setIsPlaying(!isPlaying);
  };

  const handleAudioTimeUpdate = () => {
    if (audioRef.current) {
      const progress = (audioRef.current.currentTime / audioRef.current.duration) * 100;
      setAudioProgress(progress);
    }
  };

  const handleSave = async (useAI = false) => {
    if (!content.trim() && !title.trim()) return;
    setIsSaving(true);
    if (useAI) setIsAnalyzing(true);

    try {
        if (id === 'new') {
          await addNote(content, title, 'manual', useAI);
          navigate('/');
        } else if (note) {
          const updatedNote = { ...note, title, content, tags, category, updatedAt: new Date().toISOString() };
          await updateNote(updatedNote);
          if (useAI && navigator.onLine) {
            await runAIAnalysis(note.id);
          }
        }
    } catch (e: any) {
      addLog('error', 'Ошибка при сохранении: ' + e.message);
    } finally {
        setIsSaving(false);
        setIsAnalyzing(false);
    }
  };

  const handleChatSend = async () => {
    if (!chatInput.trim() || isChatLoading) return;
    const userMsg = chatInput;
    setChatMessages(prev => [...prev, { role: 'user', content: userMsg }]);
    setChatInput('');
    setIsChatLoading(true);

    try {
      const response = await ai.chatWithNotes(userMsg, content, settings);
      setChatMessages(prev => [...prev, { role: 'assistant', content: response }]);
    } catch (e: any) {
      setChatMessages(prev => [...prev, { role: 'assistant', content: `Сбой системы: ${e.message}` }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  return (
    <div className="h-screen flex flex-col bg-white dark:bg-[#020617] overflow-hidden">
      <header className="flex items-center justify-between px-12 py-8 border-b border-gray-100 dark:border-white/5 bg-white/80 dark:bg-slate-950/80 backdrop-blur-2xl z-20 shrink-0">
        <div className="flex items-center gap-6 flex-1">
          <button onClick={() => navigate(-1)} className="p-4 text-gray-400 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-2xl transition-all">
            <ChevronLeft size={24}/>
          </button>
          <div className="flex flex-col flex-1">
              <div className="flex items-center gap-4">
                <input 
                  className="text-4xl font-extrabold bg-transparent border-none focus:outline-none text-black dark:text-white flex-1 tracking-tighter placeholder:text-gray-200" 
                  value={title} 
                  onChange={e => setTitle(e.target.value)} 
                  placeholder="Заголовок..."
                />
                <button 
                  onClick={() => ai.openInGoogle(title)}
                  className="p-3 text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-xl transition-all"
                  title="Найти в Google"
                >
                  <Globe size={24} />
                </button>
              </div>

              {note?.audioData && (
                <div className="flex items-center gap-6 mt-4 animate-in slide-in-from-top duration-500">
                  <div className="flex items-center gap-4 px-6 py-3 bg-gray-50 dark:bg-slate-900 rounded-[2rem] border border-gray-100 dark:border-white/10 shadow-sm">
                    <button 
                      onClick={toggleAudio}
                      className="w-10 h-10 bg-blue-600 text-white rounded-full flex items-center justify-center hover:scale-105 transition-all shadow-lg"
                    >
                      {isPlaying ? <Pause size={16} fill="currentColor"/> : <Play size={16} fill="currentColor" className="ml-0.5"/>}
                    </button>

                    {/* Визуализатор громкости */}
                    <div className="flex items-end gap-1 h-6 w-16 px-1">
                        {[1, 2, 3, 4, 5, 6].map(i => (
                            <div 
                                key={i}
                                className={`w-1.5 bg-blue-500 rounded-full transition-all duration-300 ${isPlaying ? 'animate-pulse' : 'h-1 opacity-30'}`}
                                style={{ 
                                    height: isPlaying ? `${20 + Math.random() * 80}%` : '4px',
                                    animationDelay: `${i * 0.1}s`
                                }}
                            />
                        ))}
                    </div>

                    <div className="w-48 h-1.5 bg-gray-200 dark:bg-slate-700 rounded-full overflow-hidden relative">
                       <div 
                        className="absolute inset-y-0 left-0 bg-blue-500 transition-all duration-300" 
                        style={{ width: `${audioProgress}%` }}
                       />
                    </div>

                    <audio 
                      ref={audioRef} 
                      src={note.audioData} 
                      onTimeUpdate={handleAudioTimeUpdate}
                      onEnded={() => setIsPlaying(false)}
                      className="hidden" 
                    />
                  </div>

                  <button 
                      disabled={isTranscribing}
                      onClick={handleTranscribe} 
                      className="flex items-center gap-3 px-6 py-3 bg-purple-600/10 text-purple-600 rounded-[2rem] text-[10px] font-black uppercase tracking-widest border border-purple-500/20 hover:bg-purple-600/20 transition-all disabled:opacity-50"
                  >
                      {isTranscribing ? <Loader2 size={14} className="animate-spin" /> : <Sparkles size={14}/>}
                      Распознать
                  </button>
                </div>
              )}
          </div>
        </div>
        <div className="flex items-center gap-4">
          <button onClick={() => handleSave(true)} className="px-8 py-4 bg-cyan-600/10 text-cyan-600 dark:text-cyan-400 rounded-2xl font-black uppercase text-[10px] tracking-widest flex items-center gap-3">
            {isAnalyzing ? <Loader2 size={18} className="animate-spin"/> : <Sparkles size={18}/>}
            Анализ
          </button>
          <button onClick={() => handleSave(false)} className="px-8 py-4 bg-blue-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-xl flex items-center gap-3 active:scale-95 transition-all">
            {isSaving ? <Loader2 size={18} className="animate-spin"/> : <Save size={18}/>}
            Записать
          </button>
        </div>
      </header>

      <div className="flex-1 flex overflow-hidden">
        <div className="flex-1 overflow-y-auto custom-scrollbar bg-gray-50/10 p-12 lg:p-20">
          <div className="max-w-5xl mx-auto w-full h-full">
            <textarea 
              className="w-full h-full bg-transparent border-none focus:outline-none text-2xl leading-relaxed text-gray-800 dark:text-slate-200 resize-none font-medium placeholder:text-gray-200"
              value={content}
              onChange={e => setContent(e.target.value)}
              placeholder="Напишите историю или распознайте голос..."
            />
          </div>
        </div>

        <div className="w-[440px] border-l border-gray-100 dark:border-white/5 bg-white dark:bg-slate-900/50 p-8 flex flex-col gap-8 overflow-y-auto custom-scrollbar">
           <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-gray-100 dark:border-white/5 shadow-sm">
             <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-3 mb-6">
               <Folder size={14} className="text-blue-500"/> Категория
             </h4>
             <select 
               className="w-full p-5 bg-gray-50 dark:bg-slate-950 rounded-2xl font-black text-xs border-none dark:text-white cursor-pointer"
               value={category}
               onChange={e => setCategory(e.target.value)}
             >
                {settings.customCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
             </select>
          </div>

          <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-gray-100 dark:border-white/5 shadow-sm">
            <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-3 mb-6">
              <Hash size={14} className="text-blue-500"/> Теги
            </h4>
            <div className="flex flex-wrap gap-2 mb-4">
              {tags.map(t => (
                <span key={t} className="px-3 py-1 bg-blue-50 text-blue-600 dark:bg-blue-900/20 dark:text-blue-400 rounded-lg text-[9px] font-black flex items-center gap-2 border border-blue-100 dark:border-blue-500/10">
                  #{t} <button onClick={() => setTags(tags.filter(x => x !== t))} className="hover:text-red-500 transition-colors"><X size={10}/></button>
                </span>
              ))}
            </div>
            <input 
              className="w-full p-4 bg-gray-50 dark:bg-slate-950 rounded-xl text-xs font-bold border-none dark:text-white" 
              placeholder="Добавить тег..."
              onKeyDown={e => {
                if (e.key === 'Enter') {
                   const val = e.currentTarget.value.trim();
                   if (val && !tags.includes(val)) {
                      setTags([...tags, val]);
                      e.currentTarget.value = '';
                   }
                }
              }}
            />
          </div>

          <div className="bg-white dark:bg-slate-900 rounded-[3rem] border border-gray-100 dark:border-white/5 flex flex-col flex-1 shadow-xl overflow-hidden min-h-[400px]">
            <header className="p-6 border-b border-gray-50 dark:border-white/5 text-[10px] font-black uppercase text-blue-500 flex items-center gap-3">
              <MessageSquare size={16}/> Neural Assistant
            </header>
            <div className="flex-1 p-6 overflow-y-auto space-y-4 custom-scrollbar">
              {chatMessages.map((msg, i) => (
                <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[90%] p-4 rounded-2xl text-xs font-bold ${msg.role === 'user' ? 'bg-blue-600 text-white shadow-lg' : 'bg-gray-50 dark:bg-slate-800 dark:text-slate-300 border border-gray-100 dark:border-white/5'}`}>
                    {msg.content}
                  </div>
                </div>
              ))}
              {isChatLoading && (
                <div className="flex justify-start">
                   <div className="p-4 bg-gray-50 dark:bg-slate-800 rounded-2xl border border-gray-100 dark:border-white/5">
                      <Loader2 size={14} className="animate-spin text-blue-500" />
                   </div>
                </div>
              )}
            </div>
            <div className="p-4 border-t border-gray-50 dark:border-white/5 flex gap-2">
              <input 
                className="flex-1 p-3 bg-gray-50 dark:bg-slate-950 rounded-xl text-xs font-bold border-none dark:text-white"
                placeholder="Спросить ассистента..."
                value={chatInput}
                onChange={e => setChatInput(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleChatSend()}
              />
              <button 
                onClick={handleChatSend}
                disabled={!chatInput.trim() || isChatLoading}
                className="p-3 bg-blue-600 text-white rounded-xl shadow-lg active:scale-90 transition-all disabled:opacity-30"
              >
                <Send size={16}/>
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

