import React, { useState, useRef, useEffect } from 'react';
import { Mic, Square, Loader2, Save, X, RotateCcw, Volume2, Sparkles, AlertCircle, Play, Pause, Headphones } from 'lucide-react';
import { useNotes } from '../contexts/NotesContext.tsx';
import * as ai from '../utils/aiAdapter.ts';

const AudioRecorder: React.FC<{ onComplete?: () => void }> = ({ onComplete }) => {
  const { addNote, addLog, settings } = useNotes();
  const [isRecording, setIsRecording] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [audioBlob, setAudioBlob] = useState<Blob | null>(null);
  const [transcript, setTranscript] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const animationRef = useRef<number | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);

  const startRecording = async () => {
    try {
      setError(null);
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;

      const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
      const analyser = audioContext.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;

      const source = audioContext.createMediaStreamSource(stream);
      source.connect(analyser);

      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      const chunks: BlobPart[] = [];

      mediaRecorder.ondataavailable = (e) => chunks.push(e.data);
      mediaRecorder.onstop = () => {
        const blob = new Blob(chunks, { type: 'audio/webm' });
        setAudioBlob(blob);
      };

      mediaRecorder.start();
      setIsRecording(true);
      addLog('info', 'Микрофон активирован');
      visualize();
    } catch (err: any) {
      setError("Микрофон недоступен");
      addLog('error', 'Ошибка доступа к микрофону');
    }
  };

  const stopRecording = () => {
    mediaRecorderRef.current?.stop();
    streamRef.current?.getTracks().forEach(t => t.stop());
    setIsRecording(false);
    if (animationRef.current) cancelAnimationFrame(animationRef.current);
  };

  const visualize = () => {
    const canvas = canvasRef.current;
    if (!canvas || !analyserRef.current) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const bufferLength = analyserRef.current.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);

    const draw = () => {
      animationRef.current = requestAnimationFrame(draw);
      analyserRef.current!.getByteFrequencyData(dataArray);

      ctx.clearRect(0, 0, canvas.width, canvas.height);
      const barWidth = (canvas.width / bufferLength) * 2.5;
      let x = 0;

      for (let i = 0; i < bufferLength; i++) {
        const barHeight = (dataArray[i] / 255) * canvas.height;

        // Красивый градиент в стиле Neural
        const hue = 210 + (i / bufferLength) * 40;
        ctx.fillStyle = `hsla(${hue}, 90%, 60%, ${0.3 + (dataArray[i]/255)})`;

        // Отрисовка симметричных баров (Volume Visualization)
        const yPos = (canvas.height - barHeight) / 2;
        ctx.fillRect(x, yPos, barWidth - 1, barHeight);
        x += barWidth;
      }
    };
    draw();
  };

  const handleTranscribe = async () => {
    if (!audioBlob) return;
    setIsProcessing(true);
    addLog('info', 'ИИ анализирует аудио...');
    try {
      const result = await ai.transcribeAudio(audioBlob, settings);
      setTranscript(result);
      addLog('success', 'Транскрибация завершена');
    } catch (e: any) {
      setError(e.message);
      addLog('error', 'Транскрибация не удалась: ' + e.message);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleSave = async () => {
    if (!audioBlob) return;
    const reader = new FileReader();
    const base64: string = await new Promise((resolve) => {
      reader.onload = () => resolve(reader.result as string);
      reader.readAsDataURL(audioBlob);
    });

    const finalContent = transcript || "[Голосовая заметка]";
    await addNote(finalContent, `Запись ${new Date().toLocaleTimeString()}`, 'audio', !!transcript, undefined, base64);
    onComplete?.();
  };

  return (
    <div className="bg-white dark:bg-slate-900 p-10 rounded-[3.5rem] border border-gray-100 dark:border-white/10 shadow-2xl space-y-8 animate-in zoom-in duration-300">
      <div className="flex items-center justify-between px-2">
        <h3 className="font-black text-xs uppercase tracking-widest text-blue-500 flex items-center gap-3">
            <Volume2 size={20} className={isRecording ? 'animate-bounce' : ''} /> 
            Neural Voice Recorder
        </h3>
        <button 
          onClick={() => { setAudioBlob(null); setTranscript(''); setError(null); }} 
          className="text-gray-400 hover:text-red-500 transition-colors"
          title="Сбросить"
        >
            <RotateCcw size={22}/>
        </button>
      </div>

      <div className="h-48 bg-gray-50 dark:bg-slate-950 rounded-[2.5rem] flex items-center justify-center overflow-hidden border-2 border-dashed border-gray-100 dark:border-white/5 relative shadow-inner">
        {isRecording ? (
          <div className="w-full h-full flex items-center justify-center p-4">
             <canvas ref={canvasRef} width={400} height={150} className="w-full h-full" />
             <div className="absolute top-4 right-6 flex items-center gap-2">
                <div className="w-2 h-2 bg-red-500 rounded-full animate-pulse" />
                <span className="text-[10px] font-black text-red-500 uppercase tracking-widest">Live REC</span>
             </div>
          </div>
        ) : audioBlob ? (
          <div className="flex flex-col items-center gap-6">
             <button 
                onClick={() => { if(isPlaying) audioRef.current?.pause(); else audioRef.current?.play(); setIsPlaying(!isPlaying); }}
                className="w-20 h-20 bg-blue-600 text-white rounded-full flex items-center justify-center hover:scale-110 active:scale-95 transition-all shadow-xl shadow-blue-500/20"
             >
                {isPlaying ? <Pause size={32}/> : <Play size={32} className="ml-1" />}
             </button>
             <p className="text-[10px] font-black uppercase tracking-widest text-blue-500 flex items-center gap-2">
                <Headphones size={14}/> Прослушивание
             </p>
             <audio ref={audioRef} src={URL.createObjectURL(audioBlob)} onEnded={() => setIsPlaying(false)} className="hidden" />
          </div>
        ) : error ? (
           <div className="flex flex-col items-center gap-4 text-red-500 px-8 text-center">
              <AlertCircle size={40} />
              <p className="text-[10px] font-black uppercase">{error}</p>
           </div>
        ) : (
          <div className="flex flex-col items-center gap-4 opacity-10">
            <Mic size={64} className="animate-pulse" />
            <p className="text-[10px] font-black uppercase tracking-[0.3em]">Готов к записи</p>
          </div>
        )}
      </div>

      <div className="flex gap-4">
        {!isRecording && !audioBlob && (
          <button onClick={startRecording} className="flex-1 py-6 bg-blue-600 text-white rounded-[2rem] font-black uppercase text-xs tracking-widest shadow-xl shadow-blue-500/20 active:scale-95 transition-all">
            Начать запись
          </button>
        )}
        {isRecording && (
          <button onClick={stopRecording} className="flex-1 py-6 bg-red-500 text-white rounded-[2rem] font-black uppercase text-xs tracking-widest animate-pulse shadow-xl">
            Остановить
          </button>
        )}
        {audioBlob && !transcript && (
          <button 
            onClick={handleTranscribe} 
            disabled={isProcessing} 
            className="flex-1 py-6 bg-purple-600 text-white rounded-[2rem] font-black uppercase text-xs tracking-widest shadow-xl flex items-center justify-center gap-3 disabled:opacity-50 active:scale-95 transition-all"
          >
            {isProcessing ? <Loader2 size={18} className="animate-spin"/> : <Sparkles size={18}/>} 
            Транскрибировать
          </button>
        )}
      </div>

      {(transcript || (audioBlob && !isRecording)) && (
        <div className="space-y-4 animate-in fade-in slide-in-from-bottom duration-500">
          {transcript && (
            <textarea 
              value={transcript}
              onChange={e => setTranscript(e.target.value)}
              className="w-full h-32 p-6 bg-gray-50 dark:bg-slate-950 border-none rounded-[2rem] text-sm font-bold dark:text-white shadow-inner resize-none focus:ring-2 focus:ring-blue-500/10 transition-all"
              placeholder="Результат распознавания..."
            />
          )}
          <button onClick={handleSave} className="w-full py-6 bg-green-600 text-white rounded-[2rem] font-black uppercase text-xs tracking-widest shadow-xl hover:bg-green-700 active:scale-95 transition-all">
            Сохранить в базу
          </button>
        </div>
      )}
    </div>
  );
};

