import React, { useState, useMemo } from 'react';
import { useNotes } from '../contexts/NotesContext.tsx';
import { Target, Plus, X, Sparkles, ChevronRight, Hash, Search, Zap, Trash2, CheckCircle, Circle, Globe, CheckCircle2 } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import * as ai from '../utils/aiAdapter.ts';

const GoalsPage: React.FC = () => {
  const { goals, addGoal, deleteGoal, toggleGoalStatus, notes, setNoteStatus } = useNotes();
  const navigate = useNavigate();
  const [showAdd, setShowAdd] = useState(false);
  const [newTitle, setNewTitle] = useState('');
  const [newDesc, setNewDesc] = useState('');
  const [selectedGoalId, setSelectedGoalId] = useState<string | null>(null);

  const handleAdd = async () => {
    if (!newTitle.trim()) return;
    await addGoal(newTitle, newDesc);
    setNewTitle('');
    setNewDesc('');
    setShowAdd(false);
  };

  const selectedGoal = useMemo(() => goals.find(g => g.id === selectedGoalId), [goals, selectedGoalId]);

  const linkedNotes = useMemo(() => {
    if (!selectedGoal) return [];
    const titleKeywords = selectedGoal.title.toLowerCase().split(' ').filter(k => k.length > 3);
    const descKeywords = selectedGoal.description.toLowerCase().split(' ').filter(k => k.length > 3);
    const keywords = [...new Set([...titleKeywords, ...descKeywords])];

    return notes.filter(n => {
      if (n.status === 'trash') return false;
      const content = n.content.toLowerCase() + n.title.toLowerCase();
      const hasKeyword = keywords.some(k => content.includes(k));
      const hasTagMatch = n.tags.some(t => keywords.some(k => t.toLowerCase().includes(k)));
      return hasKeyword || hasTagMatch;
    }).slice(0, 15);
  }, [selectedGoal, notes]);

  const handleMarkAsDone = (e: React.MouseEvent, noteId: string) => {
    e.stopPropagation();
    setNoteStatus(noteId, 'finished');
  };

  return (
    <div className="p-12 max-w-7xl mx-auto min-h-screen animate-in fade-in duration-500 pb-32">
      <header className="flex items-center justify-between mb-16 bg-white/40 dark:bg-slate-900/40 p-10 rounded-[4rem] backdrop-blur-xl border border-white/10">
        <div>
          <div className="flex items-center gap-3 text-blue-600 font-black text-[11px] uppercase tracking-[0.4em]">
            <Target size={18} /> Strategic Planner
          </div>
          <h2 className="text-6xl font-black dark:text-white mt-2 tracking-tighter">Ваши Цели</h2>
        </div>
        <button 
          onClick={() => setShowAdd(true)}
          className="px-10 py-5 bg-blue-600 text-white rounded-[2rem] font-black text-xs uppercase tracking-widest flex items-center gap-4 hover:bg-blue-700 transition-all shadow-xl active:scale-95"
        >
          <Plus size={22}/> Поставить цель
        </button>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
        <div className="lg:col-span-4 space-y-6">
           {goals.map(goal => (
             <div 
               key={goal.id} 
               onClick={() => setSelectedGoalId(goal.id)}
               className={`p-8 rounded-[3rem] border cursor-pointer transition-all group relative ${
                 selectedGoalId === goal.id 
                 ? 'bg-blue-600 border-blue-600 text-white shadow-2xl shadow-blue-500/30' 
                 : 'bg-white dark:bg-slate-900 border-gray-100 dark:border-slate-800 hover:border-blue-400'
               }`}
             >
                <div className="flex items-center justify-between mb-6">
                  <button 
                    onClick={(e) => { e.stopPropagation(); toggleGoalStatus(goal.id); }}
                    className={`p-3 rounded-2xl transition-all ${goal.status === 'completed' ? 'bg-green-500 text-white' : 'bg-gray-100 dark:bg-slate-800 text-gray-400'}`}
                  >
                    {goal.status === 'completed' ? <CheckCircle size={20}/> : <Circle size={20}/>}
                  </button>
                  <button onClick={(e) => { e.stopPropagation(); deleteGoal(goal.id); }} className={`p-3 rounded-xl opacity-0 group-hover:opacity-100 transition-opacity ${selectedGoalId === goal.id ? 'hover:bg-blue-700' : 'hover:bg-red-50 text-red-500'}`}>
                    <Trash2 size={18}/>
                  </button>
                </div>
                <h3 className={`text-2xl font-black tracking-tight leading-tight ${goal.status === 'completed' ? 'line-through opacity-50' : ''}`}>{goal.title}</h3>
                <p className={`text-xs mt-3 line-clamp-2 leading-relaxed ${selectedGoalId === goal.id ? 'text-blue-100' : 'text-gray-400'}`}>{goal.description}</p>
             </div>
           ))}
        </div>

        <div className="lg:col-span-8">
           {selectedGoal ? (
             <div className="space-y-8 animate-in slide-in-from-right duration-500">
                <div className="bg-white dark:bg-slate-900 p-12 rounded-[4rem] border border-gray-100 dark:border-slate-800 shadow-sm relative overflow-hidden">
                   {selectedGoal.status === 'completed' && (
                       <div className="absolute top-10 right-10 text-green-500 animate-bounce">
                           <CheckCircle2 size={64} />
                       </div>
                   )}
                   <div className="flex items-center gap-4 mb-6">
                      <button onClick={() => ai.openInGoogle(selectedGoal.title)} className="p-3 bg-blue-50 dark:bg-blue-900/20 text-blue-500 rounded-2xl hover:scale-110 transition-all">
                        <Globe size={24}/>
                      </button>
                      <h3 className="text-4xl font-black dark:text-white tracking-tight leading-tight">{selectedGoal.title}</h3>
                   </div>
                   <p className="text-gray-500 dark:text-slate-400 leading-relaxed text-lg max-w-2xl">{selectedGoal.description}</p>
                   <div className="mt-12 flex items-center gap-4 text-[10px] font-black uppercase tracking-widest text-blue-500">
                     <Sparkles size={18}/> Релевантные знания (связано по смыслу)
