                  <textarea 
                    className="w-full h-40 p-6 bg-gray-50 dark:bg-slate-950 border-none rounded-[2rem] font-medium resize-none dark:text-white shadow-inner leading-relaxed"
                    placeholder="Какие шаги нужно предпринять?"
                    value={newDesc}
