            <div className="flex gap-4 mt-12">
               <button onClick={() => setShowAdd(false)} className="flex-1 py-6 bg-gray-100 dark:bg-slate-800 rounded-[2rem] font-black uppercase text-[10px] tracking-widest dark:text-white active:scale-95 transition-all">Отмена</button>
