import React, { useState, useEffect, useRef, useMemo } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useNotes } from '../contexts/NotesContext.tsx';
import { Note } from '../types.ts';
import { getTagColor } from '../utils/tagColors.ts';
import { 
  ChevronLeft, Save, Loader2, Sparkles, MessageSquare, Send, X, Folder, Globe, Hash, Play, Pause, Headphones, Volume2, Search, ExternalLink, Link2, ArrowRight
} from 'lucide-react';
import * as ai from '../utils/aiAdapter.ts';

const NoteEditor: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { notes, addNote, updateNote, runAIAnalysis, settings, addLog, setFilterTag } = useNotes();

  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [tags, setTags] = useState<string[]>([]);
  const [category, setCategory] = useState('Общее');
  const [isSaving, setIsSaving] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [note, setNote] = useState<Note | null>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatMessages, setChatMessages] = useState<{role: 'user' | 'assistant', content: string}[]>([]);
  const [isChatLoading, setIsChatLoading] = useState(false);

  const [isPlaying, setIsPlaying] = useState(false);
  const [audioProgress, setAudioProgress] = useState(0);
  const [isTranscribing, setIsTranscribing] = useState(false);

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const visualizerCanvasRef = useRef<HTMLCanvasElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const animFrameRef = useRef<number | null>(null);

  useEffect(() => {
    if (id && id !== 'new') {
      const found = notes.find(n => n.id === id);
      if (found) {
        setNote(found);
        setTitle(found.title);
        setContent(found.content);
        setTags(found.tags || []);
        setCategory(found.category || 'Общее');

        if (found.summary && chatMessages.length === 0) {
            setChatMessages([{ role: 'assistant', content: `Краткий анализ: ${found.summary}` }]);
        }
      }
    } else {
        setNote(null);
        setTitle('');
        setContent('');
        setTags([]);
        setCategory('Общее');
    }
  }, [id, notes]);

  // Поиск связанных заметок (по тегам или категории)
  const relatedNotes = useMemo(() => {
    if (!id || id === 'new') return [];
    return notes.filter(n => {
        if (n.id === id || n.status === 'trash') return false;
        const sameCategory = n.category === category;
        const commonTags = n.tags.some(t => tags.includes(t));
        return sameCategory || commonTags;
    }).slice(0, 5);
  }, [id, notes, category, tags]);

  useEffect(() => {
    if (isPlaying && !audioContextRef.current && audioRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      analyserRef.current = audioContextRef.current.createAnalyser();
      analyserRef.current.fftSize = 128;
      const source = audioContextRef.current.createMediaElementSource(audioRef.current);
      source.connect(analyserRef.current);
      analyserRef.current.connect(audioContextRef.current.destination);
    }

    if (isPlaying) {
      const draw = () => {
        const canvas = visualizerCanvasRef.current;
        const analyser = analyserRef.current;
        if (!canvas || !analyser) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        const bufferLength = analyser.frequencyBinCount;
        const dataArray = new Uint8Array(bufferLength);
        analyser.getByteFrequencyData(dataArray);

        ctx.clearRect(0, 0, canvas.width, canvas.height);
        const barWidth = (canvas.width / bufferLength) * 2;
        let x = 0;
        for (let i = 0; i < bufferLength; i++) {
          const barHeight = (dataArray[i] / 255) * canvas.height;
          ctx.fillStyle = `rgba(59, 130, 246, ${0.4 + (dataArray[i]/255)})`;
          ctx.fillRect(x, canvas.height - barHeight, barWidth - 1, barHeight);
          x += barWidth;
        }
        animFrameRef.current = requestAnimationFrame(draw);
      };
      draw();
    } else if (animFrameRef.current) {
      cancelAnimationFrame(animFrameRef.current);
    }

    return () => {
      if (animFrameRef.current) cancelAnimationFrame(animFrameRef.current);
    };
  }, [isPlaying]);

  const handleTranscribe = async () => {
    if (!note?.audioData) return;
    setIsTranscribing(true);
    addLog('info', 'Транскрибация сохраненного аудио...');
    try {
        const response = await fetch(note.audioData);
        const blob = await response.blob();
        const text = await ai.transcribeAudio(blob, settings);
        setContent(text);
        addLog('success', 'Текст обновлен из аудио');
    } catch (e: any) {
        addLog('error', 'Ошибка: ' + e.message);
    } finally {
        setIsTranscribing(false);
    }
  };

  const toggleAudio = () => {
    if (!audioRef.current) return;
    if (isPlaying) {
      audioRef.current.pause();
    } else {
      audioRef.current.play().catch(e => console.error("Playback failed", e));
    }
    setIsPlaying(!isPlaying);
  };

  const handleAudioTimeUpdate = () => {
    if (audioRef.current) {
      const progress = (audioRef.current.currentTime / audioRef.current.duration) * 100;
      setAudioProgress(progress);
    }
  };

  const handleSave = async (useAI = false) => {
    if (!content.trim() && !title.trim()) return;
    setIsSaving(true);
    if (useAI) setIsAnalyzing(true);

    try {
        if (id === 'new') {
          await addNote(content, title, 'manual', useAI);
          navigate('/');
        } else if (note) {
          const updatedNote = { ...note, title, content, tags, category, updatedAt: new Date().toISOString() };
          await updateNote(updatedNote);
          if (useAI && navigator.onLine) {
            await runAIAnalysis(note.id);
          }
        }
    } catch (e: any) {
      addLog('error', 'Ошибка при сохранении: ' + e.message);
    } finally {
        setIsSaving(false);
        setIsAnalyzing(false);
    }
  };

  const handleChatSend = async () => {
    if (!chatInput.trim() || isChatLoading) return;
    const userMsg = chatInput;
    setChatMessages(prev => [...prev, { role: 'user', content: userMsg }]);
    setChatInput('');
    setIsChatLoading(true);

    try {
      const response = await ai.chatWithNotes(userMsg, content, settings);
      setChatMessages(prev => [...prev, { role: 'assistant', content: response }]);
    } catch (e: any) {
      setChatMessages(prev => [...prev, { role: 'assistant', content: `Сбой системы: ${e.message}` }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  return (
    <div className="h-screen flex flex-col bg-white dark:bg-[#020617] overflow-hidden">
      <header className="flex items-center justify-between px-12 py-8 border-b border-gray-100 dark:border-white/5 bg-white/80 dark:bg-slate-950/80 backdrop-blur-2xl z-20 shrink-0">
        <div className="flex items-center gap-6 flex-1">
          <button onClick={() => navigate(-1)} className="p-4 text-gray-400 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-2xl transition-all">
            <ChevronLeft size={24}/>
          </button>
          <div className="flex flex-col flex-1">
              <div className="flex items-center gap-4">
                <input 
                  className="text-4xl font-extrabold bg-transparent border-none focus:outline-none text-black dark:text-white flex-1 tracking-tighter placeholder:text-gray-200" 
                  value={title} 
                  onChange={e => setTitle(e.target.value)} 
                  placeholder="Заголовок..."
                />
                <button 
                  onClick={() => ai.openInGoogle(title)}
                  className="p-3 text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-xl transition-all shadow-sm"
                  title="Найти в Google"
                >
                  <Globe size={28} strokeWidth={2.5} />
                </button>
              </div>

              {note?.audioData && (
                <div className="flex items-center gap-6 mt-6 animate-in slide-in-from-top duration-500">
