};

export const performOCR = async (base64Data: string, mimeType: string, settings: Settings) => {
  const dataOnly = base64Data.split(',')[1] || base64Data;
  return await callAI("Распознай весь видимый текст на изображении максимально точно.", settings.ocrProvider, settings.ocrModel, settings.ocrApiKey, settings.ocrUrl, false, undefined, { data: dataOnly, mimeType });
};

export const testConnection = async (settings: Settings) => {
