                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {relatedNotes.map(rn => (
                    <button 
                      key={rn.id}
                      onClick={() => navigate(`/editor/${rn.id}`)}
                      className="w-full text-left p-6 bg-white dark:bg-slate-900 rounded-[2rem] border border-gray-100 dark:border-white/5 hover:border-blue-500 transition-all group shadow-sm flex flex-col justify-between h-40"
                    >
                      <div>
                        <p className="text-sm font-black dark:text-white line-clamp-2 leading-tight mb-2">{rn.title}</p>
                        <p className="text-[10px] text-gray-400 line-clamp-2">{rn.content}</p>
                      </div>
                      <div className="flex items-center justify-between mt-4">
                        <span className="text-[8px] font-black uppercase text-blue-600 bg-blue-50 dark:bg-blue-900/20 px-2 py-0.5 rounded">
                            {rn.category}
                        </span>
                        <ArrowRight size={14} className="text-gray-300 group-hover:text-blue-500 transition-colors" />
                      </div>
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="w-[450px] border-l border-gray-100 dark:border-white/5 bg-white dark:bg-[#080c14] p-8 flex flex-col gap-8 overflow-y-auto custom-scrollbar">
          {/* 1. КАТЕГОРИЯ */}
           <div className="bg-white dark:bg-slate-900 p-8 rounded-[3rem] border border-gray-100 dark:border-white/5 shadow-sm shrink-0">
             <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-3 mb-6">
               <Folder size={16} className="text-blue-500"/> Категория
             </h4>
             <select 
               className="w-full p-6 bg-gray-50 dark:bg-slate-950 rounded-[1.8rem] font-black text-xs border-none dark:text-white cursor-pointer hover:bg-gray-100 dark:hover:bg-slate-900 transition-colors"
               value={category}
               onChange={e => setCategory(e.target.value)}
             >
                {settings.customCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
             </select>
          </div>

          {/* 2. NEURAL AI ASSISTANT */}
          <div className="bg-white dark:bg-slate-900 rounded-[3.5rem] border border-gray-100 dark:border-white/5 flex flex-col flex-1 shadow-2xl overflow-hidden min-h-[400px]">
            <header className="p-8 border-b border-gray-50 dark:border-white/5 text-[10px] font-black uppercase text-blue-500 flex items-center gap-4">
              <MessageSquare size={20}/> Neural AI Assistant
            </header>
            <div className="flex-1 p-8 overflow-y-auto space-y-6 custom-scrollbar">
              {chatMessages.map((msg, i) => (
                <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[90%] p-5 rounded-[1.8rem] text-xs font-bold leading-relaxed ${
                    msg.role === 'user' 
                      ? 'bg-blue-600 text-white shadow-xl' 
                      : 'bg-gray-50 dark:bg-slate-800 dark:text-slate-300 border border-gray-100 dark:border-white/5 shadow-sm'
                  }`}>
                    {msg.content}
                  </div>
                </div>
              ))}
              {isChatLoading && (
                <div className="flex justify-start">
                   <div className="p-5 bg-gray-50 dark:bg-slate-800 rounded-[1.8rem] border border-gray-100 dark:border-white/5">
                      <Loader2 size={16} className="animate-spin text-blue-500" />
                   </div>
                </div>
              )}
            </div>
            <div className="p-6 border-t border-gray-50 dark:border-white/5 flex gap-3">
              <input 
                className="flex-1 p-5 bg-gray-50 dark:bg-slate-950 rounded-[1.5rem] text-xs font-bold border-none dark:text-white shadow-inner"
                placeholder="Спросить..."
                value={chatInput}
                onChange={e => setChatInput(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleChatSend()}
              />
              <button 
                onClick={handleChatSend}
                disabled={!chatInput.trim() || isChatLoading}
                className="p-5 bg-blue-600 text-white rounded-[1.5rem] shadow-xl active:scale-90 transition-all disabled:opacity-30"
              >
                <Send size={18}/>
              </button>
            </div>
          </div>

          {/* 3. ТЕГИ */}
          <div className="bg-white dark:bg-slate-900 p-8 rounded-[3rem] border border-gray-100 dark:border-white/5 shadow-sm shrink-0">
            <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-3 mb-6">
              <Hash size={16} className="text-blue-500"/> Теги
            </h4>
            <div className="flex flex-wrap gap-2.5 mb-6">
              {tags.map(t => (
                <button 
                    key={t} 
                    onClick={() => { setFilterTag(t); navigate('/'); }}
                    className="px-4 py-2 bg-blue-50 text-blue-600 dark:bg-blue-900/20 dark:text-blue-400 rounded-xl text-[10px] font-black flex items-center gap-3 border border-blue-100 dark:border-blue-500/10 hover:scale-105 transition-all"
                >
                  #{t} <span onClick={(e) => { e.stopPropagation(); setTags(tags.filter(x => x !== t)); }} className="hover:text-red-500 transition-colors ml-1 p-1"><X size={10}/></span>
                </button>
              ))}
            </div>
            <div className="flex gap-2">
              <input 
                className="flex-1 p-5 bg-gray-50 dark:bg-slate-950 rounded-2xl text-xs font-bold border-none dark:text-white shadow-inner" 
                placeholder="Добавить тег..."
                value={tagInput}
                onChange={e => setTagInput(e.target.value)}
                onKeyDown={e => { if (e.key === 'Enter') handleAddTag(); }}
              />
              <button 
                onClick={handleAddTag}
                className="p-5 bg-blue-600 text-white rounded-2xl shadow-xl hover:bg-blue-700 active:scale-90 transition-all"
              >
                <Plus size={18}/>
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default NoteEditor;

import React, { useState, useMemo, useRef } from 'react';
import { useNotes } from '../contexts/NotesContext.tsx';
import { NoteStatus, Note } from '../types.ts';
import { getTagColor } from '../utils/tagColors.ts';
import { 
  Search, Trash2, Sparkles, Circle, PlayCircle, Eye, CheckCircle2, 
  FileText, Globe, Folder, Plus, LayoutGrid, List, ScanLine, Lightbulb, Send, Mic, Split, X, Loader2, AlertCircle, Bookmark, Headphones, ChevronLeft, ChevronRight, Hash
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import * as ai from '../utils/aiAdapter.ts';

const StatusIcon = ({ status, className }: { status: NoteStatus, className?: string }) => {
  switch (status) {
    case 'new': return <Circle className={`${className} text-amber-500 fill-amber-500`} size={10} />;
    case 'in-work': return <PlayCircle className={`${className} text-blue-500`} size={16} />;
    case 'read': return <Eye className={`${className} text-slate-400`} size={16} />;
    case 'finished': return <CheckCircle2 className={`${className} text-green-500`} size={16} />;
    default: return null;
  }
};

const SourceBadge = ({ type, hasAudio }: { type?: Note['sourceType'], hasAudio?: boolean }) => {
    return (
      <div className="flex items-center gap-2">
        {hasAudio && <Headphones size={12} className="text-red-500" title="Аудиозапись" />}
        {(() => {
          switch (type) {
              case 'ocr': return <ScanLine size={12} className="text-cyan-500" title="OCR" />;
              case 'split': return <Split size={12} className="text-purple-500" title="Split" />;
              case 'telegram': return <Send size={12} className="text-blue-400" title="TG" />;
              case 'audio': return <Mic size={12} className="text-red-400" title="Audio" />;
              default: return <FileText size={12} className="text-gray-400" title="Manual" />;
          }
        })()}
      </div>
    )
}

const NotesPage: React.FC = () => {
  const { notes, moveToTrash, filterTag, setFilterTag, filterCategory, setFilterCategory, setNoteStatus, settings, addCategory, deleteCategory } = useNotes();
  const navigate = useNavigate();
  const [search, setSearch] = useState('');
  const [showAddGroup, setShowAddGroup] = useState(false);
  const [newGroupName, setNewGroupName] = useState('');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const scrollRef = useRef<HTMLDivElement>(null);

  const filteredNotes = useMemo(() => notes.filter(n => {
    const query = search.toLowerCase();
    const matchesSearch = n.title.toLowerCase().includes(query) || n.content.toLowerCase().includes(query);
    const matchesTag = !filterTag || n.tags.includes(filterTag);
    const matchesCategory = !filterCategory || n.category === filterCategory;
    return matchesSearch && matchesTag && matchesCategory && n.status !== 'trash';
  }), [notes, search, filterTag, filterCategory]);

  const handleScroll = (dir: 'l' | 'r') => {
    if (scrollRef.current) {
      scrollRef.current.scrollBy({ left: dir === 'l' ? -250 : 250, behavior: 'smooth' });
    }
  };

  const handleCreateGroup = async () => {
    if (!newGroupName.trim()) return;
    await addCategory(newGroupName);
    setNewGroupName('');
    setShowAddGroup(false);
  };

  const cycleStatus = (e: React.MouseEvent, note: Note) => {
    e.stopPropagation();
    const statuses: NoteStatus[] = ['new', 'in-work', 'read', 'finished'];
    const currentIndex = statuses.indexOf(note.status);
    const nextIndex = (currentIndex + 1) % statuses.length;
    setNoteStatus(note.id, statuses[nextIndex]);
  };

  const handleTagClick = (e: React.MouseEvent, tag: string) => {
    e.stopPropagation();
    setFilterTag(tag);
  };

  return (
    <div className="p-12 max-w-7xl mx-auto min-h-screen relative pb-32 animate-in fade-in duration-700">
      <header className="flex flex-col gap-8 mb-16">
        <div className="flex flex-col md:flex-row items-end justify-between gap-8">
          <h2 className="text-6xl font-black text-slate-900 dark:text-white tracking-tighter select-none leading-none">
            Библиотека<span className="text-blue-600">.</span>
          </h2>
          <div className="flex gap-4 w-full md:w-auto">
            {filterTag && (
              <button 
                onClick={() => setFilterTag(null)}
                className="flex items-center gap-3 px-6 py-2 bg-blue-600 text-white rounded-full text-[10px] font-black uppercase tracking-widest shadow-lg animate-in zoom-in"
              >
                Тег: #{filterTag} <X size={14}/>
              </button>
            )}
            <div className="relative group flex-1 md:w-[400px]">
              <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-gray-400 group-focus-within:text-blue-500 transition-colors" size={20}/>
              <input
                type="text"
                placeholder="Поиск по архиву..."
                className="w-full pl-16 pr-8 py-6 bg-white dark:bg-slate-900 border border-gray-100 dark:border-white/10 rounded-[2.5rem] focus:ring-4 focus:ring-blue-500/10 font-bold text-sm shadow-xl transition-all dark:text-white"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
            </div>
            <div className="flex bg-gray-100 dark:bg-slate-800 p-2 rounded-[2.5rem]">
               <button onClick={() => setViewMode('grid')} className={`p-4 rounded-full transition-all ${viewMode === 'grid' ? 'bg-white dark:bg-slate-700 shadow-md text-blue-600' : 'text-gray-400'}`}><LayoutGrid size={24}/></button>
               <button onClick={() => setViewMode('list')} className={`p-4 rounded-full transition-all ${viewMode === 'list' ? 'bg-white dark:bg-slate-700 shadow-md text-blue-600' : 'text-gray-400'}`}><List size={24}/></button>
            </div>
          </div>
        </div>

        <div className="space-y-4">
          <div className="flex items-center justify-between px-2">
             <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
               <Folder size={12} className="text-blue-500"/> Группы Знаний
             </h4>
             <div className="flex items-center gap-4">
                <button onClick={() => handleScroll('l')} className="p-2 text-gray-400 hover:text-blue-500 transition-colors"><ChevronLeft size={20}/></button>
                <button onClick={() => handleScroll('r')} className="p-2 text-gray-400 hover:text-blue-500 transition-colors"><ChevronRight size={20}/></button>
                <div className="w-px h-4 bg-gray-200 dark:bg-slate-800 mx-2" />
                <button onClick={() => setShowAddGroup(true)} className="text-[10px] font-black text-blue-600 uppercase flex items-center gap-2 hover:opacity-70 transition-opacity">
                    <Plus size={12}/> Новая Группа
                </button>
             </div>
          </div>
          <div ref={scrollRef} className="flex items-center gap-4 overflow-x-auto pb-4 no-scrollbar pr-10">
             {settings.customCategories.map(cat => {
               const count = notes.filter(n => n.category === cat && n.status !== 'trash').length;
               const isActive = filterCategory === cat;
               const colors = getTagColor(cat);
               return (
                 <div key={cat} className="relative group shrink-0">
                    <button 
                      onClick={() => setFilterCategory(isActive ? null : cat)}
                      style={{ backgroundColor: isActive ? colors.border : undefined, borderColor: colors.border }}
                      className={`px-8 py-6 rounded-[2rem] border-2 transition-all flex flex-col gap-2 min-w-[180px] text-left relative overflow-hidden shadow-sm ${
                        isActive ? 'text-white shadow-lg scale-105' : 'bg-white dark:bg-slate-900 text-gray-900 dark:text-white hover:border-blue-500'
                      }`}
                    >
                        <Folder size={24} className={isActive ? 'text-white' : 'text-blue-500'} />
                        <span className="text-sm font-black uppercase tracking-tight truncate mt-2">{cat}</span>
                        <span className={`absolute top-4 right-4 text-[10px] font-black px-2 py-1 rounded-lg ${isActive ? 'bg-white/20' : 'bg-gray-100 dark:bg-slate-800'}`}>{count}</span>
                    </button>
                    {cat !== 'Общее' && (
                        <button 
                          onClick={(e) => { e.stopPropagation(); if(confirm(`Удалить группу "${cat}"? Заметки вернутся в "Общее"`)) deleteCategory(cat); }}
                          className="absolute bottom-4 right-4 p-2 bg-red-500 text-white rounded-xl opacity-0 group-hover:opacity-100 transition-all shadow-lg hover:scale-110 active:scale-90"
                        >
                            <Trash2 size={12}/>
                        </button>
                    )}
                 </div>
               );
             })}
          </div>
        </div>
      </header>

      {viewMode === 'grid' ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-12">
          {filteredNotes.map((note) => {
            const colors = getTagColor(note.category);
            return (
              <div 
                key={note.id}
                onClick={() => navigate(`/editor/${note.id}`)}
                style={{ borderColor: colors.border }}
                className="group bg-white dark:bg-slate-900 p-10 rounded-[3.5rem] border-2 transition-all cursor-pointer h-[34rem] flex flex-col shadow-xl hover:shadow-2xl hover:-translate-y-2 relative overflow-hidden"
              >
                <div className="flex items-center justify-between mb-6 mt-2">
                  <div className="flex items-center gap-3">
                    <button onClick={(e) => cycleStatus(e, note)} className="p-2.5 bg-gray-50 dark:bg-white/5 rounded-2xl hover:scale-105 transition-transform">
                        <StatusIcon status={note.status} />
                    </button>
                    <div className="p-2 bg-gray-50 dark:bg-white/5 rounded-xl">
                        <SourceBadge type={note.sourceType} hasAudio={!!note.audioData} />
                    </div>
                  </div>
                  <button 
                    onClick={(e) => { e.stopPropagation(); ai.openInGoogle(note.title); }} 
                    className="p-3 text-gray-300 hover:text-blue-500 dark:hover:text-blue-400 transition-all hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-xl"
                    title="Искать в Google"
                  >
                    <Globe size={20}/>
                  </button>
                </div>

                {/* Улучшенная видимость заголовка: font-black, text-3xl и высокий контраст */}
                <h3 className="font-black text-3xl text-slate-900 dark:text-white mb-6 line-clamp-2 tracking-tight leading-snug drop-shadow-sm">
                  {note.title || "Без названия"}
                </h3>

                {note.summary && (
                  <div style={{ backgroundColor: colors.bg, borderColor: colors.border }} className="mb-6 p-5 rounded-3xl border-l-4 relative">
                      <Sparkles size={12} className="absolute -top-2 -left-2 text-blue-500 bg-white dark:bg-slate-900 rounded-full p-0.5" />
                      <p style={{ color: colors.text }} className="text-xs font-bold italic line-clamp-2 leading-relaxed">{note.summary}</p>
                  </div>
                )}

                <div className="text-[14px] text-gray-600 dark:text-slate-400 leading-relaxed line-clamp-4 font-medium mb-10 overflow-hidden">
                  {note.content}
                </div>

                <div className="flex flex-wrap gap-2 mb-6">
                    {note.tags.slice(0, 5).map(tag => (
                        <button 
                            key={tag}
                            onClick={(e) => handleTagClick(e, tag)}
                            className="px-3 py-1 bg-blue-50/50 dark:bg-blue-900/20 text-[10px] font-black uppercase tracking-widest text-blue-600 dark:text-blue-400 border border-blue-500/10 rounded-lg hover:bg-blue-600 hover:text-white transition-all shadow-sm active:scale-95"
                        >
                            #{tag}
                        </button>
                    ))}
                </div>

                <div className="pt-8 border-t border-gray-100 dark:border-white/5 flex items-center justify-between mt-auto">
                    <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                        <Bookmark size={12} className="text-blue-500" />
                        {new Date(note.createdAt).toLocaleDateString()}
                    </span>
                    <button onClick={(e) => { e.stopPropagation(); moveToTrash(note.id); }} className="text-gray-300 hover:text-red-500 transition-all active:scale-90"><Trash2 size={20}/></button>
                </div>
              </div>
            );
          })}
        </div>
      ) : (
        <div className="space-y-4">
          {filteredNotes.map(note => {
             const colors = getTagColor(note.category);
             return (
                <div key={note.id} onClick={() => navigate(`/editor/${note.id}`)} style={{ borderColor: colors.border }} className="bg-white dark:bg-slate-900 p-8 rounded-[2rem] border-2 border-transparent hover:border-blue-500 flex items-center gap-8 group cursor-pointer transition-all shadow-sm">
                  <button onClick={(e) => cycleStatus(e, note)} className="shrink-0"><StatusIcon status={note.status}/></button>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-3">
                       <h3 className="text-2xl font-black text-slate-900 dark:text-white truncate">{note.title || "Без названия"}</h3>
                       <SourceBadge type={note.sourceType} hasAudio={!!note.audioData} />
                    </div>
                    <div className="flex gap-2 mt-1">
                        {note.tags.slice(0, 3).map(tag => (
                            <span key={tag} onClick={(e) => handleTagClick(e, tag)} className="text-[8px] font-black text-gray-400 uppercase hover:text-blue-500 transition-colors">#{tag}</span>
                        ))}
                    </div>
                  </div>
                  <div className="flex items-center gap-4">
                     <button onClick={(e) => { e.stopPropagation(); ai.openInGoogle(note.title); }} className="p-3 text-gray-300 hover:text-blue-500 transition-colors"><Globe size={18}/></button>
                     <button onClick={(e) => { e.stopPropagation(); moveToTrash(note.id); }} className="p-4 text-gray-300 hover:text-red-500 transition-colors"><Trash2 size={18}/></button>
                  </div>
                </div>
             );
          })}
        </div>
      )}

      {showAddGroup && (
        <div className="fixed inset-0 bg-slate-950/70 backdrop-blur-xl z-[150] flex items-center justify-center p-6 animate-in fade-in duration-300">
          <div className="bg-white dark:bg-slate-900 w-full max-w-md rounded-[3rem] p-10 shadow-2xl border border-white/10">
            <h3 className="text-3xl font-black dark:text-white uppercase mb-6 flex items-center gap-3 tracking-tighter">Новая Группа</h3>
            <input 
              autoFocus className="w-full p-6 bg-gray-50 dark:bg-slate-950 border-none rounded-2xl font-black text-xl dark:text-white shadow-inner"
              placeholder="Название..."
              value={newGroupName}
              onChange={e => setNewGroupName(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && handleCreateGroup()}
            />
            <div className="flex gap-4 mt-8">
               <button onClick={() => setShowAddGroup(false)} className="flex-1 py-5 bg-gray-100 dark:bg-slate-800 rounded-2xl font-black uppercase text-[10px] tracking-widest dark:text-white">Отмена</button>
               <button onClick={handleCreateGroup} className="flex-1 py-5 bg-blue-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-xl shadow-blue-500/20 active:scale-95 transition-all">Создать</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

