import React, { useState, useEffect, useRef, useMemo } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useNotes } from '../contexts/NotesContext.tsx';
import { Note } from '../types.ts';
import { getTagColor } from '../utils/tagColors.ts';
import { 
  ChevronLeft, Save, Loader2, Sparkles, MessageSquare, Send, X, Folder, Globe, Hash, Play, Pause, Headphones, Volume2, Search, ExternalLink, Link2, ArrowRight, Plus
} from 'lucide-react';
import * as ai from '../utils/aiAdapter.ts';

const NoteEditor: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { notes, addNote, updateNote, runAIAnalysis, settings, addLog, setFilterTag } = useNotes();

  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [tags, setTags] = useState<string[]>([]);
  const [category, setCategory] = useState('Общее');
  const [tagInput, setTagInput] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [note, setNote] = useState<Note | null>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatMessages, setChatMessages] = useState<{role: 'user' | 'assistant', content: string}[]>([]);
  const [isChatLoading, setIsChatLoading] = useState(false);

  const [isPlaying, setIsPlaying] = useState(false);
  const [audioProgress, setAudioProgress] = useState(0);
  const [isTranscribing, setIsTranscribing] = useState(false);

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const visualizerCanvasRef = useRef<HTMLCanvasElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const animFrameRef = useRef<number | null>(null);

  useEffect(() => {
    if (id && id !== 'new') {
      const found = notes.find(n => n.id === id);
      if (found) {
        setNote(found);
        setTitle(found.title);
        setContent(found.content);
        setTags(found.tags || []);
        setCategory(found.category || 'Общее');

        if (found.summary && chatMessages.length === 0) {
            setChatMessages([{ role: 'assistant', content: `Краткий анализ: ${found.summary}` }]);
        }
      }
    }
  }, [id, notes]);

  const relatedNotes = useMemo(() => {
    if (!id || id === 'new') return [];
    return notes.filter(n => {
        if (n.id === id || n.status === 'trash') return false;
        const sameCategory = n.category === category;
        const commonTags = n.tags.some(t => tags.includes(t));
        return sameCategory || commonTags;
    }).slice(0, 6);
  }, [id, notes, category, tags]);

  const handleAddTag = () => {
    const val = tagInput.trim();
    if (val && !tags.includes(val)) {
      setTags([...tags, val]);
      setTagInput('');
    }
  };

  useEffect(() => {
    if (isPlaying && !audioContextRef.current && audioRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      analyserRef.current = audioContextRef.current.createAnalyser();
      analyserRef.current.fftSize = 128;
      const source = audioContextRef.current.createMediaElementSource(audioRef.current);
      source.connect(analyserRef.current);
      analyserRef.current.connect(audioContextRef.current.destination);
    }

    if (isPlaying) {
      const draw = () => {
        const canvas = visualizerCanvasRef.current;
        const analyser = analyserRef.current;
        if (!canvas || !analyser) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;
        const bufferLength = analyser.frequencyBinCount;
        const dataArray = new Uint8Array(bufferLength);
        analyser.getByteFrequencyData(dataArray);
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        const barWidth = (canvas.width / bufferLength) * 2;
        let x = 0;
        for (let i = 0; i < bufferLength; i++) {
          const barHeight = (dataArray[i] / 255) * canvas.height;
          ctx.fillStyle = `rgba(59, 130, 246, ${0.4 + (dataArray[i]/255)})`;
          ctx.fillRect(x, canvas.height - barHeight, barWidth - 1, barHeight);
          x += barWidth;
        }
        animFrameRef.current = requestAnimationFrame(draw);
      };
      draw();
    } else if (animFrameRef.current) {
      cancelAnimationFrame(animFrameRef.current);
    }
    return () => { if (animFrameRef.current) cancelAnimationFrame(animFrameRef.current); };
  }, [isPlaying]);

  const handleTranscribe = async () => {
    if (!note?.audioData) return;
    setIsTranscribing(true);
    try {
        const response = await fetch(note.audioData);
        const blob = await response.blob();
        const text = await ai.transcribeAudio(blob, settings);
        setContent(text);
        addLog('success', 'Текст обновлен из аудио');
    } catch (e: any) {
        addLog('error', 'Ошибка: ' + e.message);
    } finally {
        setIsTranscribing(false);
    }
  };

  const handleAudioTimeUpdate = () => {
    if (audioRef.current) {
      const progress = (audioRef.current.currentTime / audioRef.current.duration) * 100;
      setAudioProgress(isNaN(progress) ? 0 : progress);
    }
  };

  const toggleAudio = () => {
    if (!audioRef.current) return;
    if (isPlaying) audioRef.current.pause();
    else audioRef.current.play().catch(e => console.error("Playback failed", e));
    setIsPlaying(!isPlaying);
  };

  const handleSave = async (useAI = false) => {
    if (!content.trim() && !title.trim()) return;
    setIsSaving(true);
    if (useAI) setIsAnalyzing(true);
    try {
        if (id === 'new') {
          await addNote(content, title, 'manual', useAI);
          navigate('/');
        } else if (note) {
          const updatedNote = { ...note, title, content, tags, category, updatedAt: new Date().toISOString() };
          await updateNote(updatedNote);
          if (useAI && navigator.onLine) {
            await runAIAnalysis(note.id);
          }
          // Возвращаемся в библиотеку после сохранения
          navigate('/');
        }
    } catch (e: any) {
      addLog('error', 'Ошибка при сохранении: ' + e.message);
    } finally {
        setIsSaving(false);
        setIsAnalyzing(false);
    }
  };

  const handleChatSend = async () => {
    if (!chatInput.trim() || isChatLoading) return;
    const userMsg = chatInput;
    setChatMessages(prev => [...prev, { role: 'user', content: userMsg }]);
    setChatInput('');
    setIsChatLoading(true);
    try {
      const response = await ai.chatWithNotes(userMsg, content, settings);
      setChatMessages(prev => [...prev, { role: 'assistant', content: response }]);
    } catch (e: any) {
      setChatMessages(prev => [...prev, { role: 'assistant', content: `Сбой системы: ${e.message}` }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  return (
    <div className="h-screen flex flex-col bg-white dark:bg-[#020617] overflow-hidden">
      <header className="flex items-center justify-between px-12 py-8 border-b border-gray-100 dark:border-white/5 bg-white/80 dark:bg-slate-950/80 backdrop-blur-2xl z-20 shrink-0">
        <div className="flex items-center gap-6 flex-1">
          <button onClick={() => navigate(-1)} className="p-4 text-gray-400 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-2xl transition-all">
            <ChevronLeft size={24}/>
          </button>
          <div className="flex flex-col flex-1">
              <div className="flex items-center gap-4">
                <input 
                  className="text-4xl font-extrabold bg-transparent border-none focus:outline-none text-black dark:text-white flex-1 tracking-tighter placeholder:text-gray-200" 
                  value={title} 
                  onChange={e => setTitle(e.target.value)} 
                  placeholder="Заголовок..."
                />
                <button 
                  onClick={() => ai.openInGoogle(title)}
                  className="p-3 text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-xl transition-all shadow-sm"
                  title="Найти в Google"
                >
                  <Globe size={28} strokeWidth={2.5} />
                </button>
              </div>
              {note?.audioData && (
                <div className="flex items-center gap-6 mt-6 animate-in slide-in-from-top duration-500">
                  <div className="flex items-center gap-4 px-6 py-4 bg-gray-50 dark:bg-slate-900/50 rounded-[2.5rem] border border-gray-100 dark:border-white/10 shadow-sm">
                    <button onClick={toggleAudio} className="w-12 h-12 bg-blue-600 text-white rounded-full flex items-center justify-center hover:scale-105 transition-all shadow-lg active:scale-95">
                      {isPlaying ? <Pause size={20} fill="currentColor"/> : <Play size={20} fill="currentColor" className="ml-1"/>}
                    </button>
                    <div className="flex items-center h-8 w-24 px-1 bg-white/40 dark:bg-black/20 rounded-full overflow-hidden">
                        <canvas ref={visualizerCanvasRef} width={100} height={32} className="w-full h-full" />
                    </div>
                    <div className="w-48 h-2 bg-gray-200 dark:bg-slate-700 rounded-full overflow-hidden relative shadow-inner">
                       <div className="absolute inset-y-0 left-0 bg-blue-500 transition-all duration-300" style={{ width: `${audioProgress}%` }} />
                    </div>
                    <audio ref={audioRef} src={note.audioData} crossOrigin="anonymous" onTimeUpdate={handleAudioTimeUpdate} onEnded={() => setIsPlaying(false)} className="hidden" />
                  </div>
                  <button disabled={isTranscribing} onClick={handleTranscribe} className="flex items-center gap-3 px-8 py-4 bg-purple-600/10 text-purple-600 rounded-[2.5rem] text-[10px] font-black uppercase tracking-widest border border-purple-500/20 hover:bg-purple-600/20 transition-all disabled:opacity-50">
                      {isTranscribing ? <Loader2 size={16} className="animate-spin" /> : <Sparkles size={16}/>}
                      Распознать
                  </button>
                </div>
              )}
          </div>
        </div>
        <div className="flex items-center gap-4">
          <button onClick={() => handleSave(true)} className="px-8 py-5 bg-cyan-600/10 text-cyan-600 dark:text-cyan-400 rounded-[2rem] font-black uppercase text-[10px] tracking-widest flex items-center gap-3 border border-cyan-500/10">
            {isAnalyzing ? <Loader2 size={18} className="animate-spin"/> : <Sparkles size={18}/>}
            AI Анализ
          </button>
          <button onClick={() => handleSave(false)} className="px-10 py-5 bg-blue-600 text-white rounded-[2rem] font-black uppercase text-[10px] tracking-widest shadow-xl flex items-center gap-3 active:scale-95 transition-all">
            {isSaving ? <Loader2 size={18} className="animate-spin"/> : <Save size={18}/>}
            Сохранить
          </button>
        </div>
      </header>

      <div className="flex-1 flex overflow-hidden">
        <div className="flex-1 overflow-y-auto custom-scrollbar bg-gray-50/5 p-12 lg:p-24 pb-48">
          <div className="max-w-5xl mx-auto w-full space-y-16">
            <textarea 
              className="w-full h-auto min-h-[400px] bg-transparent border-none focus:outline-none text-2xl leading-relaxed text-gray-800 dark:text-slate-200 resize-none font-medium placeholder:text-gray-200"
              value={content}
              onChange={e => setContent(e.target.value)}
              placeholder="Напишите историю или распознайте голос..."
            />

            {relatedNotes.length > 0 && (
              <div className="pt-12 border-t border-gray-100 dark:border-white/5 animate-in slide-in-from-bottom duration-500">
                <h4 className="text-[12px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-3 mb-8">
                  <Link2 size={18} className="text-blue-500"/> Связанные знания
                </h4>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {relatedNotes.map(rn => (
                    <button 
                      key={rn.id}
                      onClick={() => navigate(`/editor/${rn.id}`)}
                      className="w-full text-left p-6 bg-white dark:bg-slate-900 rounded-[2rem] border border-gray-100 dark:border-white/5 hover:border-blue-500 transition-all group shadow-sm flex flex-col justify-between h-40"
                    >
                      <div>
                        <p className="text-sm font-black dark:text-white line-clamp-2 leading-tight mb-2">{rn.title}</p>
                        <p className="text-[10px] text-gray-400 line-clamp-2">{rn.content}</p>
                      </div>
                      <div className="flex items-center justify-between mt-4">
                        <span className="text-[8px] font-black uppercase text-blue-600 bg-blue-50 dark:bg-blue-900/20 px-2 py-0.5 rounded">
                            {rn.category}
                        </span>
                        <ArrowRight size={14} className="text-gray-300 group-hover:text-blue-500 transition-colors" />
                      </div>
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="w-[450px] border-l border-gray-100 dark:border-white/5 bg-white dark:bg-[#080c14] p-8 flex flex-col gap-8 overflow-y-auto custom-scrollbar">
          {/* 1. КАТЕГОРИЯ */}
           <div className="bg-white dark:bg-slate-900 p-8 rounded-[3rem] border border-gray-100 dark:border-white/5 shadow-sm shrink-0">
             <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-3 mb-6">
               <Folder size={16} className="text-blue-500"/> Категория
             </h4>
             <select 
               className="w-full p-6 bg-gray-50 dark:bg-slate-950 rounded-[1.8rem] font-black text-xs border-none dark:text-white cursor-pointer hover:bg-gray-100 dark:hover:bg-slate-900 transition-colors"
               value={category}
               onChange={e => setCategory(e.target.value)}
             >
                {settings.customCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
             </select>
          </div>

          {/* 2. NEURAL AI ASSISTANT */}
          <div className="bg-white dark:bg-slate-900 rounded-[3.5rem] border border-gray-100 dark:border-white/5 flex flex-col flex-1 shadow-2xl overflow-hidden min-h-[400px]">
            <header className="p-8 border-b border-gray-50 dark:border-white/5 text-[10px] font-black uppercase text-blue-500 flex items-center gap-4">
              <MessageSquare size={20}/> Neural AI Assistant
            </header>
            <div className="flex-1 p-8 overflow-y-auto space-y-6 custom-scrollbar">
              {chatMessages.map((msg, i) => (
                <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[90%] p-5 rounded-[1.8rem] text-xs font-bold leading-relaxed ${
                    msg.role === 'user' 
                      ? 'bg-blue-600 text-white shadow-xl' 
                      : 'bg-gray-50 dark:bg-slate-800 dark:text-slate-300 border border-gray-100 dark:border-white/5 shadow-sm'
                  }`}>
                    {msg.content}
                  </div>
                </div>
              ))}
              {isChatLoading && (
                <div className="flex justify-start">
                   <div className="p-5 bg-gray-50 dark:bg-slate-800 rounded-[1.8rem] border border-gray-100 dark:border-white/5">
                      <Loader2 size={16} className="animate-spin text-blue-500" />
                   </div>
                </div>
              )}
            </div>
            <div className="p-6 border-t border-gray-50 dark:border-white/5 flex gap-3">
              <input 
                className="flex-1 p-5 bg-gray-50 dark:bg-slate-950 rounded-[1.5rem] text-xs font-bold border-none dark:text-white shadow-inner"
                placeholder="Спросить..."
                value={chatInput}
                onChange={e => setChatInput(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleChatSend()}
              />
              <button 
                onClick={handleChatSend}
                disabled={!chatInput.trim() || isChatLoading}
                className="p-5 bg-blue-600 text-white rounded-[1.5rem] shadow-xl active:scale-90 transition-all disabled:opacity-30"
              >
                <Send size={18}/>
              </button>
            </div>
          </div>

          {/* 3. ТЕГИ */}
          <div className="bg-white dark:bg-slate-900 p-8 rounded-[3rem] border border-gray-100 dark:border-white/5 shadow-sm shrink-0">
            <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-3 mb-6">
              <Hash size={16} className="text-blue-500"/> Теги
            </h4>
            <div className="flex flex-wrap gap-2.5 mb-6">
              {tags.map(t => (
                <button 
                    key={t} 
                    onClick={() => { setFilterTag(t); navigate('/'); }}
                    className="px-4 py-2 bg-blue-50 text-blue-600 dark:bg-blue-900/20 dark:text-blue-400 rounded-xl text-[10px] font-black flex items-center gap-3 border border-blue-100 dark:border-blue-500/10 hover:scale-105 transition-all"
                >
                  #{t} <span onClick={(e) => { e.stopPropagation(); setTags(tags.filter(x => x !== t)); }} className="hover:text-red-500 transition-colors ml-1 p-1"><X size={10}/></span>
                </button>
              ))}
            </div>
            <div className="flex gap-2">
              <input 
                className="flex-1 p-5 bg-gray-50 dark:bg-slate-950 rounded-2xl text-xs font-bold border-none dark:text-white shadow-inner" 
                placeholder="Добавить тег..."
                value={tagInput}
                onChange={e => setTagInput(e.target.value)}
                onKeyDown={e => { if (e.key === 'Enter') handleAddTag(); }}
              />
              <button 
                onClick={handleAddTag}
                className="p-5 bg-blue-600 text-white rounded-2xl shadow-xl hover:bg-blue-700 active:scale-90 transition-all"
              >
                <Plus size={18}/>
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

