              <Scissors size={32} className="text-purple-500"/> Smart Text Splitter
            </h3>
            <p className="text-gray-400 font-bold text-sm mb-10 leading-relaxed max-w-2xl">
              Вставьте лонгрид, книгу или длинную статью. ИИ проанализирует контекст и разделит его на серию осмысленных карточек с заголовками и категориями.
            </p>
            <textarea 
              className="w-full h-[350px] p-8 bg-gray-50 dark:bg-slate-950 border-none rounded-[2.5rem] font-medium text-lg dark:text-white shadow-inner resize-none focus:ring-4 focus:ring-purple-500/10 transition-all outline-none"
              placeholder="Вставьте ваш огромный текст здесь..."
              value={splitText}
              onChange={e => setSplitText(e.target.value)}
            />
            <div className="flex gap-4 mt-12">
               <button 
                onClick={handleSplitSubmit}
                disabled={isSplitting || !splitText.trim()}
                className="flex-1 py-7 bg-purple-600 text-white rounded-[2.5rem] font-black uppercase text-xs tracking-widest shadow-xl shadow-purple-500/20 active:scale-95 transition-all flex items-center justify-center gap-4 disabled:opacity-30"
               >
                 {isSplitting ? <Loader2 size={22} className="animate-spin"/> : <Sparkles size={22}/>}
                 Разрезать и импортировать в базу
               </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

