                  className="w-full p-5 bg-gray-50 dark:bg-slate-950 rounded-[1.5rem] font-bold text-xs border-none dark:text-white shadow-inner cursor-pointer"
                  value={value}
                  onChange={e => onProviderChange(e.target.value as AIProvider)}
                >
                  {Object.values(AIProvider).map(p => <option key={p} value={p}>{p}</option>)}
                </select>
            </div>
            {showUrl && !isGemini && (
              <div className="space-y-3">
                  <label className="text-[10px] font-black text-gray-400 uppercase ml-4 tracking-widest">URL Сервера</label>
                  <input 
                    type="text" className="w-full p-5 bg-gray-50 dark:bg-slate-950 rounded-[1.5rem] font-mono text-[11px] border-none dark:text-white shadow-inner"
                    value={urlValue} onChange={e => onUrlChange(e.target.value)}
                    placeholder="http://localhost:11434"
                  />
              </div>
            )}
          </div>
          <div className="space-y-6">
            <div className="space-y-3">
                <label className="text-[10px] font-black text-gray-400 uppercase ml-4 tracking-widest">ID Модели</label>
                <input 
                  type="text" className="w-full p-5 bg-gray-50 dark:bg-slate-950 rounded-[1.5rem] font-bold text-xs border-none dark:text-white shadow-inner"
                  value={modelValue} onChange={e => onModelChange(e.target.value)}
                  placeholder="gemini-3-flash-preview, mistral..."
                />
            </div>
          </div>
        </div>
      </section>
    );
  };

  return (
    <div className="max-w-6xl mx-auto p-12 space-y-12 pb-32 animate-in slide-in-from-bottom duration-700">
      <header className="flex items-center justify-between bg-white dark:bg-slate-900 p-10 rounded-[4rem] border border-gray-100 dark:border-slate-800 shadow-xl">
        <div className="flex items-center gap-8">
          <div className="p-7 bg-blue-600 text-white rounded-[2.5rem] shadow-2xl shadow-blue-500/30"><SettingsIcon size={40}/></div>
          <div>
            <h2 className="text-5xl font-black dark:text-white tracking-tighter leading-none">Система</h2>
            <p className="text-[11px] font-black text-blue-600 uppercase tracking-[0.4em] mt-3 flex items-center gap-2">
                <Activity size={12}/> Diagnostic Interface v3.5
            </p>
          </div>
        </div>
        <div className="flex gap-4">
          <button 
            onClick={handleReanalyze} 
            disabled={isReanalyzing} 
            className="px-8 py-5 bg-amber-50 text-amber-600 dark:bg-amber-900/10 dark:text-amber-400 rounded-[2rem] font-black text-[11px] uppercase flex items-center gap-3 hover:bg-amber-100 transition-all active:scale-95 shadow-lg shadow-amber-500/5"
            title="Принудительный ИИ-анализ всех параметров для каждого файла в базе"
          >
            {isReanalyzing ? <RefreshCw size={18} className="animate-spin" /> : <Database size={18}/>} Глубокий Реиндекс ИИ
          </button>
          <button onClick={runSystemCheck} className="px-10 py-5 bg-blue-600 text-white rounded-[2rem] font-black text-[11px] uppercase shadow-2xl shadow-blue-500/20 hover:scale-105 active:scale-95 transition-all flex items-center gap-3">
            <Zap size={18}/> Тест Провайдеров
          </button>
        </div>
      </header>

      <div className="space-y-10">
        <ProviderSelector 
          label="ИИ Аналитик (Brain)" icon={Cpu}
          value={localSettings.provider} onProviderChange={(v: any) => setLocalSettings({...localSettings, provider: v})}
          urlValue={localSettings.url} onUrlChange={(v: any) => setLocalSettings({...localSettings, url: v})}
          modelValue={localSettings.model} onModelChange={(v: any) => setLocalSettings({...localSettings, model: v})}
        />

        <ProviderSelector 
          label="Vision Intelligence (OCR)" icon={ScanLine}
          value={localSettings.ocrProvider} onProviderChange={(v: any) => setLocalSettings({...localSettings, ocrProvider: v})}
          urlValue={localSettings.ocrUrl} onUrlChange={(v: any) => setLocalSettings({...localSettings, ocrUrl: v})}
          modelValue={localSettings.ocrModel} onModelChange={(v: any) => setLocalSettings({...localSettings, ocrModel: v})}
        />

        <ProviderSelector 
          label="Voice-to-Text Engine" icon={Mic}
          value={localSettings.transProvider} onProviderChange={(v: any) => setLocalSettings({...localSettings, transProvider: v})}
          urlValue={localSettings.transUrl} onUrlChange={(v: any) => setLocalSettings({...localSettings, transUrl: v})}
          modelValue={localSettings.transModel} onModelChange={(v: any) => setLocalSettings({...localSettings, transModel: v})}
        />

        <ProviderSelector 
          label="Neural Assistant" icon={Bot}
          value={localSettings.agentProvider} onProviderChange={(v: any) => setLocalSettings({...localSettings, agentProvider: v})}
          urlValue={localSettings.agentUrl} onUrlChange={(v: any) => setLocalSettings({...localSettings, agentUrl: v})}
          modelValue={localSettings.agentModel} onModelChange={(v: any) => setLocalSettings({...localSettings, agentModel: v})}
        />

        {/* Telegram Bridge Settings */}
        <section className="bg-white dark:bg-slate-900 p-12 rounded-[4rem] border border-gray-100 dark:border-slate-800 space-y-10 shadow-sm">
            <div className="flex items-center justify-between px-2">
                <h3 className="font-black text-[11px] uppercase tracking-widest flex items-center gap-4 text-gray-400">
                    <Send size={20} className="text-blue-500"/> Telegram Bridge Configuration
                </h3>
                <a href="https://t.me/BotFather" target="_blank" className="flex items-center gap-2 text-[10px] font-black text-blue-600 uppercase hover:underline">
                    Create Bot <ExternalLink size={12}/>
                </a>
            </div>

            <div className="bg-blue-50/50 dark:bg-blue-900/10 p-8 rounded-[2.5rem] border border-blue-100 dark:border-blue-900/30">
                <h4 className="text-[10px] font-black text-blue-600 uppercase tracking-widest mb-4 flex items-center gap-2">
                    <Info size={14}/> Инструкция по запуску
                </h4>
                <ol className="text-xs space-y-3 text-gray-600 dark:text-slate-400 font-bold leading-relaxed">
                    <li>1. Создайте бота через <span className="text-blue-600">@BotFather</span> и получите API Token.</li>
                    <li>2. Напишите что-нибудь своему новому боту в Telegram.</li>
                    <li>3. Вставьте Token ниже. Нажмите "Применить".</li>
                    <li>4. Чтобы узнать свой Chat ID, отправьте боту любое сообщение и нажмите "Синхронизировать" в Inbox — ваш ID будет в логах.</li>
                </ol>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                <div className="space-y-4">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-4">Bot API Token</label>
                    <input 
                      type="password"
                      className="w-full p-6 bg-gray-50 dark:bg-slate-950 rounded-[2rem] font-mono text-[11px] border-none dark:text-white shadow-inner focus:ring-4 focus:ring-blue-500/10 transition-all"
                      placeholder="123456789:ABCDE-FGHIJK..."
                      value={localSettings.tgToken}
                      onChange={e => setLocalSettings({...localSettings, tgToken: e.target.value})}
                    />
                </div>
                <div className="space-y-4">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-4">Admin Chat ID (Private)</label>
                    <input 
                      type="text"
                      className="w-full p-6 bg-gray-50 dark:bg-slate-950 rounded-[2rem] font-black text-xs border-none dark:text-white shadow-inner focus:ring-4 focus:ring-blue-500/10 transition-all"
                      placeholder="Например: 12345678"
                      value={localSettings.tgChatId}
                      onChange={e => setLocalSettings({...localSettings, tgChatId: e.target.value})}
                    />
                    <p className="text-[9px] text-gray-400 font-bold italic ml-4">Оставьте пустым для приема от всех, или укажите свой ID для безопасности.</p>
                </div>
            </div>
        </section>

        {/* Секция Логов */}
        <section className="bg-white dark:bg-slate-900 p-12 rounded-[4rem] border border-gray-100 dark:border-slate-800 space-y-8 shadow-sm">
           <div className="flex items-center justify-between px-2">
              <h3 className="font-black text-[11px] uppercase tracking-widest flex items-center gap-4 text-gray-400">
                  <Terminal size={22} className="text-blue-500"/> Журнал Диагностики
              </h3>
              <div className="flex items-center gap-6">
                <button 
                  onClick={() => setShowLogs(!showLogs)} 
                  className="text-[10px] font-black text-blue-500 uppercase flex items-center gap-2 hover:opacity-70 transition-opacity"
                >
                  {showLogs ? 'Скрыть историю' : 'Показать историю'} <ListFilter size={16}/>
                </button>
                <button onClick={() => storage.exportData()} className="p-3 bg-gray-50 dark:bg-slate-800 rounded-xl text-gray-400 hover:text-blue-500 transition-colors" title="Скачать бэкап">
                  <Download size={18}/>
                </button>
              </div>
           </div>

           {showLogs && (
             <div className="space-y-4 max-h-[450px] overflow-y-auto custom-scrollbar pr-6">
                {logs.length === 0 ? (
                  <div className="flex flex-col items-center justify-center py-16 text-gray-300 opacity-50">
                    <Info size={48} className="mb-4" />
                    <p className="text-center font-bold uppercase text-[10px] tracking-[0.3em]">Журнал событий пока пуст</p>
                  </div>
                ) : (
                  logs.map(log => (
                    <div key={log.id} className={`flex gap-5 p-6 rounded-[2rem] border animate-in slide-in-from-left duration-300 shadow-sm ${
                        log.level === 'error' ? 'bg-red-50/50 dark:bg-red-950/20 border-red-100' : 'bg-gray-50 dark:bg-slate-950/40 border-gray-100'
                    }`}>
                       <div className="mt-1">
                          {log.level === 'success' ? <CheckCircle2 className="text-green-500" size={20}/> : 
                           log.level === 'error' ? <AlertCircle className="text-red-500" size={20}/> : 
                           log.level === 'warn' ? <AlertCircle className="text-amber-500" size={20}/> : 
                           <Info className="text-blue-500" size={20}/>}
                       </div>
                       <div className="flex-1 min-w-0">
                          <p className={`text-sm font-black tracking-tight leading-tight ${log.level === 'error' ? 'text-red-600' : 'dark:text-white'}`}>
                            {log.message}
                          </p>
                          <div className="flex items-center gap-4 mt-3">
                             <span className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">
                                {new Date(log.timestamp).toLocaleTimeString()}
                             </span>
                             {log.details && <span className="text-[10px] text-gray-400 truncate max-w-lg italic font-medium">| {log.details}</span>}
                          </div>
                       </div>
                    </div>
                  ))
                )}
             </div>
           )}
        </section>
      </div>

      <div className="flex justify-center pb-20 pt-8">
        <button 
            onClick={() => {
                updateSettings(localSettings);
                addLog('success', 'Настройки системы применены и сохранены локально');
            }}
            className="px-32 py-8 bg-blue-600 text-white rounded-[3rem] font-black uppercase text-xs shadow-2xl shadow-blue-500/30 hover:scale-105 active:scale-95 transition-all tracking-[0.3em] border border-blue-400/20"
        >
            Сохранить изменения
        </button>
      </div>
    </div>
  );
};

export default SettingsPage;

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Note, Settings, AIProvider, AppLog, NoteStatus, TelegramMessage, Goal } from '../types.ts';
import * as storage from '../utils/storage.ts';
import * as ai from '../utils/aiAdapter.ts';

interface NotesContextType {
  notes: Note[];
  goals: Goal[];
  settings: Settings;
  isLoading: boolean;
  logs: AppLog[];
  filterTag: string | null;
  filterCategory: string | null;
  telegramMessages: any[]; 
  setFilterTag: (tag: string | null) => void;
  setFilterCategory: (cat: string | null) => void;
  addNote: (content: string, title?: string, sourceType?: Note['sourceType'], useAI?: boolean, category?: string, audioData?: string) => Promise<void>;
  processLargeText: (text: string) => Promise<void>;
  updateNote: (note: Note) => Promise<void>;
  moveToTrash: (id: string) => Promise<void>;
  restoreNote: (id: string) => Promise<void>;
  hardDelete: (id: string) => Promise<void>;
  setNoteStatus: (id: string, status: NoteStatus) => Promise<void>;
  updateSettings: (s: Settings) => Promise<void>;
  addLog: (level: AppLog['level'], message: string, details?: string) => void;
  runAIAnalysis: (id: string) => Promise<void>;
  reanalyzeAll: () => Promise<void>;
  runSystemCheck: () => Promise<void>;
  updateNotePosition: (id: string, x: number, y: number) => Promise<void>;
  updateNoteSize: (id: string, w: number, h: number) => Promise<void>;
  syncTelegram: () => Promise<void>;
  deleteTelegramMsg: (id: number) => void;
  addGoal: (title: string, description: string) => Promise<void>;
  toggleGoalStatus: (id: string) => Promise<void>;
  deleteGoal: (id: string) => Promise<void>;
  addCategory: (name: string) => Promise<void>;
  deleteCategory: (name: string) => Promise<void>;
}

const NotesContext = createContext<NotesContextType | undefined>(undefined);

export const NotesProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [notes, setNotes] = useState<Note[]>([]);
  const [goals, setGoals] = useState<Goal[]>([]);
  const [settings, setSettings] = useState<Settings>(storage.getDefaultSettings());
  const [isLoading, setIsLoading] = useState(true);
  const [logs, setLogs] = useState<AppLog[]>([]);
  const [filterTag, setFilterTag] = useState<string | null>(null);
  const [filterCategory, setFilterCategory] = useState<string | null>(null);
  const [telegramMessages, setTelegramMessages] = useState<any[]>([]);

  const addLog = (level: AppLog['level'], message: string, details?: string) => {
    setLogs(prev => [{ id: crypto.randomUUID(), timestamp: new Date().toISOString(), level, message, details }, ...prev].slice(0, 50));
  };

  useEffect(() => {
    const init = async () => {
      const [n, s, g] = await Promise.all([storage.getNotes(), storage.getSettings(), storage.getGoals()]);
      setNotes(n);
      setSettings(s);
      setGoals(g || []);
      setIsLoading(false);
      document.documentElement.classList.toggle('dark', s.theme === 'dark');
    };
    init();
  }, []);

  const syncTelegram = async () => {
    if (!settings.tgToken) {
      addLog('warn', 'Telegram Token не настроен');
      return;
    }
    try {
      const offset = settings.tgLastUpdateId + 1;
      const response = await fetch(`https://api.telegram.org/bot${settings.tgToken}/getUpdates?offset=${offset}&timeout=5`);
      const data = await response.json();

      if (data.ok && data.result.length > 0) {
        const processedMsgs = [];
        for (const u of data.result) {
          const msg = u.message;
          if (!msg) continue;
          if (settings.tgChatId && String(msg.chat.id) !== settings.tgChatId) continue;
          let entry: any = { id: u.update_id, date: new Date(msg.date * 1000).toISOString(), from: msg.from.first_name || 'User', type: 'text', text: msg.text || msg.caption || '' };
          if (msg.photo) {
            const fileId = msg.photo[msg.photo.length - 1].file_id;
            const fileRes = await fetch(`https://api.telegram.org/bot${settings.tgToken}/getFile?file_id=${fileId}`);
            const fileData = await fileRes.json();
            if (fileData.ok) entry.type = 'photo', entry.fileUrl = `https://api.telegram.org/file/bot${settings.tgToken}/${fileData.result.file_path}`;
          } else if (msg.voice) {
            const fileId = msg.voice.file_id;
            const fileRes = await fetch(`https://api.telegram.org/bot${settings.tgToken}/getFile?file_id=${fileId}`);
            const fileData = await fileRes.json();
            if (fileData.ok) entry.type = 'voice', entry.fileUrl = `https://api.telegram.org/file/bot${settings.tgToken}/${fileData.result.file_path}`;
          }
          processedMsgs.push(entry);
        }
        const lastId = data.result[data.result.length - 1].update_id;
        const newSettings = { ...settings, tgLastUpdateId: lastId };
        setSettings(newSettings);
        await storage.saveSettings(newSettings);
        setTelegramMessages(prev => [...processedMsgs, ...prev]);
        addLog('success', `Telegram sync: +${processedMsgs.length} новых сообщений`);
      }
    } catch (e: any) {
      addLog('error', `Telegram sync failed: ${e.message}`);
    }
  };

  const deleteTelegramMsg = (id: number) => setTelegramMessages(prev => prev.filter(m => m.id !== id));

  const addNote = async (content: string, title?: string, sourceType: Note['sourceType'] = 'manual', useAI = true, forceCategory?: string, audioData?: string) => {
    let analysis: any = { tags: [], category: forceCategory || filterCategory || 'Общее', summary: '', title: title };
    let isIndexed = false;
    if (useAI && navigator.onLine) {
      addLog('info', 'ИИ анализирует новый контент...');
      try { 
        analysis = await ai.analyzeText(content, settings); 
        isIndexed = true;
      } catch (e: any) { 
        addLog('warn', `ИИ анализ пропущен: ${e.message}`); 
      }
    }
    const newNote: Note = {
      id: crypto.randomUUID(),
      title: title || analysis.title || content.slice(0, 40),
      content,
      tags: analysis.tags || [],
      category: forceCategory || analysis.category || filterCategory || 'Общее',
      summary: analysis.summary || '',
      status: 'new',
      isIndexed,
      sourceType,
      audioData,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      links: [],
      position: { x: Math.random() * 200, y: Math.random() * 200 },
      size: { w: 320, h: 280 }
    };
    const updated = [newNote, ...notes];
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const processLargeText = async (text: string) => {
    try {
      const parts = await ai.splitLargeText(text, settings);
      if (Array.isArray(parts)) {
        const generatedNotes = parts.map(part => ({
          id: crypto.randomUUID(),
          title: part.title || part.content.slice(0, 40),
          content: part.content,
          tags: [],
          category: part.category || 'Общее',
          summary: '',
          status: 'new' as NoteStatus,
          isIndexed: true,
          sourceType: 'split' as any,
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
          links: [],
          position: { x: Math.random() * 200, y: Math.random() * 200 },
          size: { w: 320, h: 280 }
        }));
        setNotes(prev => {
          const u = [...generatedNotes, ...prev];
          storage.saveNotes(u);
          return u;
        });
      }
    } catch (e: any) {
      addLog('error', `Ошибка разделения текста: ${e.message}`);
    }
  };

  const reanalyzeAll = async () => {
    addLog('info', 'Запуск ГЛУБОКОГО ИИ-РЕИНДЕКСА всей базы...');
    const currentNotes = [...notes];
    let successCount = 0;

    for (let i = 0; i < currentNotes.length; i++) {
       const note = currentNotes[i];
       if (note.status === 'trash') continue;

       try {
         addLog('info', `ИИ переосмысляет (${i + 1}/${currentNotes.length}): ${note.title}`);
         // Принудительно вызываем анализ через адаптер
         const res = await ai.analyzeText(note.content, settings);

         if (res && res.title) {
            currentNotes[i] = { 
              ...note, 
              ...res, 
              isIndexed: true, 
              updatedAt: new Date().toISOString() 
            };
            successCount++;
            // Обновляем состояние на каждой итерации для визуального фидбека
            setNotes([...currentNotes]);
         }
       } catch (e: any) { 
         addLog('warn', `Сбой анализа заметки "${note.title}": ${e.message}`);
       }
    }

    await storage.saveNotes(currentNotes);
    addLog('success', `Глубокий реиндекс завершен. Успешно обновлено: ${successCount} файлов.`);
  };

  const addGoal = async (title: string, description: string) => {
    const newGoal: Goal = { id: crypto.randomUUID(), title, description, createdAt: new Date().toISOString(), color: `hsl(${Math.random() * 360}, 70%, 50%)`, status: 'active' };
    const u = [newGoal, ...goals];
    setGoals(u);
    await storage.saveGoals(u);
  };

  const toggleGoalStatus = async (id: string) => {
    const u = goals.map(g => g.id === id ? { ...g, status: (g.status === 'active' ? 'completed' : 'active') as any } : g);
    setGoals(u);
    await storage.saveGoals(u);
  };

  const deleteGoal = async (id: string) => {
    const u = goals.filter(g => g.id !== id);
    setGoals(u);
    await storage.saveGoals(u);
  };

  const updateNote = async (n: Note) => {
    const u = notes.map(x => x.id === n.id ? n : x);
    setNotes(u);
    await storage.saveNotes(u);
  };

  const setNoteStatus = async (id: string, status: NoteStatus) => {
    const u = notes.map(n => n.id === id ? { ...n, status } : n);
    setNotes(u);
    await storage.saveNotes(u);
  };

  const moveToTrash = async (id: string) => {
    const u = notes.map(n => n.id === id ? { ...n, status: 'trash' as NoteStatus } : n);
    setNotes(u);
    await storage.saveNotes(u);
  };

  const addCategory = async (name: string) => {
    if (settings.customCategories.includes(name)) return;
    const s = { ...settings, customCategories: [...settings.customCategories, name] };
    await updateSettings(s);
  };

  const deleteCategory = async (name: string) => {
    if (name === 'Общее') return;
    const s = { ...settings, customCategories: settings.customCategories.filter(c => c !== name) };
    await updateSettings(s);
    const u = notes.map(n => n.category === name ? { ...n, category: 'Общее' } : n);
    setNotes(u);
    await storage.saveNotes(u);
  };

  const updateSettings = async (s: Settings) => {
    setSettings(s);
    await storage.saveSettings(s);
    document.documentElement.classList.toggle('dark', s.theme === 'dark');
  };

  const runAIAnalysis = async (id: string) => {
    const n = notes.find(x => x.id === id);
    if (!n) return;
    const res = await ai.analyzeText(n.content, settings);
    const u = notes.map(x => x.id === id ? { ...x, ...res, isIndexed: true, updatedAt: new Date().toISOString() } : x);
    setNotes(u);
    await storage.saveNotes(u);
  };

  return (
    <NotesContext.Provider value={{ 
      notes, goals, settings, isLoading, logs, filterTag, filterCategory, telegramMessages,
      setFilterTag, setFilterCategory, addNote, processLargeText, updateNote, moveToTrash, 
      restoreNote: async (id) => setNoteStatus(id, 'new'), 
      hardDelete: async (id) => { const u = notes.filter(x => x.id !== id); setNotes(u); await storage.saveNotes(u); },
      setNoteStatus, updateSettings, addLog, runAIAnalysis, reanalyzeAll,
      runSystemCheck: async () => { const r = await ai.testConnection(settings); r.success ? addLog('success', r.message) : addLog('error', r.message); },
      updateNotePosition: async (id, x, y) => { const u = notes.map(n => n.id === id ? { ...n, position: { x, y } } : n); setNotes(u); await storage.saveNotes(u); },
      updateNoteSize: async (id, w, h) => { const u = notes.map(n => n.id === id ? { ...n, size: { w, h } } : n); setNotes(u); await storage.saveNotes(u); },
      syncTelegram, deleteTelegramMsg, addGoal, toggleGoalStatus, deleteGoal, addCategory, deleteCategory
    }}>
      {children}
    </NotesContext.Provider>
  );
};

export const useNotes = () => {
  const c = useContext(NotesContext);
  if (!c) throw new Error("useNotes error");
  return c;
};

import React, { useState, useMemo, useRef } from 'react';
import { useNotes } from '../contexts/NotesContext.tsx';
import { NoteStatus, Note } from '../types.ts';
import { getTagColor } from '../utils/tagColors.ts';
import { 
  Search, Trash2, Sparkles, Circle, PlayCircle, Eye, CheckCircle2, 
  FileText, Globe, Folder, Plus, LayoutGrid, List, ScanLine, Lightbulb, Send, Mic, Split, X, Loader2, AlertCircle, Bookmark, Headphones, ChevronLeft, ChevronRight, Hash, Scissors
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import * as ai from '../utils/aiAdapter.ts';

const StatusIcon = ({ status, className }: { status: NoteStatus, className?: string }) => {
  switch (status) {
    case 'new': return <Circle className={`${className} text-amber-500 fill-amber-500`} size={10} />;
    case 'in-work': return <PlayCircle className={`${className} text-blue-500`} size={16} />;
    case 'read': return <Eye className={`${className} text-slate-400`} size={16} />;
    case 'finished': return <CheckCircle2 className={`${className} text-green-500`} size={16} />;
    default: return null;
  }
};

const SourceBadge = ({ type, hasAudio }: { type?: Note['sourceType'], hasAudio?: boolean }) => {
    return (
      <div className="flex items-center gap-2">
        {hasAudio && <Headphones size={12} className="text-red-500" title="Аудиозапись" />}
        {(() => {
          switch (type) {
              case 'ocr': return <ScanLine size={12} className="text-cyan-500" title="OCR" />;
              case 'split': return <Split size={12} className="text-purple-500" title="Split" />;
              case 'telegram': return <Send size={12} className="text-blue-400" title="TG" />;
              case 'audio': return <Mic size={12} className="text-red-400" title="Audio" />;
              default: return <FileText size={12} className="text-gray-400" title="Manual" />;
          }
        })()}
      </div>
    )
}

const NotesPage: React.FC = () => {
