                    <li>3. Вставьте Token ниже. Нажмите "Применить".</li>
                    <li>4. Чтобы узнать свой Chat ID, отправьте боту любое сообщение и нажмите "Синхронизировать" в Inbox — ваш ID будет в логах.</li>
                </ol>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                <div className="space-y-4">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-4">Bot API Token</label>
                    <input 
                      type="password"
                      className="w-full p-6 bg-gray-50 dark:bg-slate-950 rounded-[2rem] font-mono text-[11px] border-none dark:text-white shadow-inner focus:ring-4 focus:ring-blue-500/10 transition-all"
                      placeholder="123456789:ABCDE-FGHIJK..."
                      value={localSettings.tgToken}
                      onChange={e => setLocalSettings({...localSettings, tgToken: e.target.value})}
                    />
                </div>
                <div className="space-y-4">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-4">Admin Chat ID (Private)</label>
                    <input 
                      type="text"
                      className="w-full p-6 bg-gray-50 dark:bg-slate-950 rounded-[2rem] font-black text-xs border-none dark:text-white shadow-inner focus:ring-4 focus:ring-blue-500/10 transition-all"
                      placeholder="Например: 12345678"
                      value={localSettings.tgChatId}
                      onChange={e => setLocalSettings({...localSettings, tgChatId: e.target.value})}
                    />
                    <p className="text-[9px] text-gray-400 font-bold italic ml-4">Оставьте пустым для приема от всех, или укажите свой ID для безопасности.</p>
                </div>
            </div>
        </section>

        {/* Секция Логов */}
        <section className="bg-white dark:bg-slate-900 p-12 rounded-[4rem] border border-gray-100 dark:border-slate-800 space-y-8 shadow-sm">
           <div className="flex items-center justify-between px-2">
              <h3 className="font-black text-[11px] uppercase tracking-widest flex items-center gap-4 text-gray-400">
                  <Terminal size={22} className="text-blue-500"/> Журнал Диагностики
              </h3>
              <div className="flex items-center gap-6">
                <button 
                  onClick={() => setShowLogs(!showLogs)} 
                  className="text-[10px] font-black text-blue-500 uppercase flex items-center gap-2 hover:opacity-70 transition-opacity"
                >
                  {showLogs ? 'Скрыть историю' : 'Показать историю'} <ListFilter size={16}/>
                </button>
              </div>
           </div>

           {showLogs && (
             <div className="space-y-4 max-h-[500px] overflow-y-auto custom-scrollbar pr-6">
                {logs.length === 0 ? (
                  <div className="flex flex-col items-center justify-center py-16 text-gray-300 opacity-50">
                    <Info size={48} className="mb-4" />
                    <p className="text-center font-bold uppercase text-[10px] tracking-[0.3em]">Журнал событий пока пуст</p>
                  </div>
                ) : (
                  logs.map(log => (
                    <div key={log.id} className={`flex gap-5 p-6 rounded-[2rem] border animate-in slide-in-from-left duration-300 shadow-sm ${
                        log.level === 'error' ? 'bg-red-50/50 dark:bg-red-950/20 border-red-200 dark:border-red-900' : 
                        log.level === 'success' ? 'bg-green-50/50 dark:bg-green-950/20 border-green-200 dark:border-green-900' :
                        'bg-gray-50 dark:bg-slate-950/40 border-gray-100 dark:border-slate-800'
                    }`}>
                       <div className="mt-1">
                          {log.level === 'success' ? <CheckCircle2 className="text-green-500" size={20}/> : 
                           log.level === 'error' ? <AlertCircle className="text-red-500" size={20}/> : 
                           log.level === 'warn' ? <AlertCircle className="text-amber-500" size={20}/> : 
                           <Info className="text-blue-500" size={20}/>}
                       </div>
                       <div className="flex-1 min-w-0">
                          <p className={`text-sm font-black tracking-tight leading-tight ${
                            log.level === 'error' ? 'text-red-600' : 
                            log.level === 'success' ? 'text-green-600' : 'dark:text-white'
                          }`}>
                            {log.message}
                          </p>
                          <div className="flex items-center gap-4 mt-3">
                             <span className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">
                                {new Date(log.timestamp).toLocaleTimeString()}
                             </span>
                             {log.details && <span className="text-[10px] text-gray-400 truncate max-w-lg italic font-medium">| {log.details}</span>}
                          </div>
                       </div>
                    </div>
                  ))
                )}
             </div>
           )}
        </section>
      </div>

      <div className="flex justify-center pb-20 pt-8">
        <button 
            onClick={() => {
                updateSettings(localSettings);
                addLog('success', 'Настройки системы применены и сохранены локально');
            }}
            className="px-32 py-8 bg-blue-600 text-white rounded-[3rem] font-black uppercase text-xs shadow-2xl shadow-blue-500/30 hover:scale-105 active:scale-95 transition-all tracking-[0.3em] border border-blue-400/20"
        >
            Сохранить изменения
        </button>
      </div>
    </div>
  );
};

export default SettingsPage;

import React, { useState, useMemo, useRef } from 'react';
import { useNotes } from '../contexts/NotesContext.tsx';
import { NoteStatus, Note } from '../types.ts';
import { getTagColor } from '../utils/tagColors.ts';
import { 
  Search, Trash2, Sparkles, Circle, PlayCircle, Eye, CheckCircle2, 
  FileText, Globe, Folder, Plus, LayoutGrid, List, ScanLine, Lightbulb, Send, Mic, Split, X, Loader2, AlertCircle, Bookmark, Headphones, ChevronLeft, ChevronRight, Hash, Scissors
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import * as ai from '../utils/aiAdapter.ts';

const StatusIcon = ({ status, className }: { status: NoteStatus, className?: string }) => {
  switch (status) {
    case 'new': return <Circle className={`${className} text-amber-500 fill-amber-500`} size={10} />;
    case 'in-work': return <PlayCircle className={`${className} text-blue-500`} size={16} />;
    case 'read': return <Eye className={`${className} text-slate-400`} size={16} />;
    case 'finished': return <CheckCircle2 className={`${className} text-green-500`} size={16} />;
    default: return null;
  }
};

const SourceBadge = ({ type, hasAudio }: { type?: Note['sourceType'], hasAudio?: boolean }) => {
    return (
      <div className="flex items-center gap-2">
        {/* Fix: Lucide icons do not accept 'title' prop. Wrapping in span for tooltip functionality. */}
        {hasAudio && <span title="Аудиозапись"><Headphones size={12} className="text-red-500" /></span>}
        {(() => {
          switch (type) {
              case 'ocr': return <span title="OCR"><ScanLine size={12} className="text-cyan-500" /></span>;
              case 'split': return <span title="Split"><Split size={12} className="text-purple-500" /></span>;
              case 'telegram': return <span title="TG"><Send size={12} className="text-blue-400" /></span>;
              case 'audio': return <span title="Audio"><Mic size={12} className="text-red-400" /></span>;
              default: return <span title="Manual"><FileText size={12} className="text-gray-400" /></span>;
          }
        })()}
      </div>
    )
}

const NotesPage: React.FC = () => {
  const { notes, moveToTrash, filterTag, setFilterTag, filterCategory, setFilterCategory, setNoteStatus, settings, addCategory, deleteCategory, processLargeText } = useNotes();
  const navigate = useNavigate();
  const [search, setSearch] = useState('');
  const [showAddGroup, setShowAddGroup] = useState(false);
  const [showSplitter, setShowSplitter] = useState(false);
  const [splitText, setSplitText] = useState('');
  const [isSplitting, setIsSplitting] = useState(false);
  const [newGroupName, setNewGroupName] = useState('');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const scrollRef = useRef<HTMLDivElement>(null);

  const filteredNotes = useMemo(() => notes.filter(n => {
    const query = search.toLowerCase();
    const matchesSearch = n.title.toLowerCase().includes(query) || n.content.toLowerCase().includes(query);
    const matchesTag = !filterTag || n.tags.includes(filterTag);
    const matchesCategory = !filterCategory || n.category === filterCategory;
    return matchesSearch && matchesTag && matchesCategory && n.status !== 'trash';
  }), [notes, search, filterTag, filterCategory]);

  const handleScroll = (dir: 'l' | 'r') => {
    if (scrollRef.current) {
      scrollRef.current.scrollBy({ left: dir === 'l' ? -250 : 250, behavior: 'smooth' });
    }
  };

  const handleCreateGroup = async () => {
    if (!newGroupName.trim()) return;
    await addCategory(newGroupName);
    setNewGroupName('');
    setShowAddGroup(false);
  };

  const handleSplitSubmit = async () => {
    if (!splitText.trim()) return;
    setIsSplitting(true);
    await processLargeText(splitText);
    setIsSplitting(false);
    setSplitText('');
    setShowSplitter(false);
  };

  const cycleStatus = (e: React.MouseEvent, note: Note) => {
    e.stopPropagation();
    const statuses: NoteStatus[] = ['new', 'in-work', 'read', 'finished'];
    const currentIndex = statuses.indexOf(note.status);
    const nextIndex = (currentIndex + 1) % statuses.length;
    setNoteStatus(note.id, statuses[nextIndex]);
  };

  const handleTagClick = (e: React.MouseEvent, tag: string) => {
    e.stopPropagation();
    setFilterTag(tag);
  };

  return (
    <div className="p-12 max-w-7xl mx-auto min-h-screen relative pb-32 animate-in fade-in duration-700">
      <header className="flex flex-col gap-8 mb-16">
        <div className="flex flex-col md:flex-row items-end justify-between gap-8">
          <h2 className="text-6xl font-black text-slate-900 dark:text-white tracking-tighter select-none leading-none">
            Библиотека<span className="text-blue-600">.</span>
          </h2>
          <div className="flex gap-4 w-full md:w-auto">
            <button 
              onClick={() => setShowSplitter(true)}
              className="flex items-center gap-3 px-6 py-2 bg-purple-600/10 text-purple-600 dark:text-purple-400 rounded-full text-[10px] font-black uppercase tracking-widest border border-purple-500/20 hover:bg-purple-600 hover:text-white transition-all shadow-sm"
            >
              <Scissors size={14}/> Smart Split
            </button>
            {filterTag && (
              <button 
                onClick={() => setFilterTag(null)}
                className="flex items-center gap-3 px-6 py-2 bg-blue-600 text-white rounded-full text-[10px] font-black uppercase tracking-widest shadow-lg animate-in zoom-in"
              >
                Тег: #{filterTag} <X size={14}/>
              </button>
            )}
            <div className="relative group flex-1 md:w-[400px]">
              <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-gray-400 group-focus-within:text-blue-500 transition-colors" size={20}/>
              <input
                type="text"
                placeholder="Поиск по архиву..."
                className="w-full pl-16 pr-8 py-6 bg-white dark:bg-slate-900 border border-gray-100 dark:border-white/10 rounded-[2.5rem] focus:ring-4 focus:ring-blue-500/10 font-bold text-sm shadow-xl transition-all dark:text-white"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
            </div>
            <div className="flex bg-gray-100 dark:bg-slate-800 p-2 rounded-[2.5rem]">
               <button onClick={() => setViewMode('grid')} className={`p-4 rounded-full transition-all ${viewMode === 'grid' ? 'bg-white dark:bg-slate-700 shadow-md text-blue-600' : 'text-gray-400'}`}><LayoutGrid size={24}/></button>
               <button onClick={() => setViewMode('list')} className={`p-4 rounded-full transition-all ${viewMode === 'list' ? 'bg-white dark:bg-slate-700 shadow-md text-blue-600' : 'text-gray-400'}`}><List size={24}/></button>
            </div>
          </div>
        </div>

        <div className="space-y-4">
          <div className="flex items-center justify-between px-2">
             <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
               <Folder size={12} className="text-blue-500"/> Группы Знаний
             </h4>
             <div className="flex items-center gap-4">
                <button onClick={() => handleScroll('l')} className="p-2 text-gray-400 hover:text-blue-500 transition-colors"><ChevronLeft size={20}/></button>
                <button onClick={() => handleScroll('r')} className="p-2 text-gray-400 hover:text-blue-500 transition-colors"><ChevronRight size={20}/></button>
                <div className="w-px h-4 bg-gray-200 dark:bg-slate-800 mx-2" />
                <button onClick={() => setShowAddGroup(true)} className="text-[10px] font-black text-blue-600 uppercase flex items-center gap-2 hover:opacity-70 transition-opacity">
                    <Plus size={12}/> Новая Группа
                </button>
             </div>
          </div>
          <div ref={scrollRef} className="flex items-center gap-4 overflow-x-auto pb-4 no-scrollbar pr-10">
             {settings.customCategories.map(cat => {
               const count = notes.filter(n => n.category === cat && n.status !== 'trash').length;
               const isActive = filterCategory === cat;
               const colors = getTagColor(cat);
               return (
                 <div key={cat} className="relative group shrink-0">
                    <button 
                      onClick={() => setFilterCategory(isActive ? null : cat)}
                      style={{ backgroundColor: isActive ? colors.border : undefined, borderColor: colors.border }}
                      className={`px-8 py-6 rounded-[2rem] border-2 transition-all flex flex-col gap-2 min-w-[180px] text-left relative overflow-hidden shadow-sm ${
                        isActive ? 'text-white shadow-lg scale-105' : 'bg-white dark:bg-slate-900 text-gray-900 dark:text-white hover:border-blue-500'
                      }`}
                    >
                        <Folder size={24} className={isActive ? 'text-white' : 'text-blue-500'} />
                        <span className="text-sm font-black uppercase tracking-tight truncate mt-2">{cat}</span>
                        <span className={`absolute top-4 right-4 text-[10px] font-black px-2 py-1 rounded-lg ${isActive ? 'bg-white/20' : 'bg-gray-100 dark:bg-slate-800'}`}>{count}</span>
                    </button>
                    {cat !== 'Общее' && (
                        <button 
                          onClick={(e) => { e.stopPropagation(); if(confirm(`Удалить группу "${cat}"? Заметки вернутся в "Общее"`)) deleteCategory(cat); }}
                          className="absolute bottom-4 right-4 p-2 bg-red-500 text-white rounded-xl opacity-0 group-hover:opacity-100 transition-all shadow-lg hover:scale-110 active:scale-90"
                        >
                            <Trash2 size={12}/>
                        </button>
                    )}
                 </div>
               );
             })}
          </div>
        </div>
      </header>

      {viewMode === 'grid' ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-12">
          {filteredNotes.map((note) => {
            const colors = getTagColor(note.category);
            return (
              <div 
                key={note.id}
                onClick={() => navigate(`/editor/${note.id}`)}
                style={{ borderColor: colors.border }}
                className="group bg-white dark:bg-slate-900 p-8 rounded-[3.5rem] border-2 transition-all cursor-pointer h-[38rem] flex flex-col shadow-xl hover:shadow-2xl hover:-translate-y-2 relative overflow-hidden"
              >
                {/* Header Row */}
                <div className="flex items-center justify-between mb-4 shrink-0">
                  <div className="flex items-center gap-3">
                    <button onClick={(e) => cycleStatus(e, note)} className="p-2.5 bg-gray-50 dark:bg-white/5 rounded-2xl hover:scale-105 transition-transform">
                        <StatusIcon status={note.status} />
                    </button>
                    <div className="p-2 bg-gray-50 dark:bg-white/5 rounded-xl">
                        <SourceBadge type={note.sourceType} hasAudio={!!note.audioData} />
                    </div>
                  </div>
                  <button 
                    onClick={(e) => { e.stopPropagation(); ai.openInGoogle(note.title); }} 
                    className="p-3 text-gray-300 hover:text-blue-500 dark:hover:text-blue-400 transition-all hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-xl"
                    title="Искать в Google"
                  >
                    <Globe size={20}/>
                  </button>
                </div>

                {/* Title Section: MAX CONTRAST */}
                <h3 className="font-black text-3xl text-slate-950 dark:text-white mb-6 line-clamp-2 tracking-tighter leading-tight min-h-[4rem] flex items-start shrink-0">
                  {note.title || "Без названия"}
                </h3>

                {/* Middle Content Section */}
                <div className="flex-1 overflow-hidden flex flex-col">
                    {note.summary && (
                    <div style={{ backgroundColor: colors.bg, borderColor: colors.border }} className="mb-4 p-4 rounded-3xl border-l-4 relative shrink-0">
                        <Sparkles size={12} className="absolute -top-2 -left-2 text-blue-500 bg-white dark:bg-slate-900 rounded-full p-0.5" />
                        <p style={{ color: colors.text }} className="text-[11px] font-bold italic line-clamp-2 leading-relaxed">{note.summary}</p>
                    </div>
                    )}

                    <div className="text-[13px] text-gray-600 dark:text-slate-400 leading-relaxed line-clamp-4 font-medium mb-4">
                    {note.content}
                    </div>

                    {/* Tags Section: SMALLER & COMPACT */}
                    <div className="flex flex-wrap gap-1.5 mt-auto pb-4 overflow-hidden shrink-0">
                        {note.tags.slice(0, 8).map(tag => (
                            <button 
                                key={tag}
                                onClick={(e) => handleTagClick(e, tag)}
                                className="px-2 py-0.5 bg-blue-50/50 dark:bg-blue-900/20 text-[8px] font-black uppercase tracking-tight text-blue-600 dark:text-blue-400 border border-blue-500/10 rounded-md hover:bg-blue-600 hover:text-white transition-all shadow-sm active:scale-95"
                            >
                                #{tag}
                            </button>
                        ))}
                    </div>
                </div>

                {/* Fixed Footer Row: ALWAYS PINNED TO BOTTOM */}
                <div className="mt-auto pt-4 border-t border-gray-100 dark:border-white/5 flex items-center justify-between shrink-0">
                    <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                        <Bookmark size={12} className="text-blue-500" />
                        {new Date(note.createdAt).toLocaleDateString()}
                    </span>
                    <button 
                      onClick={(e) => { e.stopPropagation(); moveToTrash(note.id); }} 
                      className="p-2.5 text-gray-300 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-xl transition-all active:scale-90"
                    >
                      <Trash2 size={20}/>
                    </button>
                </div>
              </div>
            );
          })}
        </div>
      ) : (
        <div className="space-y-4">
          {filteredNotes.map(note => {
             const colors = getTagColor(note.category);
             return (
                <div key={note.id} onClick={() => navigate(`/editor/${note.id}`)} style={{ borderColor: colors.border }} className="bg-white dark:bg-slate-900 p-8 rounded-[2rem] border-2 border-transparent hover:border-blue-500 flex items-center gap-8 group cursor-pointer transition-all shadow-sm">
                  <button onClick={(e) => cycleStatus(e, note)} className="shrink-0"><StatusIcon status={note.status}/></button>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-3">
                       <h3 className="text-2xl font-black text-slate-950 dark:text-white truncate">{note.title || "Без названия"}</h3>
                       <SourceBadge type={note.sourceType} hasAudio={!!note.audioData} />
                    </div>
                    <div className="flex gap-2 mt-1">
                        {note.tags.slice(0, 3).map(tag => (
                            <span key={tag} onClick={(e) => handleTagClick(e, tag)} className="text-[8px] font-black text-gray-400 uppercase hover:text-blue-500 transition-colors">#{tag}</span>
                        ))}
                    </div>
                  </div>
                  <div className="flex items-center gap-4">
                     <span className="text-[10px] font-black text-gray-400 uppercase">{new Date(note.createdAt).toLocaleDateString()}</span>
                     <button onClick={(e) => { e.stopPropagation(); ai.openInGoogle(note.title); }} className="p-3 text-gray-300 hover:text-blue-500 transition-colors"><Globe size={18}/></button>
                     <button onClick={(e) => { e.stopPropagation(); moveToTrash(note.id); }} className="p-4 text-gray-300 hover:text-red-500 transition-colors"><Trash2 size={18}/></button>
                  </div>
                </div>
             );
          })}
        </div>
      )}

      {/* Group Modal */}
      {showAddGroup && (
        <div className="fixed inset-0 bg-slate-950/70 backdrop-blur-xl z-[150] flex items-center justify-center p-6 animate-in fade-in duration-300">
          <div className="bg-white dark:bg-slate-900 w-full max-w-md rounded-[3rem] p-10 shadow-2xl border border-white/10">
            <h3 className="text-3xl font-black dark:text-white uppercase mb-6 flex items-center gap-3 tracking-tighter">Новая Группа</h3>
            <input 
              autoFocus className="w-full p-6 bg-gray-50 dark:bg-slate-950 border-none rounded-2xl font-black text-xl dark:text-white shadow-inner"
              placeholder="Название..."
              value={newGroupName}
              onChange={e => setNewGroupName(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && handleCreateGroup()}
            />
            <div className="flex gap-4 mt-8">
               <button onClick={() => setShowAddGroup(false)} className="flex-1 py-5 bg-gray-100 dark:bg-slate-800 rounded-2xl font-black uppercase text-[10px] tracking-widest dark:text-white">Отмена</button>
               <button onClick={handleCreateGroup} className="flex-1 py-5 bg-blue-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-xl shadow-blue-500/20 active:scale-95 transition-all">Создать</button>
            </div>
          </div>
        </div>
      )}

      {/* Splitter Modal */}
      {showSplitter && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-2xl z-[150] flex items-center justify-center p-6 animate-in zoom-in duration-300">
          <div className="bg-white dark:bg-slate-900 w-full max-w-4xl rounded-[4rem] p-16 shadow-2xl border border-white/10 relative">
            <button onClick={() => setShowSplitter(false)} className="absolute top-10 right-10 p-3 text-gray-400 hover:text-red-500 bg-gray-100 dark:bg-slate-800 rounded-full"><X size={24}/></button>
            <h3 className="text-4xl font-black dark:text-white uppercase mb-4 tracking-tighter flex items-center gap-4">
              <Scissors size={32} className="text-purple-500"/> Smart Text Splitter
            </h3>
            <p className="text-gray-400 font-bold text-sm mb-10 leading-relaxed max-w-2xl">
              Вставьте лонгрид, книгу или длинную статью. ИИ проанализирует контекст и разделит его на серию осмысленных карточек с заголовками и категориями.
            </p>
            <textarea 
              className="w-full h-[350px] p-8 bg-gray-50 dark:bg-slate-950 border-none rounded-[2.5rem] font-medium text-lg dark:text-white shadow-inner resize-none focus:ring-4 focus:ring-purple-500/10 transition-all outline-none"
              placeholder="Вставьте ваш огромный текст здесь..."
              value={splitText}
              onChange={e => setSplitText(e.target.value)}
            />
            <div className="flex gap-4 mt-12">
               <button 
                onClick={handleSplitSubmit}
                disabled={isSplitting || !splitText.trim()}
                className="flex-1 py-7 bg-purple-600 text-white rounded-[2.5rem] font-black uppercase text-xs tracking-widest shadow-xl shadow-purple-500/20 active:scale-95 transition-all flex items-center justify-center gap-4 disabled:opacity-30"
               >
                 {isSplitting ? <Loader2 size={22} className="animate-spin"/> : <Sparkles size={22}/>}
                 Разрезать и импортировать в базу
               </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default NotesPage;

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Note, Settings, AIProvider, AppLog, NoteStatus, TelegramMessage, Goal } from '../types.ts';
import * as storage from '../utils/storage.ts';
import * as ai from '../utils/aiAdapter.ts';

interface NotesContextType {
  notes: Note[];
  goals: Goal[];
  settings: Settings;
  isLoading: boolean;
  logs: AppLog[];
  filterTag: string | null;
  filterCategory: string | null;
  telegramMessages: any[]; 
  setFilterTag: (tag: string | null) => void;
  setFilterCategory: (cat: string | null) => void;
  addNote: (content: string, title?: string, sourceType?: Note['sourceType'], useAI?: boolean, category?: string, audioData?: string) => Promise<void>;
  processLargeText: (text: string) => Promise<void>;
  updateNote: (note: Note) => Promise<void>;
  moveToTrash: (id: string) => Promise<void>;
  restoreNote: (id: string) => Promise<void>;
  hardDelete: (id: string) => Promise<void>;
  setNoteStatus: (id: string, status: NoteStatus) => Promise<void>;
  updateSettings: (s: Settings) => Promise<void>;
  addLog: (level: AppLog['level'], message: string, details?: string) => void;
  runAIAnalysis: (id: string) => Promise<void>;
  reanalyzeAll: () => Promise<void>;
  runSystemCheck: () => Promise<void>;
  updateNotePosition: (id: string, x: number, y: number) => Promise<void>;
  updateNoteSize: (id: string, w: number, h: number) => Promise<void>;
  syncTelegram: () => Promise<void>;
  deleteTelegramMsg: (id: number) => void;
  addGoal: (title: string, description: string) => Promise<void>;
  toggleGoalStatus: (id: string) => Promise<void>;
  deleteGoal: (id: string) => Promise<void>;
  addCategory: (name: string) => Promise<void>;
  deleteCategory: (name: string) => Promise<void>;
}

const NotesContext = createContext<NotesContextType | undefined>(undefined);

export const NotesProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [notes, setNotes] = useState<Note[]>([]);
  const [goals, setGoals] = useState<Goal[]>([]);
  const [settings, setSettings] = useState<Settings>(storage.getDefaultSettings());
  const [isLoading, setIsLoading] = useState(true);
  const [logs, setLogs] = useState<AppLog[]>([]);
  const [filterTag, setFilterTag] = useState<string | null>(null);
  const [filterCategory, setFilterCategory] = useState<string | null>(null);
  const [telegramMessages, setTelegramMessages] = useState<any[]>([]);

  const addLog = (level: AppLog['level'], message: string, details?: string) => {
    setLogs(prev => [{ id: crypto.randomUUID(), timestamp: new Date().toISOString(), level, message, details }, ...prev].slice(0, 150));
  };

  useEffect(() => {
    const init = async () => {
      const [n, s, g] = await Promise.all([storage.getNotes(), storage.getSettings(), storage.getGoals()]);
      setNotes(n);
      setSettings(s);
      setGoals(g || []);
      setIsLoading(false);
      document.documentElement.classList.toggle('dark', s.theme === 'dark');
    };
    init();
  }, []);

  const syncTelegram = async () => {
    if (!settings.tgToken) {
      addLog('warn', 'Telegram Token не настроен');
      return;
    }
    try {
      const offset = settings.tgLastUpdateId + 1;
      const response = await fetch(`https://api.telegram.org/bot${settings.tgToken}/getUpdates?offset=${offset}&timeout=5`);
      const data = await response.json();

      if (data.ok && data.result.length > 0) {
        const processedMsgs = [];
        for (const u of data.result) {
          const msg = u.message;
          if (!msg) continue;
          if (settings.tgChatId && String(msg.chat.id) !== settings.tgChatId) continue;
          let entry: any = { id: u.update_id, date: new Date(msg.date * 1000).toISOString(), from: msg.from.first_name || 'User', type: 'text', text: msg.text || msg.caption || '' };
          if (msg.photo) {
            const fileId = msg.photo[msg.photo.length - 1].file_id;
            const fileRes = await fetch(`https://api.telegram.org/bot${settings.tgToken}/getFile?file_id=${fileId}`);
            const fileData = await fileRes.json();
            if (fileData.ok) entry.type = 'photo', entry.fileUrl = `https://api.telegram.org/file/bot${settings.tgToken}/${fileData.result.file_path}`;
          } else if (msg.voice) {
            const fileId = msg.voice.file_id;
            const fileRes = await fetch(`https://api.telegram.org/bot${settings.tgToken}/getFile?file_id=${fileId}`);
            const fileData = await fileRes.json();
            if (fileData.ok) entry.type = 'voice', entry.fileUrl = `https://api.telegram.org/file/bot${settings.tgToken}/${fileData.result.file_path}`;
          }
          processedMsgs.push(entry);
        }
        const lastId = data.result[data.result.length - 1].update_id;
        const newSettings = { ...settings, tgLastUpdateId: lastId };
        setSettings(newSettings);
        await storage.saveSettings(newSettings);
        setTelegramMessages(prev => [...processedMsgs, ...prev]);
        addLog('success', `Telegram sync: +${processedMsgs.length} новых сообщений`);
      }
    } catch (e: any) {
      addLog('error', `Telegram sync failed: ${e.message}`);
    }
  };

  const deleteTelegramMsg = (id: number) => setTelegramMessages(prev => prev.filter(m => m.id !== id));

  const addNote = async (content: string, title?: string, sourceType: Note['sourceType'] = 'manual', useAI = true, forceCategory?: string, audioData?: string) => {
    let analysis: any = { tags: [], category: forceCategory || filterCategory || 'Общее', summary: '', title: title };
    let isIndexed = false;
    if (useAI && navigator.onLine) {
      addLog('info', 'ИИ анализирует новый контент...');
      try { 
        analysis = await ai.analyzeText(content, settings); 
        isIndexed = true;
      } catch (e: any) { 
        addLog('warn', `ИИ анализ пропущен: ${e.message}`); 
      }
    }
    const newNote: Note = {
      id: crypto.randomUUID(),
      title: title || analysis.title || content.slice(0, 40),
      content,
      tags: analysis.tags || [],
      category: forceCategory || analysis.category || filterCategory || 'Общее',
      summary: analysis.summary || '',
      status: 'new',
      isIndexed,
      sourceType,
      audioData,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      links: [],
      position: { x: Math.random() * 200, y: Math.random() * 200 },
      size: { w: 320, h: 280 }
    };
    const updated = [newNote, ...notes];
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const processLargeText = async (text: string) => {
    try {
      const parts = await ai.splitLargeText(text, settings);
      if (Array.isArray(parts)) {
        const generatedNotes = parts.map(part => ({
          id: crypto.randomUUID(),
          title: part.title || part.content.slice(0, 40),
          content: part.content,
          tags: [],
          category: part.category || 'Общее',
          summary: '',
          status: 'new' as NoteStatus,
          isIndexed: true,
          sourceType: 'split' as any,
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
          links: [],
          position: { x: Math.random() * 200, y: Math.random() * 200 },
          size: { w: 320, h: 280 }
        }));
        setNotes(prev => {
          const u = [...generatedNotes, ...prev];
          storage.saveNotes(u);
          return u;
        });
      }
    } catch (e: any) {
      addLog('error', `Ошибка разделения текста: ${e.message}`);
    }
  };

  const reanalyzeAll = async () => {
    // Получаем самый свежий список заметок прямо из хранилища для надежности
    const allNotes = await storage.getNotes();
    const activeNotes = allNotes.filter(n => n.status !== 'trash');

    addLog('info', `[ГЛУБОКИЙ РЕИНДЕКС] Запуск анализа для ${activeNotes.length} активных файлов.`);

    // Работаем с локальной копией для поэтапного обновления
    const updatedNotes = [...allNotes];
    let successCount = 0;
    let failCount = 0;

    for (let i = 0; i < updatedNotes.length; i++) {
      const note = updatedNotes[i];
      if (note.status === 'trash') continue;

      try {
        if (!note.content || note.content.trim().length < 5) {
          addLog('warn', `Пропуск "${note.title}": текст слишком короткий для анализа.`);
          continue;
        }

        addLog('info', `[${successCount + failCount + 1}/${activeNotes.length}] Анализирую смысл: "${note.title}"...`);

        // Используем настройки из стейта (они всегда актуальны)
        const analysis = await ai.analyzeText(note.content, settings);

        if (analysis && (analysis.title || analysis.tags)) {
          updatedNotes[i] = {
            ...note,
            ...analysis,
            isIndexed: true,
            updatedAt: new Date().toISOString()
          };
          successCount++;

          // Мгновенно обновляем стейт и хранилище, чтобы не потерять данные при сбое
          setNotes([...updatedNotes]);
          await storage.saveNotes(updatedNotes);

          addLog('success', `Файл "${note.title}" реиндексирован: тегов (${analysis.tags?.length || 0}), категория: ${analysis.category}`);
        } else {
          throw new Error("ИИ вернул пустой или некорректный ответ.");
        }
      } catch (err: any) {
        failCount++;
        addLog('error', `Сбой реиндекса файла "${note.title}"`, err.message);
      }
    }

    addLog('success', `[РЕИНДЕКС ЗАВЕРШЕН] Успех: ${successCount}, Ошибок: ${failCount}. Все данные засинхронены с IDB.`);
  };

  const addGoal = async (title: string, description: string) => {
    const newGoal: Goal = { id: crypto.randomUUID(), title, description, createdAt: new Date().toISOString(), color: `hsl(${Math.random() * 360}, 70%, 50%)`, status: 'active' };
    const u = [newGoal, ...goals];
    setGoals(u);
    await storage.saveGoals(u);
  };

  const toggleGoalStatus = async (id: string) => {
    const u = goals.map(g => g.id === id ? { ...g, status: (g.status === 'active' ? 'completed' : 'active') as any } : g);
    setGoals(u);
    await storage.saveGoals(u);
  };

  const deleteGoal = async (id: string) => {
    const u = goals.filter(g => g.id !== id);
    setGoals(u);
    await storage.saveGoals(u);
  };

  const updateNote = async (n: Note) => {
    const u = notes.map(x => x.id === n.id ? n : x);
    setNotes(u);
    await storage.saveNotes(u);
  };

  const setNoteStatus = async (id: string, status: NoteStatus) => {
    const u = notes.map(n => n.id === id ? { ...n, status } : n);
    setNotes(u);
    await storage.saveNotes(u);
  };

  const moveToTrash = async (id: string) => {
    const u = notes.map(n => n.id === id ? { ...n, status: 'trash' as NoteStatus } : n);
    setNotes(u);
    await storage.saveNotes(u);
  };

  const addCategory = async (name: string) => {
    if (settings.customCategories.includes(name)) return;
    const s = { ...settings, customCategories: [...settings.customCategories, name] };
    await updateSettings(s);
  };

  const deleteCategory = async (name: string) => {
    if (name === 'Общее') return;
    const s = { ...settings, customCategories: settings.customCategories.filter(c => c !== name) };
    await updateSettings(s);
    const u = notes.map(n => n.category === name ? { ...n, category: 'Общее' } : n);
    setNotes(u);
    await storage.saveNotes(u);
  };

  const updateSettings = async (s: Settings) => {
    setSettings(s);
    await storage.saveSettings(s);
    document.documentElement.classList.toggle('dark', s.theme === 'dark');
  };

  const runAIAnalysis = async (id: string) => {
    const n = notes.find(x => x.id === id);
    if (!n) return;
    try {
      addLog('info', `Запуск ИИ-анализа для "${n.title}"...`);
      const res = await ai.analyzeText(n.content, settings);
      const u = notes.map(x => x.id === id ? { ...x, ...res, isIndexed: true, updatedAt: new Date().toISOString() } : x);
      setNotes(u);
      await storage.saveNotes(u);
      addLog('success', `Анализ "${n.title}" завершен.`);
    } catch (e: any) {
      addLog('error', `Сбой анализа: ${e.message}`);
    }
  };

  return (
    <NotesContext.Provider value={{ 
      notes, goals, settings, isLoading, logs, filterTag, filterCategory, telegramMessages,
      setFilterTag, setFilterCategory, addNote, processLargeText, updateNote, moveToTrash, 
      restoreNote: async (id) => setNoteStatus(id, 'new'), 
      hardDelete: async (id) => { const u = notes.filter(x => x.id !== id); setNotes(u); await storage.saveNotes(u); },
      setNoteStatus, updateSettings, addLog, runAIAnalysis, reanalyzeAll,
      runSystemCheck: async () => { const r = await ai.testConnection(settings); r.success ? addLog('success', r.message) : addLog('error', r.message); },
      updateNotePosition: async (id, x, y) => { const u = notes.map(n => n.id === id ? { ...n, position: { x, y } } : n); setNotes(u); await storage.saveNotes(u); },
      updateNoteSize: async (id, w, h) => { const u = notes.map(n => n.id === id ? { ...n, size: { w, h } } : n); setNotes(u); await storage.saveNotes(u); },
      syncTelegram, deleteTelegramMsg, addGoal, toggleGoalStatus, deleteGoal, addCategory, deleteCategory
    }}>
      {children}
    </NotesContext.Provider>
  );
};

export const useNotes = () => {
  const c = useContext(NotesContext);
  if (!c) throw new Error("useNotes error");
  return c;
};

import React, { useState, useMemo } from 'react';
import { HashRouter, Routes, Route, useNavigate, useLocation } from 'react-router-dom';
import { NotesProvider, useNotes } from './contexts/NotesContext.tsx';
import Sidebar from './components/Sidebar.tsx';
import NotesPage from './pages/NotesPage.tsx';
import NoteEditor from './pages/NoteEditor.tsx';
import GraphView from './pages/GraphView.tsx';
import ChatPage from './pages/ChatPage.tsx';
import SettingsPage from './pages/SettingsPage.tsx';
import IdeasPage from './pages/IdeasPage.tsx';
import TrashPage from './pages/TrashPage.tsx';
import TelegramPage from './pages/TelegramPage.tsx';
import OcrPage from './pages/OcrPage.tsx';
import GoalsPage from './pages/GoalsPage.tsx';
import AgentPage from './pages/AgentPage.tsx';
import AudioRecorder from './components/AudioRecorder.tsx';
import { Send, Loader2, Mic, X, Hash, BarChart3, Zap, PanelRightClose, PanelRightOpen, PlayCircle } from 'lucide-react';
import { getTagColor } from './utils/tagColors.ts';

const QuickIdeasPanel: React.FC = () => {
  const { addNote, notes, setFilterTag, setFilterCategory } = useNotes();
  const navigate = useNavigate();
  const [idea, setIdea] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [showRecorder, setShowRecorder] = useState(false);

  const activeNotes = notes.filter(n => n.status !== 'trash');

  const activeTags = useMemo(() => {
    const counts: Record<string, number> = {};
    activeNotes.forEach(n => n.tags.forEach(t => counts[t] = (counts[t] || 0) + 1));
    return Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, 10);
  }, [activeNotes]);

  const stats = useMemo(() => ({
    total: activeNotes.length,
    inWork: activeNotes.filter(n => n.status === 'in-work').length,
    finished: activeNotes.filter(n => n.status === 'finished').length,
  }), [activeNotes]);

  const handleSaveIdea = async () => {
    if (!idea.trim()) return;
    setIsSaving(true);
    await addNote(idea, undefined, 'manual', true);
    setIdea('');
    setIsSaving(false);
  };

  return (
    <div className="w-80 bg-white dark:bg-[#080c14] border-l border-gray-100 dark:border-slate-800 h-screen flex flex-col shrink-0 z-10 animate-in slide-in-from-right duration-500">
      <div className="p-8 border-b border-gray-50 dark:border-slate-800">
        <div className="flex items-center justify-between mb-6">
          <h3 className="font-black text-[10px] uppercase tracking-[0.3em] text-gray-400 flex items-center gap-3">
            <Zap size={14} className="text-amber-500" /> Быстрый Ввод
          </h3>
          <button 
            onClick={() => setShowRecorder(true)} 
            className="p-3 text-blue-600 bg-blue-50 dark:bg-blue-500/10 rounded-2xl hover:scale-110 active:scale-95 transition-all shadow-sm"
          >
            <Mic size={18} />
          </button>
        </div>
        <div className="relative group">
          <textarea 
            value={idea}
            onChange={(e) => setIdea(e.target.value)}
            placeholder="Запишите мысль..."
            className="w-full h-32 p-5 bg-gray-50 dark:bg-slate-800/50 border-none rounded-[2rem] focus:ring-4 focus:ring-blue-500/10 text-sm font-bold text-gray-700 dark:text-slate-200 placeholder:text-gray-300 resize-none transition-all shadow-inner"
          />
          <button 
            onClick={handleSaveIdea}
            disabled={isSaving || !idea.trim()}
            className="absolute bottom-4 right-4 p-3 bg-blue-600 text-white rounded-2xl shadow-xl hover:bg-blue-700 active:scale-90 transition-all disabled:opacity-30"
          >
            {isSaving ? <Loader2 size={18} className="animate-spin" /> : <Send size={18} />}
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-8 space-y-10 custom-scrollbar">
        <section>
          <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em] mb-6 flex items-center gap-3">
            <Hash size={12} className="text-cyan-500" /> Популярные узлы
          </h4>
          <div className="flex flex-wrap gap-2.5">
            {activeTags.map(([tag, count]) => {
              const colors = getTagColor(tag);
              return (
                <button 
                  key={tag} 
                  onClick={() => { setFilterTag(tag); navigate('/'); }}
                  style={{ color: colors.text, backgroundColor: colors.bg, borderColor: colors.border }} 
                  className="px-4 py-2 rounded-xl transition-all flex items-center gap-2.5 border-2 hover:scale-110 shadow-sm active:scale-95"
                >
                  <span className="text-[10px] font-black">#{tag}</span>
                  <span className="text-[8px] font-black opacity-60 ml-2">{count}</span>
                </button>
              );
            })}
          </div>
        </section>
      </div>

      <div className="p-8 bg-gray-50/50 dark:bg-[#06080c] border-t border-gray-100 dark:border-slate-800">
        <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em] mb-6 flex items-center gap-3">
          <BarChart3 size={14} className="text-cyan-500" /> Статистика
        </h4>
        <div className="space-y-3">
          <div onClick={() => { setFilterCategory(null); setFilterTag(null); navigate('/'); }} className="flex items-center justify-between p-4 bg-white dark:bg-slate-900 rounded-2xl border border-gray-100 dark:border-white/5 cursor-pointer hover:border-blue-500 transition-all shadow-sm">
            <span className="text-[10px] font-black text-blue-500 uppercase tracking-widest">Всего</span>
            <span className="text-xl font-black dark:text-white">{stats.total}</span>
          </div>
          <div onClick={() => { setFilterCategory(null); setFilterTag(null); navigate('/'); }} className="flex items-center justify-between p-4 bg-white dark:bg-slate-900 rounded-2xl border border-gray-100 dark:border-white/5 cursor-pointer hover:border-amber-500 transition-all shadow-sm">
            <div className="flex items-center gap-2">
                <PlayCircle size={14} className="text-amber-500"/>
                <span className="text-[10px] font-black text-amber-500 uppercase tracking-widest">В работе</span>
            </div>
            <span className="text-xl font-black dark:text-white">{stats.inWork}</span>
          </div>
          <div onClick={() => { setFilterCategory(null); setFilterTag(null); navigate('/'); }} className="flex items-center justify-between p-4 bg-white dark:bg-slate-900 rounded-2xl border border-gray-100 dark:border-white/5 cursor-pointer hover:border-green-500 transition-all shadow-sm">
            <span className="text-[10px] font-black text-green-500 uppercase tracking-widest">Готово</span>
            <span className="text-xl font-black dark:text-white">{stats.finished}</span>
          </div>
        </div>
      </div>

      {showRecorder && (
        <div className="fixed inset-0 z-[200] bg-slate-950/70 backdrop-blur-xl flex items-center justify-center p-6 animate-in fade-in duration-500">
            <div className="relative max-w-xl w-full">
                <button onClick={() => setShowRecorder(false)} className="absolute -top-6 -right-6 bg-white dark:bg-slate-800 p-3 rounded-full text-gray-400 hover:text-red-500 shadow-2xl transition-colors"><X size={24}/></button>
                <AudioRecorder onComplete={() => setShowRecorder(false)} />
            </div>
        </div>
      )}
    </div>
  );
};

const AppContent: React.FC = () => {
    const [showQuickPanel, setShowQuickPanel] = useState(true);
    const location = useLocation();
    const isEditor = location.pathname.startsWith('/editor/');

    return (
        <div className="flex h-screen bg-slate-50 dark:bg-[#020617] overflow-hidden transition-colors duration-1000">
          <Sidebar />
          <main className="flex-1 overflow-y-auto relative custom-scrollbar">
            {!isEditor && (
              <button 
                onClick={() => setShowQuickPanel(!showQuickPanel)}
                className={`fixed top-1/2 -translate-y-1/2 z-[60] w-12 h-12 bg-blue-600 text-white rounded-full shadow-2xl transition-all hover:scale-110 active:scale-90 flex items-center justify-center border-4 border-white dark:border-slate-800 hover:bg-blue-700 right-4 ${
                  showQuickPanel ? 'translate-x-[-300px]' : 'translate-x-0'
                }`}
              >
                {showQuickPanel ? <PanelRightClose size={22} /> : <PanelRightOpen size={22} />}
              </button>
            )}

            <Routes>
              <Route path="/" element={<NotesPage />} />
              <Route path="/ocr" element={<OcrPage />} />
              <Route path="/goals" element={<GoalsPage />} />
              <Route path="/agent" element={<AgentPage />} />
              <Route path="/telegram" element={<TelegramPage />} />
              <Route path="/ideas" element={<IdeasPage />} />
              <Route path="/editor/:id" element={<NoteEditor />} />
              <Route path="/graph" element={<GraphView />} />
              <Route path="/chat" element={<ChatPage />} />
              <Route path="/trash" element={<TrashPage />} />
              <Route path="/settings" element={<SettingsPage />} />
            </Routes>
          </main>
          {showQuickPanel && !isEditor && <QuickIdeasPanel />}
        </div>
    );
}

const App: React.FC = () => {
  return (
    <NotesProvider>
      <HashRouter>
        <AppContent />
      </HashRouter>
    </NotesProvider>
  );
};

export default App;

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Note, Settings, AIProvider, AppLog, NoteStatus, TelegramMessage, Goal } from '../types.ts';
import * as storage from '../utils/storage.ts';
import * as ai from '../utils/aiAdapter.ts';

interface NotesContextType {
  notes: Note[];
  goals: Goal[];
  settings: Settings;
  isLoading: boolean;
  logs: AppLog[];
  filterTag: string | null;
  filterCategory: string | null;
  telegramMessages: any[]; 
  setFilterTag: (tag: string | null) => void;
  setFilterCategory: (cat: string | null) => void;
  addNote: (content: string, title?: string, sourceType?: Note['sourceType'], useAI?: boolean, category?: string, audioData?: string) => Promise<void>;
  processLargeText: (text: string) => Promise<void>;
  updateNote: (note: Note) => Promise<void>;
  moveToTrash: (id: string) => Promise<void>;
  restoreNote: (id: string) => Promise<void>;
  hardDelete: (id: string) => Promise<void>;
  setNoteStatus: (id: string, status: NoteStatus) => Promise<void>;
  updateSettings: (s: Settings) => Promise<void>;
  addLog: (level: AppLog['level'], message: string, details?: string) => void;
  runAIAnalysis: (id: string) => Promise<void>;
  reanalyzeAll: () => Promise<void>;
  runSystemCheck: () => Promise<void>;
  updateNotePosition: (id: string, x: number, y: number) => Promise<void>;
  updateNoteSize: (id: string, w: number, h: number) => Promise<void>;
  syncTelegram: () => Promise<void>;
  deleteTelegramMsg: (id: number) => void;
  addGoal: (title: string, description: string) => Promise<void>;
  toggleGoalStatus: (id: string) => Promise<void>;
  deleteGoal: (id: string) => Promise<void>;
  addCategory: (name: string) => Promise<void>;
  deleteCategory: (name: string) => Promise<void>;
}

const NotesContext = createContext<NotesContextType | undefined>(undefined);

export const NotesProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [notes, setNotes] = useState<Note[]>([]);
  const [goals, setGoals] = useState<Goal[]>([]);
  const [settings, setSettings] = useState<Settings>(storage.getDefaultSettings());
  const [isLoading, setIsLoading] = useState(true);
  const [logs, setLogs] = useState<AppLog[]>([]);
  const [filterTag, setFilterTag] = useState<string | null>(null);
  const [filterCategory, setFilterCategory] = useState<string | null>(null);
  const [telegramMessages, setTelegramMessages] = useState<any[]>([]);

  const addLog = (level: AppLog['level'], message: string, details?: string) => {
    setLogs(prev => [{ id: crypto.randomUUID(), timestamp: new Date().toISOString(), level, message, details }, ...prev].slice(0, 200));
  };

  useEffect(() => {
    const init = async () => {
      const [n, s, g] = await Promise.all([storage.getNotes(), storage.getSettings(), storage.getGoals()]);
      setNotes(n);
      setSettings(s);
      setGoals(g || []);
      setIsLoading(false);
      document.documentElement.classList.toggle('dark', s.theme === 'dark');
    };
    init();
  }, []);

  const syncTelegram = async () => {
    if (!settings.tgToken) {
      addLog('warn', 'Telegram Token не настроен');
      return;
    }
    try {
      const offset = settings.tgLastUpdateId + 1;
      const response = await fetch(`https://api.telegram.org/bot${settings.tgToken}/getUpdates?offset=${offset}&timeout=5`);
      const data = await response.json();

      if (data.ok && data.result.length > 0) {
        const processedMsgs = [];
        for (const u of data.result) {
          const msg = u.message;
          if (!msg) continue;
          if (settings.tgChatId && String(msg.chat.id) !== settings.tgChatId) continue;
          let entry: any = { id: u.update_id, date: new Date(msg.date * 1000).toISOString(), from: msg.from.first_name || 'User', type: 'text', text: msg.text || msg.caption || '' };
          if (msg.photo) {
            const fileId = msg.photo[msg.photo.length - 1].file_id;
            const fileRes = await fetch(`https://api.telegram.org/bot${settings.tgToken}/getFile?file_id=${fileId}`);
            const fileData = await fileRes.json();
            if (fileData.ok) entry.type = 'photo', entry.fileUrl = `https://api.telegram.org/file/bot${settings.tgToken}/${fileData.result.file_path}`;
          } else if (msg.voice) {
            const fileId = msg.voice.file_id;
            const fileRes = await fetch(`https://api.telegram.org/bot${settings.tgToken}/getFile?file_id=${fileId}`);
            const fileData = await fileRes.json();
            if (fileData.ok) entry.type = 'voice', entry.fileUrl = `https://api.telegram.org/file/bot${settings.tgToken}/${fileData.result.file_path}`;
          }
          processedMsgs.push(entry);
        }
        const lastId = data.result[data.result.length - 1].update_id;
        const newSettings = { ...settings, tgLastUpdateId: lastId };
        setSettings(newSettings);
        await storage.saveSettings(newSettings);
        setTelegramMessages(prev => [...processedMsgs, ...prev]);
        addLog('success', `Telegram sync: +${processedMsgs.length} новых сообщений`);
      }
    } catch (e: any) {
      addLog('error', `Telegram sync failed: ${e.message}`);
    }
  };

  const deleteTelegramMsg = (id: number) => setTelegramMessages(prev => prev.filter(m => m.id !== id));

  const addNote = async (content: string, title?: string, sourceType: Note['sourceType'] = 'manual', useAI = true, forceCategory?: string, audioData?: string) => {
    let analysis: any = { tags: [], category: forceCategory || filterCategory || 'Общее', summary: '', title: title };
    let isIndexed = false;
    if (useAI && navigator.onLine) {
      addLog('info', 'ИИ анализирует новый контент...');
      try { 
        analysis = await ai.analyzeText(content, settings); 
        isIndexed = true;
      } catch (e: any) { 
        addLog('warn', `ИИ анализ пропущен: ${e.message}`); 
      }
    }
    const newNote: Note = {
      id: crypto.randomUUID(),
      title: title || analysis.title || content.slice(0, 40),
      content,
      tags: analysis.tags || [],
      category: forceCategory || analysis.category || filterCategory || 'Общее',
      summary: analysis.summary || '',
      status: 'new',
      isIndexed,
      sourceType,
      audioData,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      links: [],
      position: { x: Math.random() * 200, y: Math.random() * 200 },
      size: { w: 320, h: 280 }
    };
    const updated = [newNote, ...notes];
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const processLargeText = async (text: string) => {
    try {
      const parts = await ai.splitLargeText(text, settings);
      if (Array.isArray(parts)) {
        const generatedNotes = parts.map(part => ({
          id: crypto.randomUUID(),
          title: part.title || part.content.slice(0, 40),
          content: part.content,
          tags: [],
          category: part.category || 'Общее',
          summary: '',
          status: 'new' as NoteStatus,
          isIndexed: true,
          sourceType: 'split' as any,
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
          links: [],
          position: { x: Math.random() * 200, y: Math.random() * 200 },
          size: { w: 320, h: 280 }
        }));
        setNotes(prev => {
          const u = [...generatedNotes, ...prev];
          storage.saveNotes(u);
          return u;
        });
      }
    } catch (e: any) {
      addLog('error', `Ошибка разделения текста: ${e.message}`);
    }
  };

  const reanalyzeAll = async () => {
    const currentNotes = await storage.getNotes();
    const activeToProcess = currentNotes.filter(n => n.status !== 'trash');

    addLog('info', `[РЕИНДЕКС] Старт глубокого анализа для ${activeToProcess.length} файлов.`);

    // Работаем со стейтом поэтапно
    let processed = 0;
    let errors = 0;

    for (let i = 0; i < currentNotes.length; i++) {
      const note = currentNotes[i];
      if (note.status === 'trash') continue;

      try {
        if (!note.content || note.content.trim().length < 5) {
          addLog('warn', `Пропуск: "${note.title}" слишком короткий.`);
          continue;
        }

        addLog('info', `[${processed + 1}/${activeToProcess.length}] Анализ смысла: "${note.title}"...`);

        const result = await ai.analyzeText(note.content, settings);

        if (result && result.title) {
          const updatedNote = {
            ...note,
            ...result,
            isIndexed: true,
            updatedAt: new Date().toISOString()
          };

          // Важно: обновляем конкретный элемент в массиве
          currentNotes[i] = updatedNote;

          // Синхронизируем стейт и хранилище СРАЗУ, чтобы видеть прогресс
          setNotes([...currentNotes]);
          await storage.saveNotes([...currentNotes]);

          processed++;
          addLog('success', `Файл "${note.title}" обновлен: ${result.tags?.length || 0} тегов.`);
        } else {
          throw new Error("Пустой ответ от ИИ");
        }
      } catch (err: any) {
        errors++;
        addLog('error', `Сбой файла "${note.title}"`, err.message);
      }
    }

    addLog('success', `[РЕИНДЕКС ЗАВЕРШЕН] Успех: ${processed}, Ошибок: ${errors}. База синхронизирована.`);
  };

  const addGoal = async (title: string, description: string) => {
    const newGoal: Goal = { id: crypto.randomUUID(), title, description, createdAt: new Date().toISOString(), color: `hsl(${Math.random() * 360}, 70%, 50%)`, status: 'active' };
    const u = [newGoal, ...goals];
    setGoals(u);
    await storage.saveGoals(u);
  };

  const toggleGoalStatus = async (id: string) => {
    const u = goals.map(g => g.id === id ? { ...g, status: (g.status === 'active' ? 'completed' : 'active') as any } : g);
    setGoals(u);
    await storage.saveGoals(u);
  };

  const deleteGoal = async (id: string) => {
    const u = goals.filter(g => g.id !== id);
    setGoals(u);
    await storage.saveGoals(u);
  };

  const updateNote = async (n: Note) => {
    const u = notes.map(x => x.id === n.id ? n : x);
    setNotes(u);
    await storage.saveNotes(u);
  };

  const setNoteStatus = async (id: string, status: NoteStatus) => {
    const u = notes.map(n => n.id === id ? { ...n, status } : n);
    setNotes(u);
    await storage.saveNotes(u);
  };

  const moveToTrash = async (id: string) => {
    const u = notes.map(n => n.id === id ? { ...n, status: 'trash' as NoteStatus } : n);
    setNotes(u);
    await storage.saveNotes(u);
  };

  const addCategory = async (name: string) => {
    if (settings.customCategories.includes(name)) return;
    const s = { ...settings, customCategories: [...settings.customCategories, name] };
    await updateSettings(s);
  };

  const deleteCategory = async (name: string) => {
    if (name === 'Общее') return;
    const s = { ...settings, customCategories: settings.customCategories.filter(c => c !== name) };
    await updateSettings(s);
    const u = notes.map(n => n.category === name ? { ...n, category: 'Общее' } : n);
    setNotes(u);
    await storage.saveNotes(u);
  };

  const updateSettings = async (s: Settings) => {
    setSettings(s);
    await storage.saveSettings(s);
    document.documentElement.classList.toggle('dark', s.theme === 'dark');
  };

  const runAIAnalysis = async (id: string) => {
    const n = notes.find(x => x.id === id);
    if (!n) return;
    try {
      const res = await ai.analyzeText(n.content, settings);
      const u = notes.map(x => x.id === id ? { ...x, ...res, isIndexed: true, updatedAt: new Date().toISOString() } : x);
      setNotes(u);
      await storage.saveNotes(u);
      addLog('success', `Одиночный анализ заметки "${n.title}" завершен.`);
    } catch (e: any) {
      addLog('error', `Сбой анализа: ${e.message}`);
    }
  };

  return (
    <NotesContext.Provider value={{ 
      notes, goals, settings, isLoading, logs, filterTag, filterCategory, telegramMessages,
      setFilterTag, setFilterCategory, addNote, processLargeText, updateNote, moveToTrash, 
      restoreNote: async (id) => setNoteStatus(id, 'new'), 
      hardDelete: async (id) => { const u = notes.filter(x => x.id !== id); setNotes(u); await storage.saveNotes(u); },
      setNoteStatus, updateSettings, addLog, runAIAnalysis, reanalyzeAll,
      runSystemCheck: async () => { const r = await ai.testConnection(settings); r.success ? addLog('success', r.message) : addLog('error', r.message); },
      updateNotePosition: async (id, x, y) => { const u = notes.map(n => n.id === id ? { ...n, position: { x, y } } : n); setNotes(u); await storage.saveNotes(u); },
      updateNoteSize: async (id, w, h) => { const u = notes.map(n => n.id === id ? { ...n, size: { w, h } } : n); setNotes(u); await storage.saveNotes(u); },
      syncTelegram, deleteTelegramMsg, addGoal, toggleGoalStatus, deleteGoal, addCategory, deleteCategory
    }}>
      {children}
    </NotesContext.Provider>
  );
};

export const useNotes = () => {
  const c = useContext(NotesContext);
  if (!c) throw new Error("useNotes error");
  return c;
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useNotes } from '../contexts/NotesContext.tsx';
import { Note } from '../types.ts';
import { getTagColor } from '../utils/tagColors.ts';
import { 
  ChevronLeft, Save, Loader2, Sparkles, MessageSquare, Send, X, Folder, Globe, Hash, Play, Pause, Headphones, Volume2, Search, ExternalLink, Link2, ArrowRight, Plus
} from 'lucide-react';
import * as ai from '../utils/aiAdapter.ts';

const NoteEditor: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { notes, addNote, updateNote, runAIAnalysis, settings, addLog, setFilterTag } = useNotes();

  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [tags, setTags] = useState<string[]>([]);
  const [category, setCategory] = useState('Общее');
  const [tagInput, setTagInput] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [note, setNote] = useState<Note | null>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatMessages, setChatMessages] = useState<{role: 'user' | 'assistant', content: string}[]>([]);
  const [isChatLoading, setIsChatLoading] = useState(false);

  const [isPlaying, setIsPlaying] = useState(false);
  const [audioProgress, setAudioProgress] = useState(0);
  const [isTranscribing, setIsTranscribing] = useState(false);

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const visualizerCanvasRef = useRef<HTMLCanvasElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const animFrameRef = useRef<number | null>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    if (id && id !== 'new') {
      const found = notes.find(n => n.id === id);
      if (found) {
        setNote(found);
        setTitle(found.title);
        setContent(found.content);
        setTags(found.tags || []);
        setCategory(found.category || 'Общее');

        if (found.summary && chatMessages.length === 0) {
            setChatMessages([{ role: 'assistant', content: `Краткий анализ: ${found.summary}` }]);
        }
      }
    }
  }, [id, notes]);

  const relatedNotes = useMemo(() => {
    if (!id || id === 'new') return [];
    return notes.filter(n => {
        if (n.id === id || n.status === 'trash') return false;
        const sameCategory = n.category === category;
        const commonTags = n.tags.some(t => tags.includes(t));
        return sameCategory || commonTags;
    }).slice(0, 6);
  }, [id, notes, category, tags]);

  const handleAddTag = () => {
    const val = tagInput.trim();
    if (val && !tags.includes(val)) {
      setTags([...tags, val]);
      setTagInput('');
    }
  };

  useEffect(() => {
    if (isPlaying && !audioContextRef.current && audioRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      analyserRef.current = audioContextRef.current.createAnalyser();
      analyserRef.current.fftSize = 128;
      const source = audioContextRef.current.createMediaElementSource(audioRef.current);
      source.connect(analyserRef.current);
      analyserRef.current.connect(audioContextRef.current.destination);
    }

    if (isPlaying) {
      const draw = () => {
        const canvas = visualizerCanvasRef.current;
        const analyser = analyserRef.current;
        if (!canvas || !analyser) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;
        const bufferLength = analyser.frequencyBinCount;
        const dataArray = new Uint8Array(bufferLength);
        analyser.getByteFrequencyData(dataArray);
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        const barWidth = (canvas.width / bufferLength) * 2;
        let x = 0;
        for (let i = 0; i < bufferLength; i++) {
          const barHeight = (dataArray[i] / 255) * canvas.height;
          ctx.fillStyle = `rgba(59, 130, 246, ${0.4 + (dataArray[i]/255)})`;
          ctx.fillRect(x, canvas.height - barHeight, barWidth - 1, barHeight);
          x += barWidth;
        }
        animFrameRef.current = requestAnimationFrame(draw);
      };
      draw();
    } else if (animFrameRef.current) {
      cancelAnimationFrame(animFrameRef.current);
    }
    return () => { if (animFrameRef.current) cancelAnimationFrame(animFrameRef.current); };
  }, [isPlaying]);

  const handleTranscribe = async () => {
    if (!note?.audioData) return;
    setIsTranscribing(true);
    try {
        const response = await fetch(note.audioData);
        const blob = await response.blob();
        const text = await ai.transcribeAudio(blob, settings);
        setContent(text);
        addLog('success', 'Текст обновлен из аудио');
    } catch (e: any) {
        addLog('error', 'Ошибка: ' + e.message);
    } finally {
        setIsTranscribing(false);
    }
  };

  const handleAudioTimeUpdate = () => {
    if (audioRef.current) {
      const progress = (audioRef.current.currentTime / audioRef.current.duration) * 100;
      setAudioProgress(isNaN(progress) ? 0 : progress);
    }
  };

  const toggleAudio = () => {
    if (!audioRef.current) return;
    if (isPlaying) audioRef.current.pause();
    else audioRef.current.play().catch(e => console.error("Playback failed", e));
    setIsPlaying(!isPlaying);
  };

  const handleSave = async (useAI = false) => {
    if (!content.trim() && !title.trim()) return;
    setIsSaving(true);
    if (useAI) setIsAnalyzing(true);
    try {
        if (id === 'new') {
          await addNote(content, title, 'manual', useAI);
        } else if (note) {
          const updatedNote = { ...note, title, content, tags, category, updatedAt: new Date().toISOString() };
          await updateNote(updatedNote);
          if (useAI && navigator.onLine) {
            await runAIAnalysis(note.id);
          }
        }
        navigate('/');
    } catch (e: any) {
      addLog('error', 'Ошибка при сохранении: ' + e.message);
    } finally {
        setIsSaving(false);
        setIsAnalyzing(false);
    }
  };

  const handleChatSend = async () => {
    if (!chatInput.trim() || isChatLoading) return;
    const userMsg = chatInput;
    setChatMessages(prev => [...prev, { role: 'user', content: userMsg }]);
    setChatInput('');
    setIsChatLoading(true);
    try {
      const response = await ai.chatWithNotes(userMsg, content, settings);
      setChatMessages(prev => [...prev, { role: 'assistant', content: response }]);
    } catch (e: any) {
      setChatMessages(prev => [...prev, { role: 'assistant', content: `Сбой системы: ${e.message}` }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  return (
    <div className="h-screen flex flex-col bg-white dark:bg-[#020617] overflow-hidden">
      <header className="flex items-center justify-between px-12 py-8 border-b border-gray-100 dark:border-white/5 bg-white/80 dark:bg-slate-950/80 backdrop-blur-2xl z-20 shrink-0">
        <div className="flex items-center gap-6 flex-1">
          <button onClick={() => navigate(-1)} className="p-4 text-gray-400 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-2xl transition-all">
            <ChevronLeft size={24}/>
          </button>
          <div className="flex flex-col flex-1">
              <div className="flex items-center gap-4">
                <input 
                  className="text-4xl font-extrabold bg-transparent border-none focus:outline-none text-black dark:text-white flex-1 tracking-tighter placeholder:text-gray-200" 
                  value={title} 
                  onChange={e => setTitle(e.target.value)} 
                  placeholder="Заголовок..."
                />
                <button 
                  onClick={() => ai.openInGoogle(title)}
                  className="p-3 text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-xl transition-all shadow-sm"
                  title="Найти в Google"
                >
                  <Globe size={28} strokeWidth={2.5} />
                </button>
              </div>
              {note?.audioData && (
                <div className="flex items-center gap-6 mt-6 animate-in slide-in-from-top duration-500">
                  <div className="flex items-center gap-4 px-6 py-4 bg-gray-50 dark:bg-slate-900/50 rounded-[2.5rem] border border-gray-100 dark:border-white/10 shadow-sm">
                    <button onClick={toggleAudio} className="w-12 h-12 bg-blue-600 text-white rounded-full flex items-center justify-center hover:scale-105 transition-all shadow-lg active:scale-95">
                      {isPlaying ? <Pause size={20} fill="currentColor"/> : <Play size={20} fill="currentColor" className="ml-1"/>}
                    </button>
                    <div className="flex items-center h-8 w-24 px-1 bg-white/40 dark:bg-black/20 rounded-full overflow-hidden">
                        <canvas ref={visualizerCanvasRef} width={100} height={32} className="w-full h-full" />
                    </div>
                    <div className="w-48 h-2 bg-gray-200 dark:bg-slate-700 rounded-full overflow-hidden relative shadow-inner">
                       <div className="absolute inset-y-0 left-0 bg-blue-500 transition-all duration-300" style={{ width: `${audioProgress}%` }} />
                    </div>
                    <audio ref={audioRef} src={note.audioData} crossOrigin="anonymous" onTimeUpdate={handleAudioTimeUpdate} onEnded={() => setIsPlaying(false)} className="hidden" />
                  </div>
                  <button disabled={isTranscribing} onClick={handleTranscribe} className="flex items-center gap-3 px-8 py-4 bg-purple-600/10 text-purple-600 rounded-[2.5rem] text-[10px] font-black uppercase tracking-widest border border-purple-500/20 hover:bg-purple-600/20 transition-all disabled:opacity-50">
                      {isTranscribing ? <Loader2 size={16} className="animate-spin" /> : <Sparkles size={16}/>}
                      Распознать
                  </button>
                </div>
              )}
          </div>
        </div>
        <div className="flex items-center gap-4">
          <button onClick={() => handleSave(true)} className="px-8 py-5 bg-cyan-600/10 text-cyan-600 dark:text-cyan-400 rounded-[2rem] font-black uppercase text-[10px] tracking-widest flex items-center gap-3 border border-cyan-500/10">
            {isAnalyzing ? <Loader2 size={18} className="animate-spin"/> : <Sparkles size={18}/>}
            AI Анализ
          </button>
          <button onClick={() => handleSave(false)} className="px-10 py-5 bg-blue-600 text-white rounded-[2rem] font-black uppercase text-[10px] tracking-widest shadow-xl flex items-center gap-3 active:scale-95 transition-all">
            {isSaving ? <Loader2 size={18} className="animate-spin"/> : <Save size={18}/>}
            Сохранить
          </button>
        </div>
      </header>

      <div className="flex-1 flex overflow-hidden">
        <div className="flex-1 overflow-y-auto custom-scrollbar bg-gray-50/5 p-12 lg:p-24 pb-48">
          <div className="max-w-5xl mx-auto w-full space-y-16">
            <textarea 
              ref={textareaRef}
              className="w-full h-auto min-h-[400px] bg-transparent border-none focus:outline-none text-2xl leading-relaxed text-gray-800 dark:text-slate-200 resize-none font-medium placeholder:text-gray-200"
              value={content}
              onChange={e => setContent(e.target.value)}
              placeholder="Напишите историю или распознайте голос..."
            />

            {relatedNotes.length > 0 && (
              <div className="pt-12 border-t border-gray-100 dark:border-white/5 animate-in slide-in-from-bottom duration-500">
                <h4 className="text-[12px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-3 mb-8">
                  <Link2 size={18} className="text-blue-500"/> Связанные знания
                </h4>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {relatedNotes.map(rn => (
                    <button 
                      key={rn.id}
                      onClick={() => navigate(`/editor/${rn.id}`)}
                      className="w-full text-left p-6 bg-white dark:bg-slate-900 rounded-[2rem] border border-gray-100 dark:border-white/5 hover:border-blue-500 transition-all group shadow-sm flex flex-col justify-between h-40"
                    >
                      <div>
