export default SettingsPage;

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Note, Settings, AIProvider, AppLog, NoteStatus, Goal } from '../types.ts';
import * as storage from '../utils/storage.ts';
import * as ai from '../utils/aiAdapter.ts';

interface NotesContextType {
  notes: Note[];
  goals: Goal[];
  settings: Settings;
  isLoading: boolean;
  logs: AppLog[];
  filterTag: string | null;
  filterCategory: string | null;
  telegramMessages: any[]; 
  setFilterTag: (tag: string | null) => void;
  setFilterCategory: (cat: string | null) => void;
  addNote: (content: string, title?: string, sourceType?: Note['sourceType'], useAI?: boolean, category?: string, audioData?: string) => Promise<void>;
  processLargeText: (text: string) => Promise<void>;
  updateNote: (note: Note) => Promise<void>;
  moveToTrash: (id: string) => Promise<void>;
  restoreNote: (id: string) => Promise<void>;
  hardDelete: (id: string) => Promise<void>;
  setNoteStatus: (id: string, status: NoteStatus) => Promise<void>;
  updateSettings: (s: Settings) => Promise<void>;
  addLog: (level: AppLog['level'], message: string, details?: string) => void;
  runAIAnalysis: (id: string) => Promise<void>;
  reanalyzeAll: () => Promise<void>;
  runSystemCheck: () => Promise<void>;
  updateNotePosition: (id: string, x: number, y: number) => Promise<void>;
  updateNoteSize: (id: string, w: number, h: number) => Promise<void>;
  syncTelegram: () => Promise<void>;
  deleteTelegramMsg: (id: number) => void;
  addGoal: (title: string, description: string) => Promise<void>;
  toggleGoalStatus: (id: string) => Promise<void>;
  deleteGoal: (id: string) => Promise<void>;
  addCategory: (name: string) => Promise<void>;
  deleteCategory: (name: string) => Promise<void>;
}

const NotesContext = createContext<NotesContextType | undefined>(undefined);

export const NotesProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [notes, setNotes] = useState<Note[]>([]);
  const [goals, setGoals] = useState<Goal[]>([]);
  const [settings, setSettings] = useState<Settings>(storage.getDefaultSettings());
  const [isLoading, setIsLoading] = useState(true);
  const [logs, setLogs] = useState<AppLog[]>([]);
  const [filterTag, setFilterTag] = useState<string | null>(null);
  const [filterCategory, setFilterCategory] = useState<string | null>(null);

  const addLog = (level: AppLog['level'], message: string, details?: string) => {
    setLogs(prev => [{ id: crypto.randomUUID(), timestamp: new Date().toISOString(), level, message, details }, ...prev].slice(0, 150));
  };

  useEffect(() => {
    const init = async () => {
      const [n, s, g] = await Promise.all([storage.getNotes(), storage.getSettings(), storage.getGoals()]);
      setNotes(n);
      setSettings(s);
      setGoals(g || []);
      setIsLoading(false);
      document.documentElement.classList.toggle('dark', s.theme === 'dark');
    };
    init();
  }, []);

  const syncTelegram = async () => {
    if (!settings.tgToken) {
      addLog('warn', 'Telegram Token не настроен');
      return;
    }
    try {
      const offset = settings.tgLastUpdateId + 1;
      const response = await fetch(`https://api.telegram.org/bot${settings.tgToken}/getUpdates?offset=${offset}&timeout=5`);
      const data = await response.json();

      if (data.ok && data.result.length > 0) {
        const processedMsgs = [];
        for (const u of data.result) {
          const msg = u.message;
          if (!msg) continue;
          if (settings.tgChatId && String(msg.chat.id) !== settings.tgChatId) continue;
          let entry: any = { id: u.update_id, date: new Date(msg.date * 1000).toISOString(), from: msg.from.first_name || 'User', type: 'text', text: msg.text || msg.caption || '' };
          processedMsgs.push(entry);
        }
        const lastId = data.result[data.result.length - 1].update_id;
        const newSettings = { ...settings, tgLastUpdateId: lastId };
        setSettings(newSettings);
        await storage.saveSettings(newSettings);
        addLog('success', `Telegram sync: +${processedMsgs.length} новых сообщений`);
      }
    } catch (e: any) {
      addLog('error', `Telegram sync failed: ${e.message}`);
    }
  };

  const addNote = async (content: string, title?: string, sourceType: Note['sourceType'] = 'manual', useAI = true, forceCategory?: string, audioData?: string) => {
    let analysis: any = { tags: [], category: forceCategory || filterCategory || 'Общее', summary: '', title: title };
    let isIndexed = false;
    if (useAI && navigator.onLine) {
      addLog('info', 'ИИ анализирует новый контент...');
      try { 
        analysis = await ai.analyzeText(content, settings); 
        isIndexed = true;
      } catch (e: any) { 
        addLog('warn', `ИИ анализ пропущен: ${e.message}`); 
      }
    }
    const newNote: Note = {
      id: crypto.randomUUID(),
      title: title || analysis.title || content.slice(0, 40),
      content,
      tags: analysis.tags || [],
      category: forceCategory || analysis.category || filterCategory || 'Общее',
      summary: analysis.summary || '',
      status: 'new',
      isIndexed,
      sourceType,
      audioData,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      links: [],
      position: { x: Math.random() * 200, y: Math.random() * 200 },
      size: { w: 320, h: 280 }
    };
    setNotes(prev => {
      const updated = [newNote, ...prev];
      storage.saveNotes(updated);
      return updated;
    });
  };

  const processLargeText = async (text: string) => {
    try {
      const parts = await ai.splitLargeText(text, settings);
      if (Array.isArray(parts)) {
        const generatedNotes = parts.map(part => ({
          id: crypto.randomUUID(),
          title: part.title || part.content.slice(0, 40),
          content: part.content,
          tags: [],
          category: part.category || 'Общее',
          summary: '',
          status: 'new' as NoteStatus,
          isIndexed: true,
          sourceType: 'split' as any,
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
          links: [],
          position: { x: Math.random() * 200, y: Math.random() * 200 },
          size: { w: 320, h: 280 }
        }));
        setNotes(prev => {
          const u = [...generatedNotes, ...prev];
          storage.saveNotes(u);
          return u;
        });
      }
    } catch (e: any) {
      addLog('error', `Ошибка разделения текста: ${e.message}`);
    }
  };

  const reanalyzeAll = async () => {
    // 1. Получаем абсолютно свежий список заметок из хранилища
    const allNotesFromDB = await storage.getNotes();
    const activeNotes = allNotesFromDB.filter(n => n.status !== 'trash');

    addLog('info', `[ГЛУБОКИЙ РЕИНДЕКС] Запуск для ${activeNotes.length} активных файлов.`);

    // Работаем с локальной копией массива, которую будем обновлять инкрементально
    const results: Note[] = [...allNotesFromDB];
    let processedCount = 0;
    let errorCount = 0;

    // 2. Последовательный обход каждой активной заметки
    for (let i = 0; i < results.length; i++) {
      const note = results[i];
      if (note.status === 'trash') continue;

      try {
        if (!note.content || note.content.trim().length < 5) {
          addLog('warn', `[Пропуск] "${note.title}": слишком мало текста.`);
          continue;
        }

        const currentTaskNumber = processedCount + errorCount + 1;
        addLog('info', `[${currentTaskNumber}/${activeNotes.length}] Анализ: "${note.title}"...`);

        // 3. Вызов ИИ для переоценки смысла
        const analysis = await ai.analyzeText(note.content, settings);

        if (analysis && (analysis.title || analysis.tags)) {
          results[i] = {
            ...note,
            ...analysis,
            isIndexed: true,
            updatedAt: new Date().toISOString()
          };
          processedCount++;

          // 4. Мгновенная синхронизация: обновляем глобальное состояние и БД СРАЗУ
          // Это гарантирует, что даже при сбое мы не потеряем прогресс.
          const currentBatch = [...results];
          setNotes(currentBatch);
          await storage.saveNotes(currentBatch);

          addLog('success', `[Готово] "${note.title}" обновлен (${analysis.tags?.length || 0} тегов).`);
        } else {
          throw new Error("ИИ вернул некорректные данные или пустой ответ.");
        }
      } catch (err: any) {
        errorCount++;
        addLog('error', `[Ошибка] в заметке "${note.title}"`, err.message);
        // Не прерываем цикл, продолжаем со следующей заметкой
      }
    }

    addLog('success', `[РЕИНДЕКС ЗАВЕРШЕН] Успешно: ${processedCount}, Ошибок: ${errorCount}.`);
  };

  const addGoal = async (title: string, description: string) => {
    const newGoal: Goal = { id: crypto.randomUUID(), title, description, createdAt: new Date().toISOString(), color: `hsl(${Math.random() * 360}, 70%, 50%)`, status: 'active' };
    const u = [newGoal, ...goals];
    setGoals(u);
    await storage.saveGoals(u);
  };

  const toggleGoalStatus = async (id: string) => {
    const u = goals.map(g => g.id === id ? { ...g, status: (g.status === 'active' ? 'completed' : 'active') as any } : g);
    setGoals(u);
    await storage.saveGoals(u);
  };

  const deleteGoal = async (id: string) => {
    const u = goals.filter(g => g.id !== id);
    setGoals(u);
    await storage.saveGoals(u);
  };

  const updateNote = async (n: Note) => {
    setNotes(prev => {
      const u = prev.map(x => x.id === n.id ? n : x);
      storage.saveNotes(u);
      return u;
    });
  };

  const setNoteStatus = async (id: string, status: NoteStatus) => {
    setNotes(prev => {
      const u = prev.map(n => n.id === id ? { ...n, status } : n);
      storage.saveNotes(u);
      return u;
    });
  };

  const moveToTrash = async (id: string) => {
    setNotes(prev => {
      const u = prev.map(n => n.id === id ? { ...n, status: 'trash' as NoteStatus } : n);
      storage.saveNotes(u);
      return u;
    });
  };

  const addCategory = async (name: string) => {
    if (settings.customCategories.includes(name)) return;
    const s = { ...settings, customCategories: [...settings.customCategories, name] };
    await updateSettings(s);
  };

  const deleteCategory = async (name: string) => {
    if (name === 'Общее') return;
    const s = { ...settings, customCategories: settings.customCategories.filter(c => c !== name) };
    await updateSettings(s);
    setNotes(prev => {
        const u = prev.map(n => n.category === name ? { ...n, category: 'Общее' } : n);
        storage.saveNotes(u);
        return u;
    });
  };

  const updateSettings = async (s: Settings) => {
    setSettings(s);
    await storage.saveSettings(s);
    document.documentElement.classList.toggle('dark', s.theme === 'dark');
  };

  const runAIAnalysis = async (id: string) => {
    const n = notes.find(x => x.id === id);
    if (!n) return;
    try {
      addLog('info', `Запуск ИИ-анализа для "${n.title}"...`);
      const res = await ai.analyzeText(n.content, settings);
      setNotes(prev => {
        const u = prev.map(x => x.id === id ? { ...x, ...res, isIndexed: true, updatedAt: new Date().toISOString() } : x);
        storage.saveNotes(u);
        return u;
      });
      addLog('success', `Анализ "${n.title}" завершен.`);
    } catch (e: any) {
      addLog('error', `Сбой анализа: ${e.message}`);
    }
  };

  return (
    <NotesContext.Provider value={{ 
      notes, goals, settings, isLoading, logs, filterTag, filterCategory, telegramMessages: [],
      setFilterTag, setFilterCategory, addNote, processLargeText, updateNote, moveToTrash, 
      restoreNote: async (id) => setNoteStatus(id, 'new'), 
      hardDelete: async (id) => { setNotes(prev => { const u = prev.filter(x => x.id !== id); storage.saveNotes(u); return u; }); },
      setNoteStatus, updateSettings, addLog, runAIAnalysis, reanalyzeAll,
      runSystemCheck: async () => { const r = await ai.testConnection(settings); r.success ? addLog('success', r.message) : addLog('error', r.message); },
      updateNotePosition: async (id, x, y) => { setNotes(prev => { const u = prev.map(n => n.id === id ? { ...n, position: { x, y } } : n); storage.saveNotes(u); return u; }); },
      updateNoteSize: async (id, w, h) => { setNotes(prev => { const u = prev.map(n => n.id === id ? { ...n, size: { w, h } } : n); storage.saveNotes(u); return u; }); },
      syncTelegram, deleteTelegramMsg: () => {}, addGoal, toggleGoalStatus, deleteGoal, addCategory, deleteCategory
    }}>
      {children}
    </NotesContext.Provider>
  );
};

export const useNotes = () => {
  const c = useContext(NotesContext);
  if (!c) throw new Error("useNotes error");
  return c;
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useNotes } from '../contexts/NotesContext.tsx';
import { Note } from '../types.ts';
import { getTagColor } from '../utils/tagColors.ts';
import { 
  ChevronLeft, Save, Loader2, Sparkles, MessageSquare, Send, X, Folder, Globe, Hash, Play, Pause, Headphones, Search, Link2, ArrowRight, Plus
} from 'lucide-react';
import * as ai from '../utils/aiAdapter.ts';

const NoteEditor: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { notes, addNote, updateNote, runAIAnalysis, settings, addLog, setFilterTag } = useNotes();

  // Используем локальные стейты для предотвращения прыжков курсора при глобальных обновлениях
  const [localTitle, setLocalTitle] = useState('');
  const [localContent, setLocalContent] = useState('');
  const [localTags, setLocalTags] = useState<string[]>([]);
  const [localCategory, setLocalCategory] = useState('Общее');

  const [tagInput, setTagInput] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [note, setNote] = useState<Note | null>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatMessages, setChatMessages] = useState<{role: 'user' | 'assistant', content: string}[]>([]);
  const [isChatLoading, setIsChatLoading] = useState(false);

  const [isPlaying, setIsPlaying] = useState(false);
  const [audioProgress, setAudioProgress] = useState(0);
  const [isTranscribing, setIsTranscribing] = useState(false);

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const visualizerCanvasRef = useRef<HTMLCanvasElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const animFrameRef = useRef<number | null>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  // Инициализация данных при загрузке страницы
  useEffect(() => {
    if (id && id !== 'new') {
      const found = notes.find(n => n.id === id);
      if (found) {
        // Установка данных только если они изменились или еще не установлены
        // Это предотвращает потерю фокуса и сброс контента при обновлении массива notes в фоне.
        setNote(found);
        if (localTitle === '' || found.title !== localTitle) setLocalTitle(found.title);
        if (localContent === '' || found.content !== localContent) setLocalContent(found.content);
        setLocalTags(found.tags || []);
        setLocalCategory(found.category || 'Общее');

        if (found.summary && chatMessages.length === 0) {
            setChatMessages([{ role: 'assistant', content: `Краткий анализ: ${found.summary}` }]);
        }
      }
    }
  }, [id, notes]);

  const relatedNotes = useMemo(() => {
    if (!id || id === 'new') return [];
    return notes.filter(n => {
        if (n.id === id || n.status === 'trash') return false;
        const sameCategory = n.category === localCategory;
        const commonTags = n.tags.some(t => localTags.includes(t));
        return sameCategory || commonTags;
    }).slice(0, 6);
  }, [id, notes, localCategory, localTags]);

  const handleAddTag = () => {
    const val = tagInput.trim();
    if (val && !localTags.includes(val)) {
      setLocalTags([...localTags, val]);
      setTagInput('');
    }
  };

  useEffect(() => {
    if (isPlaying && !audioContextRef.current && audioRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      analyserRef.current = audioContextRef.current.createAnalyser();
      analyserRef.current.fftSize = 128;
      const source = audioContextRef.current.createMediaElementSource(audioRef.current);
      source.connect(analyserRef.current);
      analyserRef.current.connect(audioContextRef.current.destination);
    }

    if (isPlaying) {
      const draw = () => {
        const canvas = visualizerCanvasRef.current;
        const analyser = analyserRef.current;
        if (!canvas || !analyser) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;
        const bufferLength = analyser.frequencyBinCount;
        const dataArray = new Uint8Array(bufferLength);
        analyser.getByteFrequencyData(dataArray);
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        const barWidth = (canvas.width / bufferLength) * 2;
        let x = 0;
        for (let i = 0; i < bufferLength; i++) {
          const barHeight = (dataArray[i] / 255) * canvas.height;
          ctx.fillStyle = `rgba(59, 130, 246, ${0.4 + (dataArray[i]/255)})`;
          ctx.fillRect(x, canvas.height - barHeight, barWidth - 1, barHeight);
          x += barWidth;
        }
        animFrameRef.current = requestAnimationFrame(draw);
      };
      draw();
    } else if (animFrameRef.current) {
      cancelAnimationFrame(animFrameRef.current);
    }
    return () => { if (animFrameRef.current) cancelAnimationFrame(animFrameRef.current); };
  }, [isPlaying]);

  const handleTranscribe = async () => {
    if (!note?.audioData) return;
    setIsTranscribing(true);
    try {
        const response = await fetch(note.audioData);
