          <div>
            <h2 className="text-5xl font-black dark:text-white tracking-tighter leading-none">Система</h2>
            <p className="text-[11px] font-black text-blue-600 uppercase tracking-[0.4em] mt-3 flex items-center gap-2">
                <Activity size={12}/> Diagnostic Interface v3.7
            </p>
          </div>
        </div>
        <div className="flex flex-wrap gap-4 justify-center">
          <button 
            onClick={handleReanalyze} 
            disabled={isReanalyzing} 
            className={`px-8 py-5 rounded-[2rem] font-black text-[11px] uppercase flex items-center gap-3 transition-all active:scale-95 shadow-lg ${
              isReanalyzing ? 'bg-amber-100 text-amber-600' : 'bg-amber-50 text-amber-600 dark:bg-amber-900/10 dark:text-amber-400 hover:bg-amber-100'
            }`}
