import { Settings, AIProvider } from '../types.ts';
import { GoogleGenAI, Type } from "@google/genai";

const extractJSON = (str: string) => {
  if (!str) return {};
  let trimmed = str.trim();
  // Удаляем Markdown обертки если они есть
  trimmed = trimmed.replace(/^```json/i, '').replace(/```$/g, '').trim();

  try {
    return JSON.parse(trimmed);
  } catch (e) {
    const jsonRegex = /\{[\s\S]*\}|\[[\s\S]*\]/;
    const match = trimmed.match(jsonRegex);
    if (match) {
      try {
        const cleaned = match[0].trim();
        return JSON.parse(cleaned);
      } catch (inner) {}
    }
    console.error("Failed to parse AI JSON:", trimmed);
    return {};
  }
};

export const linkify = (text: string) => {
  const urlRegex = /(https?:\/\/[^\s]+)/g;
  return text.split(urlRegex).map((part) => {
    if (part.match(urlRegex)) {
      return `<a href="${part}" target="_blank" rel="noopener noreferrer" class="text-blue-500 underline">${part}</a>`;
    }
    return part;
  }).join('');
};

export const openInGoogle = (query: string) => {
  if (!query) return;
  window.open(`https://www.google.com/search?q=${encodeURIComponent(query)}`, '_blank');
};

async function callAI(
  prompt: string, 
  provider: AIProvider, 
  model: string, 
  apiKey: string, 
  baseUrl: string, 
  isJson: boolean, 
  systemInstruction?: string,
  mediaPart?: { data: string, mimeType: string }
) {
  if (provider === AIProvider.Gemini) {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const parts: any[] = [{ text: prompt }];
    if (mediaPart) {
      parts.unshift({ inlineData: mediaPart });
    }

    const response = await ai.models.generateContent({
      model: model || 'gemini-3-flash-preview',
      contents: [{ parts }],
      config: {
        systemInstruction,
        responseMimeType: isJson ? "application/json" : undefined
      }
    });

    const generatedText = response.text || '';
    return isJson ? extractJSON(generatedText) : generatedText;
  }

  let url = (baseUrl || '').trim().replace(/\/$/, '');
  if (provider === AIProvider.Ollama) {
    url = url || 'http://localhost:11434';
    url += '/api/chat';
  } else {
    url = url || (provider === AIProvider.OpenRouter ? 'https://openrouter.ai/api/v1' : 'http://localhost:1234/v1');
    if (!url.endsWith('/chat/completions')) url += '/chat/completions';
  }

  const messages = [
    ...(systemInstruction ? [{ role: 'system', content: systemInstruction }] : []),
    { role: 'user', content: prompt }
  ];

  const body = { 
    model, 
    messages, 
    stream: false, 
    ...(provider === AIProvider.Ollama && isJson ? { format: 'json' } : {}) 
  };
  const headers: any = { 'Content-Type': 'application/json' };
  if (apiKey) headers['Authorization'] = `Bearer ${apiKey}`;

  const res = await fetch(url, { method: 'POST', headers, body: JSON.stringify(body) });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  const data = await res.json();
  const content = provider === AIProvider.Ollama ? data.message.content : data.choices[0].message.content;
  return isJson ? extractJSON(content) : content;
}

export const analyzeText = async (text: string, settings: Settings) => {
  const prompt = `ВЕРНИ JSON ОБЪЕКТ: { "title": "краткий заголовок", "tags": ["тег1", "тег2"], "category": "категория", "summary": "суть текста одним предложением" }. ТЕКСТ: ${text}`;
  return await callAI(prompt, settings.provider, settings.model, settings.apiKey, settings.url, true, "Ты — системный аналитик базы знаний.");
};

export const transcribeAudio = async (blob: Blob, settings: Settings) => {
  const reader = new FileReader();
  const base64: string = await new Promise((resolve) => {
    reader.onload = () => resolve((reader.result as string).split(',')[1]);
    reader.readAsDataURL(blob);
  });

  return await callAI(
    "Распознай речь и верни только текст.",
    settings.transProvider,
    settings.transModel || 'gemini-2.5-flash-native-audio-preview-12-2025',
    settings.transApiKey,
    settings.transUrl,
    false,
    "Ты — профессиональный эксперт по транскрибации аудио.",
    { data: base64, mimeType: blob.type }
  );
};

export const chatWithNotes = async (query: string, context: string, settings: Settings) => {
  return await callAI(`Контекст: ${context}\nВопрос: ${query}`, settings.provider, settings.model, settings.apiKey, settings.url, false);
};

export const chatWithAgent = async (query: string, appData: any, settings: Settings) => {
  return await callAI(`Данные системы: ${JSON.stringify(appData)}\nЗапрос пользователя: ${query}`, settings.agentProvider, settings.agentModel, settings.agentApiKey, settings.agentUrl, false, "Ты — системный агент ScreenMind.");
};

export const performOCR = async (base64Data: string, mimeType: string, settings: Settings) => {
  const dataOnly = base64Data.split(',')[1] || base64Data;
  return await callAI("Распознай весь видимый текст.", settings.ocrProvider, settings.ocrModel, settings.ocrApiKey, settings.ocrUrl, false, undefined, { data: dataOnly, mimeType });
};

export const testConnection = async (settings: Settings) => {
  try {
    const res = await callAI("Say OK", settings.provider, settings.model, settings.apiKey, settings.url, false);
    return { success: true, message: `Соединение OK: ${res}` };
  } catch (e: any) {
    return { success: false, message: e.message };
  }
};

export const splitLargeText = async (text: string, settings: Settings) => {
  const prompt = `Раздели текст на логические части и верни JSON массив объектов [{ "title": "...", "content": "...", "category": "..." }]. ТЕКСТ: ${text}`;
  return await callAI(prompt, settings.provider, settings.model, settings.apiKey, settings.url, true, "Ты — эксперт по структурированию информации.");
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Note, Settings, AIProvider, AppLog, NoteStatus, Goal } from '../types.ts';
import * as storage from '../utils/storage.ts';
import * as ai from '../utils/aiAdapter.ts';

interface NotesContextType {
  notes: Note[];
  goals: Goal[];
  settings: Settings;
  isLoading: boolean;
  logs: AppLog[];
  filterTag: string | null;
  filterCategory: string | null;
  telegramMessages: any[]; 
  setFilterTag: (tag: string | null) => void;
  setFilterCategory: (cat: string | null) => void;
  addNote: (content: string, title?: string, sourceType?: Note['sourceType'], useAI?: boolean, category?: string, audioData?: string) => Promise<void>;
  processLargeText: (text: string) => Promise<void>;
  updateNote: (note: Note) => Promise<void>;
  moveToTrash: (id: string) => Promise<void>;
  restoreNote: (id: string) => Promise<void>;
  hardDelete: (id: string) => Promise<void>;
  setNoteStatus: (id: string, status: NoteStatus) => Promise<void>;
  updateSettings: (s: Settings) => Promise<void>;
  addLog: (level: AppLog['level'], message: string, details?: string) => void;
  runAIAnalysis: (id: string) => Promise<void>;
  reanalyzeAll: () => Promise<void>;
  runSystemCheck: () => Promise<void>;
  updateNotePosition: (id: string, x: number, y: number) => Promise<void>;
  updateNoteSize: (id: string, w: number, h: number) => Promise<void>;
  syncTelegram: () => Promise<void>;
  deleteTelegramMsg: (id: number) => void;
  addGoal: (title: string, description: string) => Promise<void>;
  toggleGoalStatus: (id: string) => Promise<void>;
  deleteGoal: (id: string) => Promise<void>;
  addCategory: (name: string) => Promise<void>;
  deleteCategory: (name: string) => Promise<void>;
}

const NotesContext = createContext<NotesContextType | undefined>(undefined);

export const NotesProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [notes, setNotes] = useState<Note[]>([]);
  const [goals, setGoals] = useState<Goal[]>([]);
  const [settings, setSettings] = useState<Settings>(storage.getDefaultSettings());
  const [isLoading, setIsLoading] = useState(true);
  const [logs, setLogs] = useState<AppLog[]>([]);
  const [filterTag, setFilterTag] = useState<string | null>(null);
  const [filterCategory, setFilterCategory] = useState<string | null>(null);

  const addLog = (level: AppLog['level'], message: string, details?: string) => {
    const newLog: AppLog = { 
      id: crypto.randomUUID(), 
      timestamp: new Date().toISOString(), 
      level, 
      message, 
      details 
    };
    setLogs(prev => [newLog, ...prev].slice(0, 1000));
  };

  useEffect(() => {
    const init = async () => {
      const [n, s, g] = await Promise.all([storage.getNotes(), storage.getSettings(), storage.getGoals()]);
      setNotes(n);
      setSettings(s);
      setGoals(g || []);
      setIsLoading(false);
      document.documentElement.classList.toggle('dark', s.theme === 'dark');
    };
    init();
  }, []);

  const addNote = async (content: string, title?: string, sourceType: Note['sourceType'] = 'manual', useAI = true, forceCategory?: string, audioData?: string) => {
    let analysis: any = { tags: [], category: forceCategory || filterCategory || 'Общее', summary: '', title: title };
    let isIndexed = false;
    if (useAI && navigator.onLine) {
      addLog('info', 'ИИ анализирует новый контент...');
      try { 
        analysis = await ai.analyzeText(content, settings); 
        isIndexed = true;
      } catch (e: any) { 
        addLog('warn', `ИИ анализ пропущен: ${e.message}`); 
      }
    }
    const newNote: Note = {
      id: crypto.randomUUID(),
      title: title || analysis.title || content.slice(0, 40),
      content,
      tags: analysis.tags || [],
      category: forceCategory || analysis.category || filterCategory || 'Общее',
      summary: analysis.summary || '',
      status: 'new',
      isIndexed,
      sourceType,
      audioData,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      links: [],
      position: { x: Math.random() * 200, y: Math.random() * 200 },
      size: { w: 320, h: 280 }
    };
    setNotes(prev => {
      const updated = [newNote, ...prev];
      storage.saveNotes(updated);
      return updated;
    });
  };

  const processLargeText = async (text: string) => {
    addLog('info', 'Smart Split: Сегментация ИИ запущена...');
    try {
      const parts = await ai.splitLargeText(text, settings);
      if (Array.isArray(parts) && parts.length > 0) {
        addLog('success', `ИИ разделил текст на ${parts.length} карточек. Импорт...`);
        for (const part of parts) {
          await addNote(part.content, part.title, 'split', false, part.category);
        }
        addLog('success', 'Smart Split завершен.');
      } else {
        addLog('error', 'Smart Split: ИИ вернул неверный ответ.');
      }
    } catch (e: any) {
      addLog('error', 'Smart Split Error', e.message);
    }
  };

  const reanalyzeAll = async () => {
    const allNotes = await storage.getNotes();
    const activeNotes = allNotes.filter(n => n.status !== 'trash' && n.content.length > 5);

    addLog('info', `[ГЛУБОКИЙ РЕИНДЕКС] Старт для ${activeNotes.length} файлов.`);

    let currentBatch = [...allNotes];
    let processedCount = 0;
    let errorCount = 0;

    for (let i = 0; i < currentBatch.length; i++) {
      const note = currentBatch[i];
      if (note.status === 'trash' || note.content.length <= 5) continue;

      try {
        const step = processedCount + errorCount + 1;
        addLog('info', `[${step}/${activeNotes.length}] ИИ Анализ: "${note.title}"...`);

        // Задержка против 429 Error
        await new Promise(r => setTimeout(r, 1200));

        const analysis = await ai.analyzeText(note.content, settings);

        if (analysis && (analysis.title || analysis.tags)) {
          currentBatch[i] = {
            ...note,
            ...analysis,
            isIndexed: true,
            updatedAt: new Date().toISOString()
          };

          processedCount++;
          // Сохраняем прогресс сразу в стейт и БД
          const update = [...currentBatch];
          setNotes(update);
          await storage.saveNotes(update);
          addLog('success', `Файл "${note.title}" успешно проиндексирован.`);
        } else {
          throw new Error("ИИ вернул пустой результат.");
        }
      } catch (err: any) {
        errorCount++;
        addLog('error', `Ошибка в "${note.title}": ${err.message}`);
      }
    }

    addLog('success', `[РЕИНДЕКС ЗАВЕРШЕН] Успех: ${processedCount}, Ошибок: ${errorCount}.`);
  };

  const updateSettings = async (s: Settings) => {
    setSettings(s);
    await storage.saveSettings(s);
    document.documentElement.classList.toggle('dark', s.theme === 'dark');
  };

  const updateNote = async (n: Note) => {
    setNotes(prev => {
      const u = prev.map(x => x.id === n.id ? n : x);
      storage.saveNotes(u);
      return u;
    });
  };

  const setNoteStatus = async (id: string, status: NoteStatus) => {
    setNotes(prev => {
      const u = prev.map(n => n.id === id ? { ...n, status } : n);
      storage.saveNotes(u);
      return u;
    });
  };

  const moveToTrash = async (id: string) => {
    setNoteStatus(id, 'trash');
  };

  const runAIAnalysis = async (id: string) => {
    const n = notes.find(x => x.id === id);
    if (!n) return;
    try {
      addLog('info', `Ручной ИИ-анализ: "${n.title}"...`);
      const res = await ai.analyzeText(n.content, settings);
      setNotes(prev => {
        const u = prev.map(x => x.id === id ? { ...x, ...res, isIndexed: true, updatedAt: new Date().toISOString() } : x);
        storage.saveNotes(u);
        return u;
      });
      addLog('success', `Анализ "${n.title}" завершен.`);
    } catch (e: any) {
      addLog('error', `Сбой анализа: ${e.message}`);
    }
  };

  return (
    <NotesContext.Provider value={{ 
      notes, goals, settings, isLoading, logs, filterTag, filterCategory, telegramMessages: [],
      setFilterTag, setFilterCategory, addNote, processLargeText, 
      updateNote, moveToTrash, 
      restoreNote: async (id) => setNoteStatus(id, 'new'), 
      hardDelete: async (id) => { setNotes(prev => { const u = prev.filter(x => x.id !== id); storage.saveNotes(u); return u; }); },
      setNoteStatus, updateSettings, addLog, runAIAnalysis, reanalyzeAll,
      runSystemCheck: async () => { 
        addLog('info', 'Тестирование ИИ...');
        const r = await ai.testConnection(settings); 
        r.success ? addLog('success', r.message) : addLog('error', 'Тест провален', r.message); 
      },
      updateNotePosition: async (id, x, y) => { setNotes(prev => { const u = prev.map(n => n.id === id ? { ...n, position: { x, y } } : n); storage.saveNotes(u); return u; }); },
      updateNoteSize: async (id, w, h) => { setNotes(prev => { const u = prev.map(n => n.id === id ? { ...n, size: { w, h } } : n); storage.saveNotes(u); return u; }); },
      syncTelegram: async () => {}, deleteTelegramMsg: () => {}, addGoal: async () => {}, toggleGoalStatus: async () => {}, deleteGoal: async () => {}, addCategory: async () => {}, deleteCategory: async () => {}
    }}>
      {children}
    </NotesContext.Provider>
  );
};

export const useNotes = () => {
  const c = useContext(NotesContext);
  if (!c) throw new Error("useNotes error");
  return c;
};

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useNotes } from '../contexts/NotesContext.tsx';
import { Note } from '../types.ts';
import { 
  ChevronLeft, Save, Loader2, Sparkles, MessageSquare, Send, X, Folder, Globe, Hash, Play, Pause, Headphones, Search, Link2, ArrowRight, Plus
} from 'lucide-react';
import * as ai from '../utils/aiAdapter.ts';

const NoteEditor: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { notes, addNote, updateNote, runAIAnalysis, settings, addLog, setFilterTag } = useNotes();

  const [localTitle, setLocalTitle] = useState('');
  const [localContent, setLocalContent] = useState('');
  const [localTags, setLocalTags] = useState<string[]>([]);
  const [localCategory, setLocalCategory] = useState('Общее');

  const [tagInput, setTagInput] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [note, setNote] = useState<Note | null>(null);

  const isUserTyping = useRef(false);
  const typingTimeout = useRef<number | null>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatMessages, setChatMessages] = useState<{role: 'user' | 'assistant', content: string}[]>([]);
  const [isChatLoading, setIsChatLoading] = useState(false);

  const [isPlaying, setIsPlaying] = useState(false);
  const [audioProgress, setAudioProgress] = useState(0);

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    if (id && id !== 'new' && !isUserTyping.current) {
      const found = notes.find(n => n.id === id);
      if (found) {
        setNote(found);
        setLocalTitle(found.title);
        setLocalContent(found.content);
        setLocalTags(found.tags || []);
        setLocalCategory(found.category || 'Общее');

        if (found.summary && chatMessages.length === 0) {
            setChatMessages([{ role: 'assistant', content: `Анализ: ${found.summary}` }]);
        }
      }
    }
  }, [id, notes]);

  const handleContentChange = useCallback((e: React.ChangeEvent<HTMLTextAreaElement>) => {
    isUserTyping.current = true;
    setLocalContent(e.target.value);

    if (typingTimeout.current) clearTimeout(typingTimeout.current);
    typingTimeout.current = window.setTimeout(() => {
        isUserTyping.current = false;
    }, 1200);
  }, []);

  const handleTitleChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    isUserTyping.current = true;
    setLocalTitle(e.target.value);

    if (typingTimeout.current) clearTimeout(typingTimeout.current);
    typingTimeout.current = window.setTimeout(() => {
        isUserTyping.current = false;
    }, 1200);
  }, []);

  const handleSave = async (useAI = false) => {
    if (!localContent.trim() && !localTitle.trim()) return;
    setIsSaving(true);
    if (useAI) setIsAnalyzing(true);
    try {
        if (id === 'new') {
          await addNote(localContent, localTitle, 'manual', useAI);
        } else if (note) {
          const updatedNote = { 
            ...note, 
            title: localTitle, 
            content: localContent, 
            tags: localTags, 
            category: localCategory, 
            updatedAt: new Date().toISOString() 
          };
          await updateNote(updatedNote);
          if (useAI && navigator.onLine) {
            await runAIAnalysis(note.id);
          }
        }
        navigate('/');
    } catch (e: any) {
      addLog('error', 'Ошибка сохранения: ' + e.message);
    } finally {
        setIsSaving(false);
        setIsAnalyzing(false);
    }
  };

  const handleChatSend = async () => {
    if (!chatInput.trim() || isChatLoading) return;
    const userMsg = chatInput;
    setChatMessages(prev => [...prev, { role: 'user', content: userMsg }]);
    setChatInput('');
    setIsChatLoading(true);
    try {
      const response = await ai.chatWithNotes(userMsg, localContent, settings);
      setChatMessages(prev => [...prev, { role: 'assistant', content: response }]);
    } catch (e: any) {
      setChatMessages(prev => [...prev, { role: 'assistant', content: `Сбой: ${e.message}` }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  const handleAddTag = () => {
    const val = tagInput.trim();
    if (val && !localTags.includes(val)) {
      setLocalTags([...localTags, val]);
      setTagInput('');
    }
  };

  return (
    <div className="h-screen flex flex-col bg-white dark:bg-[#020617] overflow-hidden">
      <header className="flex items-center justify-between px-12 py-8 border-b border-gray-100 dark:border-white/5 bg-white/80 dark:bg-slate-950/80 backdrop-blur-2xl z-20 shrink-0">
        <div className="flex items-center gap-6 flex-1 min-w-0">
          <button onClick={() => navigate(-1)} className="p-4 text-gray-400 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-2xl transition-all shrink-0">
            <ChevronLeft size={24}/>
          </button>
          <div className="flex flex-col flex-1 min-w-0">
              <div className="flex items-center gap-6 w-full">
                <input 
                  className="text-4xl font-extrabold bg-transparent border-none focus:outline-none text-black dark:text-white flex-1 tracking-tighter truncate" 
                  value={localTitle} 
                  onChange={handleTitleChange} 
                  placeholder="Заголовок..."
                />
                <button 
                  onClick={() => ai.openInGoogle(localTitle)}
                  className="w-14 h-14 bg-blue-600 text-white rounded-[1.5rem] hover:bg-blue-700 transition-all shadow-xl shadow-blue-500/40 shrink-0 active:scale-90 flex items-center justify-center"
                  title="Найти в Google"
                >
                  <Globe size={28} strokeWidth={2.5} />
                </button>
              </div>
              {note?.audioData && (
                <div className="flex items-center gap-6 mt-6">
                  <div className="flex items-center gap-4 px-6 py-4 bg-gray-50 dark:bg-slate-900/50 rounded-[2.5rem] border border-gray-100 dark:border-white/10">
                    <button onClick={() => setIsPlaying(!isPlaying)} className="w-12 h-12 bg-blue-600 text-white rounded-full flex items-center justify-center shadow-lg">
                      {isPlaying ? <Pause size={20} fill="currentColor"/> : <Play size={20} fill="currentColor" className="ml-1"/>}
                    </button>
                    <div className="w-48 h-2 bg-gray-200 dark:bg-slate-700 rounded-full relative">
                       <div className="absolute inset-y-0 left-0 bg-blue-500 transition-all duration-300" style={{ width: `${audioProgress}%` }} />
                    </div>
                  </div>
                </div>
              )}
          </div>
        </div>
        <div className="flex items-center gap-4 ml-8 shrink-0">
          <button onClick={() => handleSave(true)} className="px-8 py-5 bg-cyan-600/10 text-cyan-600 rounded-[2rem] font-black uppercase text-[10px] tracking-widest flex items-center gap-3 border border-cyan-500/10 hover:bg-cyan-600/20">
            {isAnalyzing ? <Loader2 size={18} className="animate-spin"/> : <Sparkles size={18}/>} AI Анализ
          </button>
          <button onClick={() => handleSave(false)} className="px-10 py-5 bg-blue-600 text-white rounded-[2rem] font-black uppercase text-[10px] tracking-widest shadow-xl active:scale-95 transition-all hover:bg-blue-700">
            {isSaving ? <Loader2 size={18} className="animate-spin"/> : <Save size={18}/>} Сохранить
          </button>
        </div>
      </header>

      <div className="flex-1 flex overflow-hidden">
        <div className="flex-1 overflow-y-auto custom-scrollbar bg-gray-50/5 p-12 lg:p-24 pb-48">
          <textarea 
            ref={textareaRef}
            className="w-full h-auto min-h-[400px] bg-transparent border-none focus:outline-none text-2xl leading-relaxed text-gray-800 dark:text-slate-200 resize-none font-medium placeholder:text-gray-200"
            value={localContent}
            onChange={handleContentChange}
            placeholder="Напишите историю..."
          />
        </div>

        <div className="w-[450px] border-l border-gray-100 dark:border-white/5 bg-white dark:bg-[#080c14] p-8 flex flex-col gap-8 overflow-y-auto custom-scrollbar">
           <div className="bg-white dark:bg-slate-900 p-8 rounded-[3rem] border border-gray-100 dark:border-white/5 shadow-sm">
             <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-3 mb-6">
               <Folder size={16} className="text-blue-500"/> Категория
             </h4>
             <select 
               className="w-full p-6 bg-gray-50 dark:bg-slate-950 rounded-[1.8rem] font-black text-xs border-none dark:text-white cursor-pointer"
               value={localCategory}
               onChange={e => setLocalCategory(e.target.value)}
             >
                {settings.customCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
             </select>
          </div>

          <div className="bg-white dark:bg-slate-900 rounded-[3.5rem] border border-gray-100 dark:border-white/5 flex flex-col flex-1 shadow-2xl overflow-hidden min-h-[400px]">
            <header className="p-8 border-b border-gray-50 dark:border-white/5 text-[10px] font-black uppercase text-blue-500 flex items-center gap-4">
              <MessageSquare size={20}/> Neural Assistant
            </header>
            <div className="flex-1 p-8 overflow-y-auto space-y-6 custom-scrollbar text-xs font-bold leading-relaxed dark:text-slate-300">
              {chatMessages.map((msg, i) => (
                <div key={i} className={`p-5 rounded-[1.8rem] ${msg.role === 'user' ? 'bg-blue-600 text-white self-end' : 'bg-gray-50 dark:bg-slate-800'}`}>
                    {msg.content}
                </div>
              ))}
              {isChatLoading && <Loader2 size={16} className="animate-spin text-blue-500" />}
            </div>
            <div className="p-6 border-t border-gray-50 dark:border-white/5 flex gap-3">
              <input className="flex-1 p-5 bg-gray-50 dark:bg-slate-950 rounded-[1.5rem] text-xs font-bold border-none dark:text-white" placeholder="Спросить..." value={chatInput} onChange={e => setChatInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleChatSend()} />
              <button onClick={handleChatSend} className="p-5 bg-blue-600 text-white rounded-[1.5rem] active:scale-90 transition-all shadow-xl"><Send size={18}/></button>
            </div>
          </div>

          <div className="bg-white dark:bg-slate-900 p-8 rounded-[3rem] border border-gray-100 dark:border-white/5 shadow-sm">
            <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-3 mb-6">
              <Hash size={16} className="text-blue-500"/> Теги
            </h4>
            <div className="flex flex-wrap gap-2.5 mb-6">
              {localTags.map(t => (
                <button key={t} className="px-4 py-2 bg-blue-50 text-blue-600 dark:bg-blue-900/20 rounded-xl text-[10px] font-black flex items-center gap-3 border border-blue-100">
                  #{t} <span onClick={(e) => { e.stopPropagation(); setLocalTags(localTags.filter(x => x !== t)); }} className="hover:text-red-500 transition-colors ml-1"><X size={10}/></span>
                </button>
              ))}
            </div>
            <div className="flex gap-2">
              <input className="flex-1 p-5 bg-gray-50 dark:bg-slate-950 rounded-2xl text-xs font-bold border-none dark:text-white" placeholder="Добавить..." value={tagInput} onChange={e => setTagInput(e.target.value)} onKeyDown={e => { if (e.key === 'Enter') handleAddTag(); }} />
              <button onClick={handleAddTag} className="p-5 bg-blue-600 text-white rounded-2xl shadow-xl active:scale-95 transition-all"><Plus size={18}/></button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default NoteEditor;

