                  <Globe size={28} strokeWidth={2.5} />
                </button>
              </div>
              {note?.audioData && (
                <div className="flex items-center gap-6 mt-6">
                  <div className="flex items-center gap-4 px-6 py-4 bg-gray-50 dark:bg-slate-900/50 rounded-[2.5rem] border border-gray-100 dark:border-white/10">
                    <button onClick={() => setIsPlaying(!isPlaying)} className="w-12 h-12 bg-blue-600 text-white rounded-full flex items-center justify-center shadow-lg">
