export default NoteEditor;

import { Settings, AIProvider } from '../types.ts';
import { GoogleGenAI } from "@google/genai";

const extractJSON = (str: string) => {
  if (!str) return {};
  let trimmed = str.trim();
  trimmed = trimmed.replace(/^```json/i, '').replace(/```$/g, '').trim();

  try {
    return JSON.parse(trimmed);
  } catch (e) {
    const jsonRegex = /\{[\s\S]*\}|\[[\s\S]*\]/;
    const match = trimmed.match(jsonRegex);
    if (match) {
      try {
        return JSON.parse(match[0].trim());
      } catch (inner) {}
    }
    console.error("AI JSON Error Content:", trimmed);
    return {};
  }
};

export const linkify = (text: string) => {
  const urlRegex = /(https?:\/\/[^\s]+)/g;
  return text.split(urlRegex).map((part) => {
    if (part.match(urlRegex)) {
      return `<a href="${part}" target="_blank" rel="noopener noreferrer" class="text-blue-500 underline">${part}</a>`;
    }
    return part;
  }).join('');
};

export const openInGoogle = (query: string) => {
  if (!query) return;
  window.open(`https://www.google.com/search?q=${encodeURIComponent(query)}`, '_blank');
};

async function callAI(
  prompt: string, 
  provider: AIProvider, 
  model: string, 
  apiKey: string, 
  baseUrl: string, 
  isJson: boolean, 
  systemInstruction?: string,
  mediaPart?: { data: string, mimeType: string }
) {
  // 1. GEMINI (Native SDK)
  if (provider === AIProvider.Gemini) {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const parts: any[] = [{ text: prompt }];
    if (mediaPart) {
      parts.unshift({ inlineData: mediaPart });
    }

    const response = await ai.models.generateContent({
      model: model || 'gemini-3-flash-preview',
      contents: [{ parts }],
      config: {
        systemInstruction,
        responseMimeType: isJson ? "application/json" : undefined
      }
    });

    const text = response.text || '';
    return isJson ? extractJSON(text) : text;
  }

  // 2. EXTERNAL PROVIDERS (Ollama, LM Studio, OpenRouter)
  let url = (baseUrl || '').trim().replace(/\/$/, '');
  let headers: Record<string, string> = { 'Content-Type': 'application/json' };
  let body: any = {};

  if (provider === AIProvider.Ollama) {
    url = url || 'http://localhost:11434';
    if (!url.includes('/api/chat')) url += '/api/chat';
    body = {
      model: model || 'mistral',
      messages: [
        ...(systemInstruction ? [{ role: 'system', content: systemInstruction }] : []),
        { role: 'user', content: prompt }
      ],
      stream: false,
      format: isJson ? 'json' : undefined
    };
  } else {
    // OpenRouter / LM Studio (OpenAI Compatibility)
    if (provider === AIProvider.OpenRouter) {
      url = url || 'https://openrouter.ai/api/v1';
      headers['HTTP-Referer'] = window.location.origin;
      headers['X-Title'] = 'ScreenMind2';
    } else {
      url = url || 'http://localhost:1234/v1';
    }

    if (!url.endsWith('/chat/completions')) url += '/chat/completions';
    if (apiKey) headers['Authorization'] = `Bearer ${apiKey}`;

    body = {
      model: model || (provider === AIProvider.OpenRouter ? 'google/gemini-2.0-flash-001' : 'model-identifier'),
      messages: [
        ...(systemInstruction ? [{ role: 'system', content: systemInstruction }] : []),
        { role: 'user', content: prompt }
      ],
      response_format: isJson ? { type: "json_object" } : undefined
    };
  }

  const res = await fetch(url, { method: 'POST', headers, body: JSON.stringify(body) });
  if (!res.ok) {
    const errData = await res.json().catch(() => ({}));
    throw new Error(errData?.error?.message || `HTTP ${res.status}`);
  }

  const data = await res.json();
  const content = provider === AIProvider.Ollama ? data.message.content : data.choices[0].message.content;

  return isJson ? extractJSON(content) : content;
}

export const analyzeText = async (text: string, settings: Settings) => {
  const prompt = `ВЕРНИ JSON ОБЪЕКТ: { "title": "краткий заголовок", "tags": ["тег1", "тег2"], "category": "категория", "summary": "суть текста одним предложением" }. ТЕКСТ: ${text}`;
  return await callAI(prompt, settings.provider, settings.model, settings.apiKey, settings.url, true, "Ты — системный аналитик базы знаний ScreenMind.");
};

export const splitLargeText = async (text: string, settings: Settings) => {
  const prompt = `Раздели текст на логические карточки. ВЕРНИ JSON МАССИВ ОБЪЕКТОВ: [{ "title": "заголовок", "content": "текст части", "category": "категория" }]. ТЕКСТ: ${text}`;
  return await callAI(prompt, settings.provider, settings.model, settings.apiKey, settings.url, true, "Ты — эксперт по структурированию лонгридов.");
};

export const transcribeAudio = async (blob: Blob, settings: Settings) => {
  const reader = new FileReader();
  const base64: string = await new Promise((resolve) => {
    reader.onload = () => resolve((reader.result as string).split(',')[1]);
    reader.readAsDataURL(blob);
  });

  return await callAI(
    "Преврати аудио в текст.",
    settings.transProvider,
    settings.transModel,
    settings.transApiKey,
    settings.transUrl,
    false,
    "Ты — профессионал по расшифровке аудио.",
    { data: base64, mimeType: blob.type }
  );
};

export const chatWithNotes = async (query: string, context: string, settings: Settings) => {
  return await callAI(`Контекст: ${context}\nВопрос: ${query}`, settings.provider, settings.model, settings.apiKey, settings.url, false);
};

export const chatWithAgent = async (query: string, appData: any, settings: Settings) => {
  return await callAI(`Данные: ${JSON.stringify(appData)}\nЗапрос: ${query}`, settings.agentProvider, settings.agentModel, settings.agentApiKey, settings.agentUrl, false, "Ты — системный агент ScreenMind.");
};

export const performOCR = async (base64Data: string, mimeType: string, settings: Settings) => {
  const dataOnly = base64Data.split(',')[1] || base64Data;
  return await callAI("Распознай текст.", settings.ocrProvider, settings.ocrModel, settings.ocrApiKey, settings.ocrUrl, false, undefined, { data: dataOnly, mimeType });
};

export const testConnection = async (settings: Settings) => {
  try {
    const res = await callAI("Say 'Online'", settings.provider, settings.model, settings.apiKey, settings.url, false);
    return { success: true, message: `Соединение с ${settings.provider} установлено: ${res}` };
  } catch (e: any) {
    return { success: false, message: `Ошибка ${settings.provider}: ${e.message}` };
  }
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Note, Settings, AIProvider, AppLog, NoteStatus, Goal } from '../types.ts';
import * as storage from '../utils/storage.ts';
import * as ai from '../utils/aiAdapter.ts';

interface NotesContextType {
  notes: Note[];
  goals: Goal[];
  settings: Settings;
  isLoading: boolean;
  logs: AppLog[];
  filterTag: string | null;
  filterCategory: string | null;
  telegramMessages: any[]; 
  setFilterTag: (tag: string | null) => void;
  setFilterCategory: (cat: string | null) => void;
  addNote: (content: string, title?: string, sourceType?: Note['sourceType'], useAI?: boolean, category?: string, audioData?: string) => Promise<void>;
  processLargeText: (text: string) => Promise<void>;
  updateNote: (note: Note) => Promise<void>;
  moveToTrash: (id: string) => Promise<void>;
  restoreNote: (id: string) => Promise<void>;
  hardDelete: (id: string) => Promise<void>;
  setNoteStatus: (id: string, status: NoteStatus) => Promise<void>;
  updateSettings: (s: Settings) => Promise<void>;
  addLog: (level: AppLog['level'], message: string, details?: string) => void;
  runAIAnalysis: (id: string) => Promise<void>;
  reanalyzeAll: () => Promise<void>;
  runSystemCheck: () => Promise<void>;
  updateNotePosition: (id: string, x: number, y: number) => Promise<void>;
  updateNoteSize: (id: string, w: number, h: number) => Promise<void>;
  syncTelegram: () => Promise<void>;
  deleteTelegramMsg: (id: number) => void;
  addGoal: (title: string, description: string) => Promise<void>;
  toggleGoalStatus: (id: string) => Promise<void>;
  deleteGoal: (id: string) => Promise<void>;
  addCategory: (name: string) => Promise<void>;
  deleteCategory: (name: string) => Promise<void>;
}

const NotesContext = createContext<NotesContextType | undefined>(undefined);

export const NotesProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [notes, setNotes] = useState<Note[]>([]);
  const [goals, setGoals] = useState<Goal[]>([]);
  const [settings, setSettings] = useState<Settings>(storage.getDefaultSettings());
  const [isLoading, setIsLoading] = useState(true);
  const [logs, setLogs] = useState<AppLog[]>([]);
  const [filterTag, setFilterTag] = useState<string | null>(null);
  const [filterCategory, setFilterCategory] = useState<string | null>(null);

  const addLog = (level: AppLog['level'], message: string, details?: string) => {
    const newLog: AppLog = { id: crypto.randomUUID(), timestamp: new Date().toISOString(), level, message, details };
    setLogs(prev => [newLog, ...prev].slice(0, 1000));
  };

  useEffect(() => {
    const init = async () => {
      const [n, s, g] = await Promise.all([storage.getNotes(), storage.getSettings(), storage.getGoals()]);
      setNotes(n || []);
      setSettings(s || storage.getDefaultSettings());
      setGoals(g || []);
      setIsLoading(false);
      document.documentElement.classList.toggle('dark', s?.theme === 'dark');
    };
    init();
  }, []);

  const addNote = async (content: string, title?: string, sourceType: Note['sourceType'] = 'manual', useAI = true, forceCategory?: string, audioData?: string) => {
    let analysis: any = { tags: [], category: forceCategory || filterCategory || 'Общее', summary: '', title: title };
    if (useAI && navigator.onLine) {
      try { analysis = await ai.analyzeText(content, settings); } catch (e) { addLog('warn', 'AI skipped', String(e)); }
    }
    const newNote: Note = {
      id: crypto.randomUUID(),
      title: title || analysis.title || content.slice(0, 40),
      content,
      tags: analysis.tags || [],
      category: forceCategory || analysis.category || filterCategory || 'Общее',
      summary: analysis.summary || '',
      status: 'new',
      isIndexed: useAI,
      sourceType,
      audioData,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      links: [],
      position: { x: Math.random() * 200, y: Math.random() * 200 },
      size: { w: 320, h: 280 }
    };
    setNotes(prev => { const u = [newNote, ...prev]; storage.saveNotes(u); return u; });
  };

  const processLargeText = async (text: string) => {
    addLog('info', 'Smart Split: Анализ структуры лонгрида...');
    try {
      const parts = await ai.splitLargeText(text, settings);
      if (Array.isArray(parts) && parts.length > 0) {
        addLog('success', `Создано ${parts.length} карточек знаний.`);
        for (const p of parts) await addNote(p.content, p.title, 'split', false, p.category);
      }
    } catch (e: any) {
      addLog('error', 'Split Error', e.message);
    }
  };

  const reanalyzeAll = async () => {
    const allNotes = await storage.getNotes();
    const active = allNotes.filter(n => n.status !== 'trash' && n.content.length > 5);
    addLog('info', `[ГЛУБОКИЙ РЕИНДЕКС] Старт для ${active.length} файлов через ${settings.provider}.`);

    let currentBatch = [...allNotes];
    let success = 0;

    for (let i = 0; i < currentBatch.length; i++) {
      const n = currentBatch[i];
      if (n.status === 'trash' || n.content.length <= 5) continue;

      try {
        addLog('info', `[${success + 1}/${active.length}] Индексация: "${n.title}"...`);
        // Троттлинг 1.5 сек для стабильности API
        await new Promise(r => setTimeout(r, 1500));

        const res = await ai.analyzeText(n.content, settings);
        if (res && (res.title || res.tags)) {
          currentBatch[i] = { ...n, ...res, isIndexed: true, updatedAt: new Date().toISOString() };
          success++;
          // Принудительное обновление для UI прогресса
          setNotes([...currentBatch]);
          await storage.saveNotes([...currentBatch]);
        }
      } catch (err: any) {
        addLog('error', `Ошибка в "${n.title}": ${err.message}`);
      }
    }
    addLog('success', `Реиндекс завершен. Обновлено карточек: ${success}`);
  };

  const updateSettings = async (s: Settings) => {
    setSettings(s);
    await storage.saveSettings(s);
    document.documentElement.classList.toggle('dark', s.theme === 'dark');
  };

  const updateNote = async (n: Note) => {
    setNotes(prev => {
      const u = prev.map(x => x.id === n.id ? n : x);
      storage.saveNotes(u);
      return u;
    });
  };

  const setNoteStatus = async (id: string, status: NoteStatus) => {
    setNotes(prev => {
      const u = prev.map(n => n.id === id ? { ...n, status } : n);
      storage.saveNotes(u);
      return u;
    });
  };

  const runAIAnalysis = async (id: string) => {
    const n = notes.find(x => x.id === id);
    if (!n) return;
    try {
      addLog('info', `ИИ-анализ для "${n.title}"...`);
      const res = await ai.analyzeText(n.content, settings);
      setNotes(prev => {
        const u = prev.map(x => x.id === id ? { ...x, ...res, isIndexed: true, updatedAt: new Date().toISOString() } : x);
        storage.saveNotes(u);
        return u;
      });
      addLog('success', `Заметка "${n.title}" обновлена.`);
    } catch (e: any) { addLog('error', `Анализ не удался: ${e.message}`); }
  };

  return (
    <NotesContext.Provider value={{ 
      notes, goals, settings, isLoading, logs, filterTag, filterCategory, telegramMessages: [],
      setFilterTag, setFilterCategory, addNote, processLargeText, updateNote, 
      moveToTrash: async (id) => setNoteStatus(id, 'trash'), 
      restoreNote: async (id) => setNoteStatus(id, 'new'), 
      hardDelete: async (id) => { setNotes(prev => { const u = prev.filter(x => x.id !== id); storage.saveNotes(u); return u; }); },
      setNoteStatus, updateSettings, addLog, runAIAnalysis, reanalyzeAll,
      runSystemCheck: async () => { addLog('info', 'Тест ИИ...'); const r = await ai.testConnection(settings); r.success ? addLog('success', r.message) : addLog('error', r.message); },
      updateNotePosition: async (id, x, y) => { setNotes(prev => { const u = prev.map(n => n.id === id ? { ...n, position: { x, y } } : n); storage.saveNotes(u); return u; }); },
      updateNoteSize: async (id, w, h) => { setNotes(prev => { const u = prev.map(n => n.id === id ? { ...n, size: { w, h } } : n); storage.saveNotes(u); return u; }); },
      syncTelegram: async () => {}, deleteTelegramMsg: () => {}, addGoal: async () => {}, toggleGoalStatus: async () => {}, deleteGoal: async () => {}, addCategory: async () => {}, deleteCategory: async () => {}
    }}>
      {children}
    </NotesContext.Provider>
  );
};

export const useNotes = () => {
  const c = useContext(NotesContext);
  if (!c) throw new Error("useNotes error");
  return c;
};

