export const transcribeAudio = async (blob: Blob, settings: Settings) => {
  const reader = new FileReader();
  const base64: string = await new Promise((resolve) => {
    reader.onload = () => resolve((reader.result as string).split(',')[1]);
    reader.readAsDataURL(blob);
  });

  return await callAI("Transcribe audio.", settings.transProvider, settings.transModel, settings.transApiKey, settings.transUrl, false, undefined, { data: base64, mimeType: blob.type });
};

