import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { Note, Settings, AIProvider, AppLog, NoteStatus, Goal } from '../types.ts';
import * as storage from '../utils/storage.ts';
import * as ai from '../utils/aiAdapter.ts';

interface NotesContextType {
  notes: Note[];
  goals: Goal[];
  settings: Settings;
  isLoading: boolean;
  isIndexing: boolean;
  indexingProgress: number;
  logs: AppLog[];
  filterTag: string | null;
  filterCategory: string | null;
  telegramMessages: any[]; 
  setFilterTag: (tag: string | null) => void;
  setFilterCategory: (cat: string | null) => void;
  addNote: (content: string, title?: string, sourceType?: Note['sourceType'], useAI?: boolean, category?: string, audioData?: string) => Promise<void>;
  processLargeText: (text: string) => Promise<void>;
  updateNote: (note: Note) => Promise<void>;
  moveToTrash: (id: string) => Promise<void>;
  restoreNote: (id: string) => Promise<void>;
  hardDelete: (id: string) => Promise<void>;
  setNoteStatus: (id: string, status: NoteStatus) => Promise<void>;
  updateSettings: (s: Settings) => Promise<void>;
  addLog: (level: AppLog['level'], message: string, details?: string) => void;
  runAIAnalysis: (id: string) => Promise<void>;
  reanalyzeAll: () => Promise<void>;
  runSystemCheck: () => Promise<void>;
  updateNotePosition: (id: string, x: number, y: number) => Promise<void>;
  updateNoteSize: (id: string, w: number, h: number) => Promise<void>;
  syncTelegram: () => Promise<void>;
  deleteTelegramMsg: (id: number) => void;
  addGoal: (title: string, description: string) => Promise<void>;
  toggleGoalStatus: (id: string) => Promise<void>;
  deleteGoal: (id: string) => Promise<void>;
  addCategory: (name: string) => Promise<void>;
  deleteCategory: (name: string) => Promise<void>;
}

const NotesContext = createContext<NotesContextType | undefined>(undefined);

export const NotesProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [notes, setNotes] = useState<Note[]>([]);
  const [goals, setGoals] = useState<Goal[]>([]);
  const [settings, setSettings] = useState<Settings>(storage.getDefaultSettings());
  const [isLoading, setIsLoading] = useState(true);
  const [isIndexing, setIsIndexing] = useState(false);
  const [indexingProgress, setIndexingProgress] = useState(0);
  const [logs, setLogs] = useState<AppLog[]>([]);
  const [filterTag, setFilterTag] = useState<string | null>(null);
  const [filterCategory, setFilterCategory] = useState<string | null>(null);

  const addLog = useCallback((level: AppLog['level'], message: string, details?: string) => {
    const newLog: AppLog = { id: crypto.randomUUID(), timestamp: new Date().toISOString(), level, message, details };
    setLogs(prev => [newLog, ...prev].slice(0, 500));
  }, []);

  useEffect(() => {
    const init = async () => {
      try {
        const [n, s, g] = await Promise.all([storage.getNotes(), storage.getSettings(), storage.getGoals()]);
        setNotes(n || []);
        setSettings(s || storage.getDefaultSettings());
        setGoals(g || []);
        document.documentElement.classList.toggle('dark', (s || storage.getDefaultSettings()).theme === 'dark');
      } catch (err) {
        addLog('error', 'Init storage failed', String(err));
      } finally {
        setIsLoading(false);
      }
    };
    init();
  }, [addLog]);

  const addNote = async (content: string, title?: string, sourceType: Note['sourceType'] = 'manual', useAI = true, forceCategory?: string, audioData?: string) => {
    let analysis: any = { tags: [], category: forceCategory || filterCategory || 'Общее', summary: '', title: title };
    if (useAI) {
      try { analysis = await ai.analyzeText(content, settings); } catch (e: any) { addLog('warn', 'AI analysis failed', e.message); }
    }
    const newNote: Note = {
      id: crypto.randomUUID(),
      title: title || analysis.title || content.slice(0, 40),
      content,
      tags: analysis.tags || [],
      category: forceCategory || analysis.category || filterCategory || 'Общее',
      summary: analysis.summary || '',
      status: 'new',
      isIndexed: useAI,
      sourceType,
      audioData,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      links: [],
      position: { x: Math.random() * 200, y: Math.random() * 200 },
      size: { w: 320, h: 280 }
    };
    setNotes(prev => { 
      const u = [newNote, ...prev]; 
      storage.saveNotes(u).catch(e => addLog('error', 'Storage save failed', e.message)); 
      return u; 
    });
  };

  const processLargeText = async (text: string) => {
    addLog('info', 'Smart Split: Analysis started...');
    try {
      const parts = await ai.splitLargeText(text, settings);
      if (Array.isArray(parts) && parts.length > 0) {
        addLog('success', `Created ${parts.length} knowledge cards.`);
        for (const p of parts) await addNote(p.content, p.title, 'split', false, p.category);
      }
    } catch (e: any) { addLog('error', 'Split Error', e.message); }
  };

  const reanalyzeAll = async () => {
    const allNotes = await storage.getNotes();
    const active = allNotes.filter(n => n.status !== 'trash' && n.content.length > 5);
    if (active.length === 0) return;

    setIsIndexing(true);
    setIndexingProgress(0);
    addLog('info', `Deep Re-index: Started for ${active.length} cards.`);

    let currentBatch = [...allNotes];
    let success = 0;

    for (let i = 0; i < currentBatch.length; i++) {
      const n = currentBatch[i];
      if (n.status === 'trash' || n.content.length <= 5) continue;

      try {
        const progress = Math.round((success / active.length) * 100);
        setIndexingProgress(progress);

        // Anti-throttle pause
        await new Promise(r => setTimeout(r, 1200));

        const res = await ai.analyzeText(n.content, settings);
        if (res && (res.title || res.tags)) {
          currentBatch[i] = { ...n, ...res, isIndexed: true, updatedAt: new Date().toISOString() };
          success++;
          // Incremental UI updates
          setNotes([...currentBatch]);
          await storage.saveNotes([...currentBatch]);
        }
      } catch (err: any) {
        addLog('error', `Error in "${n.title}": ${err.message}`);
      }
    }

    setIndexingProgress(100);
    setTimeout(() => { setIsIndexing(false); setIndexingProgress(0); }, 2000);
    addLog('success', `Deep Re-index completed. ${success} cards updated.`);
  };

  const updateSettings = async (s: Settings) => {
    setSettings(s);
    await storage.saveSettings(s);
    document.documentElement.classList.toggle('dark', s.theme === 'dark');
  };

  const updateNote = async (n: Note) => {
    setNotes(prev => {
      const u = prev.map(x => x.id === n.id ? n : x);
      storage.saveNotes(u);
      return u;
    });
  };

  const setNoteStatus = async (id: string, status: NoteStatus) => {
    setNotes(prev => {
      const u = prev.map(n => n.id === id ? { ...n, status } : n);
      storage.saveNotes(u);
      return u;
    });
  };

  const runAIAnalysis = async (id: string) => {
    const n = notes.find(x => x.id === id);
    if (!n) return;
    try {
      addLog('info', `AI analysis for "${n.title}"...`);
      const res = await ai.analyzeText(n.content, settings);
      setNotes(prev => {
        const u = prev.map(x => x.id === id ? { ...x, ...res, isIndexed: true, updatedAt: new Date().toISOString() } : x);
        storage.saveNotes(u);
        return u;
      });
      addLog('success', `Card "${n.title}" analyzed.`);
    } catch (e: any) { addLog('error', `Analysis failed: ${e.message}`); }
  };

  return (
    <NotesContext.Provider value={{ 
      notes, goals, settings, isLoading, isIndexing, indexingProgress, logs, filterTag, filterCategory, telegramMessages: [],
      setFilterTag, setFilterCategory, addNote, processLargeText, updateNote, 
      moveToTrash: async (id) => setNoteStatus(id, 'trash'), 
      restoreNote: async (id) => setNoteStatus(id, 'new'), 
      hardDelete: async (id) => { setNotes(prev => { const u = prev.filter(x => x.id !== id); storage.saveNotes(u); return u; }); },
      setNoteStatus, updateSettings, addLog, runAIAnalysis, reanalyzeAll,
      runSystemCheck: async () => { addLog('info', 'AI diagnostic started...'); const r = await ai.testConnection(settings); r.success ? addLog('success', r.message) : addLog('error', r.message); },
      updateNotePosition: async (id, x, y) => { setNotes(prev => { const u = prev.map(n => n.id === id ? { ...n, position: { x, y } } : n); storage.saveNotes(u); return u; }); },
      updateNoteSize: async (id, w, h) => { setNotes(prev => { const u = prev.map(n => n.id === id ? { ...n, size: { w, h } } : n); storage.saveNotes(u); return u; }); },
      syncTelegram: async () => {}, deleteTelegramMsg: () => {}, addGoal: async () => {}, toggleGoalStatus: async () => {}, deleteGoal: async () => {}, addCategory: async () => {}, deleteCategory: async () => {}
    }}>
      {children}
    </NotesContext.Provider>
  );
};

export const useNotes = () => {
  const c = useContext(NotesContext);
  if (!c) throw new Error("useNotes error");
  return c;
};

