import { Settings, AIProvider } from '../types.ts';
import { GoogleGenAI } from "@google/genai";

const extractJSON = (str: string) => {
  if (!str) return {};
  let trimmed = str.trim();
  trimmed = trimmed.replace(/^```json/i, '').replace(/```$/g, '').trim();

  try {
    return JSON.parse(trimmed);
  } catch (e) {
    // Попытка найти JSON объект или массив внутри текста
    const jsonRegex = /\{[\s\S]*\}|\[[\s\S]*\]/;
    const match = trimmed.match(jsonRegex);
    if (match) {
      try {
        return JSON.parse(match[0].trim());
      } catch (inner) {}
    }
    console.error("Failed to parse JSON from AI response:", trimmed);
    return {};
  }
};

// Хелпер для повторных попыток запроса с экспоненциальной задержкой
async function withRetry<T>(fn: () => Promise<T>, retries = 2, delay = 1000): Promise<T> {
  try {
    return await fn();
  } catch (error: any) {
    if (retries <= 0) throw error;
    // Повторяем только если это ошибка сети или 429 (Too Many Requests)
    const isRetryable = error.message.includes('429') || error.message.toLowerCase().includes('fetch') || error.message.includes('network');
    if (!isRetryable) throw error;

    console.warn(`Retry attempt left: ${retries}. Waiting ${delay}ms...`);
    await new Promise(resolve => setTimeout(resolve, delay));
    return withRetry(fn, retries - 1, delay * 2);
  }
}

export const linkify = (text: string) => {
  const urlRegex = /(https?:\/\/[^\s]+)/g;
  return text.split(urlRegex).map((part) => {
    if (part.match(urlRegex)) {
      return `<a href="${part}" target="_blank" rel="noopener noreferrer" class="text-blue-500 underline">${part}</a>`;
    }
    return part;
  }).join('');
};

export const openInGoogle = (query: string) => {
  if (!query) return;
  window.open(`https://www.google.com/search?q=${encodeURIComponent(query)}`, '_blank');
};

async function callAI(
  prompt: string, 
  provider: AIProvider, 
  model: string, 
  apiKey: string, 
  baseUrl: string, 
  isJson: boolean, 
  systemInstruction?: string,
  mediaPart?: { data: string, mimeType: string }
) {
  return withRetry(async () => {
    // 1. GEMINI NATIVE SDK
    if (provider === AIProvider.Gemini) {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || apiKey });
      const parts: any[] = [{ text: prompt }];
      if (mediaPart) {
        parts.unshift({ inlineData: mediaPart });
      }

      const response = await ai.models.generateContent({
        model: model || 'gemini-3-flash-preview',
        contents: [{ parts }],
        config: {
          systemInstruction,
          responseMimeType: isJson ? "application/json" : undefined
        }
      });

      const text = response.text || '';
      return isJson ? extractJSON(text) : text;
    }

    // 2. EXTERNAL PROVIDERS (REST API)
    let url = (baseUrl || '').trim().replace(/\/$/, '');
    let headers: Record<string, string> = { 'Content-Type': 'application/json' };
    let body: any = {};

    // --- LM STUDIO (Custom format requested by user) ---
    if (provider === AIProvider.LMStudio) {
        url = url || 'http://localhost:1234';
        // Используем специфичный эндпоинт, если запрошено пользователем
        if (!url.includes('/api/v1/chat') && !url.includes('/v1/chat/completions')) {
            url += '/api/v1/chat'; 
        }

        body = {
            model: model || "local-model",
            system_prompt: systemInstruction || "You are a helpful assistant.",
            input: prompt, // LM Studio specific field based on requirements
            temperature: 0.7
        };
        // Если это стандартный OpenAI-совместимый эндпоинт, переключаем формат тела
        if (url.includes('/chat/completions')) {
             body = {
                model: model || "local-model",
                messages: [
                    ...(systemInstruction ? [{ role: 'system', content: systemInstruction }] : []),
                    { role: 'user', content: prompt }
                ],
                response_format: isJson ? { type: "json_object" } : undefined
            };
        }
    } 
    // --- OLLAMA ---
    else if (provider === AIProvider.Ollama) {
        url = url || 'http://localhost:11434';
        if (!url.includes('/api/chat')) url += '/api/chat';
        body = {
            model: model || 'mistral',
            messages: [
                ...(systemInstruction ? [{ role: 'system', content: systemInstruction }] : []),
                { role: 'user', content: prompt }
            ],
            stream: false,
            format: isJson ? 'json' : undefined
        };
    } 
    // --- OPENROUTER & STANDARD OPENAI ---
    else {
        if (provider === AIProvider.OpenRouter) {
            url = url || 'https://openrouter.ai/api/v1';
            headers['HTTP-Referer'] = window.location.origin || 'https://screenmind.ai';
            headers['X-Title'] = 'ScreenMind2';
        } else {
            url = url || 'http://localhost:1234/v1';
        }

        if (!url.endsWith('/chat/completions')) url += '/chat/completions';
        if (apiKey) headers['Authorization'] = `Bearer ${apiKey}`;

        body = {
            model: model || (provider === AIProvider.OpenRouter ? 'google/gemini-2.0-flash-001' : 'local-model'),
            messages: [
                ...(systemInstruction ? [{ role: 'system', content: systemInstruction }] : []),
                { role: 'user', content: prompt }
            ],
            ...(isJson && provider !== AIProvider.OpenRouter ? { response_format: { type: "json_object" } } : {})
        };

        // Для OpenRouter, если JSON режим, добавляем инструкцию в промпт, так как не все модели поддерживают response_format
        if (isJson && provider === AIProvider.OpenRouter) {
            body.messages[body.messages.length - 1].content += "\n\nCRITICAL INSTRUCTION: Respond ONLY with valid JSON.";
        }
    }

    // Выполнение запроса
    try {
        const res = await fetch(url, { method: 'POST', headers, body: JSON.stringify(body) });

        if (!res.ok) {
            const errText = await res.text();
            let errMessage = `HTTP ${res.status}`;
            try {
                const errJson = JSON.parse(errText);
                errMessage = errJson.error?.message || errJson.error || errText;
            } catch (e) {}
            throw new Error(`Provider Error: ${errMessage}`);
        }

        const data = await res.json();

        // Универсальный парсинг ответа
        let content = "";

        if (provider === AIProvider.Ollama) {
            content = data.message?.content;
        } else {
            // Пытаемся найти контент в стандартных местах (OpenAI format)
            if (data.choices && Array.isArray(data.choices) && data.choices.length > 0) {
                content = data.choices[0].message?.content || data.choices[0].text;
            } 
            // Фоллбек для LM Studio custom format или других провайдеров
            else if (data.content) {
                content = data.content;
            } else if (data.text) {
                content = data.text;
            } else if (data.response) {
                content = data.response;
            } else {
                console.error("Unknown API Response format:", data);
                throw new Error("Empty or unknown response format from AI provider");
            }
        }

        if (!content) throw new Error("AI returned empty content");

        return isJson ? extractJSON(content) : content;

    } catch (error: any) {
        // Улучшенная диагностика ошибок
        if (error.message.includes('Failed to fetch')) {
            throw new Error(`Connection failed to ${url}. Check if the local server is running and CORS is allowed.`);
        }
        throw error;
    }
  });
}

