// Функция для тестирования конкретной конфигурации (не глобальных настроек)
export const testSpecificConnection = async (provider: AIProvider, url: string, model: string, key: string) => {
  try {
    const res = await callAI("Say 'OK'", provider, model, key, url, false);
    return { success: true, message: `Connected: ${res}` };
  } catch (e: any) {
    return { success: false, message: e.message };
  }
};

export const testConnection = async (settings: Settings) => {
    return testSpecificConnection(settings.provider, settings.url, settings.model, settings.apiKey);
};

