  Settings as SettingsIcon, Terminal, RefreshCw, Download, Database, Zap, Cpu, KeyRound, Mic, Bot, ScanLine, FileText, Send, Info, Eye, EyeOff, CheckCircle2, AlertCircle, Loader2, Save
} from 'lucide-react';
