    setTestStatus('loading');
    const res = await testSpecificConnection(provider, url, model, apiKey);
    setTestStatus(res.success ? 'success' : 'error');
    setTestMsg(res.message);
    setTimeout(() => setTestStatus('idle'), 3000);
