export const analyzeText = async (text: string, settings: Settings) => {
  const prompt = `Analyze this text. RETURN JSON: { "title": "short title (max 60 chars)", "tags": ["tag1", "tag2", "tag3"], "category": "category name", "summary": "1 sentence summary" }. TEXT: ${text.slice(0, 4000)}`;
  return await callAI(prompt, settings.provider, settings.model, settings.apiKey, settings.url, true, "You are a content analyzer.");
};

export const splitLargeText = async (text: string, settings: Settings) => {
  const prompt = `Split this text into logical knowledge cards. Each card must be self-contained. 
  RETURN JSON ARRAY: [ { "title": "Card Title", "content": "Card Content", "category": "Suggested Category" }, ... ]. 
  TEXT: ${text.slice(0, 15000)}`;
  return await callAI(prompt, settings.provider, settings.model, settings.apiKey, settings.url, true, "You are an expert editor.");
};

export const transcribeAudio = async (blob: Blob, settings: Settings) => {
  const reader = new FileReader();
  const base64: string = await new Promise((resolve) => {
    reader.onload = () => resolve((reader.result as string).split(',')[1]);
    reader.readAsDataURL(blob);
  });
  // Используем специальные настройки для транскрибации
  return await callAI("Transcribe this audio accurately.", settings.transProvider, settings.transModel, settings.transApiKey, settings.transUrl, false, undefined, { data: base64, mimeType: blob.type });
};

export const chatWithNotes = async (query: string, context: string, settings: Settings) => {
  return await callAI(`Context from notes:\n${context}\n\nUser Question: ${query}`, settings.provider, settings.model, settings.apiKey, settings.url, false, "You are a helpful assistant.");
};

export const chatWithAgent = async (query: string, appData: any, settings: Settings) => {
  // Используем настройки агента
  return await callAI(`System Data: ${JSON.stringify(appData)}\nUser Request: ${query}`, settings.agentProvider, settings.agentModel, settings.agentApiKey, settings.agentUrl, false, "You are ScreenMind System Agent.");
};

export const performOCR = async (base64Data: string, mimeType: string, settings: Settings) => {
  const dataOnly = base64Data.split(',')[1] || base64Data;
  // Используем настройки OCR
  return await callAI("Extract all text from this image.", settings.ocrProvider, settings.ocrModel, settings.ocrApiKey, settings.ocrUrl, false, undefined, { data: dataOnly, mimeType });
};

