import { get, set, del } from 'https://cdn.jsdelivr.net/npm/idb-keyval@6/+esm';
import { Note, Settings, AIProvider, Goal, AIProfile, BackupMetadata } from '../types.ts';

const NOTES_KEY = 'screenmind_notes';
const SETTINGS_KEY = 'screenmind_settings';
const PROFILES_KEY = 'screenmind_profiles';
const GOALS_KEY = 'screenmind_goals';
const BACKUPS_PREFIX = 'screenmind_backup_';

export const saveNotes = async (notes: Note[]) => {
  await set(NOTES_KEY, notes);
};

export const getNotes = async (): Promise<Note[]> => {
  const notes = await get(NOTES_KEY);
  return notes || [];
};

export const saveGoals = async (goals: Goal[]) => {
  await set(GOALS_KEY, goals);
};

export const getGoals = async (): Promise<Goal[]> => {
  const goals = await get(GOALS_KEY);
  return goals || [];
};

export const saveSettings = async (settings: Settings) => {
  await set(SETTINGS_KEY, settings);
};

export const getDefaultSettings = (): Settings => ({
  provider: AIProvider.Ollama,
  url: 'http://localhost:11434',
  model: 'mistral',
  apiKey: '',
  theme: 'light',
  customCategories: ['Общее', 'Идеи', 'Работа', 'ИИ'],
  ocrProvider: AIProvider.Gemini,
  ocrModel: 'gemini-2.5-flash-image',
  ocrApiKey: '',
  ocrUrl: '',
  transProvider: AIProvider.Gemini,
  transModel: 'gemini-2.5-flash-native-audio-preview-12-2025',
  transApiKey: '',
  transUrl: '',
  agentProvider: AIProvider.Gemini,
  agentModel: 'gemini-3-pro-preview',
  agentApiKey: '',
  agentUrl: '',
  tgToken: '',
  tgChatId: '',
  tgLastUpdateId: 0,
  cacheEnabled: true,
  cacheTTL: 60 
});

export const getSettings = async (): Promise<Settings> => {
  const settings = await get(SETTINGS_KEY);
  return { ...getDefaultSettings(), ...settings };
};

// --- PROFILES ---
export const saveProfiles = async (profiles: AIProfile[]) => {
    await set(PROFILES_KEY, profiles);
};

export const getProfiles = async (): Promise<AIProfile[]> => {
    return (await get(PROFILES_KEY)) || [];
};

// --- BACKUPS ---
export const createBackup = async (): Promise<BackupMetadata> => {
    const notes = await getNotes();
    const settings = await getSettings();
    const goals = await getGoals();
    const profiles = await getProfiles();

    const backupId = crypto.randomUUID();
    const timestamp = new Date().toISOString();
    const backupData = { notes, settings, goals, profiles, version: '3.2.0', timestamp };

    const blob = new Blob([JSON.stringify(backupData)], { type: 'application/json' });
    await set(`${BACKUPS_PREFIX}${backupId}`, backupData);

    return {
        id: backupId,
        date: timestamp,
        version: '3.2.0',
        noteCount: notes.length,
        size: blob.size
    };
};

export const restoreBackup = async (backupId: string) => {
    const data = await get(`${BACKUPS_PREFIX}${backupId}`);
    if (data) {
        if(data.notes) await saveNotes(data.notes);
        if(data.settings) await saveSettings(data.settings);
        if(data.goals) await saveGoals(data.goals);
        if(data.profiles) await saveProfiles(data.profiles);
        return true;
    }
    return false;
};

export const exportData = async () => {
  const notes = await getNotes();
  const settings = await getSettings();
  const goals = await getGoals();
  const profiles = await getProfiles();
  const data = JSON.stringify({ notes, settings, goals, profiles, version: '3.2.0', exportedAt: new Date().toISOString() }, null, 2);
  const blob = new Blob([data], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `screenmind_backup_${new Date().toISOString().slice(0,10)}.json`;
  a.click();
  URL.revokeObjectURL(url);
};

export const importData = async (file: File): Promise<boolean> => {
  try {
    const text = await file.text();
    const data = JSON.parse(text);
    if (data.notes) await saveNotes(data.notes);
    if (data.settings) await saveSettings(data.settings);
    if (data.goals) await saveGoals(data.goals);
    if (data.profiles) await saveProfiles(data.profiles);
    return true;
  } catch (e) {
    console.error("Import failed", e);
    return false;
  }
};

import { Settings, AIProvider, AIMetrics } from '../types.ts';
import { GoogleGenAI } from "@google/genai";

// --- SYSTEM METRICS & CACHE ---
const metrics: AIMetrics = {
    totalRequests: 0,
    successRequests: 0,
    failedRequests: 0,
    averageLatency: 0,
    lastRequestTime: '',
    providerUsage: {}
};

const requestCache = new Map<string, { response: any, timestamp: number }>();

export const getMetrics = () => metrics;

export const clearCache = () => {
    requestCache.clear();
    console.log("AI Cache cleared");
};

const updateMetrics = (latency: number, success: boolean, provider: string) => {
    metrics.totalRequests++;
    if (success) metrics.successRequests++;
    else metrics.failedRequests++;

    // Simple moving average for latency
    metrics.averageLatency = (metrics.averageLatency * (metrics.totalRequests - 1) + latency) / metrics.totalRequests;
    metrics.lastRequestTime = new Date().toISOString();
    metrics.providerUsage[provider] = (metrics.providerUsage[provider] || 0) + 1;
};

const getCacheKey = (prompt: string, model: string, provider: string) => {
    // Simple hash for cache key
    let hash = 0;
    const str = `${provider}:${model}:${prompt.slice(0, 100)}`; // Limit prompt len for key
    for (let i = 0; i < str.length; i++) {
        hash = ((hash << 5) - hash) + str.charCodeAt(i);
        hash |= 0;
    }
    return hash.toString();
};

// --- PLUGIN ARCHITECTURE ---
// Base interface for any AI Provider
interface AIProviderAdapter {
    id: AIProvider;
    call(prompt: string, settings: Settings, isJson: boolean, systemInstruction?: string, mediaPart?: any): Promise<any>;
}

// 1. Gemini Adapter
const GeminiAdapter: AIProviderAdapter = {
    id: AIProvider.Gemini,
    async call(prompt, settings, isJson, systemInstruction, mediaPart) {
        if (!process.env.API_KEY && !settings.apiKey && !settings.ocrApiKey) throw new Error("Gemini API Key missing");
        const key = settings.apiKey || settings.ocrApiKey || settings.transApiKey; // Fallback logic

        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || key });
        const parts: any[] = [{ text: prompt }];
        if (mediaPart) parts.unshift({ inlineData: mediaPart });

        const response = await ai.models.generateContent({
            model: settings.model || 'gemini-3-flash-preview',
            contents: [{ parts }],
            config: {
                systemInstruction,
                responseMimeType: isJson ? "application/json" : undefined
            }
        });
        return response.text || '';
    }
};

// 2. OpenAI-Compatible Adapter (LM Studio, OpenRouter, etc.)
const createOpenAIAdapter = (provider: AIProvider): AIProviderAdapter => ({
    id: provider,
    async call(prompt, settings, isJson, systemInstruction, mediaPart) {
        let url = (settings.url || '').trim().replace(/\/$/, '');
        let headers: Record<string, string> = { 'Content-Type': 'application/json' };
        let body: any = {};

        if (provider === AIProvider.LMStudio) {
            url = url || 'http://localhost:1234';
            if (url.includes('/v1/chat/completions') || url.includes('/chat/completions')) {
                 body = {
                    model: settings.model || "local-model",
                    messages: [
                        ...(systemInstruction ? [{ role: 'system', content: systemInstruction }] : []),
                        { role: 'user', content: prompt }
                    ],
                    response_format: isJson ? { type: "json_object" } : undefined,
                    temperature: 0.7
                };
            } else {
                 // Custom LM Studio Endpoint
                 if (!url.includes('/api/v1/chat')) {
                     if(url.endsWith('/v1')) url = url.replace('/v1', '') + '/api/v1/chat';
                     else url += '/api/v1/chat';
                 }
                 body = {
                    model: settings.model || "local-model",
                    system_prompt: systemInstruction || "You are a helpful assistant.",
                    input: prompt,
                    temperature: 0.7
                };
            }
        } else if (provider === AIProvider.Ollama) {
            url = url || 'http://localhost:11434';
            if (!url.includes('/api/chat')) url += '/api/chat';
            body = {
                model: settings.model || 'mistral',
                messages: [
                    ...(systemInstruction ? [{ role: 'system', content: systemInstruction }] : []),
                    { role: 'user', content: prompt }
                ],
                stream: false,
                format: isJson ? 'json' : undefined
            };
        } else if (provider === AIProvider.OpenRouter) {
            url = url || 'https://openrouter.ai/api/v1';
            headers['HTTP-Referer'] = window.location.origin || 'https://screenmind.ai';
            headers['X-Title'] = 'ScreenMind2 Ultra';
            headers['Authorization'] = `Bearer ${settings.apiKey}`;
            if (!url.endsWith('/chat/completions')) url += '/chat/completions';

            body = {
                model: settings.model || 'google/gemini-2.0-flash-001',
                messages: [
                    ...(systemInstruction ? [{ role: 'system', content: systemInstruction }] : []),
                    { role: 'user', content: prompt }
                ]
            };
            if (isJson) body.messages[body.messages.length - 1].content += "\n\nRETURN JSON ONLY.";
        }

        const res = await fetch(url, { method: 'POST', headers, body: JSON.stringify(body) });
        if (!res.ok) {
            const errText = await res.text();
            throw new Error(`${provider} Error (${res.status}): ${errText.slice(0, 200)}`);
        }

        const data = await res.json();

        if (provider === AIProvider.Ollama) return data.message?.content;
        if (data.content) return data.content; // LM Studio custom
        if (data.choices?.[0]?.message?.content) return data.choices[0].message.content;
        if (data.choices?.[0]?.text) return data.choices[0].text;

        throw new Error("Unknown response format");
    }
});

// Registry
const adapters: Record<string, AIProviderAdapter> = {
    [AIProvider.Gemini]: GeminiAdapter,
    [AIProvider.Ollama]: createOpenAIAdapter(AIProvider.Ollama),
    [AIProvider.LMStudio]: createOpenAIAdapter(AIProvider.LMStudio),
    [AIProvider.OpenRouter]: createOpenAIAdapter(AIProvider.OpenRouter)
};


// --- UTILITIES ---
const extractJSON = (str: string) => {
  if (!str) return {};
  let trimmed = str.trim();
  trimmed = trimmed.replace(/^```json/i, '').replace(/^```/i, '').replace(/```$/g, '').trim();
  try { return JSON.parse(trimmed); } catch (e) {
    const jsonRegex = /\{[\s\S]*\}|\[[\s\S]*\]/;
    const match = trimmed.match(jsonRegex);
    if (match) { try { return JSON.parse(match[0].trim()); } catch (inner) {} }
    console.warn("AI Adapter: Failed to parse JSON", trimmed.slice(0, 50));
    return {};
  }
};

async function withRetry<T>(fn: () => Promise<T>, retries = 2, delay = 1000): Promise<T> {
  try { return await fn(); } catch (error: any) {
    if (retries <= 0) throw error;
    const msg = error.message.toLowerCase();
    if (msg.includes('fetch') || msg.includes('network') || msg.includes('429') || msg.includes('50')) {
        console.log(`Retry ${3 - retries}...`);
        await new Promise(r => setTimeout(r, delay));
        return withRetry(fn, retries - 1, delay * 2);
    }
    throw error;
  }
}


// --- MAIN CALL FUNCTION ---
async function callAI(
  prompt: string, 
  provider: AIProvider, 
  model: string, 
  apiKey: string, 
  baseUrl: string, 
  isJson: boolean, 
  systemInstruction?: string,
  mediaPart?: { data: string, mimeType: string },
  settingsContext?: Settings // Full settings object to check cache config
) {
  const startTime = performance.now();

  // 1. Check Cache
  const cacheKey = getCacheKey(prompt, model, provider);
  if (settingsContext?.cacheEnabled) {
      const cached = requestCache.get(cacheKey);
      if (cached && (Date.now() - cached.timestamp < (settingsContext.cacheTTL * 60 * 1000))) {
          console.log(`[AI] Cache Hit: ${provider}/${model}`);
          return isJson ? extractJSON(cached.response) : cached.response;
      }
  }

  try {
      // 2. Resolve Adapter
      const adapter = adapters[provider];
      if (!adapter) throw new Error(`Provider ${provider} not implemented`);

      // 3. Construct temp settings object for the adapter
      const tempSettings = { ...settingsContext, provider, model, apiKey, url: baseUrl } as Settings;

      // 4. Execute with Retry
      const result = await withRetry(() => adapter.call(prompt, tempSettings, isJson, systemInstruction, mediaPart));

      // 5. Update Metrics & Cache
      const latency = performance.now() - startTime;
      updateMetrics(latency, true, provider);

      if (settingsContext?.cacheEnabled) {
          requestCache.set(cacheKey, { response: result, timestamp: Date.now() });
      }

      return isJson ? extractJSON(result) : result;

  } catch (e: any) {
      updateMetrics(performance.now() - startTime, false, provider);
      throw e;
  }
}

