                >
                  <KeyRound size={14} /> Select Google Key
                </button>
            </div>
          )}
        </div>
      </div>
      {testStatus === 'error' && (
          <div className="mt-4 p-4 bg-red-50 dark:bg-red-900/20 rounded-2xl text-[10px] text-red-600 font-medium">
              Error: {testMsg}
          </div>
      )}
    </section>
  );
});

