import { get, set, del } from 'https://cdn.jsdelivr.net/npm/idb-keyval@6/+esm';
import { Note, Settings, AIProvider, Goal, AIProfile, BackupMetadata } from '../types.ts';

const NOTES_KEY = 'screenmind_notes';
const SETTINGS_KEY = 'screenmind_settings';
const PROFILES_KEY = 'screenmind_profiles';
const GOALS_KEY = 'screenmind_goals';
const BACKUPS_PREFIX = 'screenmind_backup_';

export const saveNotes = async (notes: Note[]) => {
  await set(NOTES_KEY, notes);
};

export const getNotes = async (): Promise<Note[]> => {
  const notes = await get(NOTES_KEY);
  return notes || [];
};

export const saveGoals = async (goals: Goal[]) => {
  await set(GOALS_KEY, goals);
};

export const getGoals = async (): Promise<Goal[]> => {
  const goals = await get(GOALS_KEY);
  return goals || [];
};

export const saveSettings = async (settings: Settings) => {
  await set(SETTINGS_KEY, settings);
};

export const getDefaultSettings = (): Settings => ({
  // Основной провайдер
  provider: AIProvider.Ollama,
  url: '/api/ollama', // Используем прокси
  model: 'mistral',
  apiKey: '',
  theme: 'light',
  customCategories: ['Общее', 'Идеи', 'Работа', 'ИИ'],

  // OCR (Gemini лучше всего подходит)
  ocrProvider: AIProvider.Gemini,
  ocrModel: 'gemini-2.5-flash-image',
  ocrApiKey: '',
  ocrUrl: '',

  // Voice
  transProvider: AIProvider.Gemini,
  transModel: 'gemini-2.5-flash-native-audio-preview-12-2025',
  transApiKey: '',
  transUrl: '',

  // Agent
  agentProvider: AIProvider.Gemini,
  agentModel: 'gemini-3-pro-preview',
  agentApiKey: '',
  agentUrl: '',

  // Split
  splitProvider: AIProvider.Gemini,
  splitModel: 'gemini-3-flash-preview',
  splitApiKey: '',
  splitUrl: '',
  splitChunkSize: 15000,

  tgToken: '',
  tgChatId: '',
  tgLastUpdateId: 0,

  cacheEnabled: true,
  cacheTTL: 60 
});

export const getSettings = async (): Promise<Settings> => {
  const settings = await get(SETTINGS_KEY);
  return { ...getDefaultSettings(), ...settings };
};

// --- PROFILES ---
export const saveProfiles = async (profiles: AIProfile[]) => {
    await set(PROFILES_KEY, profiles);
};

export const getProfiles = async (): Promise<AIProfile[]> => {
    return (await get(PROFILES_KEY)) || [];
};

// --- BACKUPS ---
export const createBackup = async (): Promise<BackupMetadata> => {
    const notes = await getNotes();
    const settings = await getSettings();
    const goals = await getGoals();
    const profiles = await getProfiles();

    const backupId = crypto.randomUUID();
    const timestamp = new Date().toISOString();
    const backupData = { notes, settings, goals, profiles, version: '1.0.0', timestamp };

    const blob = new Blob([JSON.stringify(backupData)], { type: 'application/json' });
    await set(`${BACKUPS_PREFIX}${backupId}`, backupData);

    return {
        id: backupId,
        date: timestamp,
        version: '1.0.0',
        noteCount: notes.length,
        size: blob.size
    };
};

export const restoreBackup = async (backupId: string) => {
    const data = await get(`${BACKUPS_PREFIX}${backupId}`);
    if (data) {
        if(data.notes) await saveNotes(data.notes);
        if(data.settings) await saveSettings(data.settings);
        if(data.goals) await saveGoals(data.goals);
        if(data.profiles) await saveProfiles(data.profiles);
        return true;
    }
    return false;
};

export const exportData = async () => {
  const notes = await getNotes();
  const settings = await getSettings();
  const goals = await getGoals();
  const profiles = await getProfiles();
  const data = JSON.stringify({ notes, settings, goals, profiles, version: '1.0.0', exportedAt: new Date().toISOString() }, null, 2);
  const blob = new Blob([data], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `screenmind_backup_${new Date().toISOString().slice(0,10)}.json`;
  a.click();
  URL.revokeObjectURL(url);
};

export const importData = async (file: File): Promise<boolean> => {
  try {
    const text = await file.text();
    const data = JSON.parse(text);
    if (data.notes) await saveNotes(data.notes);
    if (data.settings) await saveSettings(data.settings);
    if (data.goals) await saveGoals(data.goals);
    if (data.profiles) await saveProfiles(data.profiles);
    return true;
  } catch (e) {
    console.error("Import failed", e);
    return false;
  }
};

import React, { useState, useCallback, memo, useEffect } from 'react';
import { useNotes } from '../contexts/NotesContext.tsx';
import { AIProvider } from '../types.ts';
import { 
  Settings as SettingsIcon, Terminal, RefreshCw, Download, Database, Zap, Cpu, KeyRound, Mic, Bot, ScanLine, Send, Info, Eye, EyeOff, CheckCircle2, AlertCircle, Loader2, Save, Users, Activity, HardDrive, Trash2, Scissors
} from 'lucide-react';
import * as storage from '../utils/storage.ts';
import { testSpecificConnection } from '../utils/aiAdapter.ts';

// Provider Selector Component
const ProviderSelector = memo(({ 
  label, icon: Icon, 
  provider, onProviderChange, 
  url, onUrlChange, 
  model, onModelChange, 
  apiKey, onKeyChange 
}: {
  label: string, icon: any,
  provider: AIProvider, onProviderChange: (v: AIProvider) => void,
  url: string, onUrlChange: (v: string) => void,
  model: string, onModelChange: (v: string) => void,
  apiKey: string, onKeyChange: (v: string) => void
}) => {
  const isGemini = provider === AIProvider.Gemini;
  const isOllama = provider === AIProvider.Ollama;
  const isOpenRouter = provider === AIProvider.OpenRouter;

  const [showKey, setShowKey] = useState(false);
  const [testStatus, setTestStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle');
  const [testMsg, setTestMsg] = useState('');

  // Auto-fill recommended URLs when provider changes
  useEffect(() => {
    if (provider === AIProvider.Ollama && (!url || url.includes('lmstudio'))) {
      onUrlChange('/api/ollama');
      if(!model) onModelChange('mistral');
    } else if (provider === AIProvider.LMStudio && (!url || url.includes('ollama'))) {
      onUrlChange('/api/lmstudio');
      if(!model) onModelChange('local-model');
    }
  }, [provider]);

  const handleTest = async () => {
    setTestStatus('loading');
    const res = await testSpecificConnection(provider, url, model, apiKey);
    setTestStatus(res.success ? 'success' : 'error');
    setTestMsg(res.message);
    setTimeout(() => setTestStatus('idle'), 3000);
  };

  const getUrlPlaceholder = () => {
    if (isOllama) return "/api/ollama (Local Proxy)";
    if (isOpenRouter) return "https://openrouter.ai/api/v1";
    if (provider === AIProvider.LMStudio) return "/api/lmstudio (Local Proxy)";
    return "https://api.example.com/v1";
  };

  const getModelPlaceholder = () => {
    if (isOllama) return "mistral";
    if (isOpenRouter) return "google/gemini-2.0-flash-001";
    if (provider === AIProvider.LMStudio) return "local-model";
    return "gemini-3-flash-preview";
  };

  return (
    <section className="bg-white dark:bg-slate-900 p-8 rounded-[3rem] border border-gray-100 dark:border-slate-800 shadow-sm transition-all hover:border-blue-500/30 group">
      <div className="flex justify-between items-center mb-8 px-2">
          <div className="flex flex-col gap-1">
            <h3 className="font-black text-[11px] uppercase tracking-widest flex items-center gap-3 text-gray-500 group-hover:text-blue-500 transition-colors">
                <Icon size={18}/> {label}
            </h3>
            {isOpenRouter && <span className="text-[9px] text-blue-500 font-bold ml-8">Universal Gateway</span>}
            {(isOllama || provider === AIProvider.LMStudio) && <span className="text-[9px] text-green-500 font-bold ml-8">Local Network Optimized</span>}
          </div>
          <div className="flex items-center gap-2">
            {testStatus !== 'idle' && (
                <span className={`text-[10px] font-bold px-3 py-1 rounded-full flex items-center gap-2 ${
                    testStatus === 'loading' ? 'bg-gray-100 text-gray-500' :
                    testStatus === 'success' ? 'bg-green-100 text-green-600' : 'bg-red-100 text-red-600'
                }`}>
                    {testStatus === 'loading' && <Loader2 size={10} className="animate-spin"/>}
