// --- PLUGIN ARCHITECTURE ---
// Base interface for any AI Provider
interface AIProviderAdapter {
    id: AIProvider;
    call(prompt: string, settings: Settings, isJson: boolean, systemInstruction?: string, mediaPart?: any): Promise<{text: string, usage?: any}>;
}

// 1. Gemini Adapter
const GeminiAdapter: AIProviderAdapter = {
    id: AIProvider.Gemini,
    async call(prompt, settings, isJson, systemInstruction, mediaPart) {
        // Safe check for API Key in different environments
        const envKey = (import.meta as any).env?.VITE_GOOGLE_API_KEY || ''; 
        const key = settings.apiKey || settings.splitApiKey || settings.ocrApiKey || settings.transApiKey || envKey;

        if (!key) throw new Error("Gemini API Key missing. Please set it in Settings.");

        const ai = new GoogleGenAI({ apiKey: key });
        const parts: any[] = [{ text: prompt }];
        if (mediaPart) parts.unshift({ inlineData: mediaPart });

        const response = await ai.models.generateContent({
            model: settings.model || 'gemini-3-flash-preview',
            contents: [{ parts }],
            config: {
                systemInstruction,
                responseMimeType: isJson ? "application/json" : undefined
            }
        });

        // Extract usage metadata if available
        return {
            text: response.text || '',
            usage: response.usageMetadata
        };
    }
};

// 2. OpenAI-Compatible Adapter (LM Studio, OpenRouter, etc.)
const createOpenAIAdapter = (provider: AIProvider): AIProviderAdapter => ({
    id: provider,
    async call(prompt, settings, isJson, systemInstruction, mediaPart) {
        // Normalizing URL logic for Proxy vs Direct
        let url = (settings.url || '').trim().replace(/\/$/, '');
        let headers: Record<string, string> = { 'Content-Type': 'application/json' };
        let body: any = {};

        // --- LM STUDIO LOGIC ---
        if (provider === AIProvider.LMStudio) {
            // If empty, use proxy default
            if (!url) url = '/api/lmstudio';

            // If using proxy, append correct OpenAI-compatible endpoint
            if (url.startsWith('/api/lmstudio')) {
                 if (!url.endsWith('/v1/chat/completions')) url += '/v1/chat/completions';
            } else {
                 // Direct connection (if configured without proxy)
                 url = url || 'http://localhost:1234';
                 if (!url.includes('/v1/') && !url.includes('/chat') && !url.includes('/completions')) {
                     url += '/v1/chat/completions';
                 }
            }

            body = {
                model: settings.model || "local-model",
                messages: [
                    ...(systemInstruction ? [{ role: 'system', content: systemInstruction }] : []),
                    { role: 'user', content: prompt }
                ],
                response_format: isJson ? { type: "json_object" } : undefined,
                temperature: 0.7
            };

        // --- OLLAMA LOGIC ---
        } else if (provider === AIProvider.Ollama) {
            // If empty, use proxy default
            if (!url) url = '/api/ollama';

            // If using proxy, append API endpoint
            if (url.startsWith('/api/ollama')) {
                 // Proxy rewrites /api/ollama to root, so we add /api/chat
                 if (!url.endsWith('/api/chat')) url += '/api/chat';
            } else {
                 // Direct connection
                 url = url || 'http://localhost:11434';
                 if (!url.includes('/api/')) url += '/api/chat';
            }

            body = {
                model: settings.model || 'mistral',
                messages: [
                    ...(systemInstruction ? [{ role: 'system', content: systemInstruction }] : []),
                    { role: 'user', content: prompt }
                ],
                stream: false,
                format: isJson ? 'json' : undefined
            };

        // --- OPENROUTER LOGIC ---
        } else if (provider === AIProvider.OpenRouter) {
            url = url || 'https://openrouter.ai/api/v1';
            headers['HTTP-Referer'] = window.location.origin || 'https://screenmind.ai';
            headers['X-Title'] = 'ScreenMind2 Ultra';
            headers['Authorization'] = `Bearer ${settings.apiKey}`;

            if (!url.endsWith('/chat/completions')) url += '/chat/completions';

            body = {
                model: settings.model || 'google/gemini-2.0-flash-001',
                messages: [
                    ...(systemInstruction ? [{ role: 'system', content: systemInstruction }] : []),
                    { role: 'user', content: prompt }
                ]
            };
            if (isJson) body.messages[body.messages.length - 1].content += "\n\nRETURN JSON ONLY.";
        }

        try {
            const controller = new AbortController();
            const timeoutId = setTimeout(() => controller.abort(), 30000); // 30s timeout for local models

            const res = await fetch(url, { 
                method: 'POST', 
                headers, 
                body: JSON.stringify(body),
                signal: controller.signal
            });
            clearTimeout(timeoutId);

            if (!res.ok) {
                const errText = await res.text();
                throw new Error(`${provider} Error (${res.status}): ${errText.slice(0, 200)}`);
            }

            const data = await res.json();
            if (data.error) throw new Error(data.error.message || JSON.stringify(data.error));

            const content = 
                data.choices?.[0]?.message?.content || 
                data.message?.content || 
                data.response || 
                data.content || 
                data.choices?.[0]?.text;

            if (content) return { text: content };

            console.error("AI Adapter: Unknown response format", data);
            throw new Error(`Unknown response format. Received keys: ${Object.keys(data).join(', ')}`);

        } catch (error: any) {
             if (error.name === 'AbortError') {
                 throw new Error(`${provider} timed out (30s). Model might be loading or too slow.`);
             }
             if (error.message.includes('Failed to fetch')) {
                 throw new Error(`Connection to ${provider} failed. Ensure the service is running at ${url} and CORS is configured.`);
             }
             throw error;
        }
    }
});

// Registry
const adapters: Record<string, AIProviderAdapter> = {
    [AIProvider.Gemini]: GeminiAdapter,
    [AIProvider.Ollama]: createOpenAIAdapter(AIProvider.Ollama),
    [AIProvider.LMStudio]: createOpenAIAdapter(AIProvider.LMStudio),
    [AIProvider.OpenRouter]: createOpenAIAdapter(AIProvider.OpenRouter)
};


// --- UTILITIES ---
const extractJSON = (str: string) => {
  if (!str) return {};
  let content = str.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
  content = content.replace(/^```json/i, '').replace(/^```/i, '').replace(/```$/g, '').trim();
  try { return JSON.parse(content); } catch (e) {
    const jsonRegex = /\{[\s\S]*\}|\[[\s\S]*\]/;
    const match = content.match(jsonRegex);
    if (match) { try { return JSON.parse(match[0].trim()); } catch (inner) {} }
    console.warn("AI Adapter: Failed to parse JSON", content.slice(0, 50));
    return {};
  }
};

async function withRetry<T>(fn: () => Promise<T>, retries = 2, delay = 1000): Promise<T> {
  try { return await fn(); } catch (error: any) {
    if (retries <= 0) throw error;
    const msg = error.message.toLowerCase();
    if (msg.includes('fetch') || msg.includes('network') || msg.includes('429') || msg.includes('50')) {
        console.log(`Retry ${3 - retries}...`);
        await new Promise(r => setTimeout(r, delay));
        return withRetry(fn, retries - 1, delay * 2);
    }
    throw error;
  }
}


// --- MAIN CALL FUNCTION ---
async function callAI(
  prompt: string, 
  provider: AIProvider, 
  model: string, 
  apiKey: string, 
  baseUrl: string, 
  isJson: boolean, 
  systemInstruction?: string,
  mediaPart?: { data: string, mimeType: string },
  settingsContext?: Settings
) {
  const startTime = performance.now();
  const cacheKey = getCacheKey(prompt, model, provider);

  if (settingsContext?.cacheEnabled) {
      const cached = requestCache.get(cacheKey);
      if (cached && (Date.now() - cached.timestamp < (settingsContext.cacheTTL * 60 * 1000))) {
          console.log(`[AI] Cache Hit: ${provider}/${model}`);
          return isJson ? extractJSON(cached.response) : cached.response;
      }
  }

  try {
      const adapter = adapters[provider];
      if (!adapter) throw new Error(`Provider ${provider} not implemented`);
      const tempSettings = { ...settingsContext, provider, model, apiKey, url: baseUrl } as Settings;

      const resultObj = await withRetry(() => adapter.call(prompt, tempSettings, isJson, systemInstruction, mediaPart));

      updateMetrics(performance.now() - startTime, true, provider, resultObj.usage);

      const resultText = resultObj.text;

      if (settingsContext?.cacheEnabled) {
          requestCache.set(cacheKey, { response: resultText, timestamp: Date.now() });
      }

      return isJson ? extractJSON(resultText) : resultText;

  } catch (e: any) {
      updateMetrics(performance.now() - startTime, false, provider);
      throw e;
  }
}

// --- PUBLIC INTERFACE ---

export const analyzeText = async (text: string, settings: Settings) => {
  const prompt = `Analyze this text. RETURN JSON: { "title": "short title", "tags": ["tag1", "tag2"], "category": "category", "summary": "summary" }. TEXT: ${text.slice(0, 4000)}`;
  return await callAI(prompt, settings.provider, settings.model, settings.apiKey, settings.url, true, "Content Analyzer", undefined, settings);
};

export const splitLargeText = async (text: string, settings: Settings) => {
  const limit = settings.splitChunkSize || 15000;
  const prompt = `Split this text into logical knowledge cards. Each card must be self-contained. 
  RETURN JSON ARRAY: [ { "title": "Card Title", "content": "Card Content", "category": "Suggested Category" }, ... ]. 
  TEXT: ${text.slice(0, limit)}`;
  return await callAI(prompt, settings.splitProvider, settings.splitModel, settings.splitApiKey, settings.splitUrl, true, "Expert Editor", undefined, settings);
};

export const clusterIdeas = async (ideas: {id: string, title: string, tags: string[]}[], settings: Settings) => {
    const input = JSON.stringify(ideas);
    const prompt = `Analyze these ideas and group them into logical clusters. 
    RETURN JSON: { "clusters": [ { "name": "Cluster Name", "ids": ["id1", "id2"] } ] }.
    DATA: ${input}`;
    return await callAI(prompt, settings.agentProvider, settings.agentModel, settings.agentApiKey, settings.agentUrl, true, "Data Scientist", undefined, settings);
};

export const transcribeAudio = async (blob: Blob, settings: Settings) => {
  const reader = new FileReader();
  const base64: string = await new Promise((resolve) => {
    reader.onload = () => resolve((reader.result as string).split(',')[1]);
    reader.readAsDataURL(blob);
  });
  return await callAI("Transcribe audio.", settings.transProvider, settings.transModel, settings.transApiKey, settings.transUrl, false, undefined, { data: base64, mimeType: blob.type }, settings);
};

export const chatWithNotes = async (query: string, context: string, settings: Settings) => {
  return await callAI(`Context:\n${context}\n\nUser: ${query}`, settings.provider, settings.model, settings.apiKey, settings.url, false, "Helpful Assistant", undefined, settings);
};

export const chatWithAgent = async (query: string, appData: any, settings: Settings) => {
  return await callAI(`System Data: ${JSON.stringify(appData)}\nUser: ${query}`, settings.agentProvider, settings.agentModel, settings.agentApiKey, settings.agentUrl, false, "System Agent", undefined, settings);
};

export const performOCR = async (base64Data: string, mimeType: string, settings: Settings) => {
  const dataOnly = base64Data.split(',')[1] || base64Data;
  return await callAI("Extract text.", settings.ocrProvider, settings.ocrModel, settings.ocrApiKey, settings.ocrUrl, false, undefined, { data: dataOnly, mimeType }, settings);
};

export const testConnection = async (settings: Settings) => {
    try {
        const res = await callAI("Say 'OK'", settings.provider, settings.model, settings.apiKey, settings.url, false, undefined, undefined, settings);
        return { success: true, message: `Connected: ${res}` };
    } catch (e: any) {
        return { success: false, message: e.message };
    }
};

export const testSpecificConnection = async (provider: AIProvider, url: string, model: string, key: string) => {
  const mockSettings = { provider, url, model, apiKey: key, cacheEnabled: false } as Settings;
  return testConnection(mockSettings);
};

export const openInGoogle = (query: string) => {
  if (!query) return;
  window.open(`https://www.google.com/search?q=${encodeURIComponent(query)}`, '_blank');
};

export const linkify = (text: string) => {
    const urlRegex = /(\b(https?|ftp|file):\/\/[-A-Z0-9+&@#\/%?=~_|!:,.;]*[-A-Z0-9+&@#\/%=~_|])/ig;
    return text.replace(urlRegex, function(url) {
        return `<a href="${url}" target="_blank" rel="noopener noreferrer" class="text-blue-500 underline decoration-blue-500/30 hover:text-blue-600 transition-colors break-all">${url}</a>`;
    });
};

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { Note, Settings, AIProvider, AppLog, NoteStatus, Goal, AIProfile, AIMetrics } from '../types.ts';
import * as storage from '../utils/storage.ts';
import * as ai from '../utils/aiAdapter.ts';

interface NotesContextType {
  notes: Note[];
  goals: Goal[];
  settings: Settings;
  profiles: AIProfile[];
  metrics: AIMetrics;
  isLoading: boolean;
  isIndexing: boolean;
  indexingProgress: number;
  logs: AppLog[];
  filterTag: string | null;
  filterCategory: string | null;
  telegramMessages: any[]; 
  setFilterTag: (tag: string | null) => void;
  setFilterCategory: (cat: string | null) => void;
  addNote: (content: string, title?: string, sourceType?: Note['sourceType'], useAI?: boolean, category?: string, audioData?: string) => Promise<void>;
  processLargeText: (text: string) => Promise<void>;
  updateNote: (note: Note) => Promise<void>;
  moveToTrash: (id: string) => Promise<void>;
  restoreNote: (id: string) => Promise<void>;
  hardDelete: (id: string) => Promise<void>;
  setNoteStatus: (id: string, status: NoteStatus) => Promise<void>;
  updateSettings: (s: Settings) => Promise<void>;
  addLog: (level: AppLog['level'], message: string, details?: string) => void;
  runAIAnalysis: (id: string) => Promise<void>;
  reanalyzeAll: () => Promise<void>;
  runSystemCheck: () => Promise<void>;
  updateNotePosition: (id: string, x: number, y: number) => Promise<void>;
  updateNoteSize: (id: string, w: number, h: number) => Promise<void>;
  syncTelegram: () => Promise<void>;
  deleteTelegramMsg: (id: number) => void;
  // Goals
  addGoal: (title: string, description: string) => Promise<void>;
  toggleGoalStatus: (id: string) => Promise<void>;
  deleteGoal: (id: string) => Promise<void>;
  // Categories
  addCategory: (name: string) => Promise<void>;
  deleteCategory: (name: string) => Promise<void>;
  // Ideas Grouping
  autoGroupIdeas: () => Promise<void>;
  // Profiles
  createProfile: (name: string) => Promise<void>;
  switchProfile: (id: string) => Promise<void>;
  deleteProfile: (id: string) => Promise<void>;
  // Cache & Backup
  clearSystemCache: () => void;
  triggerBackup: () => Promise<void>;
  importBackup: (file: File) => Promise<void>;
}

const NotesContext = createContext<NotesContextType | undefined>(undefined);

export const NotesProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [notes, setNotes] = useState<Note[]>([]);
  const [goals, setGoals] = useState<Goal[]>([]);
  const [settings, setSettings] = useState<Settings>(storage.getDefaultSettings());
  const [profiles, setProfiles] = useState<AIProfile[]>([]);

  const [isLoading, setIsLoading] = useState(true);
  const [isIndexing, setIsIndexing] = useState(false);
  const [indexingProgress, setIndexingProgress] = useState(0);
  const [logs, setLogs] = useState<AppLog[]>([]);
  const [filterTag, setFilterTag] = useState<string | null>(null);
  const [filterCategory, setFilterCategory] = useState<string | null>(null);

  // Real-time metrics poll
  const [metrics, setMetrics] = useState<AIMetrics>(ai.getMetrics());

  const addLog = useCallback((level: AppLog['level'], message: string, details?: string) => {
    const newLog: AppLog = { id: crypto.randomUUID(), timestamp: new Date().toISOString(), level, message, details };
    setLogs(prev => [newLog, ...prev].slice(0, 500));
  }, []);

  useEffect(() => {
    const init = async () => {
      try {
        const [n, s, g, p] = await Promise.all([
            storage.getNotes(), 
            storage.getSettings(), 
            storage.getGoals(),
            storage.getProfiles()
        ]);
        setNotes(n || []);
        setSettings(s || storage.getDefaultSettings());
        setGoals(g || []);
        setProfiles(p || []);
        document.documentElement.classList.toggle('dark', (s || storage.getDefaultSettings()).theme === 'dark');
      } catch (err) {
        addLog('error', 'Storage init failed', String(err));
      } finally {
        setIsLoading(false);
      }
    };
    init();

    // Metrics Polling & Auto Backup interval
    const interval = setInterval(() => {
        setMetrics({...ai.getMetrics()});
        // Simple auto-backup check could go here
    }, 2000);

    return () => clearInterval(interval);
  }, [addLog]);

  // --- Profiles Logic ---
  const createProfile = async (name: string) => {
      const newProfile: AIProfile = {
          id: crypto.randomUUID(),
          name,
          settings: { ...settings },
          createdAt: new Date().toISOString()
      };
      const updatedProfiles = [...profiles, newProfile];
      setProfiles(updatedProfiles);
      await storage.saveProfiles(updatedProfiles);
      addLog('success', `Profile "${name}" created`);
  };

  const switchProfile = async (id: string) => {
      const profile = profiles.find(p => p.id === id);
      if(profile) {
          await updateSettings(profile.settings);
          addLog('info', `Switched to profile: ${profile.name}`);
      }
  };

  const deleteProfile = async (id: string) => {
      const updated = profiles.filter(p => p.id !== id);
      setProfiles(updated);
      await storage.saveProfiles(updated);
  };

  const triggerBackup = async () => {
      try {
          await storage.exportData(); // Download File
          addLog('success', `Backup file generated`);
      } catch (e: any) {
          addLog('error', 'Backup failed', e.message);
      }
  };

  const importBackup = async (file: File) => {
      try {
          const success = await storage.importData(file);
          if (success) {
              addLog('success', 'Data restored successfully');
              // Reload state
              const [n, s, g, p] = await Promise.all([storage.getNotes(), storage.getSettings(), storage.getGoals(), storage.getProfiles()]);
              setNotes(n); setSettings(s); setGoals(g); setProfiles(p);
          } else {
              throw new Error("Invalid format");
          }
      } catch (e: any) {
          addLog('error', 'Restore failed', e.message);
      }
  };

  // --- Standard Note Logic ---
  const addNote = async (content: string, title?: string, sourceType: Note['sourceType'] = 'manual', useAI = true, forceCategory?: string, audioData?: string) => {
    let analysis: any = { tags: [], category: forceCategory || filterCategory || 'Общее', summary: '', title: title };
    if (useAI) {
      try { 
        analysis = await ai.analyzeText(content, settings); 
      } catch (e: any) { 
        addLog('warn', 'AI Analysis skipped', e.message); 
      }
    }
    const newNote: Note = {
      id: crypto.randomUUID(),
      title: title || analysis.title || content.slice(0, 40) + "...",
      content,
      tags: analysis.tags || [],
      category: forceCategory || analysis.category || filterCategory || 'Общее',
      summary: analysis.summary || '',
      status: 'new',
      isIndexed: useAI,
      sourceType,
      audioData,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      links: [],
      position: { x: Math.random() * 200 + 50, y: Math.random() * 200 + 50 },
      size: { w: 320, h: 280 }
    };
    setNotes(prev => { 
      const u = [newNote, ...prev]; 
      storage.saveNotes(u).catch(e => addLog('error', 'Save error', e.message)); 
      return u; 
    });
  };

  const processLargeText = async (text: string) => {
    addLog('info', 'Smart Split: Starting text segmentation...');
    try {
      const parts = await ai.splitLargeText(text, settings);
      if (Array.isArray(parts) && parts.length > 0) {
        addLog('success', `Smart Split: Text divided into ${parts.length} cards.`);
        for (const p of parts) {
            if(p.content) await addNote(p.content, p.title || "Untitled Part", 'split', false, p.category);
        }
      } else {
        throw new Error("AI did not return a valid array of cards.");
      }
    } catch (e: any) { 
        addLog('error', 'Smart Split Failed', e.message); 
    }
  };

  const autoGroupIdeas = async () => {
      const ideas = notes.filter(n => n.category === 'Идеи' && n.status !== 'trash');
      if(ideas.length < 3) return;

      addLog('info', 'Clustering ideas...');
      try {
          const minimalIdeas = ideas.map(n => ({ id: n.id, title: n.title, tags: n.tags }));
          const res = await ai.clusterIdeas(minimalIdeas, settings);

          if(res && res.clusters) {
             const newNotes = [...notes];
             for(const cluster of res.clusters) {
                 for(const id of cluster.ids) {
                     const idx = newNotes.findIndex(n => n.id === id);
                     if(idx !== -1) {
                         // Add cluster name as a tag
                         if(!newNotes[idx].tags.includes(cluster.name)) {
                             newNotes[idx].tags = [...newNotes[idx].tags, cluster.name];
                         }
                     }
                 }
             }
             setNotes(newNotes);
             await storage.saveNotes(newNotes);
             addLog('success', `Created ${res.clusters.length} clusters`);
          }
      } catch(e: any) {
          addLog('error', 'Clustering failed', e.message);
      }
  };

  // --- CRUD Wrappers ---
  const addGoal = async (title: string, description: string) => {
    const newGoal: Goal = { id: crypto.randomUUID(), title, description, createdAt: new Date().toISOString(), color: '#3b82f6', status: 'active' };
    setGoals(prev => { const u = [newGoal, ...prev]; storage.saveGoals(u); return u; });
    addLog('success', 'Goal created', title);
  };

  const toggleGoalStatus = async (id: string) => {
    setGoals(prev => { 
        const u = prev.map(g => g.id === id ? { ...g, status: (g.status === 'active' ? 'completed' : 'active') as 'active' | 'completed' } : g); 
        storage.saveGoals(u); 
        return u; 
    });
  };

  const deleteGoal = async (id: string) => {
    setGoals(prev => { const u = prev.filter(g => g.id !== id); storage.saveGoals(u); return u; });
  };

  const addCategory = async (name: string) => {
     if(settings.customCategories.includes(name)) return;
     await updateSettings({ ...settings, customCategories: [...settings.customCategories, name] });
  };

  const deleteCategory = async (name: string) => {
     await updateSettings({ ...settings, customCategories: settings.customCategories.filter(c => c !== name) });
     setNotes(prev => { const u = prev.map(n => n.category === name ? { ...n, category: 'Общее' } : n); storage.saveNotes(u); return u; });
  };

  const reanalyzeAll = async () => {
    const allNotes = await storage.getNotes();
    const active = allNotes.filter(n => n.status !== 'trash' && n.content.length > 5);
    if (active.length === 0) return;
    setIsIndexing(true); setIndexingProgress(0);
    addLog('info', `Deep Re-index: Started for ${active.length} cards.`);
    let currentBatch = [...allNotes];
    let success = 0;
    for (let i = 0; i < currentBatch.length; i++) {
      const n = currentBatch[i];
      if (n.status === 'trash' || n.content.length <= 5) continue;
      try {
        setIndexingProgress(Math.round((success / active.length) * 100));
        await new Promise(r => setTimeout(r, 1000));
        const res = await ai.analyzeText(n.content, settings);
        if (res) {
          currentBatch[i] = { ...n, ...res, isIndexed: true, updatedAt: new Date().toISOString() };
          success++;
          setNotes([...currentBatch]);
          await storage.saveNotes([...currentBatch]);
        }
      } catch (err: any) { addLog('error', `Re-index error in "${n.title}": ${err.message}`); }
    }
    setIndexingProgress(100);
    setTimeout(() => { setIsIndexing(false); setIndexingProgress(0); }, 2000);
    addLog('success', `Deep Re-index completed. ${success} cards updated.`);
  };

  const updateSettings = async (s: Settings) => {
    setSettings(s);
    await storage.saveSettings(s);
    document.documentElement.classList.toggle('dark', s.theme === 'dark');
  };

  const updateNote = async (n: Note) => {
    setNotes(prev => { const u = prev.map(x => x.id === n.id ? n : x); storage.saveNotes(u); return u; });
  };

  const setNoteStatus = async (id: string, status: NoteStatus) => {
    setNotes(prev => { const u = prev.map(n => n.id === id ? { ...n, status } : n); storage.saveNotes(u); return u; });
  };

  const runAIAnalysis = async (id: string) => {
    const n = notes.find(x => x.id === id);
    if (!n) return;
    try {
      addLog('info', `Manual AI Analysis: "${n.title}"...`);
      const res = await ai.analyzeText(n.content, settings);
      setNotes(prev => { const u = prev.map(x => x.id === id ? { ...x, ...res, isIndexed: true, updatedAt: new Date().toISOString() } : x); storage.saveNotes(u); return u; });
      addLog('success', `Analysis complete for "${n.title}"`);
    } catch (e: any) { addLog('error', `Analysis failed: ${e.message}`); }
  };

  return (
    <NotesContext.Provider value={{ 
      notes, goals, settings, profiles, metrics, isLoading, isIndexing, indexingProgress, logs, filterTag, filterCategory, telegramMessages: [],
      setFilterTag, setFilterCategory, addNote, processLargeText, updateNote, 
      moveToTrash: async (id) => setNoteStatus(id, 'trash'), 
      restoreNote: async (id) => setNoteStatus(id, 'new'), 
      hardDelete: async (id) => { setNotes(prev => { const u = prev.filter(x => x.id !== id); storage.saveNotes(u); return u; }); },
      setNoteStatus, updateSettings, addLog, runAIAnalysis, reanalyzeAll, autoGroupIdeas,
      runSystemCheck: async () => { addLog('info', 'Ping test...'); const r = await ai.testConnection(settings); r.success ? addLog('success', r.message) : addLog('error', r.message); },
      updateNotePosition: async (id, x, y) => { setNotes(prev => { const u = prev.map(n => n.id === id ? { ...n, position: { x, y } } : n); storage.saveNotes(u); return u; }); },
      updateNoteSize: async (id, w, h) => { setNotes(prev => { const u = prev.map(n => n.id === id ? { ...n, size: { w, h } } : n); storage.saveNotes(u); return u; }); },
      syncTelegram: async () => {}, deleteTelegramMsg: () => {}, 
      addGoal, toggleGoalStatus, deleteGoal, addCategory, deleteCategory,
      createProfile, switchProfile, deleteProfile, clearSystemCache: ai.clearCache, triggerBackup, importBackup
    }}>
      {children}
    </NotesContext.Provider>
  );
};

export const useNotes = () => {
  const c = useContext(NotesContext);
  if (!c) throw new Error("useNotes error");
  return c;
};

import React, { useState, useCallback, memo, useEffect, useRef } from 'react';
import { useNotes } from '../contexts/NotesContext.tsx';
