import { 
  Settings as SettingsIcon, Terminal, RefreshCw, Download, Database, Zap, Cpu, KeyRound, Mic, Bot, ScanLine, Send, Info, Eye, EyeOff, CheckCircle2, AlertCircle, Loader2, Save, Users, Activity, HardDrive, Trash2, Scissors, UploadCloud, ShieldCheck
} from 'lucide-react';
